import { Agent, GameEngine } from "../game";
import { GridSystem } from "../systems/grid";
import { HexUtils } from "../utils";
import { UNIT_BODY_OFFSET, UNIT_HOVER_OFFSET, UNIT_VISUAL_HEIGHT, UNIT_SCALE, VISUAL_ANCHORS } from "../../constants";

export interface Point3D {
    x: number;
    y: number;
    z: number;
}

export class VisualMath {

    /**
     * SSOT: Calculate the visual Y coordinate of the unit's body center.
     * Takes into account surface Y, physics Z (jump), and model offsets.
     */
    public static getVisualBodyCenterY(surfaceY: number, z: number): number {
        // HOVER_LIFT is historically 6, we can keep it hardcoded here or move to constant if needed
        // For now, let's align it with UNIT_HOVER_OFFSET
        return surfaceY - z - UNIT_BODY_OFFSET - UNIT_HOVER_OFFSET;
    }

    /**
     * 獲取單位的「核心錨點」(通常是胸口)
     * 用於投射物命中、雷射連接
     */
    public static getUnitAnchor(agent: Agent, engine: GameEngine, grid: GridSystem | null = null): Point3D {
        const terrainH = grid 
            ? grid.getTerrainHeight(agent.q, agent.r, engine) 
            : engine.map.getTerrainHeight(agent.q, agent.r);

        // 胸口高度計算：基礎偏移 + 物理高度 + 模型高度的 40%
        const chestHeight = (UNIT_VISUAL_HEIGHT * 0.45) * UNIT_SCALE;
        const z = terrainH + agent.physics.z + UNIT_BODY_OFFSET + UNIT_HOVER_OFFSET + chestHeight;

        return { x: agent.px, y: agent.py, z: z };
    }

    /**
     * 獲取單位的「腳底錨點」
     * 用於地面法陣、影子、傳送門
     */
    public static getUnitFeet(agent: Agent, engine: GameEngine): Point3D {
        const terrainH = engine.map.getTerrainHeight(agent.q, agent.r);
        return { x: agent.px, y: agent.py, z: terrainH + agent.physics.z + 2 }; // +2 解決穿插
    }

    public static getHexCenter(q: number, r: number, engine: GameEngine): Point3D {
        const p = HexUtils.toPx(q, r, engine.mapConfig);
        const h = engine.map.getTerrainHeight(q, r);
        return { x: p.x, y: p.y, z: h + 2 }; // 地面特效默認抬高 2px 避免 Z-fighting
    }

    public static resolveTargetPoint(targetId: string, engine: GameEngine): Point3D {
        if (!targetId) return { x: 0, y: 0, z: -9999 };

        const agent = engine.agents.find(a => a.id === targetId);
        if (agent) {
            return this.getUnitAnchor(agent, engine);
        }

        if (targetId.startsWith("ground-")) {
            const parts = targetId.split("-")[1].split(",");
            if (parts.length === 2) {
                const q = parseInt(parts[0]);
                const r = parseInt(parts[1]);
                return this.getHexCenter(q, r, engine);
            }
        }

        return { x: 0, y: 0, z: -9999 };
    }
}

import { Agent, GameEngine } from "../../game";
import { Projectile, Skill } from "../../../types";
import { HexUtils, Vector } from "../../utils";
import { SkillExecutor } from "./SkillExecutor";
import { PROJECTILE_VISUALS } from "../../../data/vfx/projectile_visuals";
import { VisualMath } from "../../math/VisualMath";
import { HazardManager } from "./HazardManager";
import { VISUAL_ANCHORS } from "../../../constants";

export class ProjectileSystem {
    public projectiles: Projectile[] = [];

    public reset() {
        this.projectiles = [];
    }

    public update(dt: number, engine: GameEngine, skillExecutor: SkillExecutor) {
        for (let i = this.projectiles.length - 1; i >= 0; i--) {
            const p = this.projectiles[i];

            // 1. HARD TIMEOUT: Projectiles should never live longer than 5s
            if (!p.id.includes('-')) p.id += `-${engine.battleTime}`; // Metadata for tracking
            const creationTime = parseFloat(p.id.split('-')[1]) || 0;
            if (engine.battleTime - creationTime > 5.0) {
                this.removeProjectile(i);
                continue;
            }

            // 2. Resolve Visual Definition
            const def = PROJECTILE_VISUALS[p.skill.visualProjectileEffect || p.skill.visual || 'BOLT'];
            const isInstant = def ? def.trajectory === 'INSTANT' : false;

            // 3. Update Target Position (Robust Resolution)
            const currentTargetPos = VisualMath.resolveTargetPoint(p.targetId, engine);

            // BUG FIX: Maintain trajectory if target vanishes
            if (currentTargetPos.x !== 0 || currentTargetPos.y !== 0) {
                p.targetPos = { x: currentTargetPos.x, y: currentTargetPos.y };
            }

            // 4. Movement Logic
            const dist = Vector.dist({x: p.x, y: p.y}, p.targetPos);
            const speed = isInstant ? 5000 : Math.max(300, p.speed); 
            const moveDist = speed * dt;

            // 5. Update Trail
            const lastTrail = p.trail.length > 0 ? p.trail[p.trail.length - 1] : null;
            if (!lastTrail || Vector.dist(lastTrail, {x: p.x, y: p.y}) > 15) {
                p.trail.push({x: p.x, y: p.y});
                if (p.trail.length > 20) p.trail.shift(); 
            }

            // 6. Hit Detection - Using Centralized Constant
            if (dist <= moveDist || dist < VISUAL_ANCHORS.HITBOX_RADIUS) {
                this.handleImpact(p, engine, skillExecutor);
                this.removeProjectile(i);
            } else {
                const dir = Vector.normalize(Vector.sub(p.targetPos, {x: p.x, y: p.y}));
                p.x += dir.x * moveDist;
                p.y += dir.y * moveDist;
            }
        }
    }

    private handleImpact(p: Projectile, engine: GameEngine, skillExecutor: SkillExecutor) {
        const source = engine.agents.find(a => a.id === p.sourceId);

        if (p.skill.type === 'AOE') {
            const hitPos = p.targetPos; 
            const radius = p.skill.aoeRadius || 1;
            const hitHex = HexUtils.fromPx(hitPos.x, hitPos.y, engine.mapConfig);

            const targets = engine.agents.filter(e => 
                e.team !== p.team && e.hp > 0 && !e.banished && 
                HexUtils.dist(hitHex, e) <= radius
            );

            targets.forEach(t => { 
                if (source) skillExecutor.resolveHit(source, t, p.skill, hitPos, engine); 
            });

            if (source) {
                const centerHex = HexUtils.fromPx(hitPos.x, hitPos.y, engine.mapConfig);
                HazardManager.spawnHazards(source, HexUtils.range(centerHex, radius), p.skill, engine);
            }
            engine.events.push({ type: 'IMPACT_AOE', pos: hitPos, skill: p.skill, color: p.skill.color });
        } else {
            const target = engine.agents.find(a => a.id === p.targetId);
            if (target && target.hp > 0 && !target.banished) {
                if (source) skillExecutor.resolveHit(source, target, p.skill, undefined, engine);
            }
        }
        engine.events.push({ type: 'PROJECTILE_HIT', pos: p.targetPos, skill: p.skill });
    }

    private removeProjectile(idx: number) {
        const lastIdx = this.projectiles.length - 1;
        if (idx !== lastIdx) this.projectiles[idx] = this.projectiles[lastIdx];
        this.projectiles.pop();
    }

    public spawnProjectile(source: Agent, skill: Skill, engine: GameEngine) {
        let targetId = "";
        let targetPos = {x: 0, y: 0};

        if (skill.type === 'AOE') {
             if (source.targetHex) {
                 const p = HexUtils.toPx(source.targetHex.q, source.targetHex.r, engine.mapConfig);
                 targetPos = p; 
                 targetId = `ground-${source.targetHex.q},${source.targetHex.r}`;
             } else if (source.target) {
                 targetPos = {x: source.target.px, y: source.target.py}; 
                 targetId = source.target.id;
             } else return;
        } else {
            if (source.target && !source.target.banished && source.target.hp > 0) {
                targetPos = {x: source.target.px, y: source.target.py};
                targetId = source.target.id;
            } else return;
        }

        const launchPoint = VisualMath.getUnitAnchor(source, engine);
        this.projectiles.push({
            id: Math.random().toString(36).substr(2, 6),
            x: source.px, y: source.py, 
            startX: source.px, startY: source.py, 
            startZ: launchPoint.z, 
            targetId, 
            targetPos,
            speed: skill.projectileSpeed || 600, 
            skill, 
            sourceId: source.id, 
            team: source.team, 
            trail: []
        });
        engine.events.push({ type: 'PROJECTILE_SPAWN', pos: {x: source.px, y: source.py}, skill: skill, targetId: targetId });
    }
}

import { Agent } from "../../../../game";
import { Team, AnimState, MovementType } from "../../../../../types";
import { UNIT_SCALE } from "../../../../../constants";
import { ImperialRenderer } from "../factions/ImperialRenderer";
import { CovenantRenderer } from "../factions/CovenantRenderer";
import { UnitFlightPainter } from "./UnitFlightPainter";
import { SpriteManager } from "../../../sprites";
import { VisualMath } from "../../../math/VisualMath";

export const UnitBodyPainter = {
    draw(
        ctx: CanvasRenderingContext2D, 
        agent: Agent, 
        px: number, py: number, pz: number, 
        t: number, 
        isSilhouette: boolean, 
        isSelected: boolean,
        scaleFactor: number
    ) {
        ctx.save(); 

        // 1. Transform to Body Center (Standard Anchor via VisualMath)
        // Note: py here is Surface Y (Top of block)
        const bodyY = VisualMath.getVisualBodyCenterY(py, pz);

        ctx.translate(px, bodyY); 

        // --- SCALE ADJUSTMENT ---
        // Apply global scale factor here to shrink the entire unit body composition
        ctx.scale(UNIT_SCALE, UNIT_SCALE);

        ctx.rotate(agent.physics.angle); 

        // 2. Animation Bobbing / Floating
        let bodyFloat = 0; 
        if (agent.hp > 0 && agent.movementType !== MovementType.FLYING) {
             bodyFloat = Math.sin(t * 2) * 3; 
        } else if (agent.movementType === MovementType.FLYING) {
             bodyFloat = Math.sin(t * 4) * 2;
        }
        ctx.translate(0, bodyFloat);

        // 3. Spawn Animation
        if (agent.spawnTimer > 0) {
            const SPAWN_DURATION = 0.5; 
            const progress = 1 - (agent.spawnTimer / SPAWN_DURATION); 
            const eased = 1 - Math.pow(1 - progress, 3); 
            ctx.scale(1, 2.0 - eased); 
            ctx.globalAlpha *= eased;
        }

        // 4. Status Filters
        if (agent.hp <= 0 && !isSilhouette) {
            ctx.filter = 'grayscale(100%) opacity(80%)'; 
        } else if (!isSilhouette && agent.hitFlashTimer > 0) {
             ctx.filter = 'brightness(200%)';
        }

        // 5. Flight VFX
        if (agent.movementType === MovementType.FLYING && agent.hp > 0 && !isSilhouette && agent.visualStatus === 'NONE') {
            UnitFlightPainter.drawFlightVFX(ctx, agent, t);
        }

        // 6. Facing Flip
        ctx.scale(agent.facing > 0 ? 1 : -1, 1);

        // 7. Render Strategy
        if (isSilhouette) {
            ctx.globalCompositeOperation = 'source-over'; 
            ctx.globalAlpha = 0.8; 
        }

        if (agent.visualStatus === 'POLYMORPH') {
            const sheep = SpriteManager.getSpecialModel('SHEEP');
            const bounce = Math.abs(Math.sin(t * 5) * 5);
            ctx.drawImage(sheep, -32, -32 - bounce, 64, 64);
        } else {
            // Faction Specific Renderers
            if (agent.team === Team.BLUE) {
                ImperialRenderer.draw(ctx, agent, t, isSilhouette);
            } else {
                CovenantRenderer.draw(ctx, agent, t, isSilhouette);
            }

            // Note: Casting VFX removed from here. Now handled in UnitShadowPainter (Ground Layer).

            // Frozen State Overlay
            if (agent.visualStatus === 'FROZEN') {
                const ice = SpriteManager.getSpecialModel('ICE');
                ctx.save();
                ctx.globalCompositeOperation = 'hard-light';
                ctx.drawImage(ice, -48, -64, 96, 128);
                ctx.restore();
            }
        }

        ctx.restore(); 
    }
};

import { Agent } from "../../../game";
import { Team } from "../../../../types";
import { UNIT_SCALE, VISUAL_ANCHORS } from "../../../../constants";
import { FACTION_VISUALS } from "../../../../data/vfx/faction_visuals";
import { VisualMath } from "../../../math/VisualMath";

export const UnitFlightPainter = {

    drawFlyingAnchor(ctx: CanvasRenderingContext2D, agent: Agent, t: number, physX: number, physY: number, physZ: number) {
        // Deprecated
    },

    drawFlightVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
        // This is called within the UnitBodyPainter's transformed context (Body Center)
        const faction = FACTION_VISUALS[agent.team] || FACTION_VISUALS[Team.BLUE];
        const color = faction.flightTrailColor;

        ctx.save();
        ctx.translate(0, VISUAL_ANCHORS.ENGINE_OFFSET_Y); // Use Standard Constant

        // Engine Glows (Oscillating)
        const pulse = 0.8 + Math.sin(t * 20) * 0.2;

        ctx.globalCompositeOperation = 'screen';
        ctx.fillStyle = color;
        ctx.shadowColor = color;
        ctx.shadowBlur = 10;

        // Left Engine
        ctx.beginPath(); ctx.arc(-12, 0, 4 * pulse, 0, Math.PI*2); ctx.fill();
        // Right Engine
        ctx.beginPath(); ctx.arc(12, 0, 4 * pulse, 0, Math.PI*2); ctx.fill();

        ctx.restore();
    },

    /**
     * Called from UnitShadowPainter or a dedicated pass to draw World Space trails.
     * Uses the agent's trailHistory.
     */
    drawRibbonTrail(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
        if (agent.trailHistory.length < 2) return;

        const faction = FACTION_VISUALS[agent.team] || FACTION_VISUALS[Team.BLUE];
        const color = faction.flightTrailColor;

        ctx.save();
        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';

        const currentPx = agent.px;
        const currentPy = agent.py; // Ground Y

        const points: {x: number, y: number}[] = [];

        for (const p of agent.trailHistory) {
            // Reconstruct visual Y using SSOT Math
            const vy = VisualMath.getVisualBodyCenterY(p.y, p.z) + VISUAL_ANCHORS.ENGINE_OFFSET_Y;
            points.push({ x: p.x, y: vy });
        }

        // Add current pos
        const currVy = VisualMath.getVisualBodyCenterY(currentPy, agent.physics.z) + VISUAL_ANCHORS.ENGINE_OFFSET_Y;
        points.push({ x: currentPx, y: currVy });

        if (points.length < 2) { ctx.restore(); return; }

        ctx.beginPath();

        for (let i = 0; i < points.length; i++) {
            const p = points[i];
            // Render relative to current position (assuming ctx is translated to current Visual Y by caller logic, OR calculate absolute if cleaner)
            // Note: UnitShadowPainter calls this but its context is translated to SurfaceY.
            // But we calculated absolute visual Ys in points[].
            // To draw correctly relative to UnitBodyPainter's context, we need deviations.
            // Actually, `UnitShadowPainter` doesn't call this anymore? 
            // If it did, it would be weird. 
            // Assuming this is called via `UnitBodyPainter` which is centered on Body.
            // If centered on Body, current pos is (0, ENGINE_OFFSET).
            // We need to inverse project history points.

            const dx = p.x - currentPx;
            const dy = p.y - currVy;

            // Draw relative to Engine Offset
            const engineY = VISUAL_ANCHORS.ENGINE_OFFSET_Y;

            if (i === 0) ctx.moveTo(dx, engineY + dy);
            else ctx.lineTo(dx, engineY + dy);
        }

        ctx.strokeStyle = color;
        ctx.lineWidth = 4 * UNIT_SCALE;
        ctx.globalAlpha = 0.4;
        ctx.shadowColor = color;
        ctx.shadowBlur = 10;
        ctx.stroke();

        // Inner Core
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 1 * UNIT_SCALE;
        ctx.globalAlpha = 0.8;
        ctx.shadowBlur = 0;
        ctx.stroke();

        ctx.restore();
    }
};

import { Agent } from "../../../../game";
import { AssetManager } from "../../../assets";
import { STATUS_VISUALS } from "../../../../../data/vfx/status_visuals";
import { VisualMath } from "../../../math/VisualMath";
import { VISUAL_ANCHORS } from "../../../../../constants";

export const OverheadPainter = {
    // x, y = Visual Surface Coordinates (Top of Block)
    // z = Jump Height
    draw(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number, z: number, t: number) {
        // Priority System: Only show most severe CC
        let type = '';
        if (agent.stunTimer > 0) type = 'STUN';
        else if (agent.fearTimer > 0) type = 'FEAR';
        else if (agent.tauntTimer > 0) type = 'TAUNT';
        else if (agent.silenceTimer > 0) type = 'SILENCE';
        else if (agent.blindTimer > 0) type = 'BLIND';

        if (!type) return;

        const icon = AssetManager.getStatusIcon(type);
        if (!icon) return;

        // Bobbing Animation
        const bob = Math.sin(t * 6) * 5;

        // --- ANCHOR LOGIC FIX (SSOT) ---
        const unitHeadY = VisualMath.getVisualBodyCenterY(y, z);
        const anchorY = unitHeadY - VISUAL_ANCHORS.HEAD_OFFSET_Y + bob; 

        ctx.save();
        ctx.translate(x, anchorY);

        // Glow Backing
        const def = STATUS_VISUALS[type];
        const color = def?.primaryColor || '#fff';

        ctx.shadowColor = color;
        ctx.shadowBlur = 15;

        // Draw Icon
        ctx.drawImage(icon, -24, -24, 48, 48);

        // Extra "Dizzy" stars for Stun
        if (type === 'STUN') {
            ctx.rotate(t * 2);
            ctx.fillStyle = '#fff';
            for(let i=0; i<3; i++) {
                const a = i * (Math.PI*2/3);
                const sx = Math.cos(a) * 20;
                const sy = Math.sin(a) * 20;
                ctx.beginPath(); ctx.arc(sx, sy, 3, 0, Math.PI*2); ctx.fill();
            }
        }

        ctx.restore();
    }
};

import { Agent } from "../../../../game";
import { Team } from "../../../../../types";
import { VolumePainter } from "../../../graphics/painters/VolumePainter";
import { VisualMath } from "../../../math/VisualMath";

export const ShieldPainter = {
    // x, y = Visual Surface Coordinates (Top of Block)
    draw(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number, z: number, t: number) {
        if (agent.shield <= 0) return;

        const isBlue = agent.team === Team.BLUE;
        const color = isBlue ? '#bae6fd' : '#f87171'; // Cyan vs Red tint

        // Shield Pulse based on % remaining
        const pct = Math.min(1, agent.shield / (agent.maxShield || 100));
        const pulse = 0.2 + (pct * 0.3) + Math.sin(t * 3) * 0.1;

        ctx.save();

        // ALIGNMENT FIX (SSOT)
        const bodyCenterY = VisualMath.getVisualBodyCenterY(y, z);

        ctx.translate(x, bodyCenterY); 

        // Volumetric Prism Shell around body
        // Height 90 covers most standard units. Prism draws downwards from current Y.
        // To center it, we draw from (y - half_height) = (0 + 45) -> Top (-45)
        VolumePainter.draw3DPrism(ctx, 0, 45, 35, 90, color, pulse, 'SOLID'); 

        // Inner Core Ripple (Tech Ring)
        ctx.globalCompositeOperation = 'screen';
        ctx.globalAlpha = 0.4;

        ctx.strokeStyle = color;
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.ellipse(0, 0, 25, 12, 0, 0, Math.PI*2);
        ctx.stroke();

        // Vertical Energy Line
        ctx.beginPath();
        ctx.moveTo(0, -40); ctx.lineTo(0, 40);
        ctx.lineWidth = 1;
        ctx.stroke();

        ctx.restore();
    }
};

import { Agent } from "../../../../game";
import { AssetManager } from "../../../assets";
import { VisualMath } from "../../../math/VisualMath";

export const StateModelPainter = {
    drawBanishment(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number, z: number, t: number) {
        if (!agent.banished) return;

        const isStasis = agent.visualStatus === 'STASIS';
        const color = isStasis ? '#facc15' : '#c084fc'; 
        const secondaryColor = isStasis ? '#fef08a' : '#e9d5ff';

        // ALIGNMENT FIX (SSOT)
        const centerY = VisualMath.getVisualBodyCenterY(y, z);

        ctx.save();
        ctx.translate(x, centerY);

        const size = 55; // Slightly larger
        const height = 75;
        const rotation = t * 0.8;

        const points = [];
        for(let i=0; i<4; i++) {
            const angle = rotation + (i * Math.PI / 2);
            points.push({
                x: Math.cos(angle) * size,
                y: Math.sin(angle) * size * 0.35 
            });
        }

        const drawFace = (p1: {x:number, y:number}, p2: {x:number, y:number}, tipY: number, alpha: number) => {
            ctx.beginPath();
            ctx.moveTo(p1.x, p1.y);
            ctx.lineTo(p2.x, p2.y);
            ctx.lineTo(0, tipY);
            ctx.closePath();

            ctx.fillStyle = color;
            ctx.globalAlpha = alpha; // Increased from 0.15 to 0.3 for more "mass"
            ctx.fill();

            ctx.strokeStyle = secondaryColor;
            ctx.globalAlpha = 0.9;
            ctx.stroke();
        };

        const bob = Math.sin(t * 2) * 5;
        ctx.translate(0, bob);

        for(let i=0; i<4; i++) {
            const p1 = points[i];
            const p2 = points[(i+1)%4];
            drawFace(p1, p2, -height, 0.3); // Upper
        }
        for(let i=0; i<4; i++) {
            const p1 = points[i];
            const p2 = points[(i+1)%4];
            drawFace(p1, p2, height, 0.2); // Lower
        }

        ctx.globalCompositeOperation = 'screen';
        const pulse = 1.0 + Math.sin(t * 5) * 0.2;

        const icon = AssetManager.getStatusIcon(isStasis ? 'STASIS' : 'BANISH');
        if (icon) {
            ctx.save();
            ctx.scale(pulse, pulse);
            ctx.globalAlpha = 1.0; // Solid icon
            ctx.drawImage(icon, -24, -24, 48, 48);
            ctx.restore();
        }

        ctx.restore();
    }
};

import { Team, Role } from "../../../../types";
