        impulseX: number, impulseY: number
    ) {
        const faction = FACTION_VISUALS[team] || FACTION_VISUALS[Team.BLUE];
        const assets = SpriteManager.getUnitImages(role, team);

        // 1. 強度係數：根據死前衝擊調整爆炸動能
        const force = 1.5;
        const dirX = impulseX !== 0 ? Math.sign(impulseX) : (Math.random() - 0.5);
        const dirY = impulseY !== 0 ? Math.sign(impulseY) : (Math.random() - 0.5);

        // 2. 模型解體 - 底座 (重型部件)
