        pBase.vz = 100 + Math.random() * 100;
        pBase.gravity = 3500;
        pBase.vRotation = (Math.random() - 0.5) * 2;
        pBase.life = 4.0; pBase.maxLife = 4.0;
        system.state.particles.push(pBase);

        // 3. 模型解體 - 職階圖標 (輕型部件)
        const pIcon = system.state.getParticle();
        pIcon.x = x; pIcon.y = y; pIcon.z = z;
        pIcon.image = assets.icon;
        pIcon.type = 'SPRITE';
        pIcon.size = 48 * UNIT_SCALE;
        pIcon.vx = (dirX * 300 + (Math.random() - 0.5) * 200) * force;
        pIcon.vy = (dirY * 300 + (Math.random() - 0.5) * 200) * force;
        pIcon.vz = 400 + Math.random() * 300;
