import { Agent } from "../../../game";
import { AnimState, Role } from "../../../../types";
import { getCastProgress } from "../utils";
import { THEME_IMPERIAL } from "../../../../constants";

/**
 * 藍軍 (Imperial) 渲染器 v9.2
 * 已清理廢棄的 procedural 運算，改用純向量路徑與快取材質
 */
export const ImperialRenderer = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean) {
        // 1. 標準化動態參數
        const progress = agent.animState === AnimState.ATTACK ? getCastProgress(agent) : 0;
        const isHit = agent.hitFlashTimer > 0;

        // 2. 應用受擊變形 (Squash & Stretch)
        if (isHit) {
            const trauma = agent.hitFlashTimer * 5;
            ctx.scale(1 + trauma * 0.1, 1 - trauma * 0.2);
            ctx.rotate((Math.random() - 0.5) * 0.1);
        }

        // 3. 繪製組件 (Back to Front)
        this.drawCape(ctx, agent, t, progress);
        this.drawMainBody(ctx, agent.role, isSilhouette);
        this.drawEquipment(ctx, agent, t, progress);
    },

    drawMainBody(ctx: CanvasRenderingContext2D, role: Role, isSil: boolean) {
        const { primary, secondary, armorLight, armorDark } = THEME_IMPERIAL;
        ctx.save();
        ctx.translate(0, -35); // 角色基準高度

        if (isSil) {
            ctx.fillStyle = THEME_IMPERIAL.energy;
            ctx.globalAlpha = 0.5;
        } else {
            const grad = ctx.createLinearGradient(-15, -15, 15, 15);
            grad.addColorStop(0, armorLight);
            grad.addColorStop(0.5, armorDark);
            grad.addColorStop(1, primary);
            ctx.fillStyle = grad;
        }

        ctx.strokeStyle = secondary;
        ctx.lineWidth = 1.5;

        // 身體幾何圖形 (根據角色簡化)
        ctx.beginPath();
        if (role === Role.TANK) {
            ctx.moveTo(-22, -10); ctx.lineTo(22, -10); ctx.lineTo(15, 35); ctx.lineTo(-15, 35);
        } else {
            ctx.moveTo(-18, -10); ctx.lineTo(18, -10); ctx.lineTo(10, 40); ctx.lineTo(-10, 40);
        }
        ctx.closePath();
        ctx.fill();
        if (!isSil) ctx.stroke();

        // 頭部
        ctx.fillStyle = armorLight;
        ctx.beginPath();
        ctx.arc(0, -15, 10, 0, Math.PI * 2);
        ctx.fill();
        if (!isSil) ctx.stroke();

        ctx.restore();
    },

    drawCape(ctx: CanvasRenderingContext2D, agent: Agent, t: number, progress: number) {
        ctx.save();
        ctx.translate(0, -45);
        const wind = Math.sin(t * 3) * 5;
        const recoil = progress * -15;

        ctx.fillStyle = THEME_IMPERIAL.cape;
        ctx.beginPath();
        ctx.moveTo(-12, 0);
        ctx.quadraticCurveTo(-20 + wind + recoil, 25, -15 + wind + recoil, 50);
        ctx.lineTo(15 + wind + recoil, 50);
        ctx.quadraticCurveTo(20 + wind + recoil, 25, 12, 0);
        ctx.fill();
        ctx.restore();
    },

    drawEquipment(ctx: CanvasRenderingContext2D, agent: Agent, t: number, progress: number) {
        ctx.save();
        const role = agent.role;
        const attackAngle = progress * Math.PI * 0.8;

        // 左手/副手 (盾牌或卷軸)
        ctx.save();
        ctx.translate(-22, -30);
        if (role === Role.TANK) this.drawShield(ctx);
        else if (role === Role.SUPPORT) this.drawRelic(ctx, t);
        ctx.restore();

        // 右手/武器 (劍、弓、杖)
        ctx.save();
        ctx.translate(22, -30);
        ctx.rotate(attackAngle);
        this.drawWeapon(ctx, role);
        ctx.restore();

        ctx.restore();
    },

    drawShield(ctx: CanvasRenderingContext2D) {
        ctx.fillStyle = THEME_IMPERIAL.armorLight;
        ctx.strokeStyle = THEME_IMPERIAL.secondary;
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(-10, -20); ctx.lineTo(10, -20); ctx.lineTo(12, 10); ctx.lineTo(0, 25); ctx.lineTo(-12, 10);
        ctx.closePath();
        ctx.fill();
        ctx.stroke();
    },

    drawRelic(ctx: CanvasRenderingContext2D, t: number) {
        const hover = Math.sin(t * 4) * 3;
        ctx.translate(0, hover);
        ctx.fillStyle = THEME_IMPERIAL.energy;
        ctx.shadowBlur = 10;
        ctx.shadowColor = THEME_IMPERIAL.energy;
        ctx.beginPath();
        ctx.arc(0, 0, 8, 0, Math.PI * 2);
        ctx.fill();
    },

    drawWeapon(ctx: CanvasRenderingContext2D, role: Role) {
        ctx.strokeStyle = THEME_IMPERIAL.secondary;
        ctx.lineWidth = 3;
        ctx.lineCap = 'round';

        if (role === Role.WARRIOR) {
            // 能量劍
            ctx.fillStyle = THEME_IMPERIAL.energy;
            ctx.beginPath();
            ctx.moveTo(0, 5); ctx.lineTo(0, -60); ctx.lineTo(6, -55); ctx.lineTo(4, 5);
            ctx.fill();
            ctx.stroke();
        } else if (role === Role.RANGER) {
            // 弓
            ctx.beginPath();
            ctx.arc(0, 0, 30, -Math.PI/2 - 0.5, Math.PI/2 + 0.5);
            ctx.stroke();
        } else if (role === Role.MAGE) {
            // 杖
            ctx.strokeStyle = '#4b2c20';
            ctx.beginPath(); ctx.moveTo(0, 40); ctx.lineTo(0, -40); ctx.stroke();
            ctx.fillStyle = THEME_IMPERIAL.energy;
            ctx.beginPath(); ctx.arc(0, -45, 10, 0, Math.PI*2); ctx.fill();
        }
    }
};

import { Agent } from "../../../game";
import { AnimState, Role } from "../../../../types";
import { getCastProgress } from "../utils";
import { THEME_COVENANT } from "../../../../constants";

/**
 * 紅軍 (Covenant) 渲染器 v9.2
 * 強化了視覺衝擊力，移除廢棄路徑
 */
export const CovenantRenderer = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean) {
        const progress = agent.animState === AnimState.ATTACK ? getCastProgress(agent) : 0;
        const isHit = agent.hitFlashTimer > 0;

        if (isHit) {
            const trauma = agent.hitFlashTimer * 8;
            ctx.translate((Math.random() - 0.5) * trauma, 0);
            ctx.scale(1 + trauma * 0.15, 1 - trauma * 0.1);
        }

        this.drawSpikes(ctx, t);
        this.drawMainBody(ctx, agent.role, isSilhouette);
        this.drawEquipment(ctx, agent, t, progress);
    },

    drawMainBody(ctx: CanvasRenderingContext2D, role: Role, isSil: boolean) {
        const { primary, secondary, armorDark, armorBase, accent } = THEME_COVENANT;
        ctx.save();
        ctx.translate(0, -35);

        if (isSil) {
            ctx.fillStyle = secondary;
            ctx.globalAlpha = 0.5;
        } else {
            const grad = ctx.createLinearGradient(-15, -20, 15, 20);
            grad.addColorStop(0, primary);
            grad.addColorStop(0.7, armorDark);
            grad.addColorStop(1, '#000');
            ctx.fillStyle = grad;
        }

        ctx.strokeStyle = accent;
        ctx.lineWidth = 1;

        // 粗獷的身體形狀
        ctx.beginPath();
        if (role === Role.TANK) {
            ctx.moveTo(-25, -15); ctx.lineTo(25, -15); ctx.lineTo(18, 35); ctx.lineTo(-18, 35);
        } else {
            ctx.moveTo(-15, -15); ctx.lineTo(15, -15); ctx.lineTo(12, 45); ctx.lineTo(-12, 45);
        }
        ctx.closePath();
        ctx.fill();
        if (!isSil) ctx.stroke();

        // 骨質面具
        ctx.fillStyle = '#fca5a5';
        ctx.beginPath();
        ctx.moveTo(-8, -12); ctx.lineTo(8, -12); ctx.lineTo(0, 0);
        ctx.fill();

        ctx.restore();
    },

    drawSpikes(ctx: CanvasRenderingContext2D, t: number) {
        ctx.save();
        ctx.translate(0, -40);
        ctx.fillStyle = THEME_COVENANT.spike;
        const wave = Math.sin(t * 5) * 2;

        ctx.beginPath();
        ctx.moveTo(-10, 0); ctx.lineTo(-25, -30 + wave); ctx.lineTo(-15, 0);
        ctx.moveTo(10, 0); ctx.lineTo(20, -25 - wave); ctx.lineTo(15, 0);
        ctx.fill();
        ctx.restore();
    },

    drawEquipment(ctx: CanvasRenderingContext2D, agent: Agent, t: number, progress: number) {
        ctx.save();
        const role = agent.role;
        const attackAngle = progress * Math.PI * 1.1; // 更狂野的揮擊角度

        // 副手
        ctx.save();
        ctx.translate(-22, -25);
        if (role === Role.TANK) this.drawShield(ctx);
        else if (role === Role.SUPPORT) this.drawTotem(ctx, t);
        ctx.restore();

        // 主手
        ctx.save();
        ctx.translate(22, -25);
        ctx.rotate(attackAngle);
        this.drawWeapon(ctx, role);
        ctx.restore();

        ctx.restore();
    },

    drawShield(ctx: CanvasRenderingContext2D) {
        ctx.fillStyle = THEME_COVENANT.armorBase;
        ctx.strokeStyle = THEME_COVENANT.secondary;
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(-15, -20); ctx.lineTo(15, -18); ctx.lineTo(20, 10); ctx.lineTo(0, 30); ctx.lineTo(-20, 10);
        ctx.closePath();
        ctx.fill();
        ctx.stroke();
    },

    drawTotem(ctx: CanvasRenderingContext2D, t: number) {
        ctx.fillStyle = '#3f3f46';
        ctx.fillRect(-3, -20, 6, 40);
        ctx.translate(0, -25);
        ctx.rotate(t * 2);
        ctx.fillStyle = THEME_COVENANT.secondary;
        ctx.fillRect(-8, -2, 16, 4);
        ctx.fillRect(-2, -8, 4, 16);
    },

    drawWeapon(ctx: CanvasRenderingContext2D, role: Role) {
        ctx.strokeStyle = THEME_COVENANT.secondary;
        ctx.lineWidth = 2;

        if (role === Role.WARRIOR) {
            // 巨斧
            ctx.fillStyle = THEME_COVENANT.accent;
            ctx.beginPath();
            ctx.moveTo(0, 0); ctx.lineTo(-25, -15); ctx.quadraticCurveTo(-15, 10, -25, 35); ctx.lineTo(0, 20);
            ctx.fill(); ctx.stroke();
        } else if (role === Role.RANGER) {
            // 重弩
            ctx.fillStyle = THEME_COVENANT.armorDark;
            ctx.fillRect(-5, -25, 10, 35);
            ctx.beginPath(); ctx.moveTo(-25, -20); ctx.lineTo(25, -20); ctx.stroke();
        } else if (role === Role.MAGE) {
            // 鮮血法杖
            ctx.strokeStyle = '#450a0a';
            ctx.beginPath(); ctx.moveTo(0, 50); ctx.lineTo(0, -40); ctx.stroke();
            ctx.fillStyle = THEME_COVENANT.primary;
            ctx.beginPath(); ctx.arc(0, -45, 6, 0, Math.PI*2); ctx.fill();
        }
    }
};

import { GameEvent } from "../../../../types";
import { VFXSystem } from "../../vfx";
import { CameraSystem } from "../../CameraSystem";
import { Point3D } from "../EventVFXMapper";
import { VFX_REGISTRY } from "../../../../data/vfx/VFXRegistry";
import { Vector } from "../../../utils";

/**
 * 戰鬥視覺處理器 (TA 優化版)
 * 實現精確受擊點噴濺與物理動能傳遞
 */
export class CombatVFXHandler {

    public static handle(event: GameEvent, vfx: VFXSystem, camera: CameraSystem, target: Point3D, groundZ: number) {

        // 1. 傷害事件處理
        if (event.type === 'DAMAGE') {
            const isInstant = !event.skill?.projectileSpeed;
            if (isInstant && event.skill?.ccType !== 'DOT') {
                // 直接攻擊：從攻擊者位置計算噴濺方向
                this.playImpact(event, vfx, target, groundZ);
            } else if (event.skill?.ccType === 'DOT') {
                // 持續傷害：僅在身體中心產生微量火花
                vfx.playEffect('FX_STATUS_BURN_LOOP', target.x, target.y, target.z, event.color);
            }
            return;
        }

        // 2. 投射物命中事件 (關鍵：計算命中動量)
        if (event.type === 'PROJECTILE_HIT') {
            if (event.skill?.type !== 'AOE') {
                // 單體投射物命中：使用 target.z 噴濺
                this.playImpact(event, vfx, target, groundZ);
                camera.addTrauma(0.15); 
            } else {
                // AOE 命中觸發點
                vfx.playEffect('FX_HIT_GENERIC', event.pos.x, event.pos.y, target.z, event.skill?.color, groundZ);
            }
            return;
        }

        // 3. AOE 地面爆發
        if (event.type === 'IMPACT_AOE') {
            const impactPoint = { x: event.pos.x, y: event.pos.y, z: groundZ + 5 };
            this.playImpact(event, vfx, impactPoint, groundZ);
            camera.addTrauma(0.35);
            return;
        }
    }

    private static playImpact(event: GameEvent, vfx: VFXSystem, target: Point3D, groundZ: number) {
        const skill = event.skill;
        const color = event.color || '#fff';

        let effectId = 'FX_HIT_GENERIC';
        if (skill && skill.visualHitEffect && VFX_REGISTRY[skill.visualHitEffect]) {
            effectId = skill.visualHitEffect;
        }

        // TA 重點：注入物理動量
        // 獲取受擊特效定義並手動調整噴濺方向
        vfx.playEffect(effectId, target.x, target.y, target.z, color, groundZ);

        // 追加一組具有物理碰撞的空間碎塊
        const shardCount = 3 + Math.floor(Math.random() * 3);
        for(let i=0; i < shardCount; i++) {
            const p = vfx.state.getParticle();
            p.x = target.x; p.y = target.y; p.z = target.z;

            // 噴濺向量：向上並隨機向四周彈射
            const angle = Math.random() * Math.PI * 2;
            const speed = 100 + Math.random() * 300;
            p.vx = Math.cos(angle) * speed;
            p.vy = Math.sin(angle) * speed;
            p.vz = 200 + Math.random() * 400;

            p.type = 'RUBBLE';
            p.color = color;
            p.size = 3 + Math.random() * 5;
            p.gravity = 3000;
            p.life = 0.5 + Math.random() * 0.8;
            p.maxLife = p.life;
            p.vRotation = (Math.random() - 0.5) * 20;
            vfx.state.particles.push(p);
        }
    }
}

import { Agent } from "../../../game";
import { AnimState, Role } from "../../../../types";
import { getCastProgress } from "../utils";
import { THEME_IMPERIAL } from "../../../../constants";

/**
 * 藍軍 (Imperial) 美術渲染器 v10.0
 * 核心：科技感、神聖光輝、幾何精密
 */
export const ImperialRenderer = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean) {
        const progress = agent.animState === AnimState.ATTACK ? getCastProgress(agent) : 0;
        const isHit = agent.hitFlashTimer > 0;
        const role = agent.role;

        // --- 1. 骨架動態系統 (Skeleton Dynamics) ---
        const breathe = Math.sin(t * 2.5) * 2;
        const attackSwing = Math.sin(progress * Math.PI) * 15;
        const movementTilt = agent.isMoving ? 0.1 : 0;

        ctx.save();

        // 身體整體傾斜 (移動感)
        ctx.rotate(movementTilt * agent.facing);

        // --- 2. 下層裝備 (Back Layer) ---
        this.drawEnergyCape(ctx, t, progress, breathe);

        // --- 3. 軀幹與頭部 (Core Body) ---
        ctx.save();
        ctx.translate(0, breathe); // 呼吸起伏
        this.drawMainBody(ctx, role, isSilhouette, isHit);
        this.drawHelmet(ctx, t, isSilhouette);
        ctx.restore();

        // --- 4. 上層武裝 (Front Layer) ---
        this.drawEquipment(ctx, agent, t, progress, breathe);

        ctx.restore();
    },

    drawMainBody(ctx: CanvasRenderingContext2D, role: Role, isSil: boolean, isHit: boolean) {
        const { primary, armorLight, armorDark } = THEME_IMPERIAL;
        ctx.save();
        ctx.translate(0, -35);

        const bodyGrad = ctx.createLinearGradient(-15, -15, 15, 25);
        bodyGrad.addColorStop(0, isHit ? '#fff' : armorLight);
        bodyGrad.addColorStop(0.5, isHit ? '#fff' : armorDark);
        bodyGrad.addColorStop(1, isHit ? '#fff' : primary);

        ctx.fillStyle = bodyGrad;
        ctx.strokeStyle = THEME_IMPERIAL.energy;
        ctx.lineWidth = 1.5;

        // 梯形胸甲
        ctx.beginPath();
        if (role === Role.TANK) {
            ctx.moveTo(-22, -8); ctx.lineTo(22, -8); ctx.lineTo(16, 30); ctx.lineTo(-16, 30);
        } else {
            ctx.moveTo(-16, -10); ctx.lineTo(16, -10); ctx.lineTo(10, 35); ctx.lineTo(-10, 35);
        }
        ctx.closePath();
        ctx.fill();
        if (!isSil) {
            ctx.globalAlpha = 0.6;
            ctx.stroke();
        }
        ctx.restore();
    },

    drawHelmet(ctx: CanvasRenderingContext2D, t: number, isSil: boolean) {
        ctx.save();
        ctx.translate(0, -52);

        // 頭盔主體
        ctx.fillStyle = THEME_IMPERIAL.armorLight;
        ctx.beginPath();
        ctx.arc(0, 0, 9, 0, Math.PI * 2);
        ctx.fill();

        // 護目鏡發光 (細節補回)
        if (!isSil) {
            ctx.fillStyle = '#fff';
            ctx.shadowBlur = 8;
            ctx.shadowColor = THEME_IMPERIAL.energy;
            ctx.beginPath();
            ctx.ellipse(0, -1, 6, 2, 0, 0, Math.PI * 2);
            ctx.fill();
        }
        ctx.restore();
    },

    drawEnergyCape(ctx: CanvasRenderingContext2D, t: number, progress: number, breathe: number) {
        ctx.save();
        ctx.translate(0, -42 + breathe * 0.5);

        const wave = Math.sin(t * 3) * 5;
        const grad = ctx.createLinearGradient(0, 0, 0, 50);
        grad.addColorStop(0, THEME_IMPERIAL.energy);
        grad.addColorStop(1, 'transparent');

        ctx.fillStyle = grad;
        ctx.globalAlpha = 0.4 + Math.sin(t * 5) * 0.1;
        ctx.beginPath();
        ctx.moveTo(-12, 0);
        ctx.quadraticCurveTo(-25 + wave, 25, -15, 55);
        ctx.lineTo(15, 55);
        ctx.quadraticCurveTo(25 - wave, 25, 12, 0);
        ctx.fill();
        ctx.restore();
    },

    drawEquipment(ctx: CanvasRenderingContext2D, agent: Agent, t: number, progress: number, breathe: number) {
        const role = agent.role;
        const swing = Math.sin(progress * Math.PI);

        // 右手武器
        ctx.save();
        ctx.translate(22, -30 + breathe);
        ctx.rotate(swing * -1.2); // 攻擊揮動

        ctx.shadowBlur = 10;
        ctx.shadowColor = THEME_IMPERIAL.energy;
        this.drawWeapon(ctx, role);
        ctx.restore();

        // 左手防具/副手
        ctx.save();
        ctx.translate(-22, -30 + breathe * 0.8);
        if (role === Role.TANK) this.drawShield(ctx);
        else if (role === Role.SUPPORT) this.drawRelic(ctx, t);
        ctx.restore();
    },

    drawWeapon(ctx: CanvasRenderingContext2D, role: Role) {
        ctx.lineWidth = 3;
        ctx.lineCap = 'round';
        if (role === Role.WARRIOR) {
            // 能量長劍
            ctx.strokeStyle = '#fff';
            ctx.beginPath(); ctx.moveTo(0, 5); ctx.lineTo(0, -55); ctx.stroke();
            ctx.lineWidth = 1; ctx.strokeStyle = THEME_IMPERIAL.energy;
            ctx.strokeRect(-4, -50, 8, 45);
        } else if (role === Role.RANGER) {
            // 科技短弩
            ctx.fillStyle = THEME_IMPERIAL.armorDark;
            ctx.fillRect(-8, -20, 16, 25);
            ctx.strokeStyle = THEME_IMPERIAL.energy;
            ctx.beginPath(); ctx.moveTo(-20, -15); ctx.lineTo(20, -15); ctx.stroke();
        } else if (role === Role.MAGE) {
            // 浮空法杖
            ctx.strokeStyle = THEME_IMPERIAL.armorLight;
            ctx.beginPath(); ctx.moveTo(0, 30); ctx.lineTo(0, -35); ctx.stroke();
            ctx.fillStyle = THEME_IMPERIAL.energy;
            ctx.beginPath(); ctx.arc(0, -45, 10, 0, Math.PI*2); ctx.fill();
        }
    },

    drawShield(ctx: CanvasRenderingContext2D) {
        ctx.fillStyle = THEME_IMPERIAL.armorLight;
        ctx.strokeStyle = THEME_IMPERIAL.secondary;
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(-12, -22); ctx.lineTo(12, -22); ctx.lineTo(15, 10); ctx.lineTo(0, 28); ctx.lineTo(-15, 10);
        ctx.closePath();
        ctx.fill();
        ctx.stroke();
        // 護盾中心燈光
        ctx.fillStyle = THEME_IMPERIAL.energy;
        ctx.beginPath(); ctx.arc(0, 0, 4, 0, Math.PI*2); ctx.fill();
    },

    drawRelic(ctx: CanvasRenderingContext2D, t: number) {
        const rot = t * 2;
        ctx.save();
        ctx.rotate(rot);
        ctx.fillStyle = THEME_IMPERIAL.energy;
        ctx.shadowBlur = 15;
        ctx.shadowColor = THEME_IMPERIAL.energy;
        ctx.beginPath();
        for(let i=0; i<4; i++) {
            const a = i * Math.PI / 2;
            ctx.lineTo(Math.cos(a)*10, Math.sin(a)*10);
        }
        ctx.closePath();
        ctx.fill();
        ctx.restore();
    }
};

import { Agent } from "../../../game";
import { AnimState, Role } from "../../../../types";
import { getCastProgress } from "../utils";
import { THEME_COVENANT } from "../../../../constants";

/**
 * 紅軍 (Covenant) 美術渲染器 v10.0
 * 核心：野蠻、混沌、鮮血能量、尖刺幾何
 */
export const CovenantRenderer = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean) {
        const progress = agent.animState === AnimState.ATTACK ? getCastProgress(agent) : 0;
        const isHit = agent.hitFlashTimer > 0;

        // --- 1. 骨架動態系統 ---
        const rageShake = agent.hp < agent.maxHp * 0.3 ? (Math.random() - 0.5) * 2 : 0;
        const breathe = Math.sin(t * 3.5) * 3; // 更急促的呼吸
        const attackLunge = progress * 20;

        ctx.save();
        ctx.translate(rageShake, 0);

        // --- 2. 下層細節 (Spikes & Aura) ---
        this.drawBackSpikes(ctx, t, breathe);

        // --- 3. 軀幹與頭部 ---
        ctx.save();
        ctx.translate(attackLunge * agent.facing, breathe);
        this.drawMainBody(ctx, agent.role, isSilhouette, isHit);
        this.drawBeastMask(ctx, t, isSilhouette);
        ctx.restore();

        // --- 4. 武裝 ---
        this.drawWarpWeaponry(ctx, agent, t, progress, breathe);

        ctx.restore();
    },

    drawMainBody(ctx: CanvasRenderingContext2D, role: Role, isSil: boolean, isHit: boolean) {
        const { primary, armorDark, armorBase, accent } = THEME_COVENANT;
        ctx.save();
        ctx.translate(0, -35);

        const bodyGrad = ctx.createLinearGradient(-15, -20, 15, 20);
        bodyGrad.addColorStop(0, isHit ? '#fff' : armorBase);
        bodyGrad.addColorStop(0.6, isHit ? '#fff' : armorDark);
        bodyGrad.addColorStop(1, isHit ? '#fff' : primary);

        ctx.fillStyle = bodyGrad;
        ctx.strokeStyle = accent;
        ctx.lineWidth = 1;

        // 粗獷的五邊形胸甲
        ctx.beginPath();
        if (role === Role.TANK) {
            ctx.moveTo(-24, -12); ctx.lineTo(24, -12); ctx.lineTo(20, 35); ctx.lineTo(0, 42); ctx.lineTo(-20, 35);
        } else {
            ctx.moveTo(-18, -15); ctx.lineTo(18, -15); ctx.lineTo(12, 45); ctx.lineTo(0, 50); ctx.lineTo(-12, 45);
        }
        ctx.closePath();
        ctx.fill();
        if (!isSil) ctx.stroke();

        ctx.restore();
    },

    drawBeastMask(ctx: CanvasRenderingContext2D, t: number, isSil: boolean) {
        ctx.save();
        ctx.translate(0, -55);

        // 骨質面具
        ctx.fillStyle = '#fef2f2';
        ctx.beginPath();
        ctx.moveTo(-10, -10); ctx.lineTo(10, -10); ctx.lineTo(8, 5); ctx.lineTo(0, 12); ctx.lineTo(-8, 5);
        ctx.closePath();
        ctx.fill();

        // 邪能眼光
        if (!isSil) {
            const pulse = 0.5 + Math.sin(t * 10) * 0.5;
            ctx.fillStyle = '#ef4444';
            ctx.shadowBlur = 10 * pulse;
            ctx.shadowColor = '#ff0000';
            ctx.beginPath(); ctx.arc(-4, -2, 2, 0, Math.PI*2); ctx.fill();
            ctx.beginPath(); ctx.arc(4, -2, 2, 0, Math.PI*2); ctx.fill();
        }
        ctx.restore();
    },

    drawBackSpikes(ctx: CanvasRenderingContext2D, t: number, breathe: number) {
        ctx.save();
        ctx.translate(0, -40 + breathe);
        ctx.fillStyle = THEME_COVENANT.spike;

        for (let i = 0; i < 3; i++) {
            const ang = (i - 1) * 0.5;
            const len = 30 + Math.sin(t * 5 + i) * 5;
            ctx.save();
            ctx.rotate(ang);
            ctx.beginPath();
            ctx.moveTo(-3, 0); ctx.lineTo(0, -len); ctx.lineTo(3, 0);
            ctx.fill();
            ctx.restore();
        }
        ctx.restore();
    },

    drawWarpWeaponry(ctx: CanvasRenderingContext2D, agent: Agent, t: number, progress: number, breathe: number) {
        const role = agent.role;
        const attackAngle = progress * Math.PI * 1.3;

        // 右手武器 (巨斧或利刃)
        ctx.save();
        ctx.translate(22, -28 + breathe);
        ctx.rotate(attackAngle);

        ctx.shadowBlur = 12;
        ctx.shadowColor = THEME_COVENANT.primary;
        this.drawHeavyWeapon(ctx, role);
        ctx.restore();

        // 副手 (圖騰或盾)
        ctx.save();
        ctx.translate(-22, -25 + breathe * 0.9);
        if (role === Role.TANK) this.drawBarbedShield(ctx);
        else if (role === Role.SUPPORT) this.drawBloodTotem(ctx, t);
        ctx.restore();
    },

    drawHeavyWeapon(ctx: CanvasRenderingContext2D, role: Role) {
        ctx.fillStyle = THEME_COVENANT.armorBase;
        ctx.strokeStyle = THEME_COVENANT.secondary;
        ctx.lineWidth = 2;

        if (role === Role.WARRIOR) {
            // 混沌巨斧
            ctx.beginPath();
            ctx.moveTo(0, 0); ctx.lineTo(-25, -20); ctx.bezierCurveTo(-15, 10, -15, 20, -25, 45); ctx.lineTo(0, 25);
            ctx.closePath(); ctx.fill(); ctx.stroke();
            // 斧面裂隙
            ctx.strokeStyle = '#ff0000'; ctx.lineWidth = 1;
            ctx.beginPath(); ctx.moveTo(-18, -5); ctx.lineTo(-10, 15); ctx.stroke();
        } else if (role === Role.RANGER) {
            // 重型弩機
            ctx.fillRect(-6, -25, 12, 40);
            ctx.strokeRect(-28, -22, 56, 4);
        } else if (role === Role.MAGE) {
            // 鮮血長杖
            ctx.fillStyle = '#450a0a';
            ctx.fillRect(-3, -30, 6, 70);
            ctx.fillStyle = '#ef4444';
            ctx.beginPath(); ctx.arc(0, -35, 8, 0, Math.PI*2); ctx.fill();
        }
    },

    drawBarbedShield(ctx: CanvasRenderingContext2D) {
        ctx.fillStyle = THEME_COVENANT.armorDark;
        ctx.strokeStyle = THEME_COVENANT.accent;
        ctx.beginPath();
        ctx.moveTo(-18, -25); ctx.lineTo(18, -20); ctx.lineTo(22, 15); ctx.lineTo(0, 35); ctx.lineTo(-22, 15);
        ctx.closePath(); ctx.fill(); ctx.stroke();
        // 盾面尖刺
        ctx.fillStyle = THEME_COVENANT.spike;
        ctx.beginPath(); ctx.moveTo(-5, -5); ctx.lineTo(0, -15); ctx.lineTo(5, -5); ctx.fill();
    },

    drawBloodTotem(ctx: CanvasRenderingContext2D, t: number) {
        ctx.fillStyle = '#27272a';
        ctx.fillRect(-4, -15, 8, 45);
        ctx.save();
        ctx.translate(0, -25);
        ctx.rotate(t * 3);
        ctx.fillStyle = '#ef4444';
        ctx.beginPath();
        for(let i=0; i<6; i++) {
            const a = i * Math.PI/3;
            ctx.lineTo(Math.cos(a)*12, Math.sin(a)*12);
        }
        ctx.closePath(); ctx.fill();
        ctx.restore();
    }
};

import { Agent } from "../../../../game";
import { Team, AnimState, MovementType } from "../../../../../types";
import { UNIT_SCALE } from "../../../../../constants";
import { ImperialRenderer } from "../factions/ImperialRenderer";
import { CovenantRenderer } from "../factions/CovenantRenderer";
import { UnitFlightPainter } from "./UnitFlightPainter";
import { SpriteManager } from "../../../sprites";
import { VisualMath } from "../../../math/VisualMath";

/**
 * 單位主體繪製器 v10.0 (TA 重構版)
 * 負責全局變換、狀態過濾與陣營渲染分發
 */
export const UnitBodyPainter = {
    draw(
        ctx: CanvasRenderingContext2D, 
        agent: Agent, 
        px: number, py: number, pz: number, 
        t: number, 
        isSilhouette: boolean, 
        isSelected: boolean,
        scaleFactor: number
    ) {
        ctx.save(); 

        // 1. 基於 SSOT 的視覺中心定位
        const bodyY = VisualMath.getVisualBodyCenterY(py, pz);
        ctx.translate(px, bodyY); 

        // 2. 全局比例與物理旋轉
        ctx.scale(UNIT_SCALE, UNIT_SCALE);
        ctx.rotate(agent.physics.angle); 

        // 3. 狀態濾鏡 (死亡、受擊)
        if (agent.hp <= 0 && !isSilhouette) {
            ctx.filter = 'grayscale(100%) brightness(50%)'; 
        } else if (!isSilhouette && agent.hitFlashTimer > 0) {
             ctx.filter = 'brightness(300%) contrast(150%)';
        }

        // 4. 特殊形態處理 (變形術)
        if (agent.visualStatus === 'POLYMORPH') {
            const sheep = SpriteManager.getSpecialModel('SHEEP');
            const bounce = Math.abs(Math.sin(t * 5) * 5);
            ctx.scale(agent.facing > 0 ? 1 : -1, 1);
            ctx.drawImage(sheep, -32, -32 - bounce, 64, 64);
            ctx.restore();
            return;
        }

        // 5. 陣營渲染分發
        ctx.scale(agent.facing > 0 ? 1 : -1, 1); // 轉向處理

        if (isSilhouette) {
            ctx.globalAlpha = 0.5;
            ctx.globalCompositeOperation = 'source-over';
        }

        if (agent.team === Team.BLUE) {
            ImperialRenderer.draw(ctx, agent, t, isSilhouette);
        } else {
            CovenantRenderer.draw(ctx, agent, t, isSilhouette);
        }

        // 6. 狀態層疊 (冰凍)
        if (agent.visualStatus === 'FROZEN') {
            ctx.save();
            ctx.globalCompositeOperation = 'screen';
            ctx.globalAlpha = 0.6;
            const ice = SpriteManager.getSpecialModel('ICE');
            ctx.drawImage(ice, -48, -75, 96, 110);
            ctx.restore();
        }

        ctx.restore(); 
    }
};

import { Agent } from "../../../game";
import { AnimState, Role } from "../../../../types";
import { getCastProgress } from "../utils";
import { THEME_IMPERIAL, UNIT_SCALE } from "../../../../constants";

/**
 * 藍軍 (Imperial) 美術渲染器 v11.0 - 科技秩序版
 */
export const ImperialRenderer = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean, isRunning: boolean) {
        const progress = agent.animState === AnimState.ATTACK ? getCastProgress(agent) : 0;
        const isHit = agent.hitFlashTimer > 0;
        const role = agent.role;

        // --- 1. 骨架動力學 (Skeleton Components) ---
        // 不同職業擁有不同的呼吸頻率與振幅
        const freq = role === Role.MAGE ? 1.5 : 2.5;
        const amp = role === Role.TANK ? 1.0 : 3.0;
        const breathe = Math.sin(t * freq) * amp;
        const movementTilt = agent.isMoving ? 0.15 : 0;

        ctx.save();

        // 身體整體傾斜 (移動感與動量)
        ctx.rotate(movementTilt * agent.facing);

        // --- 2. 職業被動特效 (Passive VFX Layer) ---
        if (!isSilhouette) this.drawPassiveFX(ctx, role, t, breathe);

        // --- 3. 核心軀幹 (Core Body Component) ---
        ctx.save();
        ctx.translate(0, breathe);
        this.drawMainBody(ctx, role, isSilhouette, isHit);
        this.drawHelmet(ctx, t, isSilhouette);
        ctx.restore();

        // --- 4. 戰鬥武裝系統 (Arsenal System) ---
        // 戰鬥開始後武器變大且發光，非戰鬥模式收斂
        this.drawArsenal(ctx, agent, t, progress, breathe, isRunning);

        ctx.restore();
    },

    drawPassiveFX(ctx: CanvasRenderingContext2D, role: Role, t: number, breathe: number) {
        ctx.save();
        ctx.globalCompositeOperation = 'screen';
        const color = THEME_IMPERIAL.energy;

        if (role === Role.MAGE || role === Role.SUPPORT) {
            // 浮空環繞幾何體
            const rot = t * 2;
            ctx.strokeStyle = color;
            ctx.lineWidth = 1;
            ctx.globalAlpha = 0.4;
            for(let i=0; i<3; i++) {
                const ang = rot + (i * Math.PI * 2 / 3);
                const x = Math.cos(ang) * 25;
                const y = Math.sin(ang) * 10 - 35 + breathe;
                ctx.strokeRect(x-2, y-2, 4, 4);
            }
        }
        ctx.restore();
    },

    drawMainBody(ctx: CanvasRenderingContext2D, role: Role, isSil: boolean, isHit: boolean) {
        const { primary, armorLight, armorDark, energy } = THEME_IMPERIAL;
        ctx.save();
        ctx.translate(0, -35);

        const bodyGrad = ctx.createLinearGradient(-15, -15, 15, 25);
        bodyGrad.addColorStop(0, isHit ? '#fff' : armorLight);
        bodyGrad.addColorStop(1, isHit ? '#fff' : armorDark);

        ctx.fillStyle = bodyGrad;
        ctx.strokeStyle = energy;
        ctx.lineWidth = 1.5;

        ctx.beginPath();
        if (role === Role.TANK) {
            // 厚重裝甲幾何
            ctx.moveTo(-22, -10); ctx.lineTo(22, -10); ctx.lineTo(18, 30); ctx.lineTo(-18, 30);
        } else {
            // 標準流線型甲
            ctx.moveTo(-16, -12); ctx.lineTo(16, -12); ctx.lineTo(12, 35); ctx.lineTo(-12, 35);
        }
        ctx.closePath();
        ctx.fill();
        if (!isSil) {
            ctx.globalAlpha = 0.5;
            ctx.stroke();
            // 內部發光線條
            ctx.beginPath(); ctx.moveTo(-8, 5); ctx.lineTo(8, 5); ctx.stroke();
        }
        ctx.restore();
    },

    drawHelmet(ctx: CanvasRenderingContext2D, t: number, isSil: boolean) {
        ctx.save();
        ctx.translate(0, -52);
        ctx.fillStyle = THEME_IMPERIAL.armorLight;
        ctx.beginPath();
        ctx.arc(0, 0, 10, 0, Math.PI * 2);
        ctx.fill();

        if (!isSil) {
            ctx.fillStyle = '#fff';
            ctx.shadowBlur = 10;
            ctx.shadowColor = THEME_IMPERIAL.energy;
            ctx.beginPath(); ctx.ellipse(0, -1, 7, 2, 0, 0, Math.PI * 2); ctx.fill();
        }
        ctx.restore();
    },

    drawArsenal(ctx: CanvasRenderingContext2D, agent: Agent, t: number, progress: number, breathe: number, isRunning: boolean) {
        const role = agent.role;
        const swing = Math.sin(progress * Math.PI);
        const weaponScale = isRunning ? 1.2 : 0.8; // 戰鬥時武器增大

        // 右手：主武器
        ctx.save();
        ctx.translate(22, -30 + breathe);
        ctx.rotate(swing * -1.5); 
        ctx.scale(weaponScale, weaponScale);

        ctx.shadowBlur = isRunning ? 15 : 0;
        ctx.shadowColor = THEME_IMPERIAL.energy;
        this.drawWeapon(ctx, role, isRunning);
        ctx.restore();

        // 左手：防禦/副手
        ctx.save();
        ctx.translate(-22, -30 + breathe * 0.8);
        if (role === Role.TANK) this.drawShield(ctx, isRunning);
        else if (role === Role.SUPPORT || role === Role.MAGE) this.drawRelic(ctx, t, isRunning);
        ctx.restore();
    },

    drawWeapon(ctx: CanvasRenderingContext2D, role: Role, isRunning: boolean) {
        ctx.lineWidth = 3;
        ctx.lineCap = 'round';
        const color = THEME_IMPERIAL.energy;

        if (role === Role.WARRIOR || role === Role.TANK) {
            // 強化型電離長劍
            ctx.strokeStyle = '#fff';
            ctx.beginPath(); ctx.moveTo(0, 10); ctx.lineTo(0, -65); ctx.stroke();
            ctx.lineWidth = 1;
            ctx.strokeStyle = color;
            ctx.strokeRect(-5, -60, 10, 50);
        } else if (role === Role.RANGER) {
            // 能量複合弩
            ctx.fillStyle = THEME_IMPERIAL.armorDark;
            ctx.fillRect(-10, -25, 20, 30);
            ctx.strokeStyle = color;
            ctx.beginPath(); 
            ctx.moveTo(-25, -20); ctx.bezierCurveTo(-15, -35, 15, -35, 25, -20);
            ctx.stroke();
        } else if (role === Role.MAGE) {
            // 秩序權杖
            ctx.strokeStyle = THEME_IMPERIAL.armorLight;
            ctx.beginPath(); ctx.moveTo(0, 40); ctx.lineTo(0, -40); ctx.stroke();
            ctx.fillStyle = color;
            ctx.beginPath(); ctx.arc(0, -50, 12, 0, Math.PI*2); ctx.fill();
            if (isRunning) {
                ctx.strokeStyle = '#fff';
                ctx.beginPath(); ctx.arc(0, -50, 16, 0, Math.PI*2); ctx.stroke();
            }
        }
    },

    drawShield(ctx: CanvasRenderingContext2D, isRunning: boolean) {
        ctx.fillStyle = THEME_IMPERIAL.armorLight;
        ctx.strokeStyle = THEME_IMPERIAL.secondary;
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(-15, -25); ctx.lineTo(15, -25); ctx.lineTo(18, 15); ctx.lineTo(0, 35); ctx.lineTo(-18, 15);
        ctx.closePath();
        ctx.fill();
        ctx.stroke();

        if (isRunning) {
            ctx.fillStyle = THEME_IMPERIAL.energy;
            ctx.beginPath(); ctx.arc(0, 0, 6, 0, Math.PI*2); ctx.fill();
        }
    },

    drawRelic(ctx: CanvasRenderingContext2D, t: number, isRunning: boolean) {
        ctx.save();
        ctx.rotate(t * 3);
        ctx.fillStyle = THEME_IMPERIAL.energy;
        ctx.shadowBlur = isRunning ? 20 : 5;
        ctx.shadowColor = THEME_IMPERIAL.energy;
        // 幾何方塊
        ctx.fillRect(-8, -8, 16, 16);
        ctx.restore();
    }
};

import { Agent } from "../../../game";
import { AnimState, Role } from "../../../../types";
import { getCastProgress } from "../utils";
import { THEME_COVENANT, UNIT_SCALE } from "../../../../constants";

/**
 * 紅軍 (Covenant) 美術渲染器 v11.0 - 原始混沌版
 */
export const CovenantRenderer = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean, isRunning: boolean) {
        const progress = agent.animState === AnimState.ATTACK ? getCastProgress(agent) : 0;
        const isHit = agent.hitFlashTimer > 0;

        // --- 1. 骨架動力學 ---
        const rageScale = agent.hp < agent.maxHp * 0.4 ? 1.5 : 1.0;
        const breathe = Math.sin(t * 4.0) * (2.0 * rageScale); // 更急促的動作
        const attackLunge = progress * 30;

        ctx.save();

        // --- 2. 職業被動特效 (Chaos Atmosphere) ---
        if (!isSilhouette) this.drawPassiveFX(ctx, agent.role, t, breathe);

        // --- 3. 核心軀幹 ---
        ctx.save();
        ctx.translate(attackLunge * agent.facing, breathe);
        this.drawMainBody(ctx, agent.role, isSilhouette, isHit);
        this.drawBeastMask(ctx, t, isSilhouette);
        ctx.restore();

        // --- 4. 武裝系統 ---
        this.drawArsenal(ctx, agent, t, progress, breathe, isRunning);

        ctx.restore();
    },

    drawPassiveFX(ctx: CanvasRenderingContext2D, role: Role, t: number, breathe: number) {
        ctx.save();
        ctx.globalCompositeOperation = 'lighter';
        if (role === Role.WARRIOR || role === Role.TANK) {
            // 燃燒灰燼
            ctx.fillStyle = '#f97316';
            for(let i=0; i<4; i++) {
                const x = Math.sin(t * 5 + i) * 20;
                const y = -10 - (i * 15) + breathe;
                ctx.globalAlpha = 0.3;
                ctx.beginPath(); ctx.arc(x, y, 2, 0, Math.PI*2); ctx.fill();
            }
        }
        ctx.restore();
    },

    drawMainBody(ctx: CanvasRenderingContext2D, role: Role, isSil: boolean, isHit: boolean) {
        const { primary, armorDark, armorBase, accent } = THEME_COVENANT;
        ctx.save();
        ctx.translate(0, -35);

        const bodyGrad = ctx.createLinearGradient(-15, -20, 15, 20);
        bodyGrad.addColorStop(0, isHit ? '#fff' : armorBase);
        bodyGrad.addColorStop(1, isHit ? '#fff' : armorDark);

        ctx.fillStyle = bodyGrad;
        ctx.strokeStyle = accent;
        ctx.lineWidth = 1;

        ctx.beginPath();
        if (role === Role.TANK) {
            // 嶙峋的岩石裝甲
            ctx.moveTo(-26, -15); ctx.lineTo(26, -15); ctx.lineTo(22, 35); ctx.lineTo(0, 45); ctx.lineTo(-22, 35);
        } else {
            // 尖銳的戰鬥服
            ctx.moveTo(-18, -18); ctx.lineTo(18, -18); ctx.lineTo(14, 45); ctx.lineTo(0, 55); ctx.lineTo(-14, 45);
        }
        ctx.closePath();
        ctx.fill();

        if (!isSil) {
            ctx.stroke();
            // 熔岩裂紋
            ctx.strokeStyle = '#ef4444';
            ctx.lineWidth = 0.5;
            ctx.beginPath(); ctx.moveTo(-10, 10); ctx.lineTo(5, 25); ctx.stroke();
        }

        ctx.restore();
    },

    drawBeastMask(ctx: CanvasRenderingContext2D, t: number, isSil: boolean) {
        ctx.save();
        ctx.translate(0, -55);
        ctx.fillStyle = '#fef2f2'; // 骨質
        ctx.beginPath();
        ctx.moveTo(-12, -12); ctx.lineTo(12, -12); ctx.lineTo(10, 8); ctx.lineTo(0, 15); ctx.lineTo(-10, 8);
        ctx.closePath();
        ctx.fill();

        if (!isSil) {
            const pulse = 0.6 + Math.sin(t * 12) * 0.4;
            ctx.fillStyle = '#ef4444';
            ctx.shadowBlur = 12 * pulse;
            ctx.shadowColor = '#f00';
            ctx.beginPath(); ctx.arc(-5, -2, 2.5, 0, Math.PI*2); ctx.fill();
            ctx.beginPath(); ctx.arc(5, -2, 2.5, 0, Math.PI*2); ctx.fill();
        }
        ctx.restore();
    },

    drawArsenal(ctx: CanvasRenderingContext2D, agent: Agent, t: number, progress: number, breathe: number, isRunning: boolean) {
        const role = agent.role;
        const weaponScale = isRunning ? 1.3 : 0.9;
        const attackAngle = progress * Math.PI * 1.6;

        // 右手武器 (巨大化)
        ctx.save();
        ctx.translate(25, -28 + breathe);
        ctx.rotate(attackAngle);
        ctx.scale(weaponScale, weaponScale);

        ctx.shadowBlur = isRunning ? 20 : 0;
        ctx.shadowColor = THEME_COVENANT.primary;
        this.drawHeavyWeapon(ctx, role, isRunning);
        ctx.restore();

        // 副手
        ctx.save();
        ctx.translate(-22, -25 + breathe * 0.9);
        if (role === Role.TANK) this.drawBarbedShield(ctx);
        else if (role === Role.SUPPORT || role === Role.MAGE) this.drawBloodTotem(ctx, t, isRunning);
        ctx.restore();
    },

    drawHeavyWeapon(ctx: CanvasRenderingContext2D, role: Role, isRunning: boolean) {
        ctx.fillStyle = THEME_COVENANT.armorBase;
        ctx.strokeStyle = THEME_COVENANT.secondary;
        ctx.lineWidth = 2;

        if (role === Role.WARRIOR || role === Role.TANK) {
            // 混沌巨斧
            ctx.beginPath();
            ctx.moveTo(0, 0); ctx.lineTo(-35, -25); ctx.bezierCurveTo(-20, 15, -20, 30, -35, 55); ctx.lineTo(0, 30);
            ctx.closePath(); ctx.fill(); ctx.stroke();
            if (isRunning) {
                ctx.strokeStyle = '#f00'; ctx.lineWidth = 1;
                ctx.beginPath(); ctx.moveTo(-25, 0); ctx.lineTo(-10, 20); ctx.stroke();
            }
        } else if (role === Role.RANGER) {
            // 骨質重弩
            ctx.fillRect(-8, -30, 16, 45);
            ctx.strokeRect(-35, -25, 70, 5);
        } else if (role === Role.MAGE) {
            // 鮮血法杖
            ctx.fillStyle = '#450a0a';
            ctx.fillRect(-4, -40, 8, 90);
            ctx.fillStyle = '#ef4444';
            ctx.beginPath(); ctx.arc(0, -45, 14, 0, Math.PI*2); ctx.fill();
        }
    },

    drawBarbedShield(ctx: CanvasRenderingContext2D) {
        ctx.fillStyle = THEME_COVENANT.armorDark;
        ctx.strokeStyle = THEME_COVENANT.accent;
        ctx.beginPath();
        ctx.moveTo(-20, -30); ctx.lineTo(20, -25); ctx.lineTo(25, 20); ctx.lineTo(0, 45); ctx.lineTo(-25, 20);
        ctx.closePath(); ctx.fill(); ctx.stroke();
        // 尖刺
        ctx.fillStyle = THEME_COVENANT.spike;
        ctx.beginPath(); ctx.moveTo(-8, -10); ctx.lineTo(0, -25); ctx.lineTo(8, -10); ctx.fill();
    },

    drawBloodTotem(ctx: CanvasRenderingContext2D, t: number, isRunning: boolean) {
        ctx.fillStyle = '#18181b';
        ctx.fillRect(-5, -20, 10, 55);
        ctx.save();
        ctx.translate(0, -30);
        ctx.rotate(t * -4);
        ctx.fillStyle = '#ef4444';
        ctx.beginPath();
        for(let i=0; i<8; i++) {
            const a = i * Math.PI/4;
            const r = isRunning ? 15 : 10;
            ctx.lineTo(Math.cos(a)*r, Math.sin(a)*r);
        }
        ctx.closePath(); ctx.fill();
        ctx.restore();
    }
};

