import { Agent } from "../../../../game";
import { SpriteManager } from "../../../sprites";
import { UnitIndicatorPainter } from "./UnitIndicatorPainter";
import { UnitAuraPainter } from "./UnitAuraPainter";
import { VFXFactory } from "../../../graphics/VFXFactory";
import { UNIT_SCALE, ISO_SCALE_Y } from "../../../../../constants";

const HOVER_LIFT = 6; 

/**
 * 陰影與棋盤底座繪製器 (TA 優化版)
 * 負責「棋子感」的呈現與戰鬥切換
 */
export const UnitShadowPainter = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, px: number, py: number, pz: number, t: number, isSilhouette: boolean, isRunning: boolean) {
        if (isSilhouette || agent.visualStatus === 'POLYMORPH') return;

        const assets = SpriteManager.getUnitImages(agent.role, agent.team);
        const surfaceY = py;
        const tokenY = surfaceY - HOVER_LIFT;

        ctx.save();

        // 1. 物理投影陰影
        const jumpHeight = agent.physics.z;
        const shadowScale = Math.max(0.5, 1.0 - (jumpHeight / 450));
        const shadowAlpha = Math.max(0.1, 0.8 - (jumpHeight / 250));
        const shadowBlob = VFXFactory.getTexture('SHADOW_BLOB', 'rgba(0,0,0,0.6)'); 

        ctx.save();
        ctx.translate(px, surfaceY); 
        ctx.scale(UNIT_SCALE * shadowScale, UNIT_SCALE * shadowScale * ISO_SCALE_Y); 
        ctx.globalAlpha = shadowAlpha;
        ctx.drawImage(shadowBlob, -48, -48, 96, 96); 
        ctx.restore();

        // 2. 施法特效 (詠唱環)
        if (agent.hp > 0 && agent.castingSkillIdx !== -1) {
            const skill = agent.skills[agent.castingSkillIdx];
            if (skill && skill.tag === 'ULT') {
                UnitAuraPainter.drawUltimateChantVFX(ctx, agent, px, surfaceY, t);
            } else {
                UnitAuraPainter.drawCastingVFX(ctx, agent, px, surfaceY, t);
            }
        }

        // 3. 棋子底座 (Token Base)
        // 戰鬥中底座透明度降低，非戰鬥時維持實體感
        ctx.save();
        ctx.translate(px, tokenY);
        ctx.scale(UNIT_SCALE, UNIT_SCALE); 
        ctx.globalAlpha = isRunning ? 0.4 : 1.0;
        ctx.drawImage(assets.base, -64, -64); 
        ctx.restore();

        // 4. 棋子職業圖標 (Token Icon)
        // 戰鬥開始後隱藏圖標，避免視覺汙染，專注於模型動態
        if (agent.hp > 0 && !isRunning) {
            ctx.save();
            ctx.translate(px, tokenY - 20);
            ctx.scale(UNIT_SCALE, UNIT_SCALE); 

            const breath = Math.sin(t * 2) * 2;
            ctx.translate(0, breath);

            // 圖標發光背景
            ctx.fillStyle = 'rgba(0,0,0,0.5)';
            ctx.beginPath(); ctx.ellipse(0, 30, 15, 6, 0, 0, Math.PI*2); ctx.fill();

            ctx.globalAlpha = 1.0;
            ctx.shadowColor = assets.color; ctx.shadowBlur = 10;
            ctx.drawImage(assets.icon, -32, -32, 64, 64);
            ctx.restore();
        }

        // 5. 範圍指示器
        if (agent.castingSkillIdx !== -1) {
            const skill = agent.skills[agent.castingSkillIdx];
            if (skill && skill.type === 'AOE') {
                ctx.save();
                ctx.translate(px, surfaceY);
                UnitIndicatorPainter.drawSkillGroundIndicator(ctx, 0, 0, skill.color, t, 1 - (agent.castTimer / skill.cast), skill.aoeRadius || 1, skill.tag, true);
                ctx.restore();
            }
        }

        ctx.restore();
    }
};

import { Agent, GameEngine } from "../game";
import { RenderList, RenderOpType } from "../renderers/RenderList";
import { MapConfig } from "../utils";
import { UnitVisualProcessor } from "./unit/UnitVisualProcessor";
import { UnitBodyPainter } from "../renderers/units/painters/UnitBodyPainter";
import { UnitShadowPainter } from "../renderers/units/painters/UnitShadowPainter";

export class UnitRenderSystem {

    public submitRenderables(
        renderList: RenderList,
        agents: Agent[], 
        getTerrainHeight: (q: number, r: number) => number, 
        globalTime: number, 
        highlightAgent: Agent | null,
        mapConfig: MapConfig,
        isRunning: boolean // 新增參數
    ) {
        agents.forEach(agent => {
            if (agent.hp <= 0 && agent.fullyDead) return;

            const state = UnitVisualProcessor.process(agent, getTerrainHeight, mapConfig, highlightAgent);

            const op = renderList.next();
            op.type = RenderOpType.UNIT;
            op.y = state.sortY + 1; 
            op.z = 10;
            op.agent = agent;
            op.tx = state.x; 
            op.ty = state.y - state.terrainHeight; 
            op.th = agent.physics.z; 
            op.time = globalTime;
            op.uSelected = state.isSelected;
            op.uSilhouette = false;
            // 複用 pIsUlt 欄位傳遞 isRunning 狀態 (RenderOp 擴充成本高，暫時借位)
            op.pIsUlt = isRunning; 
        });
    }

    public drawSilhouette(
        ctx: CanvasRenderingContext2D, 
        agent: Agent, 
        getTerrainHeight: (q: number, r: number) => number, 
        globalTime: number, 
        mapConfig: MapConfig
    ) {
        const state = UnitVisualProcessor.process(agent, getTerrainHeight, mapConfig, null);
        const visualGroundY = state.y - state.terrainHeight;
        this.drawAssembly(ctx, agent, state.x, visualGroundY, agent.physics.z, globalTime, false, true, false);
    }

    public drawAssembly(
        ctx: CanvasRenderingContext2D, 
        agent: Agent, 
        drawX: number, 
        drawY: number, 
        localZ: number,
        globalTime: number, 
        isSelected: boolean,
        isSilhouette: boolean,
        isRunning: boolean
    ) {
        ctx.save();
        ctx.translate(drawX, drawY); 

        // 1. 陰影層 (Shadow & Aura)
        if (!isSilhouette && agent.hp > 0) {
            UnitShadowPainter.draw(ctx, agent, 0, 0, localZ, globalTime, isSilhouette, isRunning);
        }

        // 2. 實體層 (Body & Arsenal)
        UnitBodyPainter.draw(ctx, agent, 0, 0, localZ, globalTime, isSilhouette, isSelected, 1.0, isRunning);

        ctx.restore(); 
    }
}

import { Agent, GameEngine, VICTORY_PHASE_DURATION } from "../game";
import { Camera, GameRenderer } from "../renderer"; 
import { Hex, Skill } from "../../types";

// Sub-renderers
import { BackgroundRenderer } from "./background";
import { TacticalRenderer } from "./tactical";
import { HUDRenderer } from "./HUDRenderer";
import { PostProcessor } from "./PostProcessor"; 
import { RenderList, RenderOpType } from "./RenderList";
import { ProjectileDrawer } from "./ProjectileDrawer";

// Painters
import { TerrainRenderer } from "./grid/TerrainRenderer";
import { GridOverlays } from "./grid/GridOverlays";
import { ParticleRenderer } from "../systems/vfx/renderers/ParticleRenderer";
import { SpriteManager } from "../sprites";
import { AssetManager } from "../assets";
import { ENV_ANCHOR_X, ENV_ANCHOR_Y } from "../graphics/EnvironmentFactory";

export class RenderPipeline {
    private renderer: GameRenderer;
    private backgroundRenderer: BackgroundRenderer;
    private tacticalRenderer: TacticalRenderer;
    private hudRenderer: HUDRenderer;
    private postProcessor: PostProcessor;
    private renderList: RenderList;

    private transitionT: number = 0;
    private transitionPhase: 'IN' | 'OUT' | 'IDLE' = 'IDLE';

    constructor(renderer: GameRenderer) {
        this.renderer = renderer;
        this.backgroundRenderer = new BackgroundRenderer();
        this.tacticalRenderer = new TacticalRenderer();
        this.hudRenderer = new HUDRenderer();
        this.postProcessor = new PostProcessor();
        this.renderList = new RenderList();
    }

    public setTransition(t: number, phase: 'IN' | 'OUT' | 'IDLE') {
        this.transitionT = t;
        this.transitionPhase = phase;
    }

    public update(dt: number, engine: GameEngine) {
        this.tacticalRenderer.update(dt, engine);
    }

    public draw(
        ctx: CanvasRenderingContext2D, 
        engine: GameEngine, 
        camera: Camera, 
        highlight: Agent | null, 
        fps: number, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null,
        globalTime: number
    ): void {
        const physicalWidth = ctx.canvas.width;
        const physicalHeight = ctx.canvas.height;
        if (physicalWidth === 0 || physicalHeight === 0) return;

        const dpr = window.devicePixelRatio || 1;
        const logicalWidth = physicalWidth / dpr;
        const logicalHeight = physicalHeight / dpr;
        const scene = engine.currentScene;
        const layout = engine.mapConfig.layout;

        ctx.resetTransform();
        ctx.clearRect(0, 0, physicalWidth, physicalHeight);
        ctx.scale(dpr, dpr);
        this.backgroundRenderer.draw(ctx, logicalWidth, logicalHeight, scene, engine.mapConfig, globalTime);

        ctx.save();
        this.renderer.camera.sync(camera); 
        this.renderer.camera.applyTransform(ctx, logicalWidth, logicalHeight);

        this.renderList.reset();
        const terrainHeightFunc = (q: number, r: number) => this.renderer.grid.getTerrainHeight(q, r, engine);

        this.renderer.grid.submitRenderables(
            this.renderList,
            engine, hoveredHex, hoveredSkill, highlight, 
            engine.projectiles,
            this.transitionT, this.transitionPhase,
            globalTime
        );

        this.renderer.vfxRenderer.submitRenderables(
            this.renderList,
            engine,
            this.renderer.vfx,
            terrainHeightFunc,
            engine.mapConfig,
            this.transitionT,
            this.transitionPhase,
            { width: logicalWidth, height: logicalHeight, camera } 
        );

        this.renderer.unit.submitRenderables(
            this.renderList,
            engine.agents, 
            terrainHeightFunc, 
            globalTime, 
            highlight, 
            engine.mapConfig,
            engine.isRunning // 傳遞戰鬥狀態
        );

        this.renderList.sort();

        for (let i = 0; i < this.renderList.count; i++) {
            const op = this.renderList.ops[i];
            const snapX = Math.round(op.tx);
            const snapY = Math.round(op.ty);

            switch (op.type) {
                case RenderOpType.TERRAIN:
                    TerrainRenderer.drawBlock(ctx, snapX, snapY, op.tsize, op.th, op.ttheme, op.ttype, globalTime, layout);
                    const visualTopY = snapY - op.th;
                    TerrainRenderer.drawTerrainDetail(ctx, snapX, snapY, op.th, op.ttype, op.tdetail, op.tq, op.tr);
                    GridOverlays.drawOverlays(ctx, snapX, visualTopY, op.tsize, op.oStatus, op.oDanger, op.oLightCol, op.oLightInt, op.oRange, op.oRangeCol, op.oHover, op.oHasUnit, op.tq, op.tr, op.time, op.oHazard, layout);
                    break;
                case RenderOpType.OBSTACLE:
                    const sprite = SpriteManager.getObstacleSprite(op.ttype, layout);
                    ctx.drawImage(sprite, snapX - ENV_ANCHOR_X, snapY - ENV_ANCHOR_Y);
                    break;
                case RenderOpType.UNIT:
                    if (op.agent) this.renderer.unit.drawAssembly(ctx, op.agent, snapX, snapY, op.th, op.time, op.uSelected, op.uSilhouette, op.pIsUlt);
                    break;
                case RenderOpType.DECAL:
                    const dImg = AssetManager.getBlastZone(op.dColor);
                    ctx.save();
                    ctx.translate(snapX, snapY);
                    ctx.scale(op.dScale, op.dScale);
                    ctx.globalAlpha = Math.min(1, op.dLife);
                    ctx.drawImage(dImg, -64, -32, 128, 64);
                    ctx.restore();
                    break;
                case RenderOpType.VFX:
                    if (op.particle) {
                        const p = op.particle;
                        ctx.save();
                        ctx.translate(snapX, snapY);
                        ParticleRenderer.drawSingleParticle(ctx, p, 0, 0, op.vProgress, op.vChaos, layout);
                        ctx.restore();
                    }
                    break;
                case RenderOpType.PROJECTILE:
                    ProjectileDrawer.draw(ctx, op, globalTime);
                    break;
            }
        }

        const occludedAgents = this.renderer.grid.getOccludedAgents(engine);
        if (occludedAgents.length > 0) {
            ctx.save();
            occludedAgents.forEach(agent => {
                this.renderer.unit.drawSilhouette(ctx, agent, terrainHeightFunc, globalTime, engine.mapConfig);
            });
            ctx.restore();
        }

        this.renderer.statusOrchestrator.draw(ctx, engine.agents, globalTime, terrainHeightFunc);
        this.renderer.vfxRenderer.drawTopLayerParticles(ctx, this.renderer.vfx, scene, engine.mapConfig, this.transitionT, this.transitionPhase, layout);
        ctx.restore(); 

        let transitionAberration = 0;
        if (this.transitionPhase !== 'IDLE') transitionAberration = 4 * this.transitionT * (1 - this.transitionT) * 0.5;

        this.postProcessor.apply(ctx, physicalWidth, physicalHeight, this.renderer.camera.getTrauma(), transitionAberration);

        ctx.save(); 
        this.renderer.camera.applyTransform(ctx, logicalWidth, logicalHeight);
        this.tacticalRenderer.drawOverlay(ctx, engine, highlight, this.renderer.grid, globalTime);
        this.hudRenderer.draw(ctx, this.renderer.hud, engine.agents, terrainHeightFunc, engine.mapConfig, highlight, globalTime);
        ctx.restore(); 

        if (engine.directorTargetId) this.tacticalRenderer.drawHUD(ctx, engine, logicalWidth, logicalHeight, camera, globalTime);
        this.tacticalRenderer.drawDebug(ctx, fps);

        let blurAmount = 0;
        if (engine.isFinishing) blurAmount = 1.0 - (engine.victoryTimer / VICTORY_PHASE_DURATION);
        else if (engine.winningTeam !== null) blurAmount = 1.0;

        if (this.transitionPhase === 'OUT') blurAmount = 1.0; 
        else if (this.transitionPhase === 'IN') blurAmount = 1.0 - this.transitionT;

        if (blurAmount > 0) this.postProcessor.applyFinishBlur(ctx, physicalWidth, physicalHeight, Math.max(0, Math.min(1, blurAmount)));
    }
}

import { Agent } from "../../../game";
import { AnimState, Role } from "../../../../types";
import { getCastProgress } from "../utils";
import { THEME_IMPERIAL } from "../../../../constants";

/**
 * 藍軍 (Imperial) 美術渲染器 v12.0
 * 核心功能：邊緣光、抖動光源、軌道寶珠
 */
export const ImperialRenderer = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean, isRunning: boolean) {
        const progress = agent.animState === AnimState.ATTACK ? getCastProgress(agent) : 0;
        const isHit = agent.hitFlashTimer > 0;
        const role = agent.role;

        // --- 1. 物理與骨架變換 ---
        const freq = role === Role.MAGE ? 1.8 : 2.5;
        const breathe = Math.sin(t * freq) * 2.5;
        const movementTilt = agent.isMoving ? 0.12 : 0;
        const hitJitter = isHit ? (Math.random() - 0.5) * 4 : 0;

        ctx.save();
        ctx.rotate(movementTilt * agent.facing);

        // --- 2. 軌道特效層 (Orbital Layer) ---
        if (!isSilhouette) this.drawOrbitals(ctx, role, t, breathe);

        // --- 3. 核心軀幹繪製 ---
        ctx.save();
        ctx.translate(0, breathe);

        // 繪製背景組件 (披風)
        this.drawEnergyCape(ctx, t, progress);

        // 繪製主體與光源核心
        this.drawMainBody(ctx, role, isSilhouette, isHit, hitJitter);
        this.drawHelmet(ctx, isSilhouette);

        ctx.restore();

        // --- 4. 武器系統 ---
        this.drawArsenal(ctx, agent, t, progress, breathe, isRunning);

        ctx.restore();
    },

    drawMainBody(ctx: CanvasRenderingContext2D, role: Role, isSil: boolean, isHit: boolean, jitter: number) {
        const { primary, armorLight, armorDark, energy } = THEME_IMPERIAL;
        ctx.save();
        ctx.translate(0, -35);

        // A. 邊緣光與基礎形狀
        ctx.beginPath();
        if (role === Role.TANK) {
            ctx.moveTo(-22, -10); ctx.lineTo(22, -10); ctx.lineTo(18, 30); ctx.lineTo(-18, 30);
        } else {
            ctx.moveTo(-16, -12); ctx.lineTo(16, -12); ctx.lineTo(12, 35); ctx.lineTo(-12, 35);
        }
        ctx.closePath();

        // B. 材質漸變 (增加邊緣亮色)
        const bodyGrad = ctx.createLinearGradient(-20, 0, 20, 0);
        bodyGrad.addColorStop(0, isHit ? '#fff' : armorDark);
        bodyGrad.addColorStop(0.1, isHit ? '#fff' : armorLight); // 邊緣光
        bodyGrad.addColorStop(0.5, isHit ? '#fff' : primary);
        bodyGrad.addColorStop(0.9, isHit ? '#fff' : armorLight); // 邊緣光
        bodyGrad.addColorStop(1, isHit ? '#fff' : armorDark);

        ctx.fillStyle = bodyGrad;
        ctx.fill();

        // C. 輪廓強化 (Rim Stroke)
        if (!isSil) {
            ctx.strokeStyle = energy;
            ctx.lineWidth = 1.5;
            ctx.globalAlpha = 0.8;
            ctx.stroke();
        }

        // D. 能量核心光源 (受擊會抖動)
        if (!isSil) {
            ctx.save();
            ctx.translate(jitter, 0);
            ctx.globalCompositeOperation = 'screen';
            const coreGrad = ctx.createLinearGradient(0, -10, 0, 20);
            coreGrad.addColorStop(0, 'transparent');
            coreGrad.addColorStop(0.5, isHit ? '#fff' : energy);
            coreGrad.addColorStop(1, 'transparent');

            ctx.fillStyle = coreGrad;
            ctx.shadowColor = energy;
            ctx.shadowBlur = isHit ? 15 : 5;
            ctx.fillRect(-2, -10, 4, 35);
            ctx.restore();
        }

        ctx.restore();
    },

    drawOrbitals(ctx: CanvasRenderingContext2D, role: Role, t: number, breathe: number) {
        if (role !== Role.MAGE && role !== Role.SUPPORT) return;

        ctx.save();
        ctx.globalCompositeOperation = 'screen';
        const num = 3;
        for (let i = 0; i < num; i++) {
            const angle = (t * 3) + (i * Math.PI * 2 / num);
            const radius = 28;
            const ox = Math.cos(angle) * radius;
            const oy = Math.sin(angle * 0.5) * 12 - 35 + breathe;

            ctx.fillStyle = '#fff';
            ctx.shadowColor = THEME_IMPERIAL.energy;
            ctx.shadowBlur = 8;
            ctx.beginPath();
            ctx.arc(ox, oy, 3, 0, Math.PI * 2);
            ctx.fill();

            // 軌道殘影
            ctx.globalAlpha = 0.3;
            ctx.beginPath();
            ctx.arc(ox, oy, 6, 0, Math.PI * 2);
            ctx.fill();
        }
        ctx.restore();
    },

    drawHelmet(ctx: CanvasRenderingContext2D, isSil: boolean) {
        ctx.save();
        ctx.translate(0, -52);

        // 頭盔邊緣光
        ctx.fillStyle = THEME_IMPERIAL.armorDark;
        ctx.beginPath(); ctx.arc(0, 0, 11, 0, Math.PI * 2); ctx.fill();

        ctx.fillStyle = THEME_IMPERIAL.armorLight;
        ctx.beginPath(); ctx.arc(0, 0, 9, 0, Math.PI * 2); ctx.fill();

        if (!isSil) {
            ctx.fillStyle = '#fff';
            ctx.shadowBlur = 10;
            ctx.shadowColor = THEME_IMPERIAL.energy;
            ctx.beginPath(); ctx.ellipse(0, -1, 7, 2, 0, 0, Math.PI * 2); ctx.fill();
        }
        ctx.restore();
    },

    drawEnergyCape(ctx: CanvasRenderingContext2D, t: number, progress: number) {
        ctx.save();
        ctx.translate(0, -42);
        const wave = Math.sin(t * 2.5) * 6;
        const grad = ctx.createLinearGradient(0, 0, 0, 55);
        grad.addColorStop(0, THEME_IMPERIAL.energy);
        grad.addColorStop(1, 'transparent');

        ctx.fillStyle = grad;
        ctx.globalAlpha = 0.3 + Math.sin(t * 4) * 0.1;
        ctx.beginPath();
        ctx.moveTo(-14, 0);
        ctx.bezierCurveTo(-25 + wave, 20, -15 + wave, 40, -10, 55);
        ctx.lineTo(10, 55);
        ctx.bezierCurveTo(15 - wave, 40, 25 - wave, 20, 14, 0);
        ctx.fill();
        ctx.restore();
    },

    drawArsenal(ctx: CanvasRenderingContext2D, agent: Agent, t: number, progress: number, breathe: number, isRunning: boolean) {
        const role = agent.role;
        const swing = Math.sin(progress * Math.PI);
        const weaponScale = isRunning ? 1.25 : 0.85;

        // 右手武器
        ctx.save();
        ctx.translate(22, -30 + breathe);
        ctx.rotate(swing * -1.5); 
        ctx.scale(weaponScale, weaponScale);
        this.drawWeapon(ctx, role, isRunning);
        ctx.restore();

        // 左手防具
        ctx.save();
        ctx.translate(-22, -30 + breathe * 0.8);
        if (role === Role.TANK) this.drawShield(ctx, isRunning);
        else if (role === Role.SUPPORT || role === Role.MAGE) this.drawRelic(ctx, t, isRunning);
        ctx.restore();
    },

    drawWeapon(ctx: CanvasRenderingContext2D, role: Role, isRunning: boolean) {
        ctx.lineWidth = 3;
        const color = THEME_IMPERIAL.energy;
        ctx.shadowBlur = isRunning ? 15 : 0;
        ctx.shadowColor = color;

        if (role === Role.WARRIOR || role === Role.TANK) {
            ctx.strokeStyle = '#fff';
            ctx.beginPath(); ctx.moveTo(0, 10); ctx.lineTo(0, -60); ctx.stroke();
            ctx.strokeStyle = color;
            ctx.lineWidth = 1;
            ctx.strokeRect(-4, -55, 8, 45);
        } else if (role === Role.RANGER) {
            ctx.fillStyle = THEME_IMPERIAL.armorDark;
            ctx.fillRect(-8, -25, 16, 28);
            ctx.strokeStyle = color;
            ctx.lineWidth = 2;
            ctx.beginPath(); ctx.moveTo(-28, -18); ctx.quadraticCurveTo(0, -35, 28, -18); ctx.stroke();
        } else if (role === Role.MAGE) {
            ctx.strokeStyle = THEME_IMPERIAL.armorLight;
            ctx.beginPath(); ctx.moveTo(0, 40); ctx.lineTo(0, -40); ctx.stroke();
            ctx.fillStyle = color;
            ctx.beginPath(); ctx.arc(0, -48, 14, 0, Math.PI*2); ctx.fill();
            ctx.strokeStyle = '#fff';
            ctx.beginPath(); ctx.arc(0, -48, 18, 0, Math.PI*2); ctx.stroke();
        }
    },

    drawShield(ctx: CanvasRenderingContext2D, isRunning: boolean) {
        ctx.fillStyle = THEME_IMPERIAL.armorLight;
        ctx.strokeStyle = THEME_IMPERIAL.energy;
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(-16, -25); ctx.lineTo(16, -25); ctx.lineTo(18, 15); ctx.lineTo(0, 38); ctx.lineTo(-18, 15);
        ctx.closePath();
        ctx.fill();
        ctx.stroke();
        if (isRunning) {
            ctx.fillStyle = '#fff';
            ctx.beginPath(); ctx.arc(0, 0, 5, 0, Math.PI*2); ctx.fill();
        }
    },

    drawRelic(ctx: CanvasRenderingContext2D, t: number, isRunning: boolean) {
        ctx.save();
        ctx.rotate(t * 2.5);
        ctx.fillStyle = THEME_IMPERIAL.energy;
        ctx.shadowBlur = isRunning ? 20 : 5;
        ctx.shadowColor = THEME_IMPERIAL.energy;
        ctx.fillRect(-10, -10, 20, 20);
        ctx.strokeStyle = '#fff';
        ctx.strokeRect(-6, -6, 12, 12);
        ctx.restore();
    }
};

import { Agent } from "../../../game";
import { AnimState, Role } from "../../../../types";
import { getCastProgress } from "../utils";
import { THEME_COVENANT } from "../../../../constants";

/**
 * 紅軍 (Covenant) 美術渲染器 v12.0
 * 核心功能：熔岩裂隙、抖動火核、飛灰特效
 */
export const CovenantRenderer = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean, isRunning: boolean) {
        const progress = agent.animState === AnimState.ATTACK ? getCastProgress(agent) : 0;
        const isHit = agent.hitFlashTimer > 0;

        // --- 1. 骨架動力學 ---
        const rageScale = agent.hp < agent.maxHp * 0.4 ? 1.4 : 1.0;
        const breathe = Math.sin(t * 4.2) * (2.2 * rageScale);
        const hitJitter = isHit ? (Math.random() - 0.5) * 6 : 0;
        const attackLunge = progress * 25;

        ctx.save();

        // --- 2. 被動碎屑特效 (Ash/Ember Layer) ---
        if (!isSilhouette) this.drawEmberFX(ctx, t, breathe);

        // --- 3. 核心軀幹 ---
        ctx.save();
        ctx.translate(attackLunge * agent.facing, breathe);

        this.drawSpikes(ctx, t);
        this.drawMainBody(ctx, agent.role, isSilhouette, isHit, hitJitter);
        this.drawBeastMask(ctx, t, isSilhouette);

        ctx.restore();

        // --- 4. 武裝系統 ---
        this.drawArsenal(ctx, agent, t, progress, breathe, isRunning);

        ctx.restore();
    },

    drawMainBody(ctx: CanvasRenderingContext2D, role: Role, isSil: boolean, isHit: boolean, jitter: number) {
        const { primary, armorDark, armorBase, accent } = THEME_COVENANT;
        ctx.save();
        ctx.translate(0, -35);

        // A. 崎嶇邊緣幾何
        ctx.beginPath();
        if (role === Role.TANK) {
            ctx.moveTo(-26, -14); ctx.lineTo(26, -14); ctx.lineTo(22, 35); ctx.lineTo(0, 46); ctx.lineTo(-22, 35);
        } else {
            ctx.moveTo(-18, -18); ctx.lineTo(18, -18); ctx.lineTo(14, 45); ctx.lineTo(0, 52); ctx.lineTo(-14, 45);
        }
        ctx.closePath();

        // B. 熔岩質感漸變
        const bodyGrad = ctx.createLinearGradient(-20, 0, 20, 0);
        bodyGrad.addColorStop(0, isHit ? '#fff' : '#000');
        bodyGrad.addColorStop(0.1, isHit ? '#fff' : accent); // 邊緣光
        bodyGrad.addColorStop(0.5, isHit ? '#fff' : armorDark);
        bodyGrad.addColorStop(0.9, isHit ? '#fff' : accent); // 邊緣光
        bodyGrad.addColorStop(1, isHit ? '#fff' : '#000');

        ctx.fillStyle = bodyGrad;
        ctx.fill();

        // C. 輪廓描邊
        if (!isSil) {
            ctx.strokeStyle = primary;
            ctx.lineWidth = 1;
            ctx.stroke();
        }

        // D. 熔岩核心光源 (抖動)
        if (!isSil) {
            ctx.save();
            ctx.translate(jitter, 0);
            ctx.globalCompositeOperation = 'lighter';

            const pulse = 0.8 + Math.sin(Date.now() * 0.01) * 0.2;
            const coreGrad = ctx.createRadialGradient(0, 10, 0, 0, 10, 20);
            coreGrad.addColorStop(0, isHit ? '#fff' : '#ff4d00');
            coreGrad.addColorStop(1, 'transparent');

            ctx.fillStyle = coreGrad;
            ctx.beginPath();
            ctx.moveTo(0, 0); ctx.lineTo(6, 15); ctx.lineTo(0, 30); ctx.lineTo(-6, 15);
            ctx.fill();

            // 裂隙細節
            ctx.strokeStyle = '#ff0000';
            ctx.lineWidth = 0.5;
            ctx.beginPath(); ctx.moveTo(-8, 5); ctx.lineTo(-4, 12); ctx.moveTo(8, 20); ctx.lineTo(4, 25); ctx.stroke();
            ctx.restore();
        }

        ctx.restore();
    },

    drawEmberFX(ctx: CanvasRenderingContext2D, t: number, breathe: number) {
        ctx.save();
        ctx.globalCompositeOperation = 'lighter';
        for (let i = 0; i < 4; i++) {
            const seed = i * 1.5;
            const ex = Math.sin(t * 2 + seed) * 25;
            const ey = -10 - (i * 18) + breathe + (Math.sin(t * 5 + seed) * 5);
            const size = 1.5 + Math.random();

            ctx.fillStyle = '#f97316';
            ctx.shadowColor = '#f00';
            ctx.shadowBlur = 5;
            ctx.globalAlpha = 0.4;
            ctx.beginPath(); ctx.arc(ex, ey, size, 0, Math.PI * 2); ctx.fill();
        }
        ctx.restore();
    },

    drawBeastMask(ctx: CanvasRenderingContext2D, t: number, isSil: boolean) {
        ctx.save();
        ctx.translate(0, -55);
        ctx.fillStyle = '#fffaf0'; 
        ctx.beginPath();
        ctx.moveTo(-12, -12); ctx.lineTo(12, -12); ctx.lineTo(10, 8); ctx.lineTo(0, 16); ctx.lineTo(-10, 8);
        ctx.fill();

        if (!isSil) {
            const pulse = 0.7 + Math.sin(t * 15) * 0.3;
            ctx.fillStyle = '#f00';
            ctx.shadowBlur = 15 * pulse;
            ctx.shadowColor = '#f00';
            ctx.beginPath(); ctx.arc(-5, -2, 2.5, 0, Math.PI*2); ctx.fill();
            ctx.beginPath(); ctx.arc(5, -2, 2.5, 0, Math.PI*2); ctx.fill();
        }
        ctx.restore();
    },

    drawSpikes(ctx: CanvasRenderingContext2D, t: number) {
        ctx.save();
        ctx.translate(0, -42);
        ctx.fillStyle = '#111';
        ctx.strokeStyle = THEME_COVENANT.accent;
        for (let i = 0; i < 3; i++) {
            const ang = (i - 1) * 0.6;
            const len = 35 + Math.sin(t * 6 + i) * 6;
            ctx.save();
            ctx.rotate(ang);
            ctx.beginPath();
            ctx.moveTo(-4, 0); ctx.lineTo(0, -len); ctx.lineTo(4, 0);
            ctx.fill(); ctx.stroke();
            ctx.restore();
        }
        ctx.restore();
    },

    drawArsenal(ctx: CanvasRenderingContext2D, agent: Agent, t: number, progress: number, breathe: number, isRunning: boolean) {
        const role = agent.role;
        const weaponScale = isRunning ? 1.35 : 0.95;
        const attackAngle = progress * Math.PI * 1.7;

        ctx.save();
        ctx.translate(26, -28 + breathe);
        ctx.rotate(attackAngle);
        ctx.scale(weaponScale, weaponScale);
        this.drawHeavyWeapon(ctx, role, isRunning);
        ctx.restore();

        ctx.save();
        ctx.translate(-24, -25 + breathe * 0.9);
        if (role === Role.TANK) this.drawBarbedShield(ctx);
        else if (role === Role.SUPPORT || role === Role.MAGE) this.drawBloodTotem(ctx, t, isRunning);
        ctx.restore();
    },

    drawHeavyWeapon(ctx: CanvasRenderingContext2D, role: Role, isRunning: boolean) {
        ctx.fillStyle = THEME_COVENANT.armorBase;
        ctx.strokeStyle = THEME_COVENANT.secondary;
        ctx.lineWidth = 2;
        ctx.shadowBlur = isRunning ? 25 : 0;
        ctx.shadowColor = '#f00';

        if (role === Role.WARRIOR || role === Role.TANK) {
            ctx.beginPath();
            ctx.moveTo(0, 0); ctx.lineTo(-38, -28); ctx.bezierCurveTo(-22, 15, -22, 35, -38, 60); ctx.lineTo(0, 35);
            ctx.closePath(); ctx.fill(); ctx.stroke();
            if (isRunning) {
                ctx.strokeStyle = '#f00'; ctx.lineWidth = 1.5;
                ctx.beginPath(); ctx.moveTo(-28, 5); ctx.lineTo(-12, 25); ctx.stroke();
            }
        } else if (role === Role.RANGER) {
            ctx.fillRect(-10, -32, 20, 48);
            ctx.strokeStyle = '#f00';
            ctx.strokeRect(-38, -26, 76, 6);
        } else if (role === Role.MAGE) {
            ctx.fillStyle = '#300';
            ctx.fillRect(-5, -45, 10, 100);
            ctx.fillStyle = '#f00';
            ctx.beginPath(); ctx.arc(0, -50, 16, 0, Math.PI*2); ctx.fill();
            ctx.strokeStyle = '#fff';
            ctx.beginPath(); ctx.arc(0, -50, 20, 0, Math.PI*2); ctx.stroke();
        }
    },

    drawBarbedShield(ctx: CanvasRenderingContext2D) {
        ctx.fillStyle = '#000';
        ctx.strokeStyle = THEME_COVENANT.accent;
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(-22, -32); ctx.lineTo(22, -28); ctx.lineTo(26, 22); ctx.lineTo(0, 48); ctx.lineTo(-26, 22);
        ctx.closePath();
        ctx.fill(); ctx.stroke();
        ctx.fillStyle = THEME_COVENANT.primary;
        ctx.beginPath(); ctx.moveTo(-8, -12); ctx.lineTo(0, -30); ctx.lineTo(8, -12); ctx.fill();
    },

    drawBloodTotem(ctx: CanvasRenderingContext2D, t: number, isRunning: boolean) {
        ctx.fillStyle = '#111';
        ctx.fillRect(-6, -22, 12, 60);
        ctx.save();
        ctx.translate(0, -32);
        ctx.rotate(t * -3.5);
        ctx.fillStyle = '#f00';
        ctx.beginPath();
        for(let i=0; i<8; i++) {
            const a = i * Math.PI/4;
            const r = isRunning ? 18 : 12;
            ctx.lineTo(Math.cos(a)*r, Math.sin(a)*r);
        }
        ctx.closePath(); ctx.fill();
        ctx.restore();
    }
};

import { Agent } from "../../../game";
import { AnimState, Role } from "../../../../types";
import { getCastProgress } from "../utils";
import { THEME_IMPERIAL } from "../../../../constants";

/**
 * 帝國 (Imperial) 渲染器 v13.0 - 極限戰士風格
 * 核心：動力裝甲、金邊鑲嵌、機械律令
 */
export const ImperialRenderer = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean, isRunning: boolean) {
        const progress = agent.animState === AnimState.ATTACK ? getCastProgress(agent) : 0;
        const isHit = agent.hitFlashTimer > 0;
        const role = agent.role;

        // --- 1. 活塞骨架動力學 (Mechanized Skeleton) ---
        // 呼吸更沈穩，幾乎只有垂直位移
        const breathe = Math.sin(t * 1.5) * 1.5;
        const jitter = isHit ? (Math.random() - 0.5) * 3 : 0;

        ctx.save();
        ctx.translate(jitter, 0);

        // --- 2. 外部裝備層 (Exterior Gear) ---
        if (!isSilhouette) {
            this.drawPowerPack(ctx, t, breathe);
            this.drawOrbitals(ctx, t, breathe);
        }

        // --- 3. 核心裝甲主體 (Ceramite Armor) ---
        ctx.save();
        ctx.translate(0, breathe);
        this.drawMainArmor(ctx, role, isHit, isSilhouette);
        this.drawPauldrons(ctx, isHit);
        this.drawMark(ctx, isSilhouette);
        ctx.restore();

        // --- 4. 武器系統 (Standard Arsenal) ---
        this.drawWeaponry(ctx, agent, t, progress, breathe, isRunning);

        ctx.restore();
    },

    drawMainArmor(ctx: CanvasRenderingContext2D, role: Role, isHit: boolean, isSil: boolean) {
        const { armorDark, armorLight, energy } = THEME_IMPERIAL;
        ctx.save();
        ctx.translate(0, -35);

        // A. 陶瓷裝甲基座 (深鈷藍)
        ctx.beginPath();
        const w = role === Role.TANK ? 22 : 16;
        ctx.moveTo(-w, -10); ctx.lineTo(w, -10); ctx.lineTo(w-4, 35); ctx.lineTo(-w+4, 35);
        ctx.closePath();

        const grad = ctx.createLinearGradient(-w, 0, w, 0);
        grad.addColorStop(0, isHit ? '#fff' : '#0a1a4a'); // 深影
        grad.addColorStop(0.5, isHit ? '#fff' : '#1e40af'); // 主色
        grad.addColorStop(1, isHit ? '#fff' : '#0a1a4a');

        ctx.fillStyle = grad;
        ctx.fill();

        // B. 邊緣高光強化 (防止吃色)
        if (!isSil) {
            ctx.strokeStyle = '#fcd34d'; // 金質邊緣
            ctx.lineWidth = 1.2;
            ctx.stroke();

            // 內縮高光
            ctx.beginPath();
            ctx.moveTo(-w+4, -8); ctx.lineTo(w-4, -8);
            ctx.strokeStyle = 'rgba(255,255,255,0.3)';
            ctx.lineWidth = 0.8;
            ctx.stroke();
        }
        ctx.restore();
    },

    drawPauldrons(ctx: CanvasRenderingContext2D, isHit: boolean) {
        // 標誌性的動力裝甲大肩甲
        const drawPad = (side: number) => {
            ctx.save();
            ctx.translate(side * 18, -42);
            ctx.beginPath();
            ctx.ellipse(0, 0, 10, 14, side * 0.2, 0, Math.PI * 2);
            ctx.fillStyle = isHit ? '#fff' : '#1e40af';
            ctx.fill();
            ctx.strokeStyle = '#fbbf24'; // 金邊
            ctx.lineWidth = 2;
            ctx.stroke();
            ctx.restore();
        };
        drawPad(-1);
        drawPad(1);
    },

    drawPowerPack(ctx: CanvasRenderingContext2D, t: number, breathe: number) {
        // 背部動力包 (ECS 組件)
        ctx.save();
        ctx.translate(0, -40 + breathe * 0.5);
        ctx.fillStyle = '#0f172a';
        ctx.fillRect(-15, -10, 30, 20); // 主體

        // 排氣孔發光
        const glow = 0.5 + Math.sin(t * 5) * 0.5;
        ctx.fillStyle = '#60a5fa';
        ctx.globalAlpha = glow * 0.8;
        ctx.beginPath(); ctx.arc(-12, 0, 4, 0, Math.PI*2); ctx.fill();
        ctx.beginPath(); ctx.arc(12, 0, 4, 0, Math.PI*2); ctx.fill();
        ctx.restore();
    },

    drawMark(ctx: CanvasRenderingContext2D, isSil: boolean) {
        // 頭盔與戰團標誌
        ctx.save();
        ctx.translate(0, -52);
        ctx.fillStyle = '#f8fafc'; // 潔白頭盔
        ctx.beginPath(); ctx.arc(0, 0, 9, 0, Math.PI*2); ctx.fill();
        ctx.strokeStyle = '#1e40af';
        ctx.lineWidth = 1;
        ctx.stroke();

        if (!isSil) {
            // 紅色目鏡
            ctx.fillStyle = '#ef4444';
            ctx.beginPath(); 
            ctx.fillRect(-5, -2, 3, 2);
            ctx.fillRect(2, -2, 3, 2);
        }
        ctx.restore();
    },

    drawOrbitals(ctx: CanvasRenderingContext2D, t: number, breathe: number) {
        // 戰術掃描球 (浮空寶珠)
        ctx.save();
        for(let i=0; i<2; i++) {
            const angle = t * 2 + i * Math.PI;
            const ox = Math.cos(angle) * 30;
            const oy = Math.sin(angle * 0.5) * 10 - 40 + breathe;
            ctx.fillStyle = '#fff';
            ctx.shadowColor = '#60a5fa';
            ctx.shadowBlur = 10;
            ctx.beginPath(); ctx.arc(ox, oy, 2.5, 0, Math.PI*2); ctx.fill();
        }
        ctx.restore();
    },

    drawWeaponry(ctx: CanvasRenderingContext2D, agent: Agent, t: number, progress: number, breathe: number, isRunning: boolean) {
        const role = agent.role;
        const swing = Math.sin(progress * Math.PI);
        const weaponScale = isRunning ? 1.2 : 0.85;

        ctx.save();
        ctx.translate(22, -30 + breathe);
        ctx.rotate(swing * -1.2);
        ctx.scale(weaponScale, weaponScale);

        ctx.fillStyle = '#475569'; // 金屬原色
        ctx.strokeStyle = '#fbbf24'; // 金屬鑲邊

        if (role === Role.RANGER) {
            // 爆彈槍風格 (Bolter)
            ctx.fillRect(-12, -8, 24, 14);
            ctx.fillRect(2, 6, 8, 10); // 彈匣
            ctx.strokeStyle = '#fff';
            ctx.strokeRect(-12, -8, 24, 14);
        } else {
            // 能量劍
            ctx.lineWidth = 2;
            ctx.beginPath(); ctx.moveTo(0, 5); ctx.lineTo(0, -50); ctx.stroke();
            ctx.fillStyle = 'rgba(96, 165, 250, 0.4)';
            ctx.fillRect(-4, -45, 8, 40);
        }
        ctx.restore();
    }
};

import { Agent } from "../../../game";
import { AnimState, Role } from "../../../../types";
import { getCastProgress } from "../utils";
import { THEME_COVENANT } from "../../../../constants";

/**
 * 叛軍 (Covenant) 渲染器 v13.0 - 恐虐軍團風格
 * 核心：鮮血、黃銅、骨骼、無盡怒火
 */
export const CovenantRenderer = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean, isRunning: boolean) {
        const progress = agent.animState === AnimState.ATTACK ? getCastProgress(agent) : 0;
        const isHit = agent.hitFlashTimer > 0;

        // --- 1. 狂暴骨架動力學 (Berserker Skeleton) ---
        // 受擊或低血量時會產生強烈的高頻震顫
        const hpFactor = 1 - (agent.hp / agent.maxHp);
        const rageJitter = (isRunning ? Math.sin(t * 30) * (1 + hpFactor * 2) : 0);
        const breathe = Math.sin(t * 4) * 2;
        const hitShaker = isHit ? (Math.random() - 0.5) * 8 : 0;

        ctx.save();
        ctx.translate(rageJitter + hitShaker, 0);

        // --- 2. 被動特效層 (Blood & Spikes) ---
        if (!isSilhouette) this.drawTrophies(ctx, t, breathe);

        // --- 3. 核心軀幹 (Brass & Iron) ---
        ctx.save();
        ctx.translate(progress * 25 * agent.facing, breathe);
        this.drawJaggedArmor(ctx, agent.role, isHit, isSilhouette);
        this.drawBeastHelm(ctx, t, isSilhouette);
        ctx.restore();

        // --- 4. 武裝系統 (Chain Axes) ---
        this.drawChaosArsenal(ctx, agent, t, progress, breathe, isRunning);

        ctx.restore();
    },

    drawJaggedArmor(ctx: CanvasRenderingContext2D, role: Role, isHit: boolean, isSil: boolean) {
        const { primary, armorDark, accent } = THEME_COVENANT;
        ctx.save();
        ctx.translate(0, -35);

        // A. 鋸齒狀黃銅胸甲
        ctx.beginPath();
        const w = role === Role.TANK ? 24 : 18;
        ctx.moveTo(0, -15);
        ctx.lineTo(w, -10); ctx.lineTo(w-2, 10); ctx.lineTo(w+4, 25); ctx.lineTo(0, 45);
        ctx.lineTo(-w-4, 25); ctx.lineTo(-w+2, 10); ctx.lineTo(-w, -10);
        ctx.closePath();

        const grad = ctx.createLinearGradient(-w, 0, w, 0);
        grad.addColorStop(0, isHit ? '#fff' : '#2a0a0a');
        grad.addColorStop(0.5, isHit ? '#fff' : primary);
        grad.addColorStop(1, isHit ? '#fff' : '#2a0a0a');

        ctx.fillStyle = grad;
        ctx.fill();

        if (!isSil) {
            // 黃銅封邊
            ctx.strokeStyle = '#d97706';
            ctx.lineWidth = 1.5;
            ctx.stroke();

            // 乾涸血跡特效
            ctx.fillStyle = 'rgba(127, 29, 29, 0.6)';
            ctx.beginPath(); ctx.arc(-5, 10, 4, 0, Math.PI*2); ctx.fill();
            ctx.beginPath(); ctx.arc(8, 25, 3, 0, Math.PI*2); ctx.fill();
        }
        ctx.restore();
    },

    drawTrophies(ctx: CanvasRenderingContext2D, t: number, breathe: number) {
        // 恐虐尖刺與顱骨獎杯
        ctx.save();
        ctx.translate(0, -45 + breathe);
        ctx.fillStyle = '#1c1917';

        // 兩側尖刺
        for(let i=0; i<2; i++) {
            const side = i === 0 ? -1 : 1;
            ctx.beginPath();
            ctx.moveTo(side * 10, 0);
            ctx.lineTo(side * 25, -30 + Math.sin(t * 10) * 2);
            ctx.lineTo(side * 15, 0);
            ctx.fill();
        }

        // 懸掛顱骨 (簡化)
        ctx.fillStyle = '#fef2f2';
        ctx.beginPath(); ctx.arc(0, 5, 5, 0, Math.PI*2); ctx.fill();
        ctx.restore();
    },

    drawBeastHelm(ctx: CanvasRenderingContext2D, t: number, isSil: boolean) {
        ctx.save();
        ctx.translate(0, -55);

        // 經典恐虐「兔耳」頭盔飾件
        ctx.fillStyle = '#7f1d1d';
        ctx.beginPath();
        ctx.moveTo(-12, -15); ctx.lineTo(-8, 5); ctx.lineTo(-4, -5); ctx.fill();
        ctx.moveTo(12, -15); ctx.lineTo(8, 5); ctx.lineTo(4, -5); ctx.fill();

        // 骨質面具
        ctx.fillStyle = '#fef2f2';
        ctx.beginPath(); ctx.arc(0, 0, 8, 0, Math.PI*2); ctx.fill();

        if (!isSil) {
            const flicker = 0.7 + Math.sin(t * 20) * 0.3;
            ctx.fillStyle = '#ff0000';
            ctx.shadowBlur = 10 * flicker;
            ctx.shadowColor = '#f00';
            ctx.beginPath(); ctx.arc(-3, -1, 2, 0, Math.PI*2); ctx.fill();
            ctx.beginPath(); ctx.arc(3, -1, 2, 0, Math.PI*2); ctx.fill();
        }
        ctx.restore();
    },

    drawChaosArsenal(ctx: CanvasRenderingContext2D, agent: Agent, t: number, progress: number, breathe: number, isRunning: boolean) {
        const role = agent.role;
        const attackAngle = progress * Math.PI * 1.8;
        const scale = isRunning ? 1.4 : 1.0;

        ctx.save();
        ctx.translate(25, -28 + breathe);
        ctx.rotate(attackAngle);
        ctx.scale(scale, scale);

        if (role === Role.WARRIOR || role === Role.TANK) {
            // 鏈鋸斧 (Chain Axe)
            ctx.fillStyle = '#1c1917';
            ctx.fillRect(-6, -10, 12, 40); // 斧柄

            ctx.fillStyle = '#b91c1c';
            ctx.beginPath();
            ctx.moveTo(0, 0); ctx.lineTo(-25, -15); ctx.lineTo(-20, 25); ctx.lineTo(0, 15);
            ctx.fill();

            // 鋸齒旋轉動畫感
            if (isRunning) {
                ctx.strokeStyle = '#fff';
                ctx.setLineDash([2, 2]);
                ctx.lineDashOffset = t * 50;
                ctx.stroke();
            }
        } else {
            // 毀滅法杖或重弩
            ctx.fillStyle = '#450a0a';
            ctx.fillRect(-4, -30, 8, 60);
            ctx.shadowBlur = 15;
            ctx.shadowColor = '#f00';
            ctx.beginPath(); ctx.arc(0, -35, 10, 0, Math.PI*2); ctx.fill();
        }
        ctx.restore();
    }
};

import { Agent } from "../../../../game";
import { Team, AnimState, MovementType } from "../../../../../types";
import { UNIT_SCALE } from "../../../../../../../constants";
import { ImperialRenderer } from "../factions/ImperialRenderer";
import { CovenantRenderer } from "../factions/CovenantRenderer";
import { SpriteManager } from "../../../sprites";
import { VisualMath } from "../../../math/VisualMath";

/**
 * 單位主體繪製器 v13.0 (高階 TA 版)
 * 優化：邊緣光對比度增強、陣營文化識別
 */
export const UnitBodyPainter = {
    draw(
        ctx: CanvasRenderingContext2D, 
        agent: Agent, 
        px: number, py: number, pz: number, 
        t: number, 
        isSilhouette: boolean, 
        isSelected: boolean,
        scaleFactor: number,
        isRunning: boolean
    ) {
        ctx.save(); 

        // 1. 視覺定位
        const bodyY = VisualMath.getVisualBodyCenterY(py, pz);
        ctx.translate(px, bodyY); 

        // 2. 全局比例與物理偏差
        const baseScale = UNIT_SCALE * (isSelected ? 1.1 : 1.0);
        ctx.scale(baseScale, baseScale);
        ctx.rotate(agent.physics.angle); 

        // 3. 狀態濾鏡 (優化對比度)
        if (agent.hp <= 0 && !isSilhouette) {
            ctx.filter = 'grayscale(100%) contrast(80%) brightness(50%)'; 
        } else if (!isSilhouette && agent.hitFlashTimer > 0) {
             // 受擊時高對比閃爍
             ctx.filter = 'brightness(400%) saturate(0%)';
        }

        // 4. 方向處理
        ctx.scale(agent.facing > 0 ? 1 : -1, 1); 

        // 5. 陣營渲染 (傳遞運行狀態以觸發動態特效)
        if (isSilhouette) {
            ctx.globalAlpha = 0.4;
        }

        if (agent.team === Team.BLUE) {
            ImperialRenderer.draw(ctx, agent, t, isSilhouette, isRunning);
        } else {
            CovenantRenderer.draw(ctx, agent, t, isSilhouette, isRunning);
        }

        // 6. 選擇圈與腳底陰影 (如果需要在此層繪製)
        if (isSelected && !isSilhouette) {
            ctx.save();
            ctx.globalCompositeOperation = 'screen';
            ctx.strokeStyle = agent.team === Team.BLUE ? '#60a5fa' : '#ef4444';
            ctx.lineWidth = 2;
            ctx.beginPath();
            ctx.ellipse(0, 40, 25, 10, 0, 0, Math.PI * 2);
            ctx.stroke();
            ctx.restore();
        }

        ctx.restore(); 
    }
};

import { Agent } from "../../../game";
import { AnimState, Role } from "../../../../types";
import { getCastProgress } from "../utils";
import { THEME_IMPERIAL } from "../../../../constants";

/**
 * 帝國 (Imperial) 渲染器 v14.0 - 極限戰士【靈魂核心版】
 */
export const ImperialRenderer = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean, isRunning: boolean) {
        const progress = agent.animState === AnimState.ATTACK ? getCastProgress(agent) : 0;
        const isHit = agent.hitFlashTimer > 0;

        // --- 1. 骨架動力學 ---
        const breathe = Math.sin(t * 2) * 1.5;
        const hitJitter = isHit ? (Math.random() - 0.5) * 5 : 0;

        ctx.save();
        ctx.translate(hitJitter, 0);

        // --- 2. 裝甲背板 (動力包) ---
        if (!isSilhouette) this.drawPowerPack(ctx, t, breathe);

        // --- 3. 陶瓷裝甲主體 ---
        ctx.save();
        ctx.translate(0, breathe);
        this.drawCeramitePlate(ctx, agent.role, isHit, isSilhouette);
        this.drawSoulCore(ctx, t, isHit, isSilhouette); // 靈魂核心
        this.drawPauldrons(ctx, isHit);
        this.drawHelmet(ctx, isSilhouette);
        ctx.restore();

        // --- 4. 武器系統 ---
        this.drawArsenal(ctx, agent, t, progress, breathe, isRunning);

        ctx.restore();
    },

    drawCeramitePlate(ctx: CanvasRenderingContext2D, role: Role, isHit: boolean, isSil: boolean) {
        ctx.save();
        ctx.translate(0, -35);
        const w = role === Role.TANK ? 24 : 18;

        // 幾何外廓
        ctx.beginPath();
        ctx.moveTo(-w, -12); ctx.lineTo(w, -12); ctx.lineTo(w-4, 38); ctx.lineTo(-w+4, 38);
        ctx.closePath();

        // 鈷藍色漸變
        const grad = ctx.createLinearGradient(-w, 0, w, 0);
        grad.addColorStop(0, isHit ? '#fff' : '#1e3a8a');
        grad.addColorStop(0.5, isHit ? '#fff' : '#2563eb');
        grad.addColorStop(1, isHit ? '#fff' : '#1e3a8a');

        ctx.fillStyle = grad;
        ctx.fill();

        if (!isSil) {
            // 金質邊緣 (防止吃色)
            ctx.strokeStyle = '#fcd34d';
            ctx.lineWidth = 1.8;
            ctx.stroke();

            // 內縮高光
            ctx.strokeStyle = 'rgba(255,255,255,0.4)';
            ctx.lineWidth = 0.5;
            ctx.beginPath(); ctx.moveTo(-w+6, -10); ctx.lineTo(w-6, -10); ctx.stroke();
        }
        ctx.restore();
    },

    drawSoulCore(ctx: CanvasRenderingContext2D, t: number, isHit: boolean, isSil: boolean) {
        if (isSil) return;
        ctx.save();
        ctx.translate(0, -32);

        // 核心能量條 (靈魂概念)
        const coreWidth = 4;
        const coreHeight = 30;
        const pulse = 0.7 + Math.sin(t * 8) * 0.3;

        ctx.globalCompositeOperation = 'screen';
        const coreGrad = ctx.createLinearGradient(0, 0, 0, coreHeight);
        coreGrad.addColorStop(0, 'transparent');
        coreGrad.addColorStop(0.5, isHit ? '#fff' : '#60a5fa');
        coreGrad.addColorStop(1, 'transparent');

        ctx.fillStyle = coreGrad;
        ctx.shadowBlur = isHit ? 20 : 10;
        ctx.shadowColor = '#3b82f6';

        ctx.globalAlpha = pulse;
        ctx.fillRect(-coreWidth/2, 0, coreWidth, coreHeight);

        // 中心超載點
        if (isHit) {
            ctx.fillStyle = '#fff';
            ctx.beginPath(); ctx.arc(0, coreHeight/2, 3, 0, Math.PI*2); ctx.fill();
        }
        ctx.restore();
    },

    drawPowerPack(ctx: CanvasRenderingContext2D, t: number, breathe: number) {
        ctx.save();
        ctx.translate(0, -42 + breathe * 0.5);
        ctx.fillStyle = '#0f172a';
        ctx.fillRect(-16, -12, 32, 22);
        // 排氣口
        ctx.fillStyle = '#1e293b';
        ctx.beginPath(); ctx.arc(-12, -2, 5, 0, Math.PI*2); ctx.fill();
        ctx.beginPath(); ctx.arc(12, -2, 5, 0, Math.PI*2); ctx.fill();

        const glow = 0.4 + Math.sin(t * 10) * 0.2;
        ctx.fillStyle = '#60a5fa';
        ctx.globalAlpha = glow;
        ctx.beginPath(); ctx.arc(-12, -2, 3, 0, Math.PI*2); ctx.fill();
        ctx.beginPath(); ctx.arc(12, -2, 3, 0, Math.PI*2); ctx.fill();
        ctx.restore();
    },

    drawPauldrons(ctx: CanvasRenderingContext2D, isHit: boolean) {
        const drawPad = (s: number) => {
            ctx.save();
            ctx.translate(s * 20, -45);
            ctx.beginPath();
            ctx.ellipse(0, 0, 11, 15, s * 0.15, 0, Math.PI*2);
            ctx.fillStyle = isHit ? '#fff' : '#1e40af';
            ctx.fill();
            ctx.strokeStyle = '#fcd34d';
            ctx.lineWidth = 2.5;
            ctx.stroke();
            ctx.restore();
        };
        drawPad(-1); drawPad(1);
    },

    drawHelmet(ctx: CanvasRenderingContext2D, isSil: boolean) {
        ctx.save();
        ctx.translate(0, -58);
        ctx.fillStyle = '#f8fafc';
        ctx.beginPath(); ctx.arc(0, 0, 10, 0, Math.PI*2); ctx.fill();
        ctx.strokeStyle = '#1e3a8a';
        ctx.lineWidth = 1.2;
        ctx.stroke();
        if (!isSil) {
            ctx.fillStyle = '#ef4444';
            ctx.fillRect(-6, -2, 4, 2); ctx.fillRect(2, -2, 4, 2);
        }
        ctx.restore();
    },

    drawArsenal(ctx: CanvasRenderingContext2D, agent: Agent, t: number, progress: number, breathe: number, isRunning: boolean) {
        const swing = Math.sin(progress * Math.PI);
        const scale = isRunning ? 1.3 : 0.9;
        ctx.save();
        ctx.translate(26, -30 + breathe);
        ctx.rotate(swing * -1.5);
        ctx.scale(scale, scale);

        ctx.fillStyle = '#475569';
        ctx.strokeStyle = '#fcd34d';
        ctx.lineWidth = 2;

        if (agent.role === Role.RANGER) {
            ctx.fillRect(-14, -8, 28, 16);
            ctx.strokeRect(-14, -8, 28, 16);
        } else {
            ctx.beginPath(); ctx.moveTo(0, 8); ctx.lineTo(0, -55); ctx.stroke();
            ctx.fillStyle = 'rgba(96, 165, 250, 0.4)';
            ctx.fillRect(-4, -50, 8, 45);
        }
        ctx.restore();
    }
};

import { Agent } from "../../../game";
import { AnimState, Role } from "../../../../types";
import { getCastProgress } from "../utils";
import { THEME_COVENANT } from "../../../../constants";

/**
 * 叛軍 (Covenant) 渲染器 v14.0 - 恐虐戰團【鮮血核心版】
 */
export const CovenantRenderer = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean, isRunning: boolean) {
        const progress = agent.animState === AnimState.ATTACK ? getCastProgress(agent) : 0;
        const isHit = agent.hitFlashTimer > 0;

        // --- 1. 狂暴動力學 (Chaos Jitter) ---
        const hpFactor = 1 - (agent.hp / agent.maxHp);
        const intensity = isRunning ? (2 + hpFactor * 6) : 0.5;
        const jitterX = (Math.random() - 0.5) * intensity;
        const jitterY = (Math.random() - 0.5) * intensity;
        const breathe = Math.sin(t * 4) * 2;

        ctx.save();
        ctx.translate(jitterX, jitterY);

        // --- 2. 外部裝飾 (尖刺) ---
        if (!isSilhouette) this.drawChaosSpikes(ctx, t, breathe);

        // --- 3. 核心軀幹 (黃銅與鋼) ---
        ctx.save();
        ctx.translate(progress * 28 * agent.facing, breathe);
        this.drawJaggedArmor(ctx, agent.role, isHit, isSilhouette);
        this.drawBloodCore(ctx, t, isHit, isSilhouette); // 鮮血核心
        this.drawBeastHelm(ctx, t, isSilhouette);
        ctx.restore();

        // --- 4. 混沌武裝 ---
        this.drawHeavyArsenal(ctx, agent, t, progress, breathe, isRunning);

        ctx.restore();
    },

    drawJaggedArmor(ctx: CanvasRenderingContext2D, role: Role, isHit: boolean, isSil: boolean) {
        ctx.save();
        ctx.translate(0, -35);
        const w = role === Role.TANK ? 26 : 20;

        ctx.beginPath();
        ctx.moveTo(0, -15); ctx.lineTo(w, -8); ctx.lineTo(w-4, 15); ctx.lineTo(w+2, 45);
        ctx.lineTo(0, 55); ctx.lineTo(-w-2, 45); ctx.lineTo(-w+4, 15); ctx.lineTo(-w, -8);
        ctx.closePath();

        const grad = ctx.createLinearGradient(-w, 0, w, 0);
        grad.addColorStop(0, isHit ? '#fff' : '#2a0a0a');
        grad.addColorStop(0.5, isHit ? '#fff' : '#7f1d1d');
        grad.addColorStop(1, isHit ? '#fff' : '#2a0a0a');

        ctx.fillStyle = grad;
        ctx.fill();

        if (!isSil) {
            ctx.strokeStyle = '#d97706'; // 氧化黃銅
            ctx.lineWidth = 1.5;
            ctx.stroke();

            // 乾涸血跡
            ctx.fillStyle = 'rgba(69, 10, 10, 0.6)';
            ctx.beginPath(); ctx.arc(-8, 20, 5, 0, Math.PI*2); ctx.fill();
        }
        ctx.restore();
    },

    drawBloodCore(ctx: CanvasRenderingContext2D, t: number, isHit: boolean, isSil: boolean) {
        if (isSil) return;
        ctx.save();
        ctx.translate(0, -25);

        // 混沌靈魂核心 - 不穩定、斷裂的能量條
        const pulse = 0.5 + Math.sin(t * 25) * 0.5; // 極高頻脈動
        const h = 40;

        ctx.globalCompositeOperation = 'lighter';
        const coreGrad = ctx.createLinearGradient(0, 0, 0, h);
        coreGrad.addColorStop(0, '#f87171');
        coreGrad.addColorStop(0.5, isHit ? '#fff' : '#ef4444');
        coreGrad.addColorStop(1, '#450a0a');

        ctx.fillStyle = coreGrad;
        ctx.globalAlpha = pulse * 0.8;

        // 繪製非連續的能量斷片
        for(let i=0; i<3; i++) {
            const segmentY = (i * h/3) + (Math.sin(t * 15 + i) * 3);
            ctx.fillRect(-2, segmentY, 4, 8);
        }

        ctx.shadowBlur = 15;
        ctx.shadowColor = '#f00';
        ctx.restore();
    },

    drawChaosSpikes(ctx: CanvasRenderingContext2D, t: number, breathe: number) {
        ctx.save();
        ctx.translate(0, -45 + breathe);
        ctx.fillStyle = '#18181b';
        ctx.beginPath();
        ctx.moveTo(-15, 0); ctx.lineTo(-30, -35); ctx.lineTo(-10, -5); ctx.fill();
        ctx.moveTo(15, 0); ctx.lineTo(30, -35); ctx.lineTo(10, -5); ctx.fill();
        ctx.restore();
    },

    drawBeastHelm(ctx: CanvasRenderingContext2D, t: number, isSil: boolean) {
        ctx.save();
        ctx.translate(0, -60);
        // 經典恐虐角
        ctx.fillStyle = '#450a0a';
        ctx.beginPath();
        ctx.moveTo(-12, -18); ctx.lineTo(-8, 5); ctx.lineTo(-2, -8); ctx.fill();
        ctx.moveTo(12, -18); ctx.lineTo(8, 5); ctx.lineTo(2, -8); ctx.fill();

        ctx.fillStyle = '#fef2f2'; // 骨色
        ctx.beginPath(); ctx.arc(0, 0, 9, 0, Math.PI*2); ctx.fill();

        if (!isSil) {
            const flicker = Math.random() > 0.8 ? 1.0 : 0.5;
            ctx.fillStyle = '#ff0000';
            ctx.shadowBlur = 10; ctx.shadowColor = '#f00';
            ctx.globalAlpha = flicker;
            ctx.beginPath(); ctx.arc(-3, 0, 2.5, 0, Math.PI*2); ctx.fill();
            ctx.beginPath(); ctx.arc(3, 0, 2.5, 0, Math.PI*2); ctx.fill();
        }
        ctx.restore();
    },

    drawHeavyArsenal(ctx: CanvasRenderingContext2D, agent: Agent, t: number, progress: number, breathe: number, isRunning: boolean) {
        const attackAngle = progress * Math.PI * 1.8;
        const scale = isRunning ? 1.45 : 1.0;

        ctx.save();
        ctx.translate(28, -25 + breathe);
        ctx.rotate(attackAngle);
        ctx.scale(scale, scale);

        if (agent.role === Role.WARRIOR || agent.role === Role.TANK) {
            // 鏈鋸斧
            ctx.fillStyle = '#1c1917';
            ctx.fillRect(-6, -5, 12, 45); 
            ctx.fillStyle = '#b91c1c';
            ctx.beginPath();
            ctx.moveTo(0, 0); ctx.lineTo(-35, -15); ctx.lineTo(-30, 35); ctx.lineTo(0, 20);
            ctx.fill();
            if (isRunning) {
                ctx.strokeStyle = '#fff';
                ctx.setLineDash([3, 3]);
                ctx.lineDashOffset = t * -60;
                ctx.stroke();
            }
        } else {
            ctx.fillStyle = '#450a0a';
            ctx.beginPath(); ctx.arc(0, -35, 12, 0, Math.PI*2); ctx.fill();
            ctx.strokeStyle = '#f00'; ctx.stroke();
        }
        ctx.restore();
    }
};

import { Role, Team } from "../../../types";
import { ISO_SCALE_Y } from "../../../constants";
import { createCanvas } from "../CanvasUtils";

const BASE_SIZE = 128;
const ICON_SIZE = 64;

export const ImperialTokenFactory = {

    generateBase(): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(BASE_SIZE, BASE_SIZE);
        const cx = BASE_SIZE / 2;
        const cy = BASE_SIZE / 2;
        const radius = 38;
        const thickness = 10;

        ctx.translate(cx, cy);

        // 1. 底座側面 (厚度感)
        ctx.save();
        ctx.scale(1, ISO_SCALE_Y);
        ctx.fillStyle = '#0f172a'; // 深色金屬
        for(let i=0; i<thickness; i++) {
            ctx.beginPath(); ctx.arc(0, i, radius, 0, Math.PI*2); ctx.fill();
        }
        ctx.restore();

        // 2. 頂部表面
        ctx.save();
        ctx.scale(1, ISO_SCALE_Y);
        const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, radius);
        grad.addColorStop(0, '#1e40af'); // 鈷藍
        grad.addColorStop(1, '#0a1a4a');
        ctx.fillStyle = grad;
        ctx.beginPath(); ctx.arc(0, 0, radius, 0, Math.PI*2); ctx.fill();

        // 3. 金色飾邊 (Gold Emboss)
        ctx.strokeStyle = '#fcd34d';
        ctx.lineWidth = 3;
        ctx.stroke();
        ctx.strokeStyle = '#b45309';
        ctx.lineWidth = 1;
        ctx.beginPath(); ctx.arc(0, 0, radius-2, 0, Math.PI*2); ctx.stroke();

        // 4. 戰團符號裝飾
        ctx.globalAlpha = 0.15;
        ctx.fillStyle = '#fff';
        ctx.font = 'bold 28px serif';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('U', 0, 0);
        ctx.restore();

        return canvas;
    },

    generateIcon(role: Role): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(ICON_SIZE, ICON_SIZE);
        const color = '#60a5fa';
        ctx.translate(ICON_SIZE/2, ICON_SIZE/2);
        ctx.strokeStyle = color;
        ctx.lineWidth = 3;
        ctx.shadowBlur = 10; ctx.shadowColor = color;

        ctx.beginPath();
        if (role === Role.TANK) { ctx.rect(-12, -12, 24, 24); }
        else if (role === Role.WARRIOR) { ctx.moveTo(-12, -12); ctx.lineTo(12, 12); ctx.moveTo(12, -12); ctx.lineTo(-12, 12); }
        else if (role === Role.RANGER) { ctx.arc(0, 0, 10, 0, Math.PI*2); ctx.moveTo(0, -15); ctx.lineTo(0, 15); ctx.moveTo(-15, 0); ctx.lineTo(15, 0); }
        else { ctx.moveTo(0, 12); ctx.lineTo(0, -12); ctx.lineTo(10, 0); ctx.closePath(); }
        ctx.stroke();

        return canvas;
    }
};

import { Role, Team } from "../../../types";
import { ISO_SCALE_Y } from "../../../constants";
import { createCanvas } from "../CanvasUtils";

const BASE_SIZE = 128;
const ICON_SIZE = 64;

export const CovenantTokenFactory = {

    generateBase(): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(BASE_SIZE, BASE_SIZE);
        const cx = BASE_SIZE / 2;
        const cy = BASE_SIZE / 2;
        const radius = 38;
        const thickness = 12;

        ctx.translate(cx, cy);

        // 1. 粗糙側面
        ctx.save();
        ctx.scale(1, ISO_SCALE_Y);
        ctx.fillStyle = '#1c1917';
        for(let i=0; i<thickness; i++) {
            ctx.beginPath();
            for(let j=0; j<8; j++) {
                const a = j * Math.PI/4;
                const r = radius * (j%2===0 ? 1 : 0.95);
                ctx.lineTo(Math.cos(a)*r, Math.sin(a)*r + i);
            }
            ctx.closePath();
            ctx.fill();
        }
        ctx.restore();

        // 2. 頂部表面 (血跡黃銅)
        ctx.save();
        ctx.scale(1, ISO_SCALE_Y);
        const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, radius);
        grad.addColorStop(0, '#7f1d1d'); // 血紅
        grad.addColorStop(1, '#2a0a0a');
        ctx.fillStyle = grad;

        ctx.beginPath();
        for(let j=0; j<8; j++) {
            const a = j * Math.PI/4;
            const r = radius * (j%2===0 ? 1 : 0.95);
            ctx.lineTo(Math.cos(a)*r, Math.sin(a)*r);
        }
        ctx.closePath();
        ctx.fill();

        // 3. 蝕刻黃銅邊緣
        ctx.strokeStyle = '#d97706';
        ctx.lineWidth = 2;
        ctx.stroke();

        // 4. 恐虐符號印記
        ctx.globalAlpha = 0.2;
        ctx.fillStyle = '#000';
        ctx.beginPath(); ctx.moveTo(-10, -10); ctx.lineTo(10, 10); ctx.moveTo(10, -10); ctx.lineTo(-10, 10); ctx.stroke();
        ctx.restore();

        return canvas;
    },

    generateIcon(role: Role): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(ICON_SIZE, ICON_SIZE);
        const color = '#ef4444';
        ctx.translate(ICON_SIZE/2, ICON_SIZE/2);
        ctx.strokeStyle = color;
        ctx.lineWidth = 3;
        ctx.shadowBlur = 12; ctx.shadowColor = color;

        ctx.beginPath();
        if (role === Role.TANK) { ctx.moveTo(-12, -12); ctx.lineTo(12, -12); ctx.lineTo(0, 15); ctx.closePath(); }
        else if (role === Role.WARRIOR) { ctx.moveTo(-15, 0); ctx.lineTo(15, 0); ctx.moveTo(0, -15); ctx.lineTo(0, 15); }
        else if (role === Role.RANGER) { ctx.rect(-10, -10, 20, 20); ctx.moveTo(-15, -15); ctx.lineTo(15, 15); }
        else { ctx.arc(0, 0, 8, 0, Math.PI*2); ctx.moveTo(-12, -12); ctx.lineTo(12, 12); }
        ctx.stroke();

        return canvas;
    }
};

import { ZoneRenderer } from "./ZoneRenderer";
import { HazardPainter } from "./painters/HazardPainter"; 
import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { GroundHazard, HexLayout } from "../../../types";
import { STATUS_VISUALS } from "../../../data/vfx/status_visuals";
import { ActiveZone } from "../../systems/ZoneSystem";
import { HexUtils } from "../../utils";

const OVERLAY_LIFT = -3;
const HAZARD_LIFT = -10;

export const GridOverlays = {

    drawOverlays(
        ctx: CanvasRenderingContext2D,
        x: number, y: number, 
        size: number,
        specialStatus: string | undefined, 
        zoneInfo: ActiveZone | undefined,    
        lightColor: string | null,
        lightIntensity: number,
        isRange: boolean,
        rangeColor: string,
        isHover: boolean,
        hasUnit: boolean,
        q: number, r: number,
        globalTime: number,
        hazard: GroundHazard | undefined,
        layout: HexLayout
    ) {
        const drawY = y + OVERLAY_LIFT;

        // 1. 地形危害效果
        if (hazard) {
            HazardPainter.draw(ctx, x, y + HAZARD_LIFT, hazard, globalTime);
        }

        // 2. 狀態地表染色 (例如：冰凍、中毒)
        if (specialStatus && specialStatus !== 'NONE') {
            const def = STATUS_VISUALS[specialStatus];
            if (def && def.floorColor) {
                ctx.save();
                ctx.translate(x, drawY);
                ctx.fillStyle = def.floorColor;
                ctx.globalAlpha = def.floorOpacity || 0.4;
                HexGeometry.traceHex(ctx, 0, 0, size, true, layout);
                ctx.fill();
                ctx.restore();
            }
        }

        // 3. 戰術掃描線 (修復網格感)
        this.drawTacticalGrid(ctx, x, drawY, size, globalTime, isHover, layout);

        // 4. 技能區域指示
        if (zoneInfo) {
            const dist = HexUtils.dist({q, r}, {q: zoneInfo.q, r: zoneInfo.r});
            ZoneRenderer.drawTileZoneEffect(ctx, x, drawY, size, dist, zoneInfo.radius, zoneInfo.color, zoneInfo.progress, zoneInfo.isEnemy, layout);
        }

        // 5. 動態光源 (投射物經過時)
        if (lightColor && lightIntensity > 0) {
            ctx.save();
            ctx.translate(x, drawY);
            ctx.globalCompositeOperation = 'screen'; 
            ctx.fillStyle = lightColor;
            ctx.globalAlpha = Math.min(0.5, lightIntensity * 0.4);
            HexGeometry.traceHex(ctx, 0, 0, size, true, layout);
            ctx.fill();
            ctx.restore();
        }

        // 6. 交互高亮 (射程/懸停)
        if (isRange || isHover || hasUnit) {
            ctx.save();
            ctx.translate(x, drawY);
            ctx.globalCompositeOperation = 'screen';

            if (isRange) { 
                ctx.fillStyle = rangeColor;
                ctx.globalAlpha = 0.2;
                HexGeometry.traceHex(ctx, 0, 0, size * 0.9, true, layout);
                ctx.fill();
                ctx.strokeStyle = rangeColor;
                ctx.lineWidth = 1.5;
                HexGeometry.traceHex(ctx, 0, 0, size * 0.95, true, layout);
                ctx.stroke();
            }

            if (isHover) { 
                ctx.strokeStyle = '#ffffff';
                ctx.lineWidth = 2.5;
                ctx.globalAlpha = 0.8;
                ctx.shadowBlur = 10; ctx.shadowColor = '#fff';
                HexGeometry.traceHex(ctx, 0, 0, size, true, layout);
                ctx.stroke();
            }

            ctx.restore();
        }
    },

    drawTacticalGrid(ctx: CanvasRenderingContext2D, x: number, y: number, size: number, t: number, isHover: boolean, layout: HexLayout) {
        ctx.save();
        ctx.translate(x, y);

        // 基礎網格線 (極細、冷色調)
        ctx.strokeStyle = 'rgba(255, 255, 255, 0.08)';
        ctx.lineWidth = 0.5;
        HexGeometry.traceHex(ctx, 0, 0, size, true, layout);
        ctx.stroke();

        // 戰術掃描動態線 (掃過感)
        const scanY = (Math.sin(t * 1.5 + x * 0.01) * 0.5 + 0.5);
        if (scanY > 0.9 || isHover) {
            ctx.strokeStyle = 'rgba(255, 255, 255, 0.2)';
            ctx.lineWidth = 1;
            HexGeometry.traceHex(ctx, 0, 0, size * 0.98, true, layout);
            ctx.stroke();
        }

        ctx.restore();
    }
};

import { Agent } from "../../../game";
import { AnimState, Role } from "../../../../types";
import { getCastProgress } from "../utils";
import { THEME_IMPERIAL } from "../../../../constants";
import { HexGeometry } from "../../../graphics/utils/HexGeometry";

/**
 * 帝國 (Imperial) 渲染器 v15.0 - 極限戰士【純幾何版】
 * 嚴禁任何圓形，所有組件由六邊形構成
 */
export const ImperialRenderer = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean, isRunning: boolean) {
        const progress = agent.animState === AnimState.ATTACK ? getCastProgress(agent) : 0;
        const isHit = agent.hitFlashTimer > 0;

        // --- 1. 機械化動力學 ---
        const breathe = Math.sin(t * 1.8) * 1.5;
        const hitJitter = isHit ? (Math.random() - 0.5) * 6 : 0;

        ctx.save();
        ctx.translate(hitJitter, 0);

        // --- 2. 幾何裝甲組件 ---
        if (!isSilhouette) {
            this.drawHexPowerPack(ctx, t, breathe);
        }

        // --- 3. 陶瓷裝甲主體 (六邊形堆疊) ---
        ctx.save();
        ctx.translate(0, breathe);
        this.drawCeramiteChassis(ctx, agent.role, isHit, isSilhouette);
        this.drawSoulCoreHex(ctx, t, isHit, isSilhouette); // 六邊形靈魂核心
        this.drawPolyPauldrons(ctx, isHit);
        this.drawPolyHelmet(ctx, isSilhouette);
        ctx.restore();

        // --- 4. 武器系統 (硬邊化) ---
        this.drawArsenal(ctx, agent, t, progress, breathe, isRunning);

        ctx.restore();
    },

    drawCeramiteChassis(ctx: CanvasRenderingContext2D, role: Role, isHit: boolean, isSil: boolean) {
        ctx.save();
        ctx.translate(0, -35);
        const w = role === Role.TANK ? 24 : 18;

        // 使用 traceHex 代替 moveTo 組合，確保 2.5D 比例
        const baseColor = isHit ? '#fff' : '#1e3a8a';
        const rimColor = '#fcd34d';

        ctx.fillStyle = baseColor;
        HexGeometry.traceHex(ctx, 0, 15, w, true); // 下半截裝甲
        ctx.fill();
        HexGeometry.traceHex(ctx, 0, -10, w * 0.8, true); // 上半截裝甲
        ctx.fill();

        if (!isSil) {
            ctx.strokeStyle = rimColor;
            ctx.lineWidth = 1.5;
            HexGeometry.traceHex(ctx, 0, 15, w, true); ctx.stroke();
            HexGeometry.traceHex(ctx, 0, -10, w * 0.8, true); ctx.stroke();
        }
        ctx.restore();
    },

    drawSoulCoreHex(ctx: CanvasRenderingContext2D, t: number, isHit: boolean, isSil: boolean) {
        if (isSil) return;
        ctx.save();
        ctx.translate(0, -32);

        // 核心改為窄長的六邊形柱
        const h = 35;
        const w = 4;
        const pulse = 0.6 + Math.sin(t * 8) * 0.4;

        ctx.globalCompositeOperation = 'screen';
        ctx.fillStyle = isHit ? '#fff' : '#60a5fa';
        ctx.shadowBlur = isHit ? 20 : 10;
        ctx.shadowColor = '#3b82f6';

        ctx.globalAlpha = pulse;
        // 繪製三個垂直堆疊的微型六邊形形成「能量條」
        for(let i=0; i<3; i++) {
            HexGeometry.traceHex(ctx, 0, i * 12, w, true);
            ctx.fill();
        }
        ctx.restore();
    },

    drawHexPowerPack(ctx: CanvasRenderingContext2D, t: number, breathe: number) {
        ctx.save();
        ctx.translate(0, -45 + breathe * 0.5);
        ctx.fillStyle = '#0f172a';

        // 主體背板 - 大六邊形
        HexGeometry.traceHex(ctx, 0, 0, 16, true);
        ctx.fill();

        // 兩側排氣口 - 小六邊形
        const glow = 0.5 + Math.sin(t * 12) * 0.3;
        ctx.fillStyle = '#1e293b';
        HexGeometry.traceHex(ctx, -14, 2, 6, true); ctx.fill();
        HexGeometry.traceHex(ctx, 14, 2, 6, true); ctx.fill();

        ctx.fillStyle = '#60a5fa';
        ctx.globalAlpha = glow;
        HexGeometry.traceHex(ctx, -14, 2, 3, true); ctx.fill();
        HexGeometry.traceHex(ctx, 14, 2, 3, true); ctx.fill();
        ctx.restore();
    },

    drawPolyPauldrons(ctx: CanvasRenderingContext2D, isHit: boolean) {
        const drawPad = (s: number) => {
            ctx.save();
            ctx.translate(s * 22, -45);
            // 肩甲改為旋轉的六邊形，強化 40K 的厚重感
            ctx.fillStyle = isHit ? '#fff' : '#1e40af';
            HexGeometry.traceRotatedHex(ctx, 0, 0, 12, s * 0.5, true);
            ctx.fill();
            ctx.strokeStyle = '#fcd34d';
            ctx.lineWidth = 2;
            HexGeometry.traceRotatedHex(ctx, 0, 0, 12, s * 0.5, true);
            ctx.stroke();
            ctx.restore();
        };
        drawPad(-1); drawPad(1);
    },

    drawPolyHelmet(ctx: CanvasRenderingContext2D, isSil: boolean) {
        ctx.save();
        ctx.translate(0, -60);
        // 頭盔改為正六邊形
        ctx.fillStyle = '#f8fafc';
        HexGeometry.traceHex(ctx, 0, 0, 10, true);
        ctx.fill();
        ctx.strokeStyle = '#1e3a8a';
        ctx.lineWidth = 1.5;
        HexGeometry.traceHex(ctx, 0, 0, 10, true);
        ctx.stroke();

        if (!isSil) {
            // 目鏡改為菱形 (兩個三角形組合)
            ctx.fillStyle = '#ef4444';
            ctx.beginPath();
            ctx.moveTo(-7, -1); ctx.lineTo(-4, -3); ctx.lineTo(-1, -1); ctx.lineTo(-4, 1); ctx.closePath();
            ctx.fill();
            ctx.beginPath();
            ctx.moveTo(7, -1); ctx.lineTo(4, -3); ctx.lineTo(1, -1); ctx.lineTo(4, 1); ctx.closePath();
            ctx.fill();
        }
        ctx.restore();
    },

    drawArsenal(ctx: CanvasRenderingContext2D, agent: Agent, t: number, progress: number, breathe: number, isRunning: boolean) {
        const swing = Math.sin(progress * Math.PI);
        const scale = isRunning ? 1.3 : 0.9;
        ctx.save();
        ctx.translate(28, -32 + breathe);
        ctx.rotate(swing * -1.5);
        ctx.scale(scale, scale);

        ctx.fillStyle = '#475569';
        ctx.strokeStyle = '#fcd34d';
        ctx.lineWidth = 2;

        if (agent.role === Role.RANGER) {
            // 六邊形風格爆彈槍
            ctx.beginPath();
            ctx.moveTo(-15, -8); ctx.lineTo(15, -8); ctx.lineTo(18, 0); ctx.lineTo(15, 8); ctx.lineTo(-15, 8); ctx.closePath();
            ctx.fill(); ctx.stroke();
        } else {
            // 幾何光劍
            ctx.beginPath(); 
            ctx.moveTo(0, 10); ctx.lineTo(-4, 0); ctx.lineTo(0, -55); ctx.lineTo(4, 0); ctx.closePath();
            ctx.stroke();
            ctx.fillStyle = 'rgba(96, 165, 250, 0.5)';
            ctx.fill();
        }
        ctx.restore();
    }
};

import { Agent } from "../../../game";
import { AnimState, Role } from "../../../../types";
import { getCastProgress } from "../utils";
import { THEME_COVENANT } from "../../../../constants";
import { HexGeometry } from "../../../graphics/utils/HexGeometry";

/**
 * 叛軍 (Covenant) 渲染器 v15.0 - 恐虐戰團【鮮血幾何版】
 */
export const CovenantRenderer = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean, isRunning: boolean) {
        const progress = agent.animState === AnimState.ATTACK ? getCastProgress(agent) : 0;
        const isHit = agent.hitFlashTimer > 0;

        // --- 1. 狂暴動力學 ---
        const hpFactor = 1 - (agent.hp / agent.maxHp);
        const intensity = isRunning ? (3 + hpFactor * 7) : 1;
        const jitterX = (Math.random() - 0.5) * intensity;
        const jitterY = (Math.random() - 0.5) * intensity;
        const breathe = Math.sin(t * 4.5) * 2;

        ctx.save();
        ctx.translate(jitterX, jitterY);

        // --- 2. 外部飾件 (尖刺) ---
        if (!isSilhouette) this.drawJaggedSpikes(ctx, t, breathe);

        // --- 3. 核心軀幹 (粗獷幾何) ---
        ctx.save();
        ctx.translate(progress * 30 * agent.facing, breathe);
        this.drawBrutalArmor(ctx, agent.role, isHit, isSilhouette);
        this.drawJaggedBloodCore(ctx, t, isHit, isSilhouette); // 破碎血核
        this.drawSkullHelm(ctx, t, isSilhouette);
        ctx.restore();

        // --- 4. 混沌武器 ---
        this.drawHeavyWeaponry(ctx, agent, t, progress, breathe, isRunning);

        ctx.restore();
    },

    drawBrutalArmor(ctx: CanvasRenderingContext2D, role: Role, isHit: boolean, isSil: boolean) {
        ctx.save();
        ctx.translate(0, -35);
        const w = role === Role.TANK ? 28 : 22;

        // 幾何形狀：鋸齒狀六邊形
        ctx.beginPath();
        ctx.moveTo(0, -18);
        ctx.lineTo(w, -10); ctx.lineTo(w-4, 15); ctx.lineTo(w+5, 40);
        ctx.lineTo(0, 58);
        ctx.lineTo(-w-5, 40); ctx.lineTo(-w+4, 15); ctx.lineTo(-w, -10);
        ctx.closePath();

        ctx.fillStyle = isHit ? '#fff' : '#2a0a0a';
        ctx.fill();

        if (!isSil) {
            ctx.strokeStyle = '#d97706'; // 氧化黃銅
            ctx.lineWidth = 1.8;
            ctx.stroke();

            // 刻痕細節
            ctx.strokeStyle = '#450a0a';
            ctx.beginPath(); ctx.moveTo(-w+10, 10); ctx.lineTo(-w+15, 20); ctx.stroke();
            ctx.beginPath(); ctx.moveTo(w-10, 30); ctx.lineTo(w-15, 40); ctx.stroke();
        }
        ctx.restore();
    },

    drawJaggedBloodCore(ctx: CanvasRenderingContext2D, t: number, isHit: boolean, isSil: boolean) {
        if (isSil) return;
        ctx.save();
        ctx.translate(0, -25);

        // 核心改為斷裂的鋸齒狀線條
        const h = 45;
        const pulse = 0.4 + Math.random() * 0.6; // 高頻閃爍

        ctx.globalCompositeOperation = 'lighter';
        ctx.strokeStyle = isHit ? '#fff' : '#ef4444';
        ctx.lineWidth = 4;
        ctx.shadowBlur = 15;
        ctx.shadowColor = '#f00';

        ctx.globalAlpha = pulse;
        ctx.beginPath();
        ctx.moveTo(0, 0);
        for(let i=1; i<5; i++) {
            ctx.lineTo((Math.random()-0.5)*10, i * h/4);
        }
        ctx.stroke();
        ctx.restore();
    },

    drawJaggedSpikes(ctx: CanvasRenderingContext2D, t: number, breathe: number) {
        ctx.save();
        ctx.translate(0, -45 + breathe);
        ctx.fillStyle = '#111';
        // 兩側骨刺改為尖銳多邊形
        const drawSpike = (side: number) => {
            ctx.beginPath();
            ctx.moveTo(side * 12, 0);
            ctx.lineTo(side * 35, -40);
            ctx.lineTo(side * 8, -5);
            ctx.closePath();
            ctx.fill();
            ctx.strokeStyle = '#7f1d1d';
            ctx.stroke();
        };
        drawSpike(-1); drawSpike(1);
        ctx.restore();
    },

    drawSkullHelm(ctx: CanvasRenderingContext2D, t: number, isSil: boolean) {
        ctx.save();
        ctx.translate(0, -62);

        // 經典恐虐角 - 多邊形化
        ctx.fillStyle = '#450a0a';
        ctx.beginPath();
        ctx.moveTo(-15, -25); ctx.lineTo(-10, 5); ctx.lineTo(-2, -5); ctx.closePath(); ctx.fill();
        ctx.beginPath();
        ctx.moveTo(15, -25); ctx.lineTo(10, 5); ctx.lineTo(2, -5); ctx.closePath(); ctx.fill();

        // 骨質面具 - 六邊形
        ctx.fillStyle = '#fef2f2';
        HexGeometry.traceHex(ctx, 0, 0, 11, true);
        ctx.fill();

        if (!isSil) {
            ctx.fillStyle = '#ff0000';
            ctx.shadowBlur = 12; ctx.shadowColor = '#f00';
            // 眼眶 - 三角形
            ctx.beginPath(); ctx.moveTo(-6, -2); ctx.lineTo(-2, -4); ctx.lineTo(-2, 0); ctx.closePath(); ctx.fill();
            ctx.beginPath(); ctx.moveTo(6, -2); ctx.lineTo(2, -4); ctx.lineTo(2, 0); ctx.closePath(); ctx.fill();
        }
        ctx.restore();
    },

    drawHeavyWeaponry(ctx: CanvasRenderingContext2D, agent: Agent, t: number, progress: number, breathe: number, isRunning: boolean) {
        const attackAngle = progress * Math.PI * 1.9;
        const scale = isRunning ? 1.5 : 1.0;

        ctx.save();
        ctx.translate(30, -28 + breathe);
        ctx.rotate(attackAngle);
        ctx.scale(scale, scale);

        if (agent.role === Role.WARRIOR || agent.role === Role.TANK) {
            // 幾何鏈鋸斧
            ctx.fillStyle = '#1c1917';
            ctx.fillRect(-6, -5, 12, 50); 
            ctx.fillStyle = '#b91c1c';
            ctx.beginPath();
            ctx.moveTo(0, 0); ctx.lineTo(-40, -10); ctx.lineTo(-35, 40); ctx.lineTo(0, 25); ctx.closePath();
            ctx.fill();
            ctx.strokeStyle = '#d97706'; ctx.stroke();
        } else {
            // 混沌法杖
            ctx.fillStyle = '#450a0a';
            ctx.fillRect(-5, -40, 10, 80);
            ctx.fillStyle = '#f00';
            HexGeometry.traceHex(ctx, 0, -45, 14, true);
            ctx.fill();
        }
        ctx.restore();
    }
};

import { ISO_SCALE_Y, BASE_HEIGHT, BLOCK_HEIGHT } from "../../../constants";
import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { SurfacePainter } from "../../graphics/painters/SurfacePainter";
import { HexLayout } from "../../../types";

const WALL_SLOP_EPSILON = 1.0; 

export const TerrainRenderer = {

    drawBlock(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        size: number, height: number, 
        theme: any,
        type: string,
        globalTime: number,
        layout: HexLayout
    ) {
        const visualTopY = -height;
        const vertices = HexGeometry.getVertices(size, true, layout); 

        ctx.save();
        ctx.translate(x, y);

        // --- WALL RENDERING ---
        if (layout === 'FLAT') {
            this.drawVerticalWall(ctx, vertices[1], vertices[0], visualTopY, theme.sideDark);
            this.drawVerticalWall(ctx, vertices[2], vertices[1], visualTopY, theme.sideLight);
            this.drawVerticalWall(ctx, vertices[3], vertices[2], visualTopY, theme.sideDark);
        } else {
            this.drawVerticalWall(ctx, vertices[1], vertices[0], visualTopY, theme.sideDark);
            this.drawVerticalWall(ctx, vertices[2], vertices[1], visualTopY, theme.sideLight);
        }

        // --- TOP FACE RENDERING (Restore Dynamics) ---
        ctx.translate(0, visualTopY);

        // 1. 基礎漸變
        const topGrad = ctx.createLinearGradient(-size, -size, size, size);
        topGrad.addColorStop(0, theme.rim); 
        topGrad.addColorStop(0.5, theme.top);
        topGrad.addColorStop(1, theme.sideDark); 
        ctx.fillStyle = topGrad;

        HexGeometry.traceHex(ctx, 0, 0, size, true, layout);
        ctx.fill();

        // 2. 邊緣描邊 (防止吃色)
        ctx.strokeStyle = theme.rim;
        ctx.lineWidth = 1.5;
        ctx.globalAlpha = 0.9;
        ctx.stroke();

        // 3. 場景材質動態細節 (RESTORED)
        this.applyThemeSurfaceDynamics(ctx, size, type, theme, globalTime, layout);

        ctx.restore();
    },

    applyThemeSurfaceDynamics(ctx: CanvasRenderingContext2D, size: number, type: string, theme: any, t: number, layout: HexLayout) {
        ctx.save();
        ctx.globalCompositeOperation = 'overlay';
        ctx.globalAlpha = 0.4;

        // 根據不同場景應用獨特的幾何動態
        if (type === 'FOREST') {
            // 綠色脈動網格
            ctx.strokeStyle = theme.detail;
            ctx.lineWidth = 1;
            const pulse = 0.5 + Math.sin(t * 2) * 0.2;
            ctx.globalAlpha = pulse;
            HexGeometry.traceHex(ctx, 0, 0, size * 0.8, true, layout);
            ctx.stroke();
        } 
        else if (type === 'MAGMA') {
            // 岩漿流動感
            ctx.fillStyle = '#ef4444';
            const offset = (t * 20) % 100;
            ctx.beginPath();
            ctx.moveTo(-size, -size + offset); ctx.lineTo(size, size - 50 + offset);
            ctx.lineWidth = 4; ctx.stroke();
            SurfacePainter.drawLiquid(ctx, 0, 0, '#ef4444', t, 1.0);
        }
        else if (type === 'ICE') {
            // 冰晶閃爍
            ctx.fillStyle = '#fff';
            ctx.globalAlpha = 0.2 + Math.sin(t * 5) * 0.1;
            HexGeometry.traceRotatedHex(ctx, 0, 0, size * 0.6, t * 0.1, true, layout);
            ctx.fill();
        }
        else if (type === 'VOID') {
            // 虛空掃描線
            ctx.strokeStyle = theme.detail;
            const scanY = (t * 40) % (size * 2) - size;
            ctx.beginPath();
            ctx.moveTo(-size, scanY * ISO_SCALE_Y); ctx.lineTo(size, scanY * ISO_SCALE_Y);
            ctx.stroke();
        }

        ctx.restore();
    },

    drawVerticalWall(ctx: CanvasRenderingContext2D, vBottom1: {x:number, y:number}, vBottom2: {x:number, y:number}, topY: number, color: string) {
        ctx.fillStyle = color;
        ctx.beginPath();
        ctx.moveTo(vBottom1.x, vBottom1.y);
        ctx.lineTo(vBottom2.x, vBottom2.y);
        ctx.lineTo(vBottom2.x, vBottom2.y + topY);
        ctx.lineTo(vBottom1.x, vBottom1.y + topY);
        ctx.lineTo(vBottom1.x, vBottom1.y + BASE_HEIGHT + WALL_SLOP_EPSILON);
        ctx.lineTo(vBottom2.x, vBottom2.y + BASE_HEIGHT + WALL_SLOP_EPSILON);
        ctx.lineTo(vBottom2.x, vBottom2.y); 
        ctx.closePath();
        ctx.fill();
    },

    drawTerrainDetail(
        ctx: CanvasRenderingContext2D, 
        baseX: number, baseY: number, 
        height: number,
        type: string, 
        detailColor: string,
        q: number, r: number
    ) {
        const visualY = baseY - height;
        const seed = Math.abs(Math.sin(q * 12.9 + r * 78.2));
        if (seed > 0.6) {
             // 傳遞正確的視覺 Y 給 SurfacePainter
             SurfacePainter.drawDetailTexture(ctx, baseX, visualY, type, detailColor, seed);
        }
    }
};

import { Role, Team } from "../../../types";
import { ISO_SCALE_Y } from "../../../constants";
import { createCanvas } from "../CanvasUtils";
import { HexGeometry } from "../utils/HexGeometry";

const BASE_SIZE = 128;
const ICON_SIZE = 64;

export const ImperialTokenFactory = {

    generateBase(): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(BASE_SIZE, BASE_SIZE);
        const cx = BASE_SIZE / 2;
        const cy = BASE_SIZE / 2;
        const radius = 38;
        const thickness = 10;

        ctx.translate(cx, cy);

        // 1. 六邊形底座側面 (多層疊加模擬厚度)
        ctx.save();
        ctx.fillStyle = '#0f172a';
        for(let i=0; i<thickness; i++) {
            HexGeometry.traceHex(ctx, 0, i, radius, true);
            ctx.fill();
        }
        ctx.restore();

        // 2. 六邊形頂部
        ctx.save();
        const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, radius);
        grad.addColorStop(0, '#1e40af');
        grad.addColorStop(1, '#0a1a4a');
        ctx.fillStyle = grad;
        HexGeometry.traceHex(ctx, 0, 0, radius, true);
        ctx.fill();

        // 3. 金屬鑲邊 (Chamfer)
        ctx.strokeStyle = '#fcd34d';
        ctx.lineWidth = 2.5;
        HexGeometry.traceHex(ctx, 0, 0, radius, true);
        ctx.stroke();

        ctx.restore();
        return canvas;
    },

    generateIcon(role: Role): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(ICON_SIZE, ICON_SIZE);
        const color = '#60a5fa';
        ctx.translate(ICON_SIZE/2, ICON_SIZE/2);
        ctx.strokeStyle = color;
        ctx.lineWidth = 3;

        // 圖標內部的幾何化
        ctx.beginPath();
        if (role === Role.TANK) { HexGeometry.traceHex(ctx, 0, 0, 15, false); }
        else if (role === Role.WARRIOR) { ctx.moveTo(-15,-15); ctx.lineTo(15,15); ctx.moveTo(15,-15); ctx.lineTo(-15,15); }
        else if (role === Role.RANGER) { HexGeometry.traceHex(ctx, 0, 0, 10, false); ctx.moveTo(0,-18); ctx.lineTo(0,18); }
        else { ctx.moveTo(0,-15); ctx.lineTo(15,0); ctx.lineTo(0,15); ctx.closePath(); }
        ctx.stroke();

        return canvas;
    }
};

import { Role, Team } from "../../../types";
