            ctx.fill();
        }
        ctx.restore();

        // 2. 頂部表面 (血色黃銅)
        ctx.save();
        const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, radius);
        grad.addColorStop(0, '#7f1d1d');
        grad.addColorStop(1, '#2a0a0a');
