import { Agent } from "../../../game";
import { AnimState, Role } from "../../../../types";
import { getCastProgress } from "../utils";
import { THEME_IMPERIAL } from "../../../../constants";
import { HexGeometry } from "../../../graphics/utils/HexGeometry";

/**
 * 帝國 (Imperial) 渲染器 v16.0 - 極限戰士【全像投影版】
 * 本體是投影，核心與底座是實體
 */
export const ImperialRenderer = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean, isRunning: boolean) {
        const progress = agent.animState === AnimState.ATTACK ? getCastProgress(agent) : 0;
        const isHit = agent.hitFlashTimer > 0;

        // 1. 動力學 - 活塞式沈穩呼吸
        const breathe = Math.sin(t * 1.5) * 2;
        const hitJitter = isHit ? (Math.random() - 0.5) * 8 : 0;

        ctx.save();
        ctx.translate(hitJitter, 0);

        // 2. 實體靈魂核心 (Physical Core - Always Opaque)
        this.drawSoulCoreBlock(ctx, t, breathe, isHit, isSilhouette);

        // 3. 全像投影裝甲 (Hologram Shell - Rim Lighting)
        ctx.save();
        ctx.globalAlpha = isSilhouette ? 0.4 : 0.85;
        if (!isSilhouette) {
            ctx.globalCompositeOperation = 'screen';
            this.drawHoloScanlines(ctx, t);
        }

        ctx.translate(0, breathe);
        this.drawVolumeArmor(ctx, agent.role, isHit, isSilhouette);
        this.drawPauldrons(ctx, isHit);
        this.drawHexHelmet(ctx, isSilhouette);

        ctx.restore();

        // 4. 武器投影
        this.drawArsenal(ctx, agent, t, progress, breathe, isRunning);

        ctx.restore();
    },

    drawSoulCoreBlock(ctx: CanvasRenderingContext2D, t: number, breathe: number, isHit: boolean, isSil: boolean) {
        if (isSil) return;
        ctx.save();
        ctx.translate(0, -32 + breathe);

        // 核心是實體的，不透明且帶有強力自發光
        const pulse = 0.8 + Math.sin(t * 12) * 0.2;
        ctx.fillStyle = isHit ? '#fff' : '#60a5fa';
        ctx.shadowBlur = 15 * pulse;
        ctx.shadowColor = '#3b82f6';

        // 三層實體六邊形能量塊
        for(let i=0; i<3; i++) {
            HexGeometry.traceHex(ctx, 0, i * 10, 4, true);
            ctx.fill();
        }
        ctx.restore();
    },

    drawVolumeArmor(ctx: CanvasRenderingContext2D, role: Role, isHit: boolean, isSil: boolean) {
        ctx.save();
        ctx.translate(0, -35);
        const w = role === Role.TANK ? 26 : 20;

        // 建立多層嵌套感 (體積感)
        const colors = isHit ? ['#fff', '#fff'] : ['#1e3a8a', '#2563eb'];

        // 底層裝甲 (深鈷藍)
        ctx.fillStyle = colors[0];
        HexGeometry.traceHex(ctx, 0, 18, w, true);
        ctx.fill();

        // 頂層鑲板 (淺鈷藍)
        ctx.fillStyle = colors[1];
        HexGeometry.traceHex(ctx, 0, -5, w * 0.85, true);
        ctx.fill();

        if (!isSil) {
            // 投影外輪廓發光
            ctx.strokeStyle = '#fcd34d'; // 金色電路感
            ctx.lineWidth = 2.5;
            ctx.shadowBlur = 8;
            ctx.shadowColor = '#fbbf24';
            HexGeometry.traceHex(ctx, 0, 18, w, true); ctx.stroke();
            HexGeometry.traceHex(ctx, 0, -5, w * 0.85, true); ctx.stroke();
        }
        ctx.restore();
    },

    drawPauldrons(ctx: CanvasRenderingContext2D, isHit: boolean) {
        const drawPad = (s: number) => {
            ctx.save();
            ctx.translate(s * 25, -45);
            ctx.fillStyle = isHit ? '#fff' : '#1e40af';
            // 多重六邊形堆疊增加厚度
            HexGeometry.traceRotatedHex(ctx, 0, 4, 14, s * 0.4, true); ctx.fill();
            HexGeometry.traceRotatedHex(ctx, 0, 0, 12, s * 0.4, true); ctx.fill();

            ctx.strokeStyle = '#fcd34d';
            ctx.lineWidth = 2;
            HexGeometry.traceRotatedHex(ctx, 0, 0, 12, s * 0.4, true); ctx.stroke();
            ctx.restore();
        };
        drawPad(-1); drawPad(1);
    },

    drawHexHelmet(ctx: CanvasRenderingContext2D, isSil: boolean) {
        ctx.save();
        ctx.translate(0, -62);
        ctx.fillStyle = '#f8fafc';
        HexGeometry.traceHex(ctx, 0, 0, 11, true);
        ctx.fill();

        if (!isSil) {
            ctx.strokeStyle = '#60a5fa';
            ctx.lineWidth = 1.5;
            HexGeometry.traceHex(ctx, 0, 0, 11, true); ctx.stroke();

            ctx.fillStyle = '#ef4444'; // 紅色目鏡
            ctx.beginPath();
            ctx.moveTo(-6, 0); ctx.lineTo(-2, -3); ctx.lineTo(-2, 3); ctx.closePath(); ctx.fill();
            ctx.beginPath();
            ctx.moveTo(6, 0); ctx.lineTo(2, -3); ctx.lineTo(2, 3); ctx.closePath(); ctx.fill();
        }
        ctx.restore();
    },

    drawHoloScanlines(ctx: CanvasRenderingContext2D, t: number) {
        // 投影掃描線特效
        ctx.save();
        const scanY = (t * 50) % 80 - 40;
        ctx.strokeStyle = 'rgba(96, 165, 250, 0.3)';
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(-30, scanY); ctx.lineTo(30, scanY);
        ctx.stroke();
        ctx.restore();
    },

    drawArsenal(ctx: CanvasRenderingContext2D, agent: Agent, t: number, progress: number, breathe: number, isRunning: boolean) {
        const swing = Math.sin(progress * Math.PI);
        const scale = isRunning ? 1.35 : 0.95;
        ctx.save();
        ctx.translate(32, -35 + breathe);
        ctx.rotate(swing * -1.8);
        ctx.scale(scale, scale);

        ctx.fillStyle = '#475569';
        ctx.strokeStyle = '#60a5fa';
        ctx.lineWidth = 2;

        if (agent.role === Role.RANGER) {
            // 爆彈槍：六邊形切面
            ctx.beginPath();
            ctx.moveTo(-18, -10); ctx.lineTo(12, -10); ctx.lineTo(18, 0); ctx.lineTo(12, 10); ctx.lineTo(-18, 10); ctx.closePath();
            ctx.fill(); ctx.stroke();
        } else {
            // 能量劍：幾何棱柱
            ctx.beginPath(); 
            ctx.moveTo(0, 15); ctx.lineTo(-6, 0); ctx.lineTo(0, -60); ctx.lineTo(6, 0); ctx.closePath();
            ctx.stroke();
            ctx.fillStyle = 'rgba(96, 165, 250, 0.4)';
            ctx.fill();
        }
        ctx.restore();
    }
};

import { Agent } from "../../../game";
import { AnimState, Role } from "../../../../types";
import { getCastProgress } from "../utils";
import { THEME_COVENANT } from "../../../../constants";
import { HexGeometry } from "../../../graphics/utils/HexGeometry";

/**
 * 叛軍 (Covenant) 渲染器 v16.0 - 恐虐戰團【鮮血投影版】
 * 狂暴、撕裂、不穩定的投影
 */
export const CovenantRenderer = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean, isRunning: boolean) {
        const progress = agent.animState === AnimState.ATTACK ? getCastProgress(agent) : 0;
        const isHit = agent.hitFlashTimer > 0;

        // 1. 動力學 - 狂暴高頻震顫
        const hpFactor = 1 - (agent.hp / agent.maxHp);
        const intensity = isRunning ? (4 + hpFactor * 8) : 1.5;
        const jitterX = (Math.random() - 0.5) * intensity;
        const jitterY = (Math.random() - 0.5) * intensity;
        const breathe = Math.sin(t * 5) * 2;

        ctx.save();
        ctx.translate(jitterX, jitterY);

        // 2. 實體熔岩核心 (Magma Core - Solid)
        this.drawMagmaCore(ctx, t, breathe, isHit, isSilhouette);

        // 3. 全像投影裝甲 (Jagged Hologram)
        ctx.save();
        ctx.globalAlpha = isSilhouette ? 0.4 : 0.85;
        if (!isSilhouette) {
            ctx.globalCompositeOperation = 'screen';
            // 投影雜訊感
            if (Math.random() > 0.95) ctx.translate((Math.random()-0.5)*10, 0);
        }

        ctx.translate(progress * 35 * agent.facing, breathe);
        this.drawJaggedVolume(ctx, agent.role, isHit, isSilhouette);
        this.drawChaosSpikes(ctx, t);
        this.drawSkullHelmet(ctx, t, isSilhouette);

        ctx.restore();

        // 4. 混沌武裝
        this.drawArsenal(ctx, agent, t, progress, breathe, isRunning);

        ctx.restore();
    },

    drawMagmaCore(ctx: CanvasRenderingContext2D, t: number, breathe: number, isHit: boolean, isSil: boolean) {
        if (isSil) return;
        ctx.save();
        ctx.translate(0, -25 + breathe);

        const flicker = 0.7 + Math.random() * 0.3;
        ctx.fillStyle = isHit ? '#fff' : '#ef4444';
        ctx.shadowBlur = 20 * flicker;
        ctx.shadowColor = '#f00';

        // 破碎的能量塊
        for(let i=0; i<4; i++) {
            const ox = (Math.random()-0.5)*4;
            HexGeometry.traceHex(ctx, ox, i * 12, 5, true);
            ctx.fill();
        }
        ctx.restore();
    },

    drawJaggedVolume(ctx: CanvasRenderingContext2D, role: Role, isHit: boolean, isSil: boolean) {
        ctx.save();
        ctx.translate(0, -35);
        const w = role === Role.TANK ? 30 : 24;

        const colors = isHit ? ['#fff', '#fff'] : ['#2a0a0a', '#7f1d1d'];

        // 核心板甲
        ctx.fillStyle = colors[0];
        ctx.beginPath();
        ctx.moveTo(0, -20); ctx.lineTo(w, -10); ctx.lineTo(w+5, 45); ctx.lineTo(0, 60); ctx.lineTo(-w-5, 45); ctx.lineTo(-w, -10); ctx.closePath();
        ctx.fill();

        // 外掛裝甲片
        ctx.fillStyle = colors[1];
        ctx.beginPath();
        ctx.moveTo(0, 0); ctx.lineTo(w-5, 10); ctx.lineTo(w-2, 35); ctx.lineTo(0, 45); ctx.lineTo(-w+2, 35); ctx.lineTo(-w+5, 10); ctx.closePath();
        ctx.fill();

        if (!isSil) {
            ctx.strokeStyle = '#d97706'; // 氧化黃銅邊緣
            ctx.lineWidth = 2;
            ctx.shadowBlur = 10;
            ctx.shadowColor = '#ef4444';
            ctx.stroke();
        }
        ctx.restore();
    },

    drawChaosSpikes(ctx: CanvasRenderingContext2D, t: number) {
        ctx.save();
        ctx.translate(0, -50);
        ctx.fillStyle = '#111';
        const drawSpike = (s: number) => {
            ctx.beginPath();
            ctx.moveTo(s * 15, 0); ctx.lineTo(s * 40, -45 + Math.sin(t*10)*5); ctx.lineTo(s * 10, -5); ctx.closePath();
            ctx.fill();
            ctx.strokeStyle = '#7f1d1d'; ctx.stroke();
        };
        drawSpike(-1); drawSpike(1);
        ctx.restore();
    },

    drawSkullHelmet(ctx: CanvasRenderingContext2D, t: number, isSil: boolean) {
        ctx.save();
        ctx.translate(0, -65);

        // 恐虐之角
        ctx.fillStyle = '#450a0a';
        const drawHorn = (s: number) => {
            ctx.beginPath(); ctx.moveTo(s * 15, -25); ctx.lineTo(s * 10, 5); ctx.lineTo(s * 2, -5); ctx.closePath(); ctx.fill();
        };
        drawHorn(-1); drawHorn(1);

        ctx.fillStyle = '#fef2f2';
        HexGeometry.traceHex(ctx, 0, 0, 12, true); ctx.fill();

        if (!isSil) {
            ctx.fillStyle = '#ff0000';
            ctx.shadowBlur = 10; ctx.shadowColor = '#f00';
            ctx.beginPath(); ctx.moveTo(-6, -2); ctx.lineTo(-2, -5); ctx.lineTo(-2, 1); ctx.closePath(); ctx.fill();
            ctx.beginPath(); ctx.moveTo(6, -2); ctx.lineTo(2, -5); ctx.lineTo(2, 1); ctx.closePath(); ctx.fill();
        }
        ctx.restore();
    },

    drawArsenal(ctx: CanvasRenderingContext2D, agent: Agent, t: number, progress: number, breathe: number, isRunning: boolean) {
        const attackAngle = progress * Math.PI * 2.0;
        const scale = isRunning ? 1.55 : 1.05;
        ctx.save();
        ctx.translate(35, -30 + breathe);
        ctx.rotate(attackAngle);
        ctx.scale(scale, scale);

        if (agent.role === Role.WARRIOR || agent.role === Role.TANK) {
            ctx.fillStyle = '#1c1917';
            ctx.fillRect(-6, -5, 12, 55); 
            ctx.fillStyle = '#b91c1c';
            ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(-45, -15); ctx.lineTo(-40, 45); ctx.lineTo(0, 30); ctx.closePath(); ctx.fill();
            ctx.strokeStyle = '#d97706'; ctx.stroke();
        } else {
            ctx.fillStyle = '#450a0a';
            ctx.fillRect(-6, -45, 12, 90);
            ctx.fillStyle = '#f00';
            HexGeometry.traceHex(ctx, 0, -50, 16, true); ctx.fill();
        }
        ctx.restore();
    }
};

import { Agent } from "../../../../game";
import { SpriteManager } from "../../../sprites";
import { UnitIndicatorPainter } from "./UnitIndicatorPainter";
import { UnitAuraPainter } from "./UnitAuraPainter";
import { VFXFactory } from "../../../graphics/VFXFactory";
import { UNIT_SCALE, ISO_SCALE_Y } from "../../../../../constants";

const HOVER_LIFT = 6; 

/**
 * 陰影與棋盤底座繪製器 v16.0 (實體棋座版)
 * 核心設定：棋座是本體 (不透明)，模型是投影
 */
export const UnitShadowPainter = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, px: number, py: number, pz: number, t: number, isSilhouette: boolean, isRunning: boolean) {
        if (isSilhouette || agent.visualStatus === 'POLYMORPH') return;

        const assets = SpriteManager.getUnitImages(agent.role, agent.team);
        const surfaceY = py;
        const tokenY = surfaceY - HOVER_LIFT;

        ctx.save();

        // 1. 物理投影陰影 (地表層)
        const jumpHeight = agent.physics.z;
        const shadowScale = Math.max(0.5, 1.0 - (jumpHeight / 450));
        const shadowAlpha = Math.max(0.1, 0.6 - (jumpHeight / 250));
        const shadowBlob = VFXFactory.getTexture('SHADOW_BLOB', 'rgba(0,0,0,0.8)'); 

        ctx.save();
        ctx.translate(px, surfaceY); 
        ctx.scale(UNIT_SCALE * shadowScale, UNIT_SCALE * shadowScale * ISO_SCALE_Y); 
        ctx.globalAlpha = shadowAlpha;
        ctx.drawImage(shadowBlob, -48, -48, 96, 96); 
        ctx.restore();

        // 2. 實體棋座 (Plinth - Fully Opaque)
        // 這是本體，所以透明度永遠為 1.0
        ctx.save();
        ctx.translate(px, tokenY);
        ctx.scale(UNIT_SCALE, UNIT_SCALE); 
        ctx.globalAlpha = 1.0; 
        ctx.shadowColor = 'rgba(0,0,0,0.5)';
        ctx.shadowBlur = 15;
        ctx.drawImage(assets.base, -64, -64); 
        ctx.restore();

        // 3. 戰術職業圖標 (浮動於棋座上方)
        if (agent.hp > 0 && !isRunning) {
            ctx.save();
            ctx.translate(px, tokenY - 25);
            ctx.scale(UNIT_SCALE * 0.9, UNIT_SCALE * 0.9); 

            const breath = Math.sin(t * 2.5) * 3;
            ctx.translate(0, breath);

            ctx.globalAlpha = 1.0;
            ctx.shadowColor = assets.color; 
            ctx.shadowBlur = 12;
            ctx.drawImage(assets.icon, -32, -32, 64, 64);
            ctx.restore();
        }

        // 4. 施法特效與範圍
        if (agent.hp > 0 && agent.castingSkillIdx !== -1) {
            const skill = agent.skills[agent.castingSkillIdx];
            if (skill) {
                if (skill.tag === 'ULT') UnitAuraPainter.drawUltimateChantVFX(ctx, agent, px, surfaceY, t);
                else UnitAuraPainter.drawCastingVFX(ctx, agent, px, surfaceY, t);

                if (skill.type === 'AOE') {
                    ctx.save();
                    ctx.translate(px, surfaceY);
                    UnitIndicatorPainter.drawSkillGroundIndicator(ctx, 0, 0, skill.color, t, 1 - (agent.castTimer / skill.cast), skill.aoeRadius || 1, skill.tag, true);
                    ctx.restore();
                }
            }
        }

        ctx.restore();
    }
};

import { ISO_SCALE_Y, BASE_HEIGHT, BLOCK_HEIGHT } from "../../../constants";
import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { SurfacePainter } from "../../graphics/painters/SurfacePainter";
import { HexLayout } from "../../../types";

const WALL_SLOP_EPSILON = 1.0; 

export const TerrainRenderer = {

    drawBlock(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        size: number, height: number, 
        theme: any,
        type: string,
        globalTime: number,
        layout: HexLayout
    ) {
        const visualTopY = -height;
        const vertices = HexGeometry.getVertices(size, true, layout); 

        ctx.save();
        ctx.translate(x, y);

        // --- WALL RENDERING ---
        if (layout === 'FLAT') {
            this.drawVerticalWall(ctx, vertices[1], vertices[0], visualTopY, theme.sideDark);
            this.drawVerticalWall(ctx, vertices[2], vertices[1], visualTopY, theme.sideLight);
            this.drawVerticalWall(ctx, vertices[3], vertices[2], visualTopY, theme.sideDark);
        } else {
            this.drawVerticalWall(ctx, vertices[1], vertices[0], visualTopY, theme.sideDark);
            this.drawVerticalWall(ctx, vertices[2], vertices[1], visualTopY, theme.sideLight);
        }

        // --- TOP FACE RENDERING ---
        ctx.translate(0, visualTopY);

        // 1. 基礎漸變與環境反射
        const topGrad = ctx.createLinearGradient(-size, -size, size, size);
        topGrad.addColorStop(0, theme.rim); 
        topGrad.addColorStop(0.5, theme.top);
        topGrad.addColorStop(1, theme.sideDark); 
        ctx.fillStyle = topGrad;

        HexGeometry.traceHex(ctx, 0, 0, size, true, layout);
        ctx.fill();

        // 2. 邊緣描邊 (立體感)
        ctx.strokeStyle = theme.rim;
        ctx.lineWidth = 1.2;
        ctx.globalAlpha = 0.8;
        ctx.stroke();

        // 3. 場景材質動態細節 (增強版)
        this.applyThemeSurfaceDynamics(ctx, size, type, theme, globalTime, layout);

        ctx.restore();
    },

    applyThemeSurfaceDynamics(ctx: CanvasRenderingContext2D, size: number, type: string, theme: any, t: number, layout: HexLayout) {
        ctx.save();
        ctx.globalAlpha = 0.6; // 提高動態細節不透明度

        if (type === 'FOREST') {
            ctx.globalCompositeOperation = 'screen';
            ctx.strokeStyle = theme.detail;
            ctx.lineWidth = 1.5;
            const pulse = 0.6 + Math.sin(t * 2.5) * 0.3;
            ctx.globalAlpha = pulse;
            HexGeometry.traceHex(ctx, 0, 0, size * 0.75, true, layout);
            ctx.stroke();
        } 
        else if (type === 'MAGMA') {
            ctx.globalCompositeOperation = 'lighter';
            const offset = (t * 25) % 120;
            ctx.strokeStyle = '#ef4444';
            ctx.lineWidth = 2;
            ctx.beginPath();
            ctx.moveTo(-size, -size + offset); ctx.lineTo(size, size - 40 + offset);
            ctx.stroke();
            SurfacePainter.drawLiquid(ctx, 0, 0, '#ef4444', t, 1.2);
        }
        else if (type === 'ICE') {
            ctx.globalCompositeOperation = 'overlay';
            ctx.fillStyle = '#fff';
            ctx.globalAlpha = 0.3 + Math.sin(t * 6) * 0.15;
            HexGeometry.traceRotatedHex(ctx, 0, 0, size * 0.55, t * 0.2, true, layout);
            ctx.fill();
        }
        else if (type === 'VOID') {
            ctx.globalCompositeOperation = 'screen';
            ctx.strokeStyle = theme.detail;
            const scanY = (t * 45) % (size * 2.5) - size * 1.25;
            ctx.beginPath();
            ctx.moveTo(-size * 0.8, scanY * ISO_SCALE_Y); ctx.lineTo(size * 0.8, scanY * ISO_SCALE_Y);
            ctx.stroke();
        }

        ctx.restore();
    },

    drawVerticalWall(ctx: CanvasRenderingContext2D, vBottom1: {x:number, y:number}, vBottom2: {x:number, y:number}, topY: number, color: string) {
        ctx.fillStyle = color;
        ctx.beginPath();
        ctx.moveTo(vBottom1.x, vBottom1.y);
        ctx.lineTo(vBottom2.x, vBottom2.y);
        ctx.lineTo(vBottom2.x, vBottom2.y + topY);
        ctx.lineTo(vBottom1.x, vBottom1.y + topY);
        ctx.lineTo(vBottom1.x, vBottom1.y + BASE_HEIGHT + WALL_SLOP_EPSILON);
        ctx.lineTo(vBottom2.x, vBottom2.y + BASE_HEIGHT + WALL_SLOP_EPSILON);
        ctx.lineTo(vBottom2.x, vBottom2.y); 
        ctx.closePath();
        ctx.fill();
    },

    drawTerrainDetail(
        ctx: CanvasRenderingContext2D, 
        baseX: number, baseY: number, 
        height: number,
        type: string, 
        detailColor: string,
        q: number, r: number
    ) {
        const visualY = baseY - height;
        const seed = Math.abs(Math.sin(q * 12.9 + r * 78.2));
        if (seed > 0.55) {
             SurfacePainter.drawDetailTexture(ctx, baseX, visualY, type, detailColor, seed);
        }
    }
};

import { Agent } from "../../../game";
import { AnimState, Role } from "../../../../types";
import { getCastProgress } from "../utils";
import { THEME_IMPERIAL } from "../../../../constants";
import { HexGeometry } from "../../../graphics/utils/HexGeometry";

/**
 * 帝國 (Imperial) 渲染器 v16.0 - 極限戰士【厚重投影版】
 * 特色：棋座實體、模型投影、核心實體發光
 */
export const ImperialRenderer = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean, isRunning: boolean) {
        const progress = agent.animState === AnimState.ATTACK ? getCastProgress(agent) : 0;
        const isHit = agent.hitFlashTimer > 0;

        // 1. 動力學 - 穩定的活塞式呼吸
        const breathe = Math.sin(t * 1.5) * 2;
        const hitJitter = isHit ? (Math.random() - 0.5) * 6 : 0;

        ctx.save();
        ctx.translate(hitJitter, 0);

        // 2. 實體靈魂核心 (Physical Soul Core - Always Opaque)
        this.drawSoulCore(ctx, t, breathe, isHit, isSilhouette);

        // 3. 全像投影外殼 (Hologram Shell)
        ctx.save();
        if (!isSilhouette) {
            ctx.globalAlpha = 0.85;
            ctx.globalCompositeOperation = 'screen';
            this.drawProjectionGlitch(ctx, t);
        } else {
            ctx.globalAlpha = 0.3;
        }

        ctx.translate(0, breathe);
        this.drawVolumeArmor(ctx, agent.role, isHit, isSilhouette);
        this.drawHeavyPauldrons(ctx, isHit);
        this.drawTacticalHelmet(ctx, isSilhouette);
        ctx.restore();

        // 4. 武器投影
        this.drawHoloArsenal(ctx, agent, t, progress, breathe, isRunning);

        ctx.restore();
    },

    drawSoulCore(ctx: CanvasRenderingContext2D, t: number, breathe: number, isHit: boolean, isSil: boolean) {
        if (isSil) return;
        ctx.save();
        ctx.translate(0, -32 + breathe);

        // 核心是實體的，不透明且帶有強力自發光
        const pulse = 0.8 + Math.sin(t * 12) * 0.2;
        ctx.fillStyle = isHit ? '#fff' : '#60a5fa';
        ctx.shadowBlur = 15 * pulse;
        ctx.shadowColor = '#3b82f6';

        // 實體六邊形能量塊
        HexGeometry.traceHex(ctx, 0, 8, 5, true);
        ctx.fill();
        HexGeometry.traceHex(ctx, 0, 18, 4, true);
        ctx.fill();
        ctx.restore();
    },

    drawVolumeArmor(ctx: CanvasRenderingContext2D, role: Role, isHit: boolean, isSil: boolean) {
        ctx.save();
        ctx.translate(0, -35);
        const w = role === Role.TANK ? 26 : 20;

        // 藍方體積感提升：多層陶瓷裝甲堆疊
        const baseColor = isHit ? '#fff' : '#1e3a8a';
        const trimColor = '#fcd34d';

        // 底層裝甲 (深)
        ctx.fillStyle = baseColor;
        HexGeometry.traceHex(ctx, 0, 20, w, true);
        ctx.fill();

        // 頂層鑲板 (淺)
        ctx.fillStyle = isHit ? '#fff' : '#2563eb';
        HexGeometry.traceHex(ctx, 0, 0, w * 0.85, true);
        ctx.fill();

        if (!isSil) {
            // 邊緣自發光 (Neon Rim)
            ctx.strokeStyle = trimColor;
            ctx.lineWidth = 2.5;
            ctx.shadowBlur = 8;
            ctx.shadowColor = trimColor;
            HexGeometry.traceHex(ctx, 0, 20, w, true); ctx.stroke();
            HexGeometry.traceHex(ctx, 0, 0, w * 0.85, true); ctx.stroke();
        }
        ctx.restore();
    },

    drawHeavyPauldrons(ctx: CanvasRenderingContext2D, isHit: boolean) {
        const drawPad = (s: number) => {
            ctx.save();
            ctx.translate(s * 25, -45);
            ctx.fillStyle = isHit ? '#fff' : '#1e40af';
            // 多重六邊形堆疊增加體積
            HexGeometry.traceRotatedHex(ctx, 0, 4, 14, s * 0.4, true); ctx.fill();
            HexGeometry.traceRotatedHex(ctx, 0, 0, 12, s * 0.4, true); ctx.fill();

            ctx.strokeStyle = '#fcd34d';
            ctx.lineWidth = 2;
            HexGeometry.traceRotatedHex(ctx, 0, 0, 12, s * 0.4, true); ctx.stroke();
            ctx.restore();
        };
        drawPad(-1); drawPad(1);
    },

    drawTacticalHelmet(ctx: CanvasRenderingContext2D, isSil: boolean) {
        ctx.save();
        ctx.translate(0, -62);
        ctx.fillStyle = '#f8fafc';
        HexGeometry.traceHex(ctx, 0, 0, 11, true);
        ctx.fill();
        if (!isSil) {
            ctx.strokeStyle = '#60a5fa';
            ctx.lineWidth = 1.5;
            HexGeometry.traceHex(ctx, 0, 0, 11, true); ctx.stroke();

            // 目鏡改為菱形
            ctx.fillStyle = '#ef4444';
            ctx.beginPath();
            ctx.moveTo(-6, 0); ctx.lineTo(-2, -3); ctx.lineTo(-2, 3); ctx.closePath(); ctx.fill();
            ctx.beginPath();
            ctx.moveTo(6, 0); ctx.lineTo(2, -3); ctx.lineTo(2, 3); ctx.closePath(); ctx.fill();
        }
        ctx.restore();
    },

    drawProjectionGlitch(ctx: CanvasRenderingContext2D, t: number) {
        // 投影掃描線特效
        const scanY = (t * 60) % 80 - 40;
        ctx.save();
        ctx.strokeStyle = 'rgba(96, 165, 250, 0.4)';
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(-30, scanY); ctx.lineTo(30, scanY);
        ctx.stroke();
        ctx.restore();
    },

    drawHoloArsenal(ctx: CanvasRenderingContext2D, agent: Agent, t: number, progress: number, breathe: number, isRunning: boolean) {
        const swing = Math.sin(progress * Math.PI);
        const scale = isRunning ? 1.4 : 1.0;
        ctx.save();
        ctx.translate(32, -35 + breathe);
        ctx.rotate(swing * -1.8);
        ctx.scale(scale, scale);

        ctx.fillStyle = '#475569';
        ctx.strokeStyle = '#60a5fa';
        ctx.lineWidth = 2;

        if (agent.role === Role.RANGER) {
            ctx.beginPath();
            ctx.moveTo(-18, -10); ctx.lineTo(12, -10); ctx.lineTo(18, 0); ctx.lineTo(12, 10); ctx.lineTo(-18, 10); ctx.closePath();
            ctx.fill(); ctx.stroke();
        } else {
            ctx.beginPath(); 
            ctx.moveTo(0, 15); ctx.lineTo(-6, 0); ctx.lineTo(0, -60); ctx.lineTo(6, 0); ctx.closePath();
            ctx.stroke();
            ctx.fillStyle = 'rgba(96, 165, 250, 0.4)';
            ctx.fill();
        }
        ctx.restore();
    }
};

import { Agent } from "../../../game";
import { AnimState, Role } from "../../../../types";
import { getCastProgress } from "../utils";
import { THEME_COVENANT } from "../../../../constants";
import { HexGeometry } from "../../../graphics/utils/HexGeometry";

/**
 * 叛軍 (Covenant) 渲染器 v16.0 - 恐虐戰團【狂暴投影版】
 */
export const CovenantRenderer = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean, isRunning: boolean) {
        const progress = agent.animState === AnimState.ATTACK ? getCastProgress(agent) : 0;
        const isHit = agent.hitFlashTimer > 0;

        // 1. 動力學 - 狂暴高頻震顫
        const hpFactor = 1 - (agent.hp / agent.maxHp);
        const intensity = isRunning ? (4 + hpFactor * 8) : 1.5;
        const jitterX = (Math.random() - 0.5) * intensity;
        const jitterY = (Math.random() - 0.5) * intensity;
        const breathe = Math.sin(t * 5) * 2;

        ctx.save();
        ctx.translate(jitterX, jitterY);

        // 2. 實體熔岩核心 (Magma Core - Always Opaque)
        this.drawMagmaCore(ctx, t, breathe, isHit, isSilhouette);

        // 3. 全像投影裝甲 (Jagged Hologram)
        ctx.save();
        if (!isSilhouette) {
            ctx.globalAlpha = 0.85;
            ctx.globalCompositeOperation = 'screen';
            // 隨機掃描雜訊
            if (Math.random() > 0.96) ctx.translate((Math.random()-0.5)*15, 0);
        } else {
            ctx.globalAlpha = 0.3;
        }

        ctx.translate(progress * 35 * agent.facing, breathe);
        this.drawJaggedVolume(ctx, agent.role, isHit, isSilhouette);
        this.drawSpikeCrown(ctx, t);
        this.drawSkullHelmet(ctx, t, isSilhouette);
        ctx.restore();

        // 4. 武器系統
        this.drawHeavyArsenal(ctx, agent, t, progress, breathe, isRunning);

        ctx.restore();
    },

    drawMagmaCore(ctx: CanvasRenderingContext2D, t: number, breathe: number, isHit: boolean, isSil: boolean) {
        if (isSil) return;
        ctx.save();
        ctx.translate(0, -25 + breathe);

        const flicker = 0.7 + Math.random() * 0.3;
        ctx.fillStyle = isHit ? '#fff' : '#ef4444';
        ctx.shadowBlur = 20 * flicker;
        ctx.shadowColor = '#f00';

        // 破碎但實體的能量塊
        for(let i=0; i<3; i++) {
            const ox = (Math.random()-0.5)*5;
            HexGeometry.traceHex(ctx, ox, i * 14, 5, true);
            ctx.fill();
        }
        ctx.restore();
    },

    drawJaggedVolume(ctx: CanvasRenderingContext2D, role: Role, isHit: boolean, isSil: boolean) {
        ctx.save();
        ctx.translate(0, -35);
        const w = role === Role.TANK ? 30 : 24;

        const colors = isHit ? ['#fff', '#fff'] : ['#2a0a0a', '#7f1d1d'];

        // 內層板甲
        ctx.fillStyle = colors[0];
        ctx.beginPath();
        ctx.moveTo(0, -20); ctx.lineTo(w, -10); ctx.lineTo(w+5, 45); ctx.lineTo(0, 60); ctx.lineTo(-w-5, 45); ctx.lineTo(-w, -10); ctx.closePath();
        ctx.fill();

        // 外層鋸齒飾片
        ctx.fillStyle = colors[1];
        ctx.beginPath();
        ctx.moveTo(0, 0); ctx.lineTo(w-5, 10); ctx.lineTo(w-2, 35); ctx.lineTo(0, 45); ctx.lineTo(-w+2, 35); ctx.lineTo(-w+5, 10); ctx.closePath();
        ctx.fill();

        if (!isSil) {
            ctx.strokeStyle = '#d97706'; 
            ctx.lineWidth = 2.2;
            ctx.shadowBlur = 12;
            ctx.shadowColor = '#ef4444';
            ctx.stroke();
        }
        ctx.restore();
    },

    drawSpikeCrown(ctx: CanvasRenderingContext2D, t: number) {
        ctx.save();
        ctx.translate(0, -50);
        ctx.fillStyle = '#111';
        const drawSpike = (s: number) => {
            ctx.beginPath();
            ctx.moveTo(s * 15, 0); ctx.lineTo(s * 45, -45 + Math.sin(t*12)*5); ctx.lineTo(s * 10, -5); ctx.closePath();
            ctx.fill();
            ctx.strokeStyle = '#7f1d1d'; ctx.stroke();
        };
        drawSpike(-1); drawSpike(1);
        ctx.restore();
    },

    drawSkullHelmet(ctx: CanvasRenderingContext2D, t: number, isSil: boolean) {
        ctx.save();
        ctx.translate(0, -68);
        // 角
        ctx.fillStyle = '#450a0a';
        ctx.beginPath(); ctx.moveTo(-15, -25); ctx.lineTo(-10, 5); ctx.lineTo(-2, -5); ctx.closePath(); ctx.fill();
        ctx.beginPath(); ctx.moveTo(15, -25); ctx.lineTo(10, 5); ctx.lineTo(2, -5); ctx.closePath(); ctx.fill();

        ctx.fillStyle = '#fef2f2';
        HexGeometry.traceHex(ctx, 0, 0, 12, true); ctx.fill();

        if (!isSil) {
            ctx.fillStyle = '#ff0000';
            ctx.shadowBlur = 10; ctx.shadowColor = '#f00';
            ctx.beginPath(); ctx.moveTo(-6, -2); ctx.lineTo(-2, -5); ctx.lineTo(-2, 1); ctx.closePath(); ctx.fill();
            ctx.beginPath(); ctx.moveTo(6, -2); ctx.lineTo(2, -5); ctx.lineTo(2, 1); ctx.closePath(); ctx.fill();
        }
        ctx.restore();
    },

    drawHeavyArsenal(ctx: CanvasRenderingContext2D, agent: Agent, t: number, progress: number, breathe: number, isRunning: boolean) {
        const attackAngle = progress * Math.PI * 2.0;
        const scale = isRunning ? 1.6 : 1.1;
        ctx.save();
        ctx.translate(35, -30 + breathe);
        ctx.rotate(attackAngle);
        ctx.scale(scale, scale);

        if (agent.role === Role.WARRIOR || agent.role === Role.TANK) {
            ctx.fillStyle = '#1c1917';
            ctx.fillRect(-6, -5, 12, 55); 
            ctx.fillStyle = '#b91c1c';
            ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(-45, -15); ctx.lineTo(-40, 45); ctx.lineTo(0, 30); ctx.closePath(); ctx.fill();
            ctx.strokeStyle = '#d97706'; ctx.stroke();
        } else {
            ctx.fillStyle = '#450a0a';
            ctx.fillRect(-6, -45, 12, 90);
            ctx.fillStyle = '#f00';
            HexGeometry.traceHex(ctx, 0, -50, 16, true); ctx.fill();
        }
        ctx.restore();
    }
};

import { Agent } from "../../../../game";
import { SpriteManager } from "../../../sprites";
import { UnitIndicatorPainter } from "./UnitIndicatorPainter";
import { UnitAuraPainter } from "./UnitAuraPainter";
import { VFXFactory } from "../../../graphics/VFXFactory";
import { UNIT_SCALE, ISO_SCALE_Y } from "../../../../../constants";

const HOVER_LIFT = 6; 

/**
 * 陰影與棋盤底座繪製器 v16.0
 * 核心設定：棋座是本體 (實體)，模型是全像投影 (Hologram)
 */
export const UnitShadowPainter = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, px: number, py: number, pz: number, t: number, isSilhouette: boolean, isRunning: boolean) {
        if (isSilhouette || agent.visualStatus === 'POLYMORPH') return;

        const assets = SpriteManager.getUnitImages(agent.role, agent.team);
        const surfaceY = py;
        const tokenY = surfaceY - HOVER_LIFT;

        ctx.save();

        // 1. 物理投影陰影 (地表層)
        const jumpHeight = agent.physics.z;
        const shadowScale = Math.max(0.5, 1.0 - (jumpHeight / 400));
        const shadowAlpha = Math.max(0.1, 0.5 - (jumpHeight / 200));
        const shadowBlob = VFXFactory.getTexture('SHADOW_BLOB', 'rgba(0,0,0,0.8)'); 

        ctx.save();
        ctx.translate(px, surfaceY); 
        ctx.scale(UNIT_SCALE * shadowScale, UNIT_SCALE * shadowScale * ISO_SCALE_Y); 
        ctx.globalAlpha = shadowAlpha;
        ctx.drawImage(shadowBlob, -48, -48, 96, 96); 
        ctx.restore();

        // 2. 實體棋座 (Plinth - Fully Opaque)
        // 設定：棋座是實體本體，透明度永遠為 1.0
        ctx.save();
        ctx.translate(px, tokenY);
        ctx.scale(UNIT_SCALE, UNIT_SCALE); 
        ctx.globalAlpha = 1.0; 
        ctx.shadowColor = 'rgba(0,0,0,0.4)';
        ctx.shadowBlur = 10;
        ctx.drawImage(assets.base, -64, -64); 
        ctx.restore();

        // 3. 戰術圖標 (浮動於棋座上方)
        if (agent.hp > 0 && !isRunning) {
            ctx.save();
            ctx.translate(px, tokenY - 20);
            ctx.scale(UNIT_SCALE * 0.8, UNIT_SCALE * 0.8); 
            const bob = Math.sin(t * 3) * 4;
            ctx.translate(0, bob);
            ctx.globalAlpha = 1.0;
            ctx.shadowColor = assets.color; 
            ctx.shadowBlur = 10;
            ctx.drawImage(assets.icon, -32, -32, 64, 64);
            ctx.restore();
        }

        // 4. 施法與區域效果
        if (agent.hp > 0 && agent.castingSkillIdx !== -1) {
            const skill = agent.skills[agent.castingSkillIdx];
            if (skill) {
                if (skill.tag === 'ULT') UnitAuraPainter.drawUltimateChantVFX(ctx, agent, px, surfaceY, t);
                else UnitAuraPainter.drawCastingVFX(ctx, agent, px, surfaceY, t);

                if (skill.type === 'AOE') {
                    ctx.save();
                    ctx.translate(px, surfaceY);
                    UnitIndicatorPainter.drawSkillGroundIndicator(ctx, 0, 0, skill.color, t, 1 - (agent.castTimer / skill.cast), skill.aoeRadius || 1, skill.tag, true);
                    ctx.restore();
                }
            }
        }

        ctx.restore();
    }
};

import { ISO_SCALE_Y, BASE_HEIGHT, BLOCK_HEIGHT } from "../../../constants";
import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { SurfacePainter } from "../../graphics/painters/SurfacePainter";
import { HexLayout } from "../../../types";

const WALL_SLOP_EPSILON = 1.0; 

export const TerrainRenderer = {

    drawBlock(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        size: number, height: number, 
        theme: any,
        type: string,
        globalTime: number,
        layout: HexLayout
    ) {
        const visualTopY = -height;
        const vertices = HexGeometry.getVertices(size, true, layout); 

        ctx.save();
        ctx.translate(x, y);

        // --- WALL RENDERING ---
        if (layout === 'FLAT') {
            this.drawVerticalWall(ctx, vertices[1], vertices[0], visualTopY, theme.sideDark);
            this.drawVerticalWall(ctx, vertices[2], vertices[1], visualTopY, theme.sideLight);
            this.drawVerticalWall(ctx, vertices[3], vertices[2], visualTopY, theme.sideDark);
        } else {
            this.drawVerticalWall(ctx, vertices[1], vertices[0], visualTopY, theme.sideDark);
            this.drawVerticalWall(ctx, vertices[2], vertices[1], visualTopY, theme.sideLight);
        }

        // --- TOP FACE RENDERING ---
        ctx.translate(0, visualTopY);

        // 1. 基礎漸變
        const topGrad = ctx.createLinearGradient(-size, -size, size, size);
        topGrad.addColorStop(0, theme.rim); 
        topGrad.addColorStop(0.5, theme.top);
        topGrad.addColorStop(1, theme.sideDark); 
        ctx.fillStyle = topGrad;

        HexGeometry.traceHex(ctx, 0, 0, size, true, layout);
        ctx.fill();

        // 2. 邊緣描邊 (立體感修復)
        ctx.strokeStyle = theme.rim;
        ctx.lineWidth = 1.5;
        ctx.globalAlpha = 0.8;
        ctx.stroke();

        // 3. 場景材質動態細節 (RESTORED & ENHANCED)
        this.applyThemeSurfaceDynamics(ctx, size, type, theme, globalTime, layout);

        ctx.restore();
    },

    applyThemeSurfaceDynamics(ctx: CanvasRenderingContext2D, size: number, type: string, theme: any, t: number, layout: HexLayout) {
        ctx.save();
        ctx.globalAlpha = 0.65; // 調高特效不透明度

        if (type === 'FOREST') {
            ctx.globalCompositeOperation = 'screen';
            ctx.strokeStyle = theme.detail;
            ctx.lineWidth = 1.2;
            const pulse = 0.6 + Math.sin(t * 2) * 0.3;
            ctx.globalAlpha = pulse;
            HexGeometry.traceHex(ctx, 0, 0, size * 0.75, true, layout);
            ctx.stroke();
        } 
        else if (type === 'MAGMA') {
            ctx.globalCompositeOperation = 'lighter';
            const offset = (t * 25) % 120;
            ctx.strokeStyle = '#ef4444';
            ctx.lineWidth = 2;
            ctx.beginPath();
            ctx.moveTo(-size, -size + offset); ctx.lineTo(size, size - 40 + offset);
            ctx.stroke();
            SurfacePainter.drawLiquid(ctx, 0, 0, '#ef4444', t, 1.2);
        }
        else if (type === 'ICE') {
            ctx.globalCompositeOperation = 'overlay';
            ctx.fillStyle = '#fff';
            ctx.globalAlpha = 0.4 + Math.sin(t * 5) * 0.2;
            HexGeometry.traceRotatedHex(ctx, 0, 0, size * 0.5, t * 0.15, true, layout);
            ctx.fill();
        }
        else if (type === 'VOID') {
            ctx.globalCompositeOperation = 'screen';
            ctx.strokeStyle = theme.detail;
            const scanY = (t * 40) % (size * 2.5) - size * 1.25;
            ctx.beginPath();
            ctx.moveTo(-size * 0.8, scanY * ISO_SCALE_Y); ctx.lineTo(size * 0.8, scanY * ISO_SCALE_Y);
            ctx.stroke();
        }

        ctx.restore();
    },

    drawVerticalWall(ctx: CanvasRenderingContext2D, vBottom1: {x:number, y:number}, vBottom2: {x:number, y:number}, topY: number, color: string) {
        ctx.fillStyle = color;
        ctx.beginPath();
        ctx.moveTo(vBottom1.x, vBottom1.y);
        ctx.lineTo(vBottom2.x, vBottom2.y);
        ctx.lineTo(vBottom2.x, vBottom2.y + topY);
        ctx.lineTo(vBottom1.x, vBottom1.y + topY);
        ctx.lineTo(vBottom1.x, vBottom1.y + BASE_HEIGHT + WALL_SLOP_EPSILON);
        ctx.lineTo(vBottom2.x, vBottom2.y + BASE_HEIGHT + WALL_SLOP_EPSILON);
        ctx.lineTo(vBottom2.x, vBottom2.y); 
        ctx.closePath();
        ctx.fill();
    },

    drawTerrainDetail(
        ctx: CanvasRenderingContext2D, 
        baseX: number, baseY: number, 
        height: number,
        type: string, 
        detailColor: string,
        q: number, r: number
    ) {
        const visualY = baseY - height;
        const seed = Math.abs(Math.sin(q * 12.9 + r * 78.2));
        if (seed > 0.55) {
             SurfacePainter.drawDetailTexture(ctx, baseX, visualY, type, detailColor, seed);
        }
    }
};

import { Agent } from "../../../game";
import { AnimState, Role } from "../../../../types";
import { getCastProgress } from "../utils";
import { THEME_IMPERIAL } from "../../../../constants";
import { HexGeometry } from "../../../graphics/utils/HexGeometry";

/**
 * 帝國 (Imperial) 渲染器 v17.0 - 重裝幾何版
 * 徹底解決「沒體積感」問題，強化核心與輪廓
 */
export const ImperialRenderer = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean, isRunning: boolean) {
        const isHit = agent.hitFlashTimer > 0;
        const breathe = Math.sin(t * 1.5) * 2;
        const hitJitter = isHit ? (Math.random() - 0.5) * 10 : 0;

        ctx.save();
        ctx.translate(hitJitter, 0);

        // 1. 實體靈魂引擎 (Physical Engine Core - 100% Opaque)
        // 核心放在最底層，但發出最強的光
        this.drawSoulEngine(ctx, t, breathe, isHit, isSilhouette);

        // 2. 重裝投影殼體 (Multi-layered Armor Shell)
        ctx.save();
        if (!isSilhouette) {
            ctx.globalAlpha = 0.98; // 接近實體
            ctx.globalCompositeOperation = 'screen';
            this.drawScanlineOverlay(ctx, t);
        } else {
            ctx.globalAlpha = 0.4;
        }

        ctx.translate(0, breathe);
        // 藍方重構：多層板塊堆疊
        this.drawHeavyChassis(ctx, agent.role, isHit, isSilhouette);
        this.drawTieredPauldrons(ctx, isHit);
        this.drawCombatHelmet(ctx, isSilhouette);
        ctx.restore();

        // 3. 武器系統
        this.drawArsenal(ctx, agent, t, breathe, isRunning);

        ctx.restore();
    },

    drawSoulEngine(ctx: CanvasRenderingContext2D, t: number, breathe: number, isHit: boolean, isSil: boolean) {
        if (isSil) return;
        ctx.save();
        ctx.translate(0, -32 + breathe);

        // 核心晶體：實心不透明
        const pulse = 0.9 + Math.sin(t * 10) * 0.1;
        ctx.fillStyle = isHit ? '#fff' : '#60a5fa';
        ctx.shadowBlur = 20 * pulse;
        ctx.shadowColor = '#3b82f6';

        // 垂直排列的能量晶體塊
        HexGeometry.traceHex(ctx, 0, 10, 6, true); ctx.fill();
        HexGeometry.traceHex(ctx, 0, 22, 5, true); ctx.fill();

        // 核心內部的白色高溫區
        ctx.fillStyle = '#fff';
        ctx.shadowBlur = 0;
        HexGeometry.traceHex(ctx, 0, 10, 2.5, true); ctx.fill();
        ctx.restore();
    },

    drawHeavyChassis(ctx: CanvasRenderingContext2D, role: Role, isHit: boolean, isSil: boolean) {
        ctx.save();
        ctx.translate(0, -35);
        const w = role === Role.TANK ? 28 : 22;

        // 實心配色
        const armorBase = isHit ? '#fff' : '#1e3a8a';
        const armorPlate = isHit ? '#fff' : '#2563eb';
        const rimGold = '#fcd34d';

        // 第一層：主體裝甲 (底層)
        ctx.fillStyle = armorBase;
        HexGeometry.traceHex(ctx, 0, 25, w, true); ctx.fill();

        // 第二層：胸部裝甲板 (中層)
        ctx.fillStyle = armorPlate;
        HexGeometry.traceHex(ctx, 0, 5, w * 0.85, true); ctx.fill();

        // 第三層：能源裝甲板 (頂層)
        ctx.fillStyle = isHit ? '#fff' : '#3b82f6';
        HexGeometry.traceHex(ctx, 0, -10, w * 0.6, true); ctx.fill();

        if (!isSil) {
            // 實心加粗外輪廓
            ctx.strokeStyle = rimGold;
            ctx.lineWidth = 3;
            ctx.shadowBlur = 10;
            ctx.shadowColor = rimGold;

            HexGeometry.traceHex(ctx, 0, 25, w, true); ctx.stroke();
            HexGeometry.traceHex(ctx, 0, 5, w * 0.85, true); ctx.stroke();

            ctx.shadowBlur = 0; // 內層細線
            ctx.lineWidth = 1;
            HexGeometry.traceHex(ctx, 0, -10, w * 0.6, true); ctx.stroke();
        }
        ctx.restore();
    },

    drawTieredPauldrons(ctx: CanvasRenderingContext2D, isHit: boolean) {
        const drawPad = (s: number) => {
            ctx.save();
            ctx.translate(s * 28, -48);

            // 雙層疊加肩甲，強化厚度
            ctx.fillStyle = isHit ? '#fff' : '#1e40af';
            HexGeometry.traceRotatedHex(ctx, 0, 6, 16, s * 0.4, true); ctx.fill();

            ctx.fillStyle = isHit ? '#fff' : '#1d4ed8';
            HexGeometry.traceRotatedHex(ctx, 0, 0, 14, s * 0.4, true); ctx.fill();

            ctx.strokeStyle = '#fcd34d';
            ctx.lineWidth = 2.5;
            HexGeometry.traceRotatedHex(ctx, 0, 0, 14, s * 0.4, true); ctx.stroke();
            ctx.restore();
        };
        drawPad(-1); drawPad(1);
    },

    drawCombatHelmet(ctx: CanvasRenderingContext2D, isSil: boolean) {
        ctx.save();
        ctx.translate(0, -65);
        ctx.fillStyle = '#f8fafc';
        // 正六邊形重型頭盔
        HexGeometry.traceHex(ctx, 0, 0, 12, true); ctx.fill();

        if (!isSil) {
            ctx.strokeStyle = '#1e40af';
            ctx.lineWidth = 2;
            HexGeometry.traceHex(ctx, 0, 0, 12, true); ctx.stroke();

            // 實心紅目鏡
            ctx.fillStyle = '#ef4444';
            ctx.beginPath();
            ctx.moveTo(-7, 0); ctx.lineTo(-2, -4); ctx.lineTo(-2, 4); ctx.closePath(); ctx.fill();
            ctx.beginPath();
            ctx.moveTo(7, 0); ctx.lineTo(2, -4); ctx.lineTo(2, 4); ctx.closePath(); ctx.fill();
        }
        ctx.restore();
    },

    drawScanlineOverlay(ctx: CanvasRenderingContext2D, t: number) {
        const scanY = (t * 80) % 100 - 50;
        ctx.save();
        ctx.strokeStyle = 'rgba(96, 165, 250, 0.5)';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(-35, scanY); ctx.lineTo(35, scanY);
        ctx.stroke();
        ctx.restore();
    },

    drawArsenal(ctx: CanvasRenderingContext2D, agent: Agent, t: number, breathe: number, isRunning: boolean) {
        ctx.save();
        ctx.translate(35, -35 + breathe);
        const scale = isRunning ? 1.4 : 1.0;
        ctx.scale(scale, scale);

        ctx.fillStyle = '#475569';
        ctx.strokeStyle = '#60a5fa';
        ctx.lineWidth = 3;

        if (agent.role === Role.RANGER) {
            // 重型幾何爆彈槍
            ctx.beginPath();
            ctx.moveTo(-20, -12); ctx.lineTo(10, -12); ctx.lineTo(20, 0); ctx.lineTo(10, 12); ctx.lineTo(-20, 12); ctx.closePath();
            ctx.fill(); ctx.stroke();
        } else {
            // 實心光劍刃
            ctx.beginPath(); 
            ctx.moveTo(0, 15); ctx.lineTo(-8, 0); ctx.lineTo(0, -65); ctx.lineTo(8, 0); ctx.closePath();
            ctx.stroke();
            ctx.fillStyle = 'rgba(96, 165, 250, 0.6)';
            ctx.fill();
        }
        ctx.restore();
    }
};

import { Agent } from "../../../game";
import { AnimState, Role } from "../../../../types";
import { getCastProgress } from "../utils";
import { THEME_COVENANT } from "../../../../constants";
import { HexGeometry } from "../../../graphics/utils/HexGeometry";

/**
 * 叛軍 (Covenant) 渲染器 v17.0 - 狂暴實體版
 */
export const CovenantRenderer = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean, isRunning: boolean) {
        const isHit = agent.hitFlashTimer > 0;
        const hpFactor = 1 - (agent.hp / agent.maxHp);
        const intensity = isRunning ? (5 + hpFactor * 10) : 2;
        const jitterX = (Math.random() - 0.5) * intensity;
        const jitterY = (Math.random() - 0.5) * intensity;
        const breathe = Math.sin(t * 5) * 2;

        ctx.save();
        ctx.translate(jitterX, jitterY);

        // 1. 實體熔岩血核 (Physical Magma Core - 100% Opaque)
        this.drawMagmaCore(ctx, t, breathe, isHit, isSilhouette);

        // 2. 撕裂投影裝甲 (Jagged Plating)
        ctx.save();
        if (!isSilhouette) {
            ctx.globalAlpha = 0.95;
            ctx.globalCompositeOperation = 'screen';
            if (Math.random() > 0.97) ctx.translate((Math.random()-0.5)*20, 0);
        } else {
            ctx.globalAlpha = 0.4;
        }

        ctx.translate(0, breathe);
        this.drawBrutalArmor(ctx, agent.role, isHit, isSilhouette);
        this.drawSpikeArray(ctx, t);
        this.drawSkullHelmet(ctx, t, isSilhouette);
        ctx.restore();

        // 3. 武器系統
        this.drawArsenal(ctx, agent, t, breathe, isRunning);

        ctx.restore();
    },

    drawMagmaCore(ctx: CanvasRenderingContext2D, t: number, breathe: number, isHit: boolean, isSil: boolean) {
        if (isSil) return;
        ctx.save();
        ctx.translate(0, -25 + breathe);

        const flicker = 0.8 + Math.random() * 0.2;
        ctx.fillStyle = isHit ? '#fff' : '#ef4444';
        ctx.shadowBlur = 25 * flicker;
        ctx.shadowColor = '#f00';

        // 核心晶體塊
        for(let i=0; i<3; i++) {
            HexGeometry.traceHex(ctx, (Math.random()-0.5)*8, i * 15, 7, true);
            ctx.fill();
        }
        // 中心高溫白
        ctx.fillStyle = '#fff';
        ctx.shadowBlur = 0;
        HexGeometry.traceHex(ctx, 0, 15, 3, true); ctx.fill();
        ctx.restore();
    },

    drawBrutalArmor(ctx: CanvasRenderingContext2D, role: Role, isHit: boolean, isSil: boolean) {
        ctx.save();
        ctx.translate(0, -35);
        const w = role === Role.TANK ? 32 : 26;

        const baseColor = isHit ? '#fff' : '#1c1917';
        const plateColor = isHit ? '#fff' : '#7f1d1d';
        const rimBrass = '#d97706';

        // 底層裝甲板
        ctx.fillStyle = baseColor;
        ctx.beginPath();
        ctx.moveTo(0, -25); ctx.lineTo(w, -15); ctx.lineTo(w+8, 45); ctx.lineTo(0, 65); ctx.lineTo(-w-8, 45); ctx.lineTo(-w, -15); ctx.closePath();
        ctx.fill();

        // 外掛裝甲飾片
        ctx.fillStyle = plateColor;
        ctx.beginPath();
        ctx.moveTo(0, 5); ctx.lineTo(w-8, 15); ctx.lineTo(w-4, 40); ctx.lineTo(0, 50); ctx.lineTo(-w+4, 40); ctx.lineTo(-w+8, 15); ctx.closePath();
        ctx.fill();

        if (!isSil) {
            ctx.strokeStyle = rimBrass;
            ctx.lineWidth = 3.5;
            ctx.shadowBlur = 12;
            ctx.shadowColor = '#ef4444';
            ctx.stroke();
        }
        ctx.restore();
    },

    drawSpikeArray(ctx: CanvasRenderingContext2D, t: number) {
        ctx.save();
        ctx.translate(0, -55);
        ctx.fillStyle = '#111';
        const drawSpike = (s: number) => {
            ctx.beginPath();
            ctx.moveTo(s * 18, 0); ctx.lineTo(s * 48, -50 + Math.sin(t*15)*8); ctx.lineTo(s * 12, -8); ctx.closePath();
            ctx.fill();
            ctx.strokeStyle = '#7f1d1d'; ctx.lineWidth = 2; ctx.stroke();
        };
        drawSpike(-1); drawSpike(1);
        ctx.restore();
    },

    drawSkullHelmet(ctx: CanvasRenderingContext2D, t: number, isSil: boolean) {
        ctx.save();
        ctx.translate(0, -72);

        ctx.fillStyle = '#450a0a';
        const drawHorn = (s: number) => {
            ctx.beginPath(); ctx.moveTo(s * 18, -30); ctx.lineTo(s * 12, 8); ctx.lineTo(s * 3, -8); ctx.closePath(); ctx.fill();
        };
        drawHorn(-1); drawHorn(1);

        ctx.fillStyle = '#fef2f2';
        HexGeometry.traceHex(ctx, 0, 0, 13, true); ctx.fill();

        if (!isSil) {
            ctx.strokeStyle = '#d97706'; ctx.lineWidth = 1.5;
            HexGeometry.traceHex(ctx, 0, 0, 13, true); ctx.stroke();

            ctx.fillStyle = '#ff0000';
            ctx.shadowBlur = 15; ctx.shadowColor = '#f00';
            ctx.beginPath(); ctx.moveTo(-7, -2); ctx.lineTo(-2, -6); ctx.lineTo(-2, 2); ctx.closePath(); ctx.fill();
            ctx.beginPath(); ctx.moveTo(7, -2); ctx.lineTo(2, -6); ctx.lineTo(2, 2); ctx.closePath(); ctx.fill();
        }
        ctx.restore();
    },

    drawArsenal(ctx: CanvasRenderingContext2D, agent: Agent, t: number, breathe: number, isRunning: boolean) {
        ctx.save();
        ctx.translate(38, -32 + breathe);
        const scale = isRunning ? 1.6 : 1.1;
        ctx.scale(scale, scale);

        ctx.fillStyle = '#1c1917';
        ctx.strokeStyle = '#d97706';
        ctx.lineWidth = 3;

        if (agent.role === Role.WARRIOR || agent.role === Role.TANK) {
            // 實體粗獷斧刃
            ctx.fillRect(-8, -5, 16, 60); 
            ctx.fillStyle = '#b91c1c';
            ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(-50, -20); ctx.lineTo(-45, 50); ctx.lineTo(0, 35); ctx.closePath(); ctx.fill();
            ctx.stroke();
        } else {
            // 邪能法杖
            ctx.fillRect(-8, -50, 16, 100);
            ctx.fillStyle = '#f00';
            HexGeometry.traceHex(ctx, 0, -55, 18, true); ctx.fill();
            ctx.stroke();
        }
        ctx.restore();
    }
};

import { Agent } from "../../../../game";
import { SpriteManager } from "../../../sprites";
import { UnitIndicatorPainter } from "./UnitIndicatorPainter";
import { UnitAuraPainter } from "./UnitAuraPainter";
import { VFXFactory } from "../../../graphics/VFXFactory";
import { UNIT_SCALE, ISO_SCALE_Y } from "../../../../../constants";

const HOVER_LIFT = 6; 

/**
 * 陰影與棋盤底座繪製器 v17.0
 * 棋座 = 本體 (100% 實心)
 */
export const UnitShadowPainter = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, px: number, py: number, pz: number, t: number, isSilhouette: boolean, isRunning: boolean) {
        if (isSilhouette || agent.visualStatus === 'POLYMORPH') return;

        const assets = SpriteManager.getUnitImages(agent.role, agent.team);
        const surfaceY = py;
        const tokenY = surfaceY - HOVER_LIFT;

        ctx.save();

        // 1. 物理接觸陰影 (Soft Shadow)
        const jumpHeight = agent.physics.z;
        const shadowScale = Math.max(0.5, 1.0 - (jumpHeight / 400));
        const shadowAlpha = Math.max(0.1, 0.6 - (jumpHeight / 200));
        const shadowBlob = VFXFactory.getTexture('SHADOW_BLOB', 'rgba(0,0,0,0.9)'); 

        ctx.save();
        ctx.translate(px, surfaceY); 
        ctx.scale(UNIT_SCALE * shadowScale, UNIT_SCALE * shadowScale * ISO_SCALE_Y); 
        ctx.globalAlpha = shadowAlpha;
        ctx.drawImage(shadowBlob, -48, -48, 96, 96); 
        ctx.restore();

        // 2. 實體棋座 (Plinth - SOLID ENTITY)
        // 這是棋盤上的本體，透明度強制為 1.0
        ctx.save();
        ctx.translate(px, tokenY);
        ctx.scale(UNIT_SCALE, UNIT_SCALE); 
        ctx.globalAlpha = 1.0; 
        ctx.shadowColor = 'rgba(0,0,0,0.6)';
        ctx.shadowBlur = 20;
        ctx.drawImage(assets.base, -64, -64); 
        ctx.restore();

        // 3. 職階標識 (實體漂浮)
        if (agent.hp > 0 && !isRunning) {
            ctx.save();
            ctx.translate(px, tokenY - 25);
            ctx.scale(UNIT_SCALE * 0.85, UNIT_SCALE * 0.85); 
            const bob = Math.sin(t * 3.5) * 5;
            ctx.translate(0, bob);
            ctx.globalAlpha = 1.0;
            ctx.shadowColor = assets.color; 
            ctx.shadowBlur = 15;
            ctx.drawImage(assets.icon, -32, -32, 64, 64);
            ctx.restore();
        }

        // 4. 戰術法陣
        if (agent.hp > 0 && agent.castingSkillIdx !== -1) {
            const skill = agent.skills[agent.castingSkillIdx];
            if (skill) {
                if (skill.tag === 'ULT') UnitAuraPainter.drawUltimateChantVFX(ctx, agent, px, surfaceY, t);
                else UnitAuraPainter.drawCastingVFX(ctx, agent, px, surfaceY, t);

                if (skill.type === 'AOE') {
                    ctx.save();
                    ctx.translate(px, surfaceY);
                    UnitIndicatorPainter.drawSkillGroundIndicator(ctx, 0, 0, skill.color, t, 1 - (agent.castTimer / skill.cast), skill.aoeRadius || 1, skill.tag, true);
                    ctx.restore();
                }
            }
        }

        ctx.restore();
    }
};

import { ISO_SCALE_Y, BASE_HEIGHT, BLOCK_HEIGHT } from "../../../constants";
import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { SurfacePainter } from "../../graphics/painters/SurfacePainter";
import { HexLayout } from "../../../types";

const WALL_SLOP_EPSILON = 1.0; 

export const TerrainRenderer = {

    drawBlock(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        size: number, height: number, 
        theme: any,
        type: string,
        globalTime: number,
        layout: HexLayout
    ) {
        const visualTopY = -height;
        const vertices = HexGeometry.getVertices(size, true, layout); 

        ctx.save();
        ctx.translate(x, y);

        // --- WALL RENDERING ---
        if (layout === 'FLAT') {
            this.drawVerticalWall(ctx, vertices[1], vertices[0], visualTopY, theme.sideDark);
            this.drawVerticalWall(ctx, vertices[2], vertices[1], visualTopY, theme.sideLight);
            this.drawVerticalWall(ctx, vertices[3], vertices[2], visualTopY, theme.sideDark);
        } else {
            this.drawVerticalWall(ctx, vertices[1], vertices[0], visualTopY, theme.sideDark);
            this.drawVerticalWall(ctx, vertices[2], vertices[1], visualTopY, theme.sideLight);
        }

        // --- TOP FACE RENDERING ---
        ctx.translate(0, visualTopY);

        // 1. 基礎漸變 (高對比)
        const topGrad = ctx.createLinearGradient(-size, -size, size, size);
        topGrad.addColorStop(0, theme.rim); 
        topGrad.addColorStop(0.4, theme.top);
        topGrad.addColorStop(1, theme.sideDark); 
        ctx.fillStyle = topGrad;

        HexGeometry.traceHex(ctx, 0, 0, size, true, layout);
        ctx.fill();

        // 2. 立體描邊
        ctx.strokeStyle = theme.rim;
        ctx.lineWidth = 1.5;
        ctx.globalAlpha = 0.9;
        ctx.stroke();

        // 3. 場景材質動態細節 (RESTORED HIGH STRENGTH)
        this.applyThemeSurfaceDynamics(ctx, size, type, theme, globalTime, layout);

        ctx.restore();
    },

    applyThemeSurfaceDynamics(ctx: CanvasRenderingContext2D, size: number, type: string, theme: any, t: number, layout: HexLayout) {
        ctx.save();
        ctx.globalAlpha = 0.8; // 顯著調高動態層不透明度

        if (type === 'FOREST') {
            ctx.globalCompositeOperation = 'screen';
            ctx.strokeStyle = theme.detail;
            ctx.lineWidth = 2;
            const pulse = 0.7 + Math.sin(t * 3) * 0.3;
            ctx.globalAlpha = pulse;
            HexGeometry.traceHex(ctx, 0, 0, size * 0.8, true, layout);
            ctx.stroke();
        } 
        else if (type === 'MAGMA') {
            ctx.globalCompositeOperation = 'lighter';
            const offset = (t * 30) % 150;
            ctx.strokeStyle = '#ef4444';
            ctx.lineWidth = 3;
            ctx.beginPath();
            ctx.moveTo(-size, -size + offset); ctx.lineTo(size, size - 40 + offset);
            ctx.stroke();
            SurfacePainter.drawLiquid(ctx, 0, 0, '#ef4444', t, 1.4);
        }
        else if (type === 'ICE') {
            ctx.globalCompositeOperation = 'overlay';
            ctx.fillStyle = '#fff';
            ctx.globalAlpha = 0.5 + Math.sin(t * 8) * 0.2;
            HexGeometry.traceRotatedHex(ctx, 0, 0, size * 0.55, t * 0.3, true, layout);
            ctx.fill();
        }
        else if (type === 'VOID') {
            ctx.globalCompositeOperation = 'screen';
            ctx.strokeStyle = theme.detail;
            ctx.lineWidth = 1.5;
            const scanY = (t * 50) % (size * 3) - size * 1.5;
            ctx.beginPath();
            ctx.moveTo(-size * 0.9, scanY * ISO_SCALE_Y); ctx.lineTo(size * 0.9, scanY * ISO_SCALE_Y);
            ctx.stroke();
        }

        ctx.restore();
    },

    drawVerticalWall(ctx: CanvasRenderingContext2D, vBottom1: {x:number, y:number}, vBottom2: {x:number, y:number}, topY: number, color: string) {
        ctx.fillStyle = color;
        ctx.beginPath();
        ctx.moveTo(vBottom1.x, vBottom1.y);
        ctx.lineTo(vBottom2.x, vBottom2.y);
        ctx.lineTo(vBottom2.x, vBottom2.y + topY);
        ctx.lineTo(vBottom1.x, vBottom1.y + topY);
        ctx.lineTo(vBottom1.x, vBottom1.y + BASE_HEIGHT + WALL_SLOP_EPSILON);
        ctx.lineTo(vBottom2.x, vBottom2.y + BASE_HEIGHT + WALL_SLOP_EPSILON);
        ctx.lineTo(vBottom2.x, vBottom2.y); 
        ctx.closePath();
        ctx.fill();
    },

    drawTerrainDetail(
        ctx: CanvasRenderingContext2D, 
        baseX: number, baseY: number, 
        height: number,
        type: string, 
        detailColor: string,
        q: number, r: number
    ) {
        const visualY = baseY - height;
        const seed = Math.abs(Math.sin(q * 12.9 + r * 78.2));
        if (seed > 0.5) { // 增加細節出現頻率
             SurfacePainter.drawDetailTexture(ctx, baseX, visualY, type, detailColor, seed);
        }
    }
};

import { Agent } from "../../../game";
import { AnimState, Role } from "../../../../types";
import { getCastProgress } from "../utils";
import { THEME_IMPERIAL } from "../../../../constants";
import { HexGeometry } from "../../../graphics/utils/HexGeometry";

/**
 * 帝國 (Imperial) 渲染器 v18.0 - 聖域構造體
 * 設計語彙：神聖幾何、多層力場、實體能量核
 */
export const ImperialRenderer = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean, isRunning: boolean) {
        const isHit = agent.hitFlashTimer > 0;

        // 1. 動力學：消除亂抖，改為「神聖懸浮」
        // 使用複合正弦波達成平滑且具有「神性」的起伏
        const floatY = Math.sin(t * 1.2) * 4 + Math.cos(t * 0.7) * 2;
        const hitJitter = isHit ? (Math.random() - 0.5) * 12 : 0;

        ctx.save();
        ctx.translate(hitJitter, floatY);

        // 2. 實體靈魂引擎 (Physical Core - 100% Opaque)
        this.drawSacredCore(ctx, t, isHit, isSilhouette);

        // 3. 全像投影裝甲 (Architectural Projection)
        ctx.save();
        if (!isSilhouette) {
            ctx.globalAlpha = 0.9;
            ctx.globalCompositeOperation = 'screen';
            this.drawEnergyVeins(ctx, t);
        } else {
            ctx.globalAlpha = 0.3;
        }

        // 核心設計：多層嵌套力場板塊 (建立體積感)
        this.drawTieredArmor(ctx, agent.role, isHit, isSilhouette);
        this.drawFloatingSentinels(ctx, t, isHit);
        this.drawOracleVisor(ctx, isSilhouette);

        ctx.restore();

        // 4. 投影武裝
        this.drawArsenal(ctx, agent, t, isRunning);

        ctx.restore();
    },

    drawSacredCore(ctx: CanvasRenderingContext2D, t: number, isHit: boolean, isSil: boolean) {
        if (isSil) return;
        ctx.save();
        ctx.translate(0, -35);

        // 核心旋轉速度
        const rot = t * 2.5;
        const pulse = 0.8 + Math.sin(t * 8) * 0.2;

        // 實體核心：不透明、高自發光
        ctx.fillStyle = isHit ? '#fff' : '#60a5fa';
        ctx.shadowBlur = 25 * pulse;
        ctx.shadowColor = '#3b82f6';

        // 核心幾何體 (旋轉的實體)
        HexGeometry.traceRotatedHex(ctx, 0, 0, 8, rot, false);
        ctx.fill();

        // 內部白核
        ctx.fillStyle = '#fff';
        ctx.shadowBlur = 0;
        HexGeometry.traceRotatedHex(ctx, 0, 0, 3, -rot * 2, false);
        ctx.fill();

        ctx.restore();
    },

    drawTieredArmor(ctx: CanvasRenderingContext2D, role: Role, isHit: boolean, isSil: boolean) {
        ctx.save();
        ctx.translate(0, -35);
        const w = role === Role.TANK ? 30 : 24;

        const colors = isHit ? ['#fff', '#fff', '#fff'] : ['#1e3a8a', '#2563eb', '#60a5fa'];
        const rimColor = '#fcd34d';

        // 第一層：重型外殼 (底層 - 偏深)
        ctx.fillStyle = colors[0];
        HexGeometry.traceHex(ctx, 0, 25, w, true); ctx.fill();

        // 第二層：中置板塊 (浮空感)
        ctx.fillStyle = colors[1];
        HexGeometry.traceHex(ctx, 0, 5, w * 0.8, true); ctx.fill();

        // 第三層：中心穩定器 (最亮)
        ctx.fillStyle = colors[2];
        HexGeometry.traceHex(ctx, 0, -10, w * 0.5, true); ctx.fill();

        if (!isSil) {
            // 絕對實心的金屬外輪廓線
            ctx.strokeStyle = rimColor;
            ctx.lineWidth = 3;
            ctx.shadowBlur = 12;
            ctx.shadowColor = rimColor;

            // 僅描繪最外層與關鍵分界面，強化結構
            HexGeometry.traceHex(ctx, 0, 25, w, true); ctx.stroke();

            ctx.lineWidth = 1.5;
            ctx.shadowBlur = 0;
            HexGeometry.traceHex(ctx, 0, 5, w * 0.8, true); ctx.stroke();
        }
        ctx.restore();
    },

    drawFloatingSentinels(ctx: CanvasRenderingContext2D, t: number, isHit: boolean) {
        // 取代肩甲：左右各一個獨立旋轉的浮空衛星
        const drawSentinel = (s: number) => {
            ctx.save();
            const orbitX = s * 35;
            const orbitY = -45 + Math.sin(t * 3 + s) * 5;
            ctx.translate(orbitX, orbitY);
            ctx.rotate(t * s * 1.5);

            ctx.fillStyle = isHit ? '#fff' : '#1e40af';
            HexGeometry.traceHex(ctx, 0, 0, 10, false); ctx.fill();

            ctx.strokeStyle = '#fcd34d';
            ctx.lineWidth = 2.5;
            HexGeometry.traceHex(ctx, 0, 0, 10, false); ctx.stroke();

            // 衛星發光點
            ctx.fillStyle = '#60a5fa';
            ctx.beginPath(); ctx.arc(0, 0, 3, 0, Math.PI*2); ctx.fill();
            ctx.restore();
        };
        drawSentinel(-1); drawSentinel(1);
    },

    drawOracleVisor(ctx: CanvasRenderingContext2D, isSil: boolean) {
        ctx.save();
        ctx.translate(0, -68);

        // 頭盔主體
        ctx.fillStyle = '#f8fafc';
        HexGeometry.traceHex(ctx, 0, 0, 14, true); ctx.fill();

        if (!isSil) {
            ctx.strokeStyle = '#1e3a8a';
            ctx.lineWidth = 2;
            HexGeometry.traceHex(ctx, 0, 0, 14, true); ctx.stroke();

            // 十字形掃描目鏡
            ctx.fillStyle = '#ef4444';
            ctx.fillRect(-8, -1, 16, 2);
            ctx.fillRect(-1, -6, 2, 12);

            // 強力發光點
            ctx.shadowColor = '#f00';
            ctx.shadowBlur = 10;
            ctx.beginPath(); ctx.arc(0, 0, 2, 0, Math.PI*2); ctx.fill();
        }
        ctx.restore();
    },

    drawEnergyVeins(ctx: CanvasRenderingContext2D, t: number) {
        // 投影表面的流動能量線
        const offset = (t * 40) % 120 - 60;
        ctx.save();
        ctx.strokeStyle = 'rgba(96, 165, 250, 0.4)';
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(-25, offset); ctx.lineTo(25, offset);
        ctx.stroke();
        ctx.restore();
    },

    drawArsenal(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isRunning: boolean) {
        ctx.save();
        ctx.translate(35, -35);
        const scale = isRunning ? 1.4 : 1.0;
        ctx.scale(scale, scale);

        // 武器改為「碎片懸浮」風格
        if (agent.role === Role.RANGER) {
            // 浮空爆彈組
            ctx.fillStyle = '#475569';
            ctx.strokeStyle = '#60a5fa';
            ctx.lineWidth = 2;
            for(let i=0; i<3; i++) {
                const ox = i * 6;
                const oy = Math.sin(t*5 + i) * 3;
                ctx.fillRect(-10 + ox, -5 + oy, 8, 10);
                ctx.strokeRect(-10 + ox, -5 + oy, 8, 10);
            }
        } else {
            // 能量幾何劍
            ctx.strokeStyle = '#60a5fa';
            ctx.lineWidth = 3;
            ctx.shadowColor = '#60a5fa';
            ctx.shadowBlur = 15;
            ctx.beginPath();
            ctx.moveTo(0, 10); ctx.lineTo(-8, 0); ctx.lineTo(0, -70); ctx.lineTo(8, 0); ctx.closePath();
            ctx.stroke();
            ctx.fillStyle = 'rgba(255,255,255,0.4)';
            ctx.fill();
        }
        ctx.restore();
    }
};

import { Agent } from "../../../game";
import { AnimState, Role } from "../../../../types";
import { getCastProgress } from "../utils";
import { THEME_COVENANT } from "../../../../constants";
import { HexGeometry } from "../../../graphics/utils/HexGeometry";

/**
 * 叛軍 (Covenant) 渲染器 v18.0 - 煉獄騎士
 * 設計語彙：破碎、熔岩、狂暴
 */
export const CovenantRenderer = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean, isRunning: boolean) {
        const isHit = agent.hitFlashTimer > 0;
        const hpFactor = 1 - (agent.hp / agent.maxHp);

        // 1. 動力學：穩定的呼吸，僅在受擊或奔跑時才劇烈抖動
        const breathe = Math.sin(t * 3) * 3;
        const intensity = isRunning ? (4 + hpFactor * 6) : (isHit ? 8 : 0);
        const jitterX = (Math.random() - 0.5) * intensity;
        const jitterY = (Math.random() - 0.5) * intensity;

        ctx.save();
        ctx.translate(jitterX, jitterY);

        // 2. 實體熔岩血核 (Physical Magma Core - 100% Opaque)
        this.drawMagmaCore(ctx, t, breathe, isHit, isSilhouette);

        // 3. 破碎投影裝甲 (Jagged Plating)
        ctx.save();
        if (!isSilhouette) {
            ctx.globalAlpha = 0.95;
            ctx.globalCompositeOperation = 'screen';
        } else {
            ctx.globalAlpha = 0.3;
        }

        ctx.translate(0, breathe);
        this.drawJaggedMass(ctx, agent.role, isHit, isSilhouette);
        this.drawObsidianSpikes(ctx, t);
        this.drawSkullHelmet(ctx, isSilhouette);
        ctx.restore();

        // 4. 武器系統
        this.drawHeavyArsenal(ctx, agent, t, isRunning);

        ctx.restore();
    },

    drawMagmaCore(ctx: CanvasRenderingContext2D, t: number, breathe: number, isHit: boolean, isSil: boolean) {
        if (isSil) return;
        ctx.save();
        ctx.translate(0, -30 + breathe);

        // 核心：像心臟一樣脈動
        const pulse = 0.9 + Math.sin(t * 12) * 0.15;
        ctx.fillStyle = isHit ? '#fff' : '#ef4444';
        ctx.shadowBlur = 30 * pulse;
        ctx.shadowColor = '#f00';

        // 三個不規則的能量塊
        for(let i=0; i<3; i++) {
            const rot = t + i;
            HexGeometry.traceRotatedHex(ctx, 0, i * 8, 6, rot, false);
            ctx.fill();
        }
        ctx.restore();
    },

    drawJaggedMass(ctx: CanvasRenderingContext2D, role: Role, isHit: boolean, isSil: boolean) {
        ctx.save();
        ctx.translate(0, -35);
        const w = role === Role.TANK ? 32 : 26;

        const baseColor = isHit ? '#fff' : '#1c1917';
        const plateColor = isHit ? '#fff' : '#7f1d1d';
        const rimColor = '#ef4444';

        // 建立體積感：錯位的厚重甲片
        ctx.fillStyle = baseColor;
        ctx.beginPath();
        ctx.moveTo(0, -25); ctx.lineTo(w, -10); ctx.lineTo(w+5, 50); ctx.lineTo(0, 65); ctx.lineTo(-w-5, 50); ctx.lineTo(-w, -10); ctx.closePath();
        ctx.fill();

        ctx.fillStyle = plateColor;
        ctx.beginPath();
        ctx.moveTo(0, 0); ctx.lineTo(w-5, 10); ctx.lineTo(w-2, 45); ctx.lineTo(0, 55); ctx.lineTo(-w+2, 45); ctx.lineTo(-w+5, 10); ctx.closePath();
        ctx.fill();

        if (!isSil) {
            ctx.strokeStyle = rimColor;
            ctx.lineWidth = 3.5;
            ctx.shadowBlur = 10;
            ctx.shadowColor = rimColor;
            ctx.stroke();
        }
        ctx.restore();
    },

    drawObsidianSpikes(ctx: CanvasRenderingContext2D, t: number) {
        ctx.save();
        ctx.translate(0, -50);
        ctx.fillStyle = '#0a0a0a';
        const drawSpike = (s: number) => {
            ctx.beginPath();
            ctx.moveTo(s * 15, 0); ctx.lineTo(s * 45, -40 + Math.sin(t*8)*5); ctx.lineTo(s * 10, -5); ctx.closePath();
            ctx.fill();
            ctx.strokeStyle = '#ef4444'; ctx.lineWidth = 2; ctx.stroke();
        };
        drawSpike(-1); drawSpike(1);
        ctx.restore();
    },

    drawSkullHelmet(ctx: CanvasRenderingContext2D, isSil: boolean) {
        ctx.save();
        ctx.translate(0, -70);

        // 邪惡的頭盔廓形
        ctx.fillStyle = '#fef2f2';
        ctx.beginPath();
        ctx.moveTo(0, -15); ctx.lineTo(12, 0); ctx.lineTo(8, 15); ctx.lineTo(-8, 15); ctx.lineTo(-12, 0); ctx.closePath();
        ctx.fill();

        if (!isSil) {
            ctx.strokeStyle = '#7f1d1d'; ctx.lineWidth = 2; ctx.stroke();

            ctx.fillStyle = '#ff0000';
            ctx.shadowBlur = 15; ctx.shadowColor = '#f00';
            ctx.beginPath(); ctx.arc(-5, 0, 3, 0, Math.PI*2); ctx.fill();
            ctx.beginPath(); ctx.arc(5, 0, 3, 0, Math.PI*2); ctx.fill();
        }
        ctx.restore();
    },

    drawHeavyArsenal(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isRunning: boolean) {
        ctx.save();
        ctx.translate(38, -30);
        const scale = isRunning ? 1.6 : 1.1;
        ctx.scale(scale, scale);

        ctx.fillStyle = '#1c1917';
        ctx.strokeStyle = '#d97706';
        ctx.lineWidth = 3;

        if (agent.role === Role.WARRIOR || agent.role === Role.TANK) {
            ctx.fillRect(-8, -5, 16, 65); 
            ctx.fillStyle = '#b91c1c';
            ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(-50, -15); ctx.lineTo(-45, 55); ctx.lineTo(0, 35); ctx.closePath(); ctx.fill();
            ctx.stroke();
        } else {
            ctx.fillRect(-8, -50, 16, 100);
            ctx.fillStyle = '#f00';
            HexGeometry.traceHex(ctx, 0, -55, 18, true); ctx.fill();
            ctx.stroke();
        }
        ctx.restore();
    }
};

import { Agent } from "../../../../game";
import { SpriteManager } from "../../../sprites";
import { UnitIndicatorPainter } from "./UnitIndicatorPainter";
import { UnitAuraPainter } from "./UnitAuraPainter";
import { VFXFactory } from "../../../graphics/VFXFactory";
import { UNIT_SCALE, ISO_SCALE_Y } from "../../../../../constants";

const HOVER_LIFT = 6; 

/**
 * 陰影與棋盤底座繪製器 v18.0
 * 設定：棋座是 100% 實體本體 (Entity Master)
 */
export const UnitShadowPainter = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, px: number, py: number, pz: number, t: number, isSilhouette: boolean, isRunning: boolean) {
        if (isSilhouette || agent.visualStatus === 'POLYMORPH') return;

        const assets = SpriteManager.getUnitImages(agent.role, agent.team);
        const surfaceY = py;
        const tokenY = surfaceY - HOVER_LIFT;

        ctx.save();

        // 1. 接地陰影 (Ground AO)
        const jumpHeight = agent.physics.z;
        const shadowScale = Math.max(0.5, 1.0 - (jumpHeight / 400));
        const shadowAlpha = Math.max(0.1, 0.7 - (jumpHeight / 200));
        const shadowBlob = VFXFactory.getTexture('SHADOW_BLOB', 'rgba(0,0,0,1.0)'); 

        ctx.save();
        ctx.translate(px, surfaceY); 
        ctx.scale(UNIT_SCALE * shadowScale, UNIT_SCALE * shadowScale * ISO_SCALE_Y); 
        ctx.globalAlpha = shadowAlpha;
        ctx.drawImage(shadowBlob, -48, -48, 96, 96); 
        ctx.restore();

        // 2. 實體棋座 (Plinth - SOLID)
        // 這裡是重點：完全不透明、厚重感的深色金屬
        ctx.save();
        ctx.translate(px, tokenY);
        ctx.scale(UNIT_SCALE, UNIT_SCALE); 
        ctx.globalAlpha = 1.0; // 強制 1.0

        // 棋座投影出的輝光 (由下而上)
        ctx.shadowColor = agent.team === 0 ? 'rgba(59,130,246,0.6)' : 'rgba(239,68,68,0.6)';
        ctx.shadowBlur = 20;

        ctx.drawImage(assets.base, -64, -64); 

        // 追加一層金屬反光
        ctx.globalCompositeOperation = 'overlay';
        ctx.globalAlpha = 0.3;
        ctx.drawImage(assets.base, -64, -64);
        ctx.restore();

        // 3. 戰術狀態標識
        if (agent.hp > 0 && !isRunning) {
            ctx.save();
            ctx.translate(px, tokenY - 22);
            ctx.scale(UNIT_SCALE * 0.85, UNIT_SCALE * 0.85); 
            const bob = Math.sin(t * 3.5) * 4;
            ctx.translate(0, bob);
            ctx.globalAlpha = 1.0;
            ctx.shadowColor = assets.color; 
            ctx.shadowBlur = 15;
            ctx.drawImage(assets.icon, -32, -32, 64, 64);
            ctx.restore();
        }

        // 4. 法陣繪製
        if (agent.hp > 0 && agent.castingSkillIdx !== -1) {
            const skill = agent.skills[agent.castingSkillIdx];
            if (skill) {
                if (skill.tag === 'ULT') UnitAuraPainter.drawUltimateChantVFX(ctx, agent, px, surfaceY, t);
                else UnitAuraPainter.drawCastingVFX(ctx, agent, px, surfaceY, t);

                if (skill.type === 'AOE') {
                    ctx.save();
                    ctx.translate(px, surfaceY);
                    UnitIndicatorPainter.drawSkillGroundIndicator(ctx, 0, 0, skill.color, t, 1 - (agent.castTimer / skill.cast), skill.aoeRadius || 1, skill.tag, true);
                    ctx.restore();
                }
            }
        }

        ctx.restore();
    }
};

import { ISO_SCALE_Y, BASE_HEIGHT, BLOCK_HEIGHT } from "../../../constants";
import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { SurfacePainter } from "../../graphics/painters/SurfacePainter";
import { HexLayout } from "../../../types";

const WALL_SLOP_EPSILON = 1.0; 

export const TerrainRenderer = {

    drawBlock(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        size: number, height: number, 
        theme: any,
        type: string,
        globalTime: number,
        layout: HexLayout
    ) {
        const visualTopY = -height;
        const vertices = HexGeometry.getVertices(size, true, layout); 

        ctx.save();
        ctx.translate(x, y);

        // --- WALL RENDERING (AO 強化版) ---
        if (layout === 'FLAT') {
            this.drawVerticalWall(ctx, vertices[1], vertices[0], visualTopY, theme.sideDark);
            this.drawVerticalWall(ctx, vertices[2], vertices[1], visualTopY, theme.sideLight);
            this.drawVerticalWall(ctx, vertices[3], vertices[2], visualTopY, theme.sideDark);
        } else {
            this.drawVerticalWall(ctx, vertices[1], vertices[0], visualTopY, theme.sideDark);
            this.drawVerticalWall(ctx, vertices[2], vertices[1], visualTopY, theme.sideLight);
        }

        // --- TOP FACE RENDERING ---
        ctx.translate(0, visualTopY);

        // 1. 高對比漸變
        const topGrad = ctx.createLinearGradient(-size, -size, size, size);
        topGrad.addColorStop(0, theme.rim); 
        topGrad.addColorStop(0.3, theme.top); // 拉大陰影區
        topGrad.addColorStop(1, theme.sideDark); 
        ctx.fillStyle = topGrad;

        HexGeometry.traceHex(ctx, 0, 0, size, true, layout);
        ctx.fill();

        // 2. 厚重邊緣線
        ctx.strokeStyle = theme.rim;
        ctx.lineWidth = 1.8;
        ctx.globalAlpha = 0.9;
        ctx.stroke();

        // 3. 場景動態強化
        this.applyThemeSurfaceDynamics(ctx, size, type, theme, globalTime, layout);

        ctx.restore();
    },

    applyThemeSurfaceDynamics(ctx: CanvasRenderingContext2D, size: number, type: string, theme: any, t: number, layout: HexLayout) {
        ctx.save();
        ctx.globalAlpha = 0.85; 

        if (type === 'FOREST') {
            ctx.globalCompositeOperation = 'screen';
            ctx.strokeStyle = theme.detail;
            ctx.lineWidth = 2;
            const pulse = 0.7 + Math.sin(t * 2.5) * 0.3;
            ctx.globalAlpha = pulse;
            HexGeometry.traceHex(ctx, 0, 0, size * 0.8, true, layout); ctx.stroke();
        } 
        else if (type === 'MAGMA') {
            ctx.globalCompositeOperation = 'lighter';
            const offset = (t * 40) % 150;
            ctx.strokeStyle = '#ef4444';
            ctx.lineWidth = 3;
            ctx.beginPath();
            ctx.moveTo(-size, -size + offset); ctx.lineTo(size, size - 40 + offset);
            ctx.stroke();
            SurfacePainter.drawLiquid(ctx, 0, 0, '#ef4444', t, 1.5);
        }
        else if (type === 'ICE') {
            ctx.globalCompositeOperation = 'overlay';
            ctx.fillStyle = '#fff';
            ctx.globalAlpha = 0.6 + Math.sin(t * 6) * 0.2;
            HexGeometry.traceRotatedHex(ctx, 0, 0, size * 0.6, t * 0.4, true, layout);
            ctx.fill();
        }
        else if (type === 'VOID') {
            ctx.globalCompositeOperation = 'screen';
            ctx.strokeStyle = theme.detail;
            ctx.lineWidth = 1.5;
            const scanY = (t * 60) % (size * 3) - size * 1.5;
            ctx.beginPath();
            ctx.moveTo(-size * 0.95, scanY * ISO_SCALE_Y); ctx.lineTo(size * 0.95, scanY * ISO_SCALE_Y);
            ctx.stroke();
        }

        ctx.restore();
    },

    drawVerticalWall(ctx: CanvasRenderingContext2D, vBottom1: {x:number, y:number}, vBottom2: {x:number, y:number}, topY: number, color: string) {
        ctx.fillStyle = color;
        ctx.beginPath();
        ctx.moveTo(vBottom1.x, vBottom1.y);
        ctx.lineTo(vBottom2.x, vBottom2.y);
        ctx.lineTo(vBottom2.x, vBottom2.y + topY);
        ctx.lineTo(vBottom1.x, vBottom1.y + topY);
        ctx.lineTo(vBottom1.x, vBottom1.y + BASE_HEIGHT + WALL_SLOP_EPSILON);
        ctx.lineTo(vBottom2.x, vBottom2.y + BASE_HEIGHT + WALL_SLOP_EPSILON);
        ctx.lineTo(vBottom2.x, vBottom2.y); 
        ctx.closePath();
        ctx.fill();

        // 加強 AO 黑影
        ctx.fillStyle = 'rgba(0,0,0,0.2)';
        ctx.fill();
    },

    drawTerrainDetail(
        ctx: CanvasRenderingContext2D, 
        baseX: number, baseY: number, 
        height: number,
        type: string, 
        detailColor: string,
        q: number, r: number
    ) {
        const visualY = baseY - height;
        const seed = Math.abs(Math.sin(q * 12.9 + r * 78.2));
        if (seed > 0.45) { 
             SurfacePainter.drawDetailTexture(ctx, baseX, visualY, type, detailColor, seed);
        }
    }
};

import { Agent } from "../../../game";
import { AnimState, Role } from "../../../../types";
import { getCastProgress } from "../utils";
import { THEME_IMPERIAL } from "../../../../constants";
import { HexGeometry } from "../../../graphics/utils/HexGeometry";

/**
 * 帝國 (Imperial) 渲染器 v19.0 - 聖域構造體 [全實體化重製版]
 * 核心語彙：幾何秩序、多層力場、實心核心引擎
 */
export const ImperialRenderer = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean, isRunning: boolean) {
        const isHit = agent.hitFlashTimer > 0;

        // 1. 動力學骨架：所有部件共用一個主頻率，消除亂抖
        const mainWave = Math.sin(t * 1.5);
        const floatY = mainWave * 5; // 整體垂直浮動
        const armorWave = Math.cos(t * 2) * 2; // 裝甲板的獨立呼吸感

        ctx.save();
        if (isHit) ctx.translate((Math.random() - 0.5) * 8, (Math.random() - 0.5) * 8);

        // 2. [主從關係] 第一層：實心靈魂引擎 (Physical Anchor - 100% Opaque)
        this.drawEngineCore(ctx, t, floatY, isHit, isSilhouette);

        // 3. 第二層：投影裝甲殼體 (Volumetric Projection)
        ctx.save();
        ctx.translate(0, floatY);

        if (!isSilhouette) {
            ctx.globalAlpha = 0.95; // 幾乎不透明，維持實體感
            ctx.globalCompositeOperation = 'source-over'; // 實體疊加
        } else {
            ctx.globalAlpha = 0.4;
        }

        this.drawHeavyGeometry(ctx, agent.role, armorWave, isHit, isSilhouette);
        this.drawFloatingSentinels(ctx, t, armorWave, isHit);
        this.drawCommandVisor(ctx, isSilhouette);

        ctx.restore();

        // 4. 第三層：同步武裝
        this.drawArsenal(ctx, agent, t, floatY, isRunning);

        ctx.restore();
    },

    drawEngineCore(ctx: CanvasRenderingContext2D, t: number, floatY: number, isHit: boolean, isSil: boolean) {
        if (isSil) return;
        ctx.save();
        ctx.translate(0, -35 + floatY);

        const rot = t * 2.0;
        const pulse = 0.8 + Math.sin(t * 8) * 0.2;

        // 核心是絕對實體的
        ctx.fillStyle = isHit ? '#fff' : '#60a5fa';
        ctx.shadowBlur = 20 * pulse;
        ctx.shadowColor = '#3b82f6';

        // 旋轉的實體核心塊
        HexGeometry.traceRotatedHex(ctx, 0, 0, 10, rot, false);
        ctx.fill();

        // 核心白點 (高能中心)
        ctx.fillStyle = '#fff';
        ctx.shadowBlur = 0;
        HexGeometry.traceRotatedHex(ctx, 0, 0, 4, -rot * 1.5, false);
        ctx.fill();
        ctx.restore();
    },

    drawHeavyGeometry(ctx: CanvasRenderingContext2D, role: Role, armorWave: number, isHit: boolean, isSil: boolean) {
        ctx.save();
        ctx.translate(0, -35);
        const w = role === Role.TANK ? 32 : 26;

        const armorColor = isHit ? '#fff' : '#1e3a8a';
        const plateColor = isHit ? '#fff' : '#2563eb';
        const rimColor = '#fcd34d';

        // 建立體積感：多層物理堆疊
        // 底層板甲
        ctx.fillStyle = armorColor;
        HexGeometry.traceHex(ctx, 0, 20 + armorWave, w, true); ctx.fill();

        // 中層防護
        ctx.fillStyle = plateColor;
        HexGeometry.traceHex(ctx, 0, 5, w * 0.8, true); ctx.fill();

        // 頂層穩定器
        ctx.fillStyle = isHit ? '#fff' : '#60a5fa';
        HexGeometry.traceHex(ctx, 0, -10 - armorWave, w * 0.5, true); ctx.fill();

        if (!isSil) {
            // 強實心輪廓線 - 絕對禁絕透明
            ctx.strokeStyle = rimColor;
            ctx.lineWidth = 3;
            ctx.shadowBlur = 10;
            ctx.shadowColor = rimColor;
            HexGeometry.traceHex(ctx, 0, 20 + armorWave, w, true); ctx.stroke();

            ctx.lineWidth = 1;
            ctx.shadowBlur = 0;
            HexGeometry.traceHex(ctx, 0, 5, w * 0.8, true); ctx.stroke();
        }
        ctx.restore();
    },

    drawFloatingSentinels(ctx: CanvasRenderingContext2D, t: number, armorWave: number, isHit: boolean) {
        const drawS = (s: number) => {
            ctx.save();
            const orbitX = s * (35 + armorWave);
            const orbitY = -45 + Math.sin(t * 3 + s) * 8;
            ctx.translate(orbitX, orbitY);
            ctx.rotate(t * s * 1.2);

            ctx.fillStyle = isHit ? '#fff' : '#1e40af';
            HexGeometry.traceHex(ctx, 0, 0, 11, false); ctx.fill();

            ctx.strokeStyle = '#fcd34d';
            ctx.lineWidth = 2.5;
            HexGeometry.traceHex(ctx, 0, 0, 11, false); ctx.stroke();
            ctx.restore();
        };
        drawS(-1); drawS(1);
    },

    drawCommandVisor(ctx: CanvasRenderingContext2D, isSil: boolean) {
        ctx.save();
        ctx.translate(0, -72);
        ctx.fillStyle = '#f8fafc';
        HexGeometry.traceHex(ctx, 0, 0, 15, true); ctx.fill();

        if (!isSil) {
            ctx.strokeStyle = '#1e3a8a';
            ctx.lineWidth = 2.5;
            HexGeometry.traceHex(ctx, 0, 0, 15, true); ctx.stroke();

            // 實心紅色電子眼
            ctx.fillStyle = '#ef4444';
            ctx.fillRect(-9, -2, 18, 4);
            ctx.shadowColor = '#f00';
            ctx.shadowBlur = 8;
            ctx.beginPath(); ctx.arc(0,0,2.5,0,Math.PI*2); ctx.fill();
        }
        ctx.restore();
    },

    drawArsenal(ctx: CanvasRenderingContext2D, agent: Agent, t: number, floatY: number, isRunning: boolean) {
        ctx.save();
        ctx.translate(38, -35 + floatY); // 隨身體整體浮動同步
        const swing = Math.sin(t * 2) * 5;
        ctx.translate(0, swing); // 武器額外的靈動感

        const scale = isRunning ? 1.3 : 1.0;
        ctx.scale(scale, scale);

        ctx.strokeStyle = '#60a5fa';
        ctx.lineWidth = 3.5;
        ctx.shadowColor = '#60a5fa';
        ctx.shadowBlur = 15;

        if (agent.role === Role.RANGER) {
            // 實心能量爆彈槍
            ctx.fillStyle = '#1e293b';
            ctx.beginPath();
            ctx.moveTo(-22, -14); ctx.lineTo(12, -14); ctx.lineTo(22, 0); ctx.lineTo(12, 14); ctx.lineTo(-22, 14); ctx.closePath();
            ctx.fill(); ctx.stroke();
        } else {
            // 實心光刃
            ctx.beginPath(); 
            ctx.moveTo(0, 15); ctx.lineTo(-10, 0); ctx.lineTo(0, -75); ctx.lineTo(10, 0); ctx.closePath();
            ctx.stroke();
            ctx.fillStyle = 'rgba(255,255,255,0.7)';
            ctx.fill();
        }
        ctx.restore();
    }
};

import { Agent } from "../../../game";
import { AnimState, Role } from "../../../../types";
import { getCastProgress } from "../utils";
import { THEME_COVENANT } from "../../../../constants";
import { HexGeometry } from "../../../graphics/utils/HexGeometry";

/**
 * 叛軍 (Covenant) 渲染器 v19.0 - 深淵獵殺者 [極致體積版]
 * 核心語彙：破碎、熔岩心臟、黑曜石重甲
 */
export const CovenantRenderer = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean, isRunning: boolean) {
        const isHit = agent.hitFlashTimer > 0;
        const hpFactor = 1 - (agent.hp / agent.maxHp);

        // 1. 動力學骨架：脈動式的律動
        const heartPulse = Math.sin(t * 5); 
        const floatY = heartPulse * 3;

        // 狂暴模式：低血量時抖動更強
        const jitterIntensity = isHit ? 12 : (isRunning ? (4 + hpFactor * 6) : 0);
        const jitterX = (Math.random() - 0.5) * jitterIntensity;

        ctx.save();
        ctx.translate(jitterX, 0);

        // 2. 核心：惡魔心臟 (Devil's Heart - 100% Opaque)
        this.drawDevilHeart(ctx, t, floatY, isHit, isSilhouette);

        // 3. 裝甲：黑曜石碎塊 (Obsidian Plating)
        ctx.save();
        ctx.translate(0, floatY);

        if (!isSilhouette) {
            ctx.globalAlpha = 0.98;
            ctx.globalCompositeOperation = 'source-over';
        } else {
            ctx.globalAlpha = 0.4;
        }

        this.drawJaggedObsidian(ctx, agent.role, heartPulse, isHit, isSilhouette);
        this.drawDemonicSpikes(ctx, t, heartPulse);
        this.drawTerrorMask(ctx, isSilhouette);

        ctx.restore();

        // 4. 武裝系統
        this.drawArsenal(ctx, agent, t, floatY, isRunning);

        ctx.restore();
    },

    drawDevilHeart(ctx: CanvasRenderingContext2D, t: number, floatY: number, isHit: boolean, isSil: boolean) {
        if (isSil) return;
        ctx.save();
        ctx.translate(0, -32 + floatY);

        const pulse = 0.9 + Math.sin(t * 12) * 0.2;
        ctx.fillStyle = isHit ? '#fff' : '#ef4444';
        ctx.shadowBlur = 30 * pulse;
        ctx.shadowColor = '#f00';

        // 脈動的核心組件
        for(let i=0; i<3; i++) {
            const rot = t * 3 + i;
            HexGeometry.traceRotatedHex(ctx, 0, i * 10, 8, rot, false);
            ctx.fill();
        }
        ctx.restore();
    },

    drawJaggedObsidian(ctx: CanvasRenderingContext2D, role: Role, heartPulse: number, isHit: boolean, isSil: boolean) {
        ctx.save();
        ctx.translate(0, -35);
        const w = role === Role.TANK ? 34 : 28;

        const baseColor = isHit ? '#fff' : '#0a0a0a';
        const plateColor = isHit ? '#fff' : '#7f1d1d';
        const rimColor = '#ef4444';

        // 建立厚度：多重交錯甲片
        ctx.fillStyle = baseColor;
        ctx.beginPath();
        // 寬闊重甲基礎
        ctx.moveTo(0, -25 - heartPulse * 5); 
        ctx.lineTo(w, -15); ctx.lineTo(w+10, 50); ctx.lineTo(0, 70); ctx.lineTo(-w-10, 50); ctx.lineTo(-w, -15); 
        ctx.closePath();
        ctx.fill();

        // 覆蓋血色裝甲板
        ctx.fillStyle = plateColor;
        ctx.beginPath();
        ctx.moveTo(0, 5); ctx.lineTo(w-10, 15); ctx.lineTo(w-5, 45); ctx.lineTo(0, 60); ctx.lineTo(-w+5, 45); ctx.lineTo(-w+10, 15);
        ctx.closePath();
        ctx.fill();

        if (!isSil) {
            // 實心強輪廓線
            ctx.strokeStyle = rimColor;
            ctx.lineWidth = 3.5;
            ctx.shadowBlur = 12;
            ctx.shadowColor = rimColor;
            ctx.stroke();
        }
        ctx.restore();
    },

    drawDemonicSpikes(ctx: CanvasRenderingContext2D, t: number, heartPulse: number) {
        ctx.save();
        ctx.translate(0, -55);
        ctx.fillStyle = '#000';
        const drawSpike = (s: number) => {
            ctx.beginPath();
            ctx.moveTo(s * 20, 0); 
            ctx.lineTo(s * 50, -45 + heartPulse * 10); 
            ctx.lineTo(s * 15, -10); 
            ctx.closePath();
            ctx.fill();
            ctx.strokeStyle = '#ef4444'; ctx.lineWidth = 2.5; ctx.stroke();
        };
        drawSpike(-1); drawSpike(1);
        ctx.restore();
    },

    drawTerrorMask(ctx: CanvasRenderingContext2D, isSil: boolean) {
        ctx.save();
        ctx.translate(0, -75);
        ctx.fillStyle = '#fef2f2';
        ctx.beginPath();
        ctx.moveTo(0, -18); ctx.lineTo(15, 0); ctx.lineTo(10, 18); ctx.lineTo(-10, 18); ctx.lineTo(-15, 0); ctx.closePath();
        ctx.fill();

        if (!isSil) {
            ctx.strokeStyle = '#450a0a'; ctx.lineWidth = 3; ctx.stroke();

            // 實心血眼
            ctx.fillStyle = '#ff0000';
            ctx.shadowBlur = 15; ctx.shadowColor = '#f00';
            ctx.beginPath(); ctx.arc(-6, 0, 4, 0, Math.PI*2); ctx.fill();
            ctx.beginPath(); ctx.arc(6, 0, 4, 0, Math.PI*2); ctx.fill();
        }
        ctx.restore();
    },

    drawArsenal(ctx: CanvasRenderingContext2D, agent: Agent, t: number, floatY: number, isRunning: boolean) {
        ctx.save();
        ctx.translate(40, -32 + floatY);
        const scale = isRunning ? 1.5 : 1.1;
        ctx.scale(scale, scale);
        ctx.rotate(Math.sin(t * 4) * 0.2); // 武器隨呼吸擺動

        ctx.fillStyle = '#1c1917';
        ctx.strokeStyle = '#ea580c';
        ctx.lineWidth = 3.5;

        if (agent.role === Role.WARRIOR || agent.role === Role.TANK) {
            // 實心重型屠刀
            ctx.fillRect(-10, -5, 20, 70); 
            ctx.fillStyle = '#b91c1c';
            ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(-55, -20); ctx.lineTo(-50, 60); ctx.lineTo(0, 40); ctx.closePath();
            ctx.fill(); ctx.stroke();
        } else {
            // 實心邪能法杖
            ctx.fillRect(-10, -50, 20, 110);
            ctx.fillStyle = '#ef4444';
            HexGeometry.traceHex(ctx, 0, -60, 22, true); ctx.fill(); ctx.stroke();
        }
        ctx.restore();
    }
};

import { Agent } from "../../../../game";
import { SpriteManager } from "../../../sprites";
import { UnitIndicatorPainter } from "./UnitIndicatorPainter";
import { UnitAuraPainter } from "./UnitAuraPainter";
import { VFXFactory } from "../../../graphics/VFXFactory";
import { UNIT_SCALE, ISO_SCALE_Y } from "../../../../../constants";

const HOVER_LIFT = 6; 

/**
 * 陰影與棋盤底座繪製器 v19.0
 * 核心設定：棋座是 100% 實體本體，且具備絕對不透明度
 */
export const UnitShadowPainter = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, px: number, py: number, pz: number, t: number, isSilhouette: boolean, isRunning: boolean) {
        if (isSilhouette || agent.visualStatus === 'POLYMORPH') return;

        const assets = SpriteManager.getUnitImages(agent.role, agent.team);
        const surfaceY = py;
        const tokenY = surfaceY - HOVER_LIFT;

        ctx.save();

        // 1. 環境光遮蔽陰影 (Ambient Occlusion)
        const jumpHeight = agent.physics.z;
        const shadowScale = Math.max(0.4, 1.0 - (jumpHeight / 500));
        const shadowAlpha = Math.max(0.1, 0.8 - (jumpHeight / 250));
        const shadowBlob = VFXFactory.getTexture('SHADOW_BLOB', 'rgba(0,0,0,1.0)'); 

        ctx.save();
        ctx.translate(px, surfaceY); 
        ctx.scale(UNIT_SCALE * shadowScale, UNIT_SCALE * shadowScale * ISO_SCALE_Y); 
        ctx.globalAlpha = shadowAlpha;
        ctx.drawImage(shadowBlob, -48, -48, 96, 96); 
        ctx.restore();

        // 2. 實體棋座 (Physical Plinth - 100% OPAQUE)
        // 這是棋子的物理本體，嚴禁透明
        ctx.save();
        ctx.translate(px, tokenY);
        ctx.scale(UNIT_SCALE, UNIT_SCALE); 
        ctx.globalAlpha = 1.0; 

        // 底部自發光 (向上投影感)
        ctx.shadowColor = agent.team === 0 ? 'rgba(59,130,246,0.8)' : 'rgba(239,68,68,0.8)';
        ctx.shadowBlur = 25;

        ctx.drawImage(assets.base, -64, -64); 

        // 追加金屬質感層
        ctx.globalCompositeOperation = 'overlay';
        ctx.globalAlpha = 0.4;
        ctx.drawImage(assets.base, -64, -64);
        ctx.restore();

        // 3. 戰術狀態標識
        if (agent.hp > 0 && !isRunning) {
            ctx.save();
            ctx.translate(px, tokenY - 25);
            ctx.scale(UNIT_SCALE * 0.9, UNIT_SCALE * 0.9); 
            const bob = Math.sin(t * 3) * 6;
            ctx.translate(0, bob);
            ctx.globalAlpha = 1.0;
            ctx.shadowColor = assets.color; 
            ctx.shadowBlur = 20;
            ctx.drawImage(assets.icon, -32, -32, 64, 64);
            ctx.restore();
        }

        // 4. 詠唱法陣
        if (agent.hp > 0 && agent.castingSkillIdx !== -1) {
            const skill = agent.skills[agent.castingSkillIdx];
            if (skill) {
                if (skill.tag === 'ULT') UnitAuraPainter.drawUltimateChantVFX(ctx, agent, px, surfaceY, t);
                else UnitAuraPainter.drawCastingVFX(ctx, agent, px, surfaceY, t);

                if (skill.type === 'AOE') {
                    ctx.save();
                    ctx.translate(px, surfaceY);
                    UnitIndicatorPainter.drawSkillGroundIndicator(ctx, 0, 0, skill.color, t, 1 - (agent.castTimer / skill.cast), skill.aoeRadius || 1, skill.tag, true);
                    ctx.restore();
                }
            }
        }

        ctx.restore();
    }
};

import { ISO_SCALE_Y, BASE_HEIGHT, BLOCK_HEIGHT } from "../../../constants";
import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { SurfacePainter } from "../../graphics/painters/SurfacePainter";
import { HexLayout } from "../../../types";

const WALL_SLOP_EPSILON = 1.0; 

export const TerrainRenderer = {

    drawBlock(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        size: number, height: number, 
        theme: any,
        type: string,
        globalTime: number,
        layout: HexLayout
    ) {
        const visualTopY = -height;
        const vertices = HexGeometry.getVertices(size, true, layout); 

        ctx.save();
        ctx.translate(x, y);

        // --- WALL RENDERING (AO & DEPTH UPGRADE) ---
        if (layout === 'FLAT') {
            this.drawVerticalWall(ctx, vertices[1], vertices[0], visualTopY, theme.sideDark);
            this.drawVerticalWall(ctx, vertices[2], vertices[1], visualTopY, theme.sideLight);
            this.drawVerticalWall(ctx, vertices[3], vertices[2], visualTopY, theme.sideDark);
        } else {
            this.drawVerticalWall(ctx, vertices[1], vertices[0], visualTopY, theme.sideDark);
            this.drawVerticalWall(ctx, vertices[2], vertices[1], visualTopY, theme.sideLight);
        }

        // --- TOP FACE RENDERING ---
        ctx.translate(0, visualTopY);

        // 1. High Contrast Top Gradient
        const topGrad = ctx.createLinearGradient(-size, -size, size, size);
        topGrad.addColorStop(0, theme.rim); 
        topGrad.addColorStop(0.2, theme.top); // Sharper transition
        topGrad.addColorStop(1, theme.sideDark); 
        ctx.fillStyle = topGrad;

        HexGeometry.traceHex(ctx, 0, 0, size, true, layout);
        ctx.fill();

        // 2. Heavy Tactical Rim
        ctx.strokeStyle = theme.rim;
        ctx.lineWidth = 2.0;
        ctx.globalAlpha = 1.0; 
        ctx.stroke();

        // 3. Surface Dynamics
        this.applyThemeSurfaceDynamics(ctx, size, type, theme, globalTime, layout);

        ctx.restore();
    },

    applyThemeSurfaceDynamics(ctx: CanvasRenderingContext2D, size: number, type: string, theme: any, t: number, layout: HexLayout) {
        ctx.save();
        ctx.globalAlpha = 0.9; 

        if (type === 'FOREST') {
            ctx.globalCompositeOperation = 'screen';
            ctx.strokeStyle = theme.detail;
            ctx.lineWidth = 2.5;
            const pulse = 0.7 + Math.sin(t * 3) * 0.3;
            ctx.globalAlpha = pulse;
            HexGeometry.traceHex(ctx, 0, 0, size * 0.82, true, layout); ctx.stroke();
        } 
        else if (type === 'MAGMA') {
            ctx.globalCompositeOperation = 'lighter';
            const offset = (t * 45) % 150;
            ctx.strokeStyle = '#ef4444';
            ctx.lineWidth = 4;
            ctx.beginPath();
            ctx.moveTo(-size, -size + offset); ctx.lineTo(size, size - 40 + offset);
            ctx.stroke();
            SurfacePainter.drawLiquid(ctx, 0, 0, '#ef4444', t, 1.6);
        }
        else if (type === 'ICE') {
            ctx.globalCompositeOperation = 'overlay';
            ctx.fillStyle = '#fff';
            ctx.globalAlpha = 0.7 + Math.sin(t * 7) * 0.3;
            HexGeometry.traceRotatedHex(ctx, 0, 0, size * 0.65, t * 0.5, true, layout);
            ctx.fill();
        }
        else if (type === 'VOID') {
            ctx.globalCompositeOperation = 'screen';
            ctx.strokeStyle = theme.detail;
            ctx.lineWidth = 2.0;
            const scanY = (t * 70) % (size * 3) - size * 1.5;
            ctx.beginPath();
            ctx.moveTo(-size, scanY * ISO_SCALE_Y); ctx.lineTo(size, scanY * ISO_SCALE_Y);
            ctx.stroke();
        }

        ctx.restore();
    },

    drawVerticalWall(ctx: CanvasRenderingContext2D, vBottom1: {x:number, y:number}, vBottom2: {x:number, y:number}, topY: number, color: string) {
        ctx.fillStyle = color;
        ctx.beginPath();
        ctx.moveTo(vBottom1.x, vBottom1.y);
        ctx.lineTo(vBottom2.x, vBottom2.y);
        ctx.lineTo(vBottom2.x, vBottom2.y + topY);
        ctx.lineTo(vBottom1.x, vBottom1.y + topY);
        ctx.lineTo(vBottom1.x, vBottom1.y + BASE_HEIGHT + WALL_SLOP_EPSILON);
        ctx.lineTo(vBottom2.x, vBottom2.y + BASE_HEIGHT + WALL_SLOP_EPSILON);
        ctx.lineTo(vBottom2.x, vBottom2.y); 
        ctx.closePath();
        ctx.fill();

        // Heavy Wall AO
        ctx.fillStyle = 'rgba(0,0,0,0.3)';
        ctx.fill();
    },

    drawTerrainDetail(
        ctx: CanvasRenderingContext2D, 
        baseX: number, baseY: number, 
        height: number,
        type: string, 
        detailColor: string,
        q: number, r: number
    ) {
        const visualY = baseY - height;
        const seed = Math.abs(Math.sin(q * 12.9 + r * 78.2));
        if (seed > 0.4) { 
             SurfacePainter.drawDetailTexture(ctx, baseX, visualY, type, detailColor, seed);
        }
    }
};

import { Agent } from "../../../game";
import { AnimState, Role } from "../../../../types";
import { getCastProgress } from "../utils";
import { THEME_IMPERIAL } from "../../../../constants";
import { HexGeometry } from "../../../graphics/utils/HexGeometry";

/**
 * 帝國 (Imperial) 渲染器 v20.0 - 低多邊形聖騎士
 * 設計風格：WC3 Classic, 實體幾何, 強力輪廓
 */
export const ImperialRenderer = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean, isRunning: boolean) {
        const isHit = agent.hitFlashTimer > 0;

        // 1. 低多邊形骨架動力學 (Skeleton Dynamics)
        // 行走時有強烈的垂直 bobbing (魔獸 3 行走特色)
        const walkFreq = isRunning ? 12 : 2.5;
        const walkAmp = isRunning ? 6 : 1.5;
        const bob = Math.sin(t * walkFreq) * walkAmp;

        // 呼吸頻率
        const breathe = Math.sin(t * 2) * 1.2;
        const yOffset = -35 + bob + (isRunning ? 0 : breathe);

        // 受擊震盪 (瞬間且硬派)
        const hitX = isHit ? (Math.sin(t * 50) * 5) : 0;

        ctx.save();
        ctx.translate(hitX, yOffset);

        // 2. [實體層] 多邊形建模 (低多邊形分面法)
        this.drawLowPolyBody(ctx, agent.role, isHit);
        this.drawHeavyShoulders(ctx, t, isRunning, isHit);
        this.drawKnightHelmet(ctx, isHit);

        // 3. 核心能源 (嵌入式實體水晶)
        this.drawManaCore(ctx, t, isHit);

        // 4. 重型武裝
        this.drawHeroicWeapon(ctx, agent, t, isRunning, isHit);

        ctx.restore();
    },

    /**
     * 軀幹：六邊形重型胸甲
     */
    drawLowPolyBody(ctx: CanvasRenderingContext2D, role: Role, isHit: boolean) {
        const w = role === Role.TANK ? 32 : 26;
        const h = 45;

        ctx.save();
        // 底層分面 (暗部)
        ctx.fillStyle = isHit ? '#fff' : '#1e3a8a';
        HexGeometry.traceHex(ctx, 0, 10, w, true); ctx.fill();

        // 正面裝甲板 (亮部 - 手動模擬 Faceted Lighting)
        ctx.fillStyle = isHit ? '#fff' : '#3b82f6';
        ctx.beginPath();
        ctx.moveTo(-w * 0.7, -5);
        ctx.lineTo(w * 0.7, -5);
        ctx.lineTo(w * 0.9, 25);
        ctx.lineTo(0, 40);
        ctx.lineTo(-w * 0.9, 25);
        ctx.closePath();
        ctx.fill();

        // 黃金裝飾線 (100% 實心)
        ctx.strokeStyle = '#fcd34d';
        ctx.lineWidth = 2.5;
        ctx.stroke();
        ctx.restore();
    },

    /**
     * 肩甲：巨大的稜形部件 (隨動作擺動)
     */
    drawHeavyShoulders(ctx: CanvasRenderingContext2D, t: number, isRunning: boolean, isHit: boolean) {
        const swing = Math.cos(t * (isRunning ? 12 : 2.5)) * (isRunning ? 0.3 : 0.05);

        const drawPauldron = (side: number) => {
            ctx.save();
            ctx.translate(side * 28, -5);
            ctx.rotate(side * swing);

            // 下層 (主色)
            ctx.fillStyle = isHit ? '#fff' : '#1e40af';
            ctx.beginPath();
            ctx.moveTo(0, -15);
            ctx.lineTo(side * 18, 0);
            ctx.lineTo(0, 15);
            ctx.lineTo(side * -5, 0);
            ctx.closePath();
            ctx.fill();

            // 上層包邊 (黃金)
            ctx.strokeStyle = '#fcd34d';
            ctx.lineWidth = 3;
            ctx.stroke();

            ctx.restore();
        };
        drawPauldron(-1); drawPauldron(1);
    },

    /**
     * 頭部：典型的中世紀十字桶盔
     */
    drawKnightHelmet(ctx: CanvasRenderingContext2D, isHit: boolean) {
        ctx.save();
        ctx.translate(0, -32);

        // 桶盔主體
        ctx.fillStyle = isHit ? '#fff' : '#cbd5e1';
        ctx.fillRect(-12, -18, 24, 24);

        // 頂部裝飾
        ctx.fillStyle = '#1e40af';
        ctx.beginPath();
        ctx.moveTo(-12, -18); ctx.lineTo(12, -18); ctx.lineTo(0, -28); ctx.closePath();
        ctx.fill();

        // 十字面罩縫隙
        ctx.fillStyle = '#0f172a';
        ctx.fillRect(-10, -8, 20, 2);
        ctx.fillRect(-1, -14, 2, 14);

        ctx.strokeStyle = '#94a3b8';
        ctx.lineWidth = 1.5;
        ctx.strokeRect(-12, -18, 24, 24);
        ctx.restore();
    },

    /**
     * 核心：嵌入體內的魔力水晶
     */
    drawManaCore(ctx: CanvasRenderingContext2D, t: number, isHit: boolean) {
        ctx.save();
        const pulse = 0.8 + Math.sin(t * 5) * 0.2;
        ctx.translate(0, 5);
        ctx.fillStyle = isHit ? '#fff' : '#60a5fa';
        ctx.shadowBlur = 15 * pulse;
        ctx.shadowColor = '#3b82f6';

        // 實體六邊形晶體
        HexGeometry.traceHex(ctx, 0, 0, 8, false);
        ctx.fill();

        // 亮點
        ctx.fillStyle = '#fff';
        ctx.shadowBlur = 0;
        ctx.beginPath(); ctx.arc(0, 0, 2, 0, Math.PI*2); ctx.fill();
        ctx.restore();
    },

    /**
     * 武器：巨大的低多邊形劍/槍
     */
    drawHeroicWeapon(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isRunning: boolean, isHit: boolean) {
        ctx.save();
        const weaponSwing = Math.sin(t * (isRunning ? 12 : 2.5)) * (isRunning ? 0.4 : 0.1);
        ctx.translate(30, 0);
        ctx.rotate(weaponSwing);

        if (agent.role === Role.RANGER) {
            // 重型弩砲 (Heavy Ballista)
            ctx.fillStyle = '#475569';
            ctx.fillRect(-15, -6, 40, 12);
            ctx.fillStyle = '#fcd34d';
            ctx.beginPath(); // 弓臂
            ctx.moveTo(10, -15); ctx.lineTo(15, 0); ctx.lineTo(10, 15); ctx.stroke();
            ctx.strokeStyle = '#60a5fa'; ctx.stroke();
        } else {
            // 實體大劍 (Greatsword)
            const swordLen = 70;
            ctx.fillStyle = '#94a3b8'; // 劍身
            ctx.beginPath();
            ctx.moveTo(0, 10); ctx.lineTo(-8, 0); ctx.lineTo(0, -swordLen); ctx.lineTo(8, 0); ctx.closePath();
            ctx.fill();

            ctx.fillStyle = '#fcd34d'; // 護手
            ctx.fillRect(-15, -2, 30, 6);

            ctx.strokeStyle = '#1e3a8a';
            ctx.lineWidth = 1;
            ctx.stroke(); // 強化邊界
        }
        ctx.restore();
    }
};

import { Agent } from "../../../game";
import { AnimState, Role } from "../../../../types";
import { getCastProgress } from "../utils";
import { THEME_COVENANT } from "../../../../constants";
import { HexGeometry } from "../../../graphics/utils/HexGeometry";

/**
 * 叛軍 (Covenant) 渲染器 v20.0 - 深淵掠奪者
 * 設計風格：WC3 Horde, 鋸齒狀邊緣, 殘暴動能
 */
export const CovenantRenderer = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean, isRunning: boolean) {
        const isHit = agent.hitFlashTimer > 0;
        const hpFactor = 1 - (agent.hp / agent.maxHp);

        // 1. 殘暴動力學 (Brutal Dynamics)
        // 動作更頻繁、振幅更大
        const moveFreq = isRunning ? 15 : 4;
        const moveAmp = isRunning ? 8 : 2;
        const bob = Math.abs(Math.sin(t * moveFreq)) * -moveAmp; // 跳躍式前進

        // 前傾角度 (戰鬥姿態)
        const lean = isRunning ? 0.3 : 0.15;

        ctx.save();
        ctx.translate(0, -35 + bob);
        ctx.rotate(lean);

        if (isHit) ctx.translate((Math.random()-0.5)*10, 0);

        // 2. [實體層] 幾何建模 (Jagged Polygons)
        this.drawBrutalChassis(ctx, agent.role, isHit);
        this.drawSpikedPauldrons(ctx, t, isRunning, isHit);
        this.drawTerrorMask(ctx, isHit);

        // 3. 熔岩核心 (脈動心臟)
        this.drawLavaCore(ctx, t, isHit);

        // 4. 殘暴武裝
        this.drawHeavyArsenal(ctx, agent, t, isRunning, isHit);

        ctx.restore();
    },

    /**
     * 軀幹：倒三角形重裝甲
     */
    drawBrutalChassis(ctx: CanvasRenderingContext2D, role: Role, isHit: boolean) {
        const w = role === Role.TANK ? 35 : 28;
        ctx.save();

        // 底層鋼鐵
        ctx.fillStyle = isHit ? '#fff' : '#18181b';
        ctx.beginPath();
        ctx.moveTo(0, -20);
        ctx.lineTo(w, -10);
        ctx.lineTo(w * 0.8, 50);
        ctx.lineTo(0, 65);
        ctx.lineTo(-w * 0.8, 50);
        ctx.lineTo(-w, -10);
        ctx.closePath();
        ctx.fill();

        // 血漬塗裝
        ctx.fillStyle = isHit ? '#fff' : '#7f1d1d';
        ctx.beginPath();
        ctx.moveTo(0, 0);
        ctx.lineTo(w * 0.6, 10);
        ctx.lineTo(0, 45);
        ctx.lineTo(-w * 0.6, 10);
        ctx.closePath();
        ctx.fill();

        ctx.strokeStyle = '#450a0a';
        ctx.lineWidth = 2;
        ctx.stroke();
        ctx.restore();
    },

    /**
     * 肩甲：巨大的骨刺或尖角
     */
    drawSpikedPauldrons(ctx: CanvasRenderingContext2D, t: number, isRunning: boolean, isHit: boolean) {
        const drawSpike = (side: number) => {
            ctx.save();
            ctx.translate(side * 25, -10);
            const shake = Math.sin(t * 20) * (isRunning ? 0.1 : 0);
            ctx.rotate(side * (0.4 + shake));

            ctx.fillStyle = isHit ? '#fff' : '#27272a';
            ctx.beginPath();
            ctx.moveTo(0, 0);
            ctx.lineTo(side * 35, -45); // 巨大的尖刺
            ctx.lineTo(side * 15, 10);
            ctx.closePath();
            ctx.fill();

            ctx.strokeStyle = '#ea580c'; // 銅邊
            ctx.lineWidth = 2.5;
            ctx.stroke();
            ctx.restore();
        };
        drawSpike(-1); drawSpike(1);
    },

    /**
     * 頭部：帶角的猙獰面具
     */
    drawTerrorMask(ctx: CanvasRenderingContext2D, isHit: boolean) {
        ctx.save();
        ctx.translate(0, -35);

        // 面具
        ctx.fillStyle = isHit ? '#fff' : '#fef2f2';
        ctx.beginPath();
        ctx.moveTo(0, -15); ctx.lineTo(12, 0); ctx.lineTo(0, 18); ctx.lineTo(-12, 0); ctx.closePath();
        ctx.fill();

        // 血紅眼窩
        ctx.fillStyle = '#f00';
        ctx.beginPath(); ctx.arc(-5, 0, 3, 0, Math.PI*2); ctx.fill();
        ctx.beginPath(); ctx.arc(5, 0, 3, 0, Math.PI*2); ctx.fill();

        ctx.restore();
    },

    /**
     * 核心：岩漿能量源
     */
    drawLavaCore(ctx: CanvasRenderingContext2D, t: number, isHit: boolean) {
        ctx.save();
        const pulse = 0.9 + Math.sin(t * 15) * 0.1;
        ctx.translate(0, 20);
        ctx.fillStyle = isHit ? '#fff' : '#ef4444';
        ctx.shadowBlur = 20 * pulse;
        ctx.shadowColor = '#f00';

        // 粗糙的碎塊
        for(let i=0; i<3; i++) {
            ctx.rotate(i);
            ctx.fillRect(-5, -5, 10, 10);
        }
        ctx.restore();
    },

    /**
     * 武器：巨大的碎骨斧或法杖
     */
    drawHeavyArsenal(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isRunning: boolean, isHit: boolean) {
        ctx.save();
        ctx.translate(35, 10);
        const swing = Math.cos(t * (isRunning ? 15 : 4)) * 0.3;
        ctx.rotate(swing);

        ctx.fillStyle = '#1c1917';
        ctx.strokeStyle = '#ea580c';
        ctx.lineWidth = 3;

        if (agent.role === Role.WARRIOR || agent.role === Role.TANK) {
            // 雙面巨斧 (Double-Headed Axe)
            ctx.fillRect(-5, -10, 10, 80); // 柄
            ctx.fillStyle = isHit ? '#fff' : '#991b1b';
            ctx.beginPath(); // 斧刃 A
            ctx.moveTo(0, 10); ctx.lineTo(-45, -5); ctx.lineTo(-40, 45); ctx.lineTo(0, 30); ctx.closePath(); ctx.fill(); ctx.stroke();
            ctx.beginPath(); // 斧刃 B
            ctx.moveTo(0, 10); ctx.lineTo(45, -5); ctx.lineTo(40, 45); ctx.lineTo(0, 30); ctx.closePath(); ctx.fill(); ctx.stroke();
        } else {
            // 邪能圖騰 (Fel Totem)
            ctx.fillRect(-12, -40, 24, 90);
            ctx.fillStyle = '#f00';
            ctx.fillRect(-15, -45, 30, 10);
            ctx.strokeRect(-12, -40, 24, 90);
        }
        ctx.restore();
    }
};

import { Agent } from "../../../../game";
import { Team, AnimState, MovementType } from "../../../../../types";
import { UNIT_SCALE } from "../../../../../../../constants";
import { ImperialRenderer } from "../factions/ImperialRenderer";
import { CovenantRenderer } from "../factions/CovenantRenderer";
import { SpriteManager } from "../../../sprites";
import { VisualMath } from "../../../math/VisualMath";

/**
 * 單位主體繪製器 v20.0 (Warcraft 3 實體版)
 * 優化：完全移除全像投影混合，強化實體幾何感
 */
export const UnitBodyPainter = {
    draw(
        ctx: CanvasRenderingContext2D, 
        agent: Agent, 
        px: number, py: number, pz: number, 
        t: number, 
        isSilhouette: boolean, 
        isSelected: boolean,
        scaleFactor: number,
        isRunning: boolean
    ) {
        ctx.save(); 

        // 1. 視覺定位 (SSOT)
        const bodyY = VisualMath.getVisualBodyCenterY(py, pz);
        ctx.translate(px, bodyY); 

        // 2. 全局比例
        const baseScale = UNIT_SCALE * (isSelected ? 1.15 : 1.0);
        ctx.scale(baseScale, baseScale);
        ctx.rotate(agent.physics.angle); 

        // 3. 狀態濾鏡 (強化實體對比)
        if (agent.hp <= 0 && !isSilhouette) {
            ctx.filter = 'grayscale(100%) brightness(40%)'; 
        } else if (!isSilhouette && agent.hitFlashTimer > 0) {
             ctx.filter = 'brightness(300%) contrast(150%)';
        }

        // 4. 方向 (魔獸風格：誇張的水平翻轉)
        ctx.scale(agent.facing > 0 ? 1 : -1, 1); 

        // 5. 陣營渲染 (實體繪製)
        if (isSilhouette) {
            ctx.globalAlpha = 0.5;
            ctx.fillStyle = agent.team === Team.BLUE ? '#3b82f6' : '#ef4444';
            // 剪影模式仍維持基本輪廓
        }

        if (agent.team === Team.BLUE) {
            ImperialRenderer.draw(ctx, agent, t, isSilhouette, isRunning);
        } else {
            CovenantRenderer.draw(ctx, agent, t, isSilhouette, isRunning);
        }

        // 6. 選擇圈 (實體風格)
        if (isSelected && !isSilhouette) {
            ctx.save();
            ctx.strokeStyle = agent.team === Team.BLUE ? '#60a5fa' : '#ef4444';
            ctx.lineWidth = 3;
            ctx.beginPath();
            ctx.ellipse(0, 50, 35, 12, 0, 0, Math.PI * 2);
            ctx.stroke();
            // 追加旋轉標記
            ctx.rotate(t * 2);
            ctx.strokeRect(-40, 48, 80, 4);
            ctx.restore();
        }

        ctx.restore(); 
    }
};

import { Agent } from "../../../game";
import { AnimState, Role } from "../../../../types";
import { THEME_IMPERIAL } from "../../../../constants";
import { HexGeometry } from "../../../graphics/utils/HexGeometry";

/**
 * 帝國 (Imperial) 渲染器 v21.0 - 低多邊形戰爭
 * 特色：職階建模特化、WC3 補間動態
 */
export const ImperialRenderer = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean, isRunning: boolean) {
        const isHit = agent.hitFlashTimer > 0;
        const role = agent.role;

        // 1. 動力學骨架 (Role-Specific Animation)
        let bob = 0;
        let swing = 0;

        if (isRunning) {
            // 魔獸 3 經典笨重跑姿
            const freq = role === Role.TANK ? 10 : 14;
            const amp = role === Role.TANK ? 8 : 5;
            bob = Math.abs(Math.sin(t * freq)) * -amp;
            swing = Math.sin(t * freq) * 0.2;
        } else {
            // 待機呼吸感
            bob = Math.sin(t * 2) * 2;
        }

        ctx.save();
        if (isHit) ctx.translate((Math.random() - 0.5) * 10, 0);
        ctx.translate(0, -35 + bob);
        ctx.rotate(swing);

        // 2. 職階建模 (Faceted Class Models)
        this.drawRoleModel(ctx, role, isHit, isSilhouette, t);

        // 3. 武器系統
        this.drawRoleWeapon(ctx, agent, t, isRunning);

        ctx.restore();
    },

    /**
     * 根據職階繪製不同的低多邊形主體
     */
    drawRoleModel(ctx: CanvasRenderingContext2D, role: Role, isHit: boolean, isSil: boolean, t: number) {
        const primary = isHit ? '#fff' : '#1e40af'; // 深藍
        const highlight = isHit ? '#fff' : '#3b82f6'; // 亮藍
        const gold = '#fcd34d';

        ctx.save();

        switch (role) {
            case Role.TANK:
                // 【坦克】：重型方體，厚重感
                ctx.fillStyle = primary;
                ctx.fillRect(-22, -10, 44, 45); // 巨型胸甲
                ctx.fillStyle = highlight;
                ctx.fillRect(-18, 0, 36, 15);
                ctx.strokeStyle = gold;
                ctx.lineWidth = 3;
                ctx.strokeRect(-22, -10, 44, 45);

                // 額外肩甲
                this.drawCubePauldron(ctx, -25, -15, 12, gold);
                this.drawCubePauldron(ctx, 25, -15, 12, gold);
                break;

            case Role.WARRIOR:
                // 【戰士】：倒三角英雄身材
                ctx.fillStyle = primary;
                ctx.beginPath();
                ctx.moveTo(-25, -15); ctx.lineTo(25, -15); ctx.lineTo(15, 35); ctx.lineTo(-15, 35);
                ctx.closePath(); ctx.fill();
                ctx.strokeStyle = gold;
                ctx.lineWidth = 2;
                ctx.stroke();

                this.drawCubePauldron(ctx, -28, -18, 15, highlight);
                this.drawCubePauldron(ctx, 28, -18, 15, highlight);
                break;

            case Role.MAGE:
            case Role.SUPPORT:
                // 【法系】：懸浮稜鏡法袍
                ctx.fillStyle = primary;
                HexGeometry.traceHex(ctx, 0, 15, 22, true); ctx.fill();
                ctx.fillStyle = highlight;
                HexGeometry.traceHex(ctx, 0, -5, 18, true); ctx.fill();

                // 漂浮的幾何光環
                ctx.save();
                ctx.rotate(t);
                ctx.strokeStyle = gold;
                ctx.setLineDash([5, 5]);
                HexGeometry.traceHex(ctx, 0, 0, 35, false); ctx.stroke();
                ctx.restore();
                break;

            case Role.RANGER:
                // 【遊俠】：纖細流線型
                ctx.fillStyle = primary;
                ctx.fillRect(-14, -10, 28, 45);
                ctx.fillStyle = highlight;
                ctx.beginPath();
                ctx.moveTo(-14, -10); ctx.lineTo(14, -10); ctx.lineTo(0, -35); // 披風感
                ctx.closePath(); ctx.fill();
                break;
        }

        // 統一頭部：低多邊形桶盔
        ctx.fillStyle = '#cbd5e1';
        ctx.fillRect(-10, -28, 20, 20);
        ctx.strokeStyle = '#475569';
        ctx.lineWidth = 1.5;
        ctx.strokeRect(-10, -28, 20, 20);
        ctx.fillStyle = '#ef4444'; // 電子眼
        ctx.fillRect(-8, -18, 16, 3);

        ctx.restore();
    },

    drawCubePauldron(ctx: CanvasRenderingContext2D, x: number, y: number, size: number, color: string) {
        ctx.fillStyle = color;
        ctx.fillRect(x - size/2, y - size/2, size, size);
        ctx.strokeStyle = '#000';
        ctx.lineWidth = 1;
        ctx.strokeRect(x - size/2, y - size/2, size, size);
    },

    drawRoleWeapon(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isRunning: boolean) {
        ctx.save();
        ctx.translate(32, 0);
        const swing = Math.sin(t * (isRunning ? 15 : 3)) * 0.3;
        ctx.rotate(swing);

        ctx.fillStyle = '#94a3b8';
        ctx.strokeStyle = '#1e3a8a';
        ctx.lineWidth = 2;

        if (agent.role === Role.TANK) {
            // 巨型塔盾
            ctx.fillStyle = '#475569';
            ctx.fillRect(-5, -20, 35, 60);
            ctx.strokeStyle = '#fcd34d';
            ctx.strokeRect(-5, -20, 35, 60);
            ctx.fillStyle = '#3b82f6';
            ctx.fillRect(5, 5, 15, 15); // 盾徽
        } else if (agent.role === Role.RANGER) {
            // 長型火槍/弩
            ctx.fillStyle = '#334155';
            ctx.fillRect(-15, -4, 50, 8);
            ctx.fillStyle = '#60a5fa';
            ctx.fillRect(30, -5, 10, 10); // 瞄準鏡
        } else if (agent.role === Role.WARRIOR) {
            // 寬刃大劍
            ctx.beginPath();
            ctx.moveTo(0, 15); ctx.lineTo(-10, 0); ctx.lineTo(0, -65); ctx.lineTo(10, 0);
            ctx.closePath(); ctx.fill(); ctx.stroke();
        } else {
            // 魔法權杖 (漂浮核心)
            ctx.fillRect(-3, -20, 6, 60);
            ctx.fillStyle = '#60a5fa';
            ctx.save();
            ctx.translate(0, -30);
            ctx.rotate(t * 2);
            HexGeometry.traceHex(ctx, 0, 0, 12, false); ctx.fill();
            ctx.restore();
        }
        ctx.restore();
    }
};

import { Agent } from "../../../game";
import { AnimState, Role } from "../../../../types";
import { THEME_COVENANT } from "../../../../constants";
import { HexGeometry } from "../../../graphics/utils/HexGeometry";

/**
 * 叛軍 (Covenant) 渲染器 v21.0 - 深淵狂暴
 * 特色：非對稱低多邊形、高頻震動動態
 */
export const CovenantRenderer = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean, isRunning: boolean) {
        const isHit = agent.hitFlashTimer > 0;
        const role = agent.role;

        // 1. 狂暴動態 (Aggressive Dynamics)
        let bob = 0;
        let lean = 0.2; // 預設前傾

        if (isRunning) {
            const freq = 18; // 極高頻率
            bob = Math.abs(Math.cos(t * freq)) * -10; // 彈跳感
            lean = 0.4;
        } else {
            bob = Math.sin(t * 5) * 3;
        }

        ctx.save();
        if (isHit) ctx.translate((Math.random() - 0.5) * 15, 0);
        ctx.translate(0, -35 + bob);
        ctx.rotate(lean);

        // 2. 職階建模 (Jagged Poly Models)
        this.drawRoleModel(ctx, role, isHit, isSilhouette, t);

        // 3. 武裝
        this.drawRoleWeapon(ctx, agent, t, isRunning);

        ctx.restore();
    },

    drawRoleModel(ctx: CanvasRenderingContext2D, role: Role, isHit: boolean, isSil: boolean, t: number) {
        const dark = isHit ? '#fff' : '#18181b';
        const blood = isHit ? '#fff' : '#991b1b';
        const fire = '#ea580c';

        ctx.save();

        switch (role) {
            case Role.TANK:
                // 【大隻佬】：多刺的圓筒體
                ctx.fillStyle = dark;
                HexGeometry.traceHex(ctx, 0, 15, 28, true); ctx.fill();
                ctx.strokeStyle = blood;
                ctx.lineWidth = 3;
                HexGeometry.traceHex(ctx, 0, 15, 28, true); ctx.stroke();

                // 背部尖刺
                this.drawSpike(ctx, -20, -10, 30, t, -0.5);
                this.drawSpike(ctx, 20, -10, 30, t, 0.5);
                break;

            case Role.WARRIOR:
                // 【掠奪者】：極端倒三角
                ctx.fillStyle = dark;
                ctx.beginPath();
                ctx.moveTo(-30, -20); ctx.lineTo(30, -20); ctx.lineTo(10, 40); ctx.lineTo(-10, 40);
                ctx.closePath(); ctx.fill();

                this.drawSpike(ctx, -32, -22, 25, t * 1.5, -0.8);
                this.drawSpike(ctx, 32, -22, 25, t * 1.5, 0.8);
                break;

            case Role.MAGE:
            case Role.SUPPORT:
                // 【邪能者】：不規則破碎體
                ctx.fillStyle = dark;
                ctx.save();
                ctx.rotate(t * 0.5);
                HexGeometry.traceRotatedHex(ctx, 0, 0, 25, 0, false); ctx.fill();
                ctx.strokeStyle = fire;
                ctx.lineWidth = 2;
                HexGeometry.traceRotatedHex(ctx, 0, 0, 25, 0.5, false); ctx.stroke();
                ctx.restore();

                // 懸浮法球
                ctx.fillStyle = fire;
                ctx.beginPath(); ctx.arc(Math.cos(t*4)*40, Math.sin(t*4)*20 - 20, 6, 0, Math.PI*2); ctx.fill();
                break;

            case Role.RANGER:
                // 【追獵者】：輕捷、帶刺
                ctx.fillStyle = dark;
                ctx.fillRect(-15, -15, 30, 50);
                ctx.fillStyle = blood;
                ctx.fillRect(-15, -15, 30, 10);
                this.drawSpike(ctx, 0, -35, 20, t, 0);
                break;
        }

        // 頭部：猙獰面具
        ctx.fillStyle = '#fef2f2';
        ctx.beginPath();
        ctx.moveTo(0, -15); ctx.lineTo(12, 0); ctx.lineTo(0, 18); ctx.lineTo(-12, 0);
        ctx.closePath(); ctx.fill();
        ctx.fillStyle = '#f00'; // 血眼
        ctx.fillRect(-6, -2, 4, 4); ctx.fillRect(2, -2, 4, 4);

        ctx.restore();
    },

    drawSpike(ctx: CanvasRenderingContext2D, x: number, y: number, h: number, t: number, ang: number) {
        ctx.save();
        ctx.translate(x, y);
        ctx.rotate(ang + Math.sin(t*10)*0.1);
        ctx.fillStyle = '#27272a';
        ctx.beginPath();
        ctx.moveTo(-5, 0); ctx.lineTo(5, 0); ctx.lineTo(0, -h);
        ctx.closePath(); ctx.fill();
        ctx.strokeStyle = '#ef4444';
        ctx.stroke();
        ctx.restore();
    },

    drawRoleWeapon(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isRunning: boolean) {
        ctx.save();
        ctx.translate(35, 10);
        const swing = Math.cos(t * (isRunning ? 18 : 5)) * 0.4;
        ctx.rotate(swing);

        ctx.fillStyle = '#1c1917';
        ctx.strokeStyle = '#ea580c';
        ctx.lineWidth = 2.5;

        if (agent.role === Role.WARRIOR || agent.role === Role.TANK) {
            // 雙頭巨斧
            ctx.fillRect(-4, -10, 8, 80);
            ctx.fillStyle = '#7f1d1d';
            ctx.beginPath(); 
            ctx.moveTo(0, 10); ctx.lineTo(-40, -5); ctx.lineTo(-35, 40); ctx.lineTo(0, 25);
            ctx.closePath(); ctx.fill(); ctx.stroke();
            ctx.beginPath();
            ctx.moveTo(0, 10); ctx.lineTo(40, -5); ctx.lineTo(35, 40); ctx.lineTo(0, 25);
            ctx.closePath(); ctx.fill(); ctx.stroke();
        } else {
            // 邪能圖騰/弩
            ctx.fillRect(-10, -40, 20, 100);
            ctx.fillStyle = '#ef4444';
            ctx.shadowBlur = 15; ctx.shadowColor = '#f00';
            ctx.fillRect(-12, -45, 24, 12);
        }
        ctx.restore();
    }
};

import { ISO_SCALE_Y, BASE_HEIGHT, BLOCK_HEIGHT } from "../../../constants";
import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { SurfacePainter } from "../../graphics/painters/SurfacePainter";
import { HexLayout } from "../../../types";

const WALL_SLOP_EPSILON = 1.0; 

export const TerrainRenderer = {

    drawBlock(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        size: number, height: number, 
        theme: any,
        type: string,
        globalTime: number,
        layout: HexLayout
    ) {
        const visualTopY = -height;
        const vertices = HexGeometry.getVertices(size, true, layout); 

        ctx.save();
        ctx.translate(x, y);

        // --- WALL RENDERING (AO & DEPTH) ---
        // 側向牆面增加硬派的高對比線條
        this.drawVerticalWall(ctx, vertices[1], vertices[0], visualTopY, theme.sideDark);
        this.drawVerticalWall(ctx, vertices[2], vertices[1], visualTopY, theme.sideLight);
        if (layout === 'FLAT') {
            this.drawVerticalWall(ctx, vertices[3], vertices[2], visualTopY, theme.sideDark);
        }

        // --- TOP FACE RENDERING ---
        ctx.translate(0, visualTopY);

        // 1. 低多邊形分面填充 (Faceted Top)
        const topGrad = ctx.createLinearGradient(-size, -size, size, size);
        topGrad.addColorStop(0, theme.rim); 
        topGrad.addColorStop(0.15, theme.top); 
        topGrad.addColorStop(0.8, theme.sideDark); 
        ctx.fillStyle = topGrad;

        HexGeometry.traceHex(ctx, 0, 0, size, true, layout);
        ctx.fill();

        // 2. 增加「材質噪點 (Faceted Grit)」
        // 這是重點：用來區分地形與 AOE 圈
        this.drawMaterialGrit(ctx, size, theme.detail, layout);

        // 3. 厚重硬邊緣
        ctx.strokeStyle = theme.rim;
        ctx.lineWidth = 1.5;
        ctx.globalAlpha = 1.0; 
        ctx.stroke();

        // 4. 動態場景效果
        this.applyThemeSurfaceDynamics(ctx, size, type, theme, globalTime, layout);

        ctx.restore();
    },

    drawMaterialGrit(ctx: CanvasRenderingContext2D, size: number, color: string, layout: HexLayout) {
        ctx.save();
        ctx.globalAlpha = 0.15;
        ctx.fillStyle = color;
        // 在表面隨機繪製一些微小的三角形/幾何塊
        const seed = Math.abs(Math.sin(ctx.canvas.width + ctx.canvas.height));
        for(let i=0; i<3; i++) {
            const gx = (Math.sin(seed * 123 + i) * 0.6) * size;
            const gy = (Math.cos(seed * 456 + i) * 0.4) * size * ISO_SCALE_Y;
            ctx.beginPath();
            ctx.moveTo(gx, gy);
            ctx.lineTo(gx + 10, gy + 5);
            ctx.lineTo(gx + 5, gy + 12);
            ctx.closePath();
            ctx.fill();
        }
        ctx.restore();
    },

    applyThemeSurfaceDynamics(ctx: CanvasRenderingContext2D, size: number, type: string, theme: any, t: number, layout: HexLayout) {
        ctx.save();
        ctx.globalAlpha = 0.8; 

        if (type === 'FOREST') {
            ctx.strokeStyle = theme.detail;
            ctx.lineWidth = 1;
            const pulse = 0.5 + Math.sin(t * 2) * 0.2;
            ctx.globalAlpha = pulse;
            // 繪製內嵌的小型六邊形裝飾，維持低多邊形語言
            HexGeometry.traceHex(ctx, 0, 0, size * 0.7, true, layout); ctx.stroke();
        } 
        else if (type === 'MAGMA') {
            const offset = (t * 30) % 100;
            ctx.strokeStyle = '#ef4444';
            ctx.lineWidth = 2;
            ctx.beginPath();
            ctx.moveTo(-size, -size/2 + offset); ctx.lineTo(size, size/2 - 20 + offset);
            ctx.stroke();
            SurfacePainter.drawLiquid(ctx, 0, 0, '#ef4444', t, 1.2);
        }
        else if (type === 'VOID') {
            ctx.strokeStyle = theme.detail;
            ctx.lineWidth = 1.2;
            const scanY = (t * 50) % (size * 2.5) - size * 1.25;
            ctx.beginPath();
            ctx.moveTo(-size * 0.9, scanY * ISO_SCALE_Y); ctx.lineTo(size * 0.9, scanY * ISO_SCALE_Y);
            ctx.stroke();
        }

        ctx.restore();
    },

    drawVerticalWall(ctx: CanvasRenderingContext2D, vBottom1: {x:number, y:number}, vBottom2: {x:number, y:number}, topY: number, color: string) {
        ctx.fillStyle = color;
        ctx.beginPath();
        ctx.moveTo(vBottom1.x, vBottom1.y);
        ctx.lineTo(vBottom2.x, vBottom2.y);
        ctx.lineTo(vBottom2.x, vBottom2.y + topY);
        ctx.lineTo(vBottom1.x, vBottom1.y + topY);
        ctx.closePath();
        ctx.fill();

        // 增加牆面分界的硬邊緣線
        ctx.strokeStyle = 'rgba(0,0,0,0.3)';
        ctx.lineWidth = 1;
        ctx.stroke();
    },

    drawTerrainDetail(
        ctx: CanvasRenderingContext2D, 
        baseX: number, baseY: number, 
        height: number,
        type: string, 
        detailColor: string,
        q: number, r: number
    ) {
        const visualY = baseY - height;
        const seed = Math.abs(Math.sin(q * 12.9 + r * 78.2));
        if (seed > 0.6) { // 降低頻率
             SurfacePainter.drawDetailTexture(ctx, baseX, visualY, type, detailColor, seed);
        }
    }
};

import { useRef, useState, useCallback, useEffect } from 'react';
import { GameEngine, Agent } from '../engine/game';
import { ToolType, Team, Skill, Role, HexLayout } from '../types';
import { SCENE_DB } from '../data/scenes';
import { DesignExporter } from '../engine/systems/DesignExporter';
import { DEFAULT_HEX_LAYOUT } from '../constants';
import { UNIT_DB } from '../data/units';

export const useGameApp = () => {
    const engineRef = useRef(new GameEngine());

    // --- STATE ---
    const [isShowcaseMode, setIsShowcaseMode] = useState(true);
    const [isPlaying, setIsPlaying] = useState(false);
    const [unitCount, setUnitCount] = useState(0); 
    const [tool, setTool] = useState<ToolType>(ToolType.SELECT);
    const [selectedObstacle, setSelectedObstacle] = useState<string>('WALL'); 
    const [selectedAgent, setSelectedAgent] = useState<Agent | null>(null);
    const [hoveredSkill, setHoveredSkill] = useState<Skill | null>(null);
    const [hpInput, setHpInput] = useState(600); 
    const [mapW, setMapW] = useState(12);
    const [mapH, setMapH] = useState(8);
    const [timeScale, setTimeScale] = useState(1.0);
    const [winner, setWinner] = useState<Team | null>(null);
    const [currentSceneId, setCurrentSceneId] = useState('VOID');
    const [spawnMode, setSpawnMode] = useState<'RANDOM' | 'DRAFT'>('RANDOM');
    const [draftRole, setDraftRole] = useState<Role>(Role.WARRIOR);
    const [hexLayout, setHexLayout] = useState<HexLayout>(DEFAULT_HEX_LAYOUT);

    // UI State
    const [showLogs, setShowLogs] = useState(false);
    const [showDB, setShowDB] = useState(false);
    const [showVFXMap, setShowVFXMap] = useState(false); 
    const [transitionPhase, setTransitionPhase] = useState<'IDLE' | 'IN' | 'OUT'>('IDLE');
    const [showFactionWarning, setShowFactionWarning] = useState(false);

    // --- EVENT LISTENER SETUP ---
    useEffect(() => {
        const engine = engineRef.current;
        const handleGameOver = (data: { winner: Team }) => {
            setWinner(data.winner);
            if (engine.isRunning) engine.stop(); 
            setIsPlaying(false);
        };
        engine.bus.on('GAME_OVER', handleGameOver);
        return () => {
            engine.bus.off('GAME_OVER', handleGameOver);
        };
    }, []);

    // Showcase Auto-Loop Logic
    useEffect(() => {
        if (isShowcaseMode && winner !== null) {
            const timer = setTimeout(() => {
                setTransitionPhase('OUT');
                engineRef.current.agents = [];
                engineRef.current.combat.projectiles = [];

                setTimeout(() => {
                    setupShowcaseMap(); 
                    setTransitionPhase('IN'); 
                    setTimeout(() => {
                        setTransitionPhase('IDLE');
                        spawnShowcaseUnits(); 
                    }, 1200); 
                }, 1200); 
            }, 800); 
            return () => clearTimeout(timer);
        }
    }, [winner, isShowcaseMode]);

    // --- LOGIC ---

    const setupShowcaseMap = useCallback(() => {
        const engine = engineRef.current;
        engine.stop();
        setWinner(null);
        setSelectedAgent(null);

        engine.mapConfig.w = Math.floor(10 + Math.random() * 4);
        engine.mapConfig.h = Math.floor(8 + Math.random() * 4);

        const newLayout: HexLayout = Math.random() > 0.5 ? 'FLAT' : 'POINTY';
        engine.mapConfig.layout = newLayout;
        setHexLayout(newLayout);

        engine.randomizeEnvironment(); 
        setCurrentSceneId(engine.currentScene.id);
    }, []);

    /**
     * 重寫生成邏輯：保證每隊擁有全職業
     */
    const spawnShowcaseUnits = useCallback(() => {
        const engine = engineRef.current;
        let validHexes = (Array.from(engine.mapKeys) as string[])
            .map(k => {
                const [q, r] = k.split(',').map(Number);
                return {q, r};
            })
            .filter(h => !engine.map.hasObstacle(h.q, h.r));

        // 洗牌可用座標
        for (let i = validHexes.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [validHexes[i], validHexes[j]] = [validHexes[j], validHexes[i]];
        }

        let spawnIndex = 0;
        const ROLES = [Role.TANK, Role.WARRIOR, Role.RANGER, Role.MAGE, Role.SUPPORT];

        const spawnTeam = (team: Team) => {
            // 1. 保證每個職業至少生成一個
            ROLES.forEach(role => {
                if (spawnIndex < validHexes.length) {
                    const h = validHexes[spawnIndex++];
                    const hp = 600 + Math.floor(Math.random() * 400);
                    const agent = engine.addAgent(team, h.q, h.r, hp);
                    if (agent) {
                        agent.role = role;
                        // 重新計算屬性以匹配職階
                        const stats = UNIT_DB[role];
                        agent.maxHp = hp; agent.hp = hp;
                        agent.moveSpeed = stats.moveSpeed;
                        agent.movementType = stats.movementType;
                        agent.saveState();
                        agent.reset(engine.mapConfig);
                    }
                }
            });

            // 2. 隨機補充額外單位
            const EXTRA = 1;
            for(let i=0; i<EXTRA; i++) {
                if (spawnIndex < validHexes.length) {
                    const h = validHexes[spawnIndex++];
                    engine.addAgent(team, h.q, h.r, 500);
                }
            }
        };

        spawnTeam(Team.BLUE);
        spawnTeam(Team.RED);

        engine.play();
        setIsPlaying(true);
    }, []);

    const startShowcaseMatch = useCallback(() => {
        setupShowcaseMap();
        spawnShowcaseUnits();
    }, [setupShowcaseMap, spawnShowcaseUnits]);

    useEffect(() => {
        startShowcaseMatch();
    }, [startShowcaseMatch]);

    useEffect(() => {
        const interval = setInterval(() => {
            setUnitCount(engineRef.current.agents.length);
        }, 500); 
        return () => clearInterval(interval);
    }, []);

    useEffect(() => {
        engineRef.current.timeScale = timeScale;
    }, [timeScale]);

    const enterManualMode = () => {
        setIsShowcaseMode(false);
        engineRef.current.stop();
        setIsPlaying(false);
        setWinner(null);
        engineRef.current.clear(true); 
        engineRef.current.agents = [];
        setUnitCount(0);
        setMapW(engineRef.current.mapConfig.w);
        setMapH(engineRef.current.mapConfig.h);
        setHexLayout(engineRef.current.mapConfig.layout);
        setCurrentSceneId(engineRef.current.currentScene.id);
    };

    const handleUpdateMapSize = useCallback((w: number, h: number) => {
        setMapW(w);
        setMapH(h);
        engineRef.current.mapConfig.w = w;
        engineRef.current.mapConfig.h = h;
        engineRef.current.clear(false); 
        setSelectedAgent(null);
        setWinner(null);
    }, []);

    const handleUpdateLayout = useCallback((l: HexLayout) => {
        setHexLayout(l);
        engineRef.current.mapConfig.layout = l;
        engineRef.current.clear(true); 
        setSelectedAgent(null);
        setWinner(null);
    }, []);

    const handleSetScene = useCallback((id: string) => {
        const scene = SCENE_DB.find(s => s.id === id);
        if (scene) {
            engineRef.current.currentScene = scene;
            engineRef.current.map.rebuildMap(engineRef.current);
            setCurrentSceneId(id);
        }
    }, []);

    const handleRandomBattlefield = useCallback(() => {
        const engine = engineRef.current;
        engine.stop();
        setWinner(null);
        setSelectedAgent(null);
        engine.clear(false); 

        const newLayout: HexLayout = Math.random() > 0.5 ? 'FLAT' : 'POINTY';
        engine.mapConfig.layout = newLayout;
        setHexLayout(newLayout);

        engine.randomizeEnvironment();
        setMapW(engine.mapConfig.w);
        setMapH(engine.mapConfig.h);
        setCurrentSceneId(engine.currentScene.id);

        spawnShowcaseUnits(); // 使用改進後的生成邏輯
    }, [spawnShowcaseUnits]);

    const handleNextLevel = useCallback(() => {
        handleRandomBattlefield();
        const engine = engineRef.current;
        engine.play();
        setIsPlaying(true);
        setTool(ToolType.SELECT);
    }, [handleRandomBattlefield]);

    const handleReset = useCallback(() => {
        engineRef.current.restart();
        setIsPlaying(false); 
        setWinner(null);
    }, []);

    const togglePlay = useCallback(() => {
        if (winner !== null) return;
        if (isPlaying) {
            engineRef.current.stop();
            setIsPlaying(false);
        } else {
            const hasBlue = engineRef.current.agents.some(a => a.team === Team.BLUE);
            const hasRed = engineRef.current.agents.some(a => a.team === Team.RED);
            if (!hasBlue || !hasRed) {
                setShowFactionWarning(true);
                setTimeout(() => setShowFactionWarning(false), 2500);
                return;
            }
            engineRef.current.play();
            setIsPlaying(true);
            setTool(ToolType.SELECT);
        }
    }, [isPlaying, winner]);

    const handleSelectAgent = (a: Agent | null) => {
        setSelectedAgent(a);
    };

    return {
        engineRef,
        state: {
            isShowcaseMode, isPlaying, unitCount, tool, selectedObstacle,
            selectedAgent, hoveredSkill, hpInput, mapW, mapH, timeScale,
            winner, currentSceneId, spawnMode, draftRole, showLogs, showDB, showVFXMap,
            transitionPhase, showFactionWarning, hexLayout
        },
        setters: {
            setTool, setSelectedObstacle, setHpInput, setTimeScale, 
            setSpawnMode, setDraftRole, setShowLogs, setShowDB, setShowVFXMap,
            setIsShowcaseMode, setSelectedAgent, setHoveredSkill
        },
        actions: {
            enterManualMode,
            handleUpdateMapSize,
            handleUpdateLayout,
            handleSetScene,
            handleRandomBattlefield,
            handleNextLevel,
            handleReset,
            togglePlay,
            onWin: (team: Team) => { engineRef.current.bus.emit('GAME_OVER', {winner: team}) },
            handleSelectAgent,
            startShowcaseMatch,
            downloadSpec: DesignExporter.downloadSpec,
            rematch: () => { 
                setWinner(null); 
                engineRef.current.restart(); 
                engineRef.current.play(); 
                setIsPlaying(true); 
            }
        }
    };
};

import { Agent } from "../../../game";
import { AnimState, Role } from "../../../../types";
import { HexGeometry } from "../../../graphics/utils/HexGeometry";

/**
 * 帝國 (Imperial) 渲染器 v21.0 - 魔獸經典低多邊形版
 * 核心語言：秩序、白銀與黃金、實體幾何
 */
export const ImperialRenderer = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean, isRunning: boolean) {
        const isHit = agent.hitFlashTimer > 0;
        const role = agent.role;

        // 1. 動力學骨架 (Role-Specific Animation)
        // 魔獸 3 經典的垂直重心起伏 (Bobbing)
        let bob = 0;
        let tilt = 0;

        if (isRunning) {
            const freq = role === Role.TANK ? 10 : 14;
            const amp = role === Role.TANK ? 7 : 4;
            bob = Math.abs(Math.sin(t * freq)) * -amp;
            tilt = Math.sin(t * freq) * 0.15;
        } else {
            // 英雄待機呼吸
            bob = Math.sin(t * 2.5) * 1.5;
        }

        ctx.save();
        if (isHit) ctx.translate((Math.random() - 0.5) * 12, 0);

        // 渲染主體位置
        ctx.translate(0, -35 + bob);
        ctx.rotate(tilt);

        // 2. 實體職階建模 (Faceted Modeling)
        this.drawFacetedBody(ctx, role, isHit, t);

        // 3. 英雄武裝
        this.drawWeapon(ctx, role, t, isRunning);

        ctx.restore();
    },

    /**
     * 根據職階繪製不同的分面實體
     */
    drawFacetedBody(ctx: CanvasRenderingContext2D, role: Role, isHit: boolean, t: number) {
        const silver = isHit ? '#fff' : '#cbd5e1';
        const cobalt = isHit ? '#fff' : '#1e40af';
        const gold = '#fcd34d';

        ctx.save();

        switch (role) {
            case Role.TANK:
                // 【重裝坦克】：厚重的長方體胸甲
                ctx.fillStyle = cobalt;
                ctx.fillRect(-22, -10, 44, 45); 
                ctx.fillStyle = silver; // 正面亮部
                ctx.fillRect(-18, 0, 36, 12);
                ctx.strokeStyle = gold;
                ctx.lineWidth = 3;
                ctx.strokeRect(-22, -10, 44, 45);

                // 巨型肩盾
                this.drawPrismPauldron(ctx, -25, -15, 14, gold);
                this.drawPrismPauldron(ctx, 25, -15, 14, gold);
                break;

            case Role.WARRIOR:
                // 【戰士】：倒三角英雄闊肩
                ctx.fillStyle = cobalt;
                ctx.beginPath();
                ctx.moveTo(-26, -18); ctx.lineTo(26, -18); ctx.lineTo(15, 35); ctx.lineTo(-15, 35);
                ctx.closePath(); ctx.fill();
                ctx.strokeStyle = gold;
                ctx.lineWidth = 2.5;
                ctx.stroke();

                this.drawPrismPauldron(ctx, -28, -20, 16, silver);
                this.drawPrismPauldron(ctx, 28, -20, 16, silver);
                break;

            case Role.MAGE:
            case Role.SUPPORT:
                // 【法系】：懸浮的稜鏡法袍
                ctx.fillStyle = cobalt;
                HexGeometry.traceHex(ctx, 0, 15, 22, true); ctx.fill();
                ctx.fillStyle = silver;
                HexGeometry.traceHex(ctx, 0, -5, 18, true); ctx.fill();

                // 旋轉的奧術核心
                ctx.save();
                ctx.rotate(t * 1.5);
                ctx.strokeStyle = gold;
                ctx.setLineDash([6, 4]);
                HexGeometry.traceHex(ctx, 0, 0, 38, false); ctx.stroke();
                ctx.restore();
                break;

            case Role.RANGER:
                // 【遊俠】：纖細流線，不對稱斗篷
                ctx.fillStyle = cobalt;
                ctx.fillRect(-15, -10, 30, 45);
                ctx.fillStyle = silver;
                ctx.beginPath();
                ctx.moveTo(-15, -10); ctx.lineTo(15, -10); ctx.lineTo(0, -38);
                ctx.closePath(); ctx.fill();
                break;
        }

        // 統一頭部：白銀桶盔
        ctx.fillStyle = silver;
        ctx.fillRect(-10, -28, 20, 20);
        ctx.strokeStyle = '#475569';
        ctx.lineWidth = 2;
        ctx.strokeRect(-10, -28, 20, 20);
        // T 字型面具縫隙
        ctx.fillStyle = '#0f172a';
        ctx.fillRect(-8, -18, 16, 3);
        ctx.fillRect(-1, -25, 2, 10);

        ctx.restore();
    },

    drawPrismPauldron(ctx: CanvasRenderingContext2D, x: number, y: number, size: number, color: string) {
        ctx.save();
        ctx.translate(x, y);
        ctx.fillStyle = color;
        ctx.fillRect(-size/2, -size/2, size, size);
        ctx.strokeStyle = '#000';
        ctx.lineWidth = 1.5;
        ctx.strokeRect(-size/2, -size/2, size, size);
        ctx.restore();
    },

    drawWeapon(ctx: CanvasRenderingContext2D, role: Role, t: number, isRunning: boolean) {
        ctx.save();
        ctx.translate(35, 0);
        const swing = Math.sin(t * (isRunning ? 14 : 3)) * 0.35;
        ctx.rotate(swing);

        ctx.fillStyle = '#94a3b8'; // 鋼鐵色
        ctx.strokeStyle = '#1e3a8a';
        ctx.lineWidth = 2.5;

        if (role === Role.TANK) {
            // 塔盾 (Tower Shield)
            ctx.fillStyle = '#475569';
            ctx.fillRect(-5, -25, 40, 65);
            ctx.strokeStyle = '#fcd34d';
            ctx.strokeRect(-5, -25, 40, 65);
            ctx.fillStyle = '#3b82f6';
            ctx.fillRect(8, 5, 15, 15);
        } else if (role === Role.WARRIOR) {
            // 雙手大劍
            ctx.beginPath();
            ctx.moveTo(0, 15); ctx.lineTo(-12, 0); ctx.lineTo(0, -75); ctx.lineTo(12, 0);
            ctx.closePath(); ctx.fill(); ctx.stroke();
            ctx.fillStyle = '#fcd34d';
            ctx.fillRect(-18, -2, 36, 8); // 護手
        } else if (role === Role.RANGER) {
            // 長火槍
            ctx.fillStyle = '#1e293b';
            ctx.fillRect(-20, -4, 55, 10);
            ctx.fillStyle = '#60a5fa';
            ctx.fillRect(25, -6, 12, 12);
        } else {
            // 秩序權杖
            ctx.fillRect(-3, -25, 6, 65);
            ctx.fillStyle = '#60a5fa';
            ctx.save();
            ctx.translate(0, -35);
            ctx.rotate(t * 3);
            HexGeometry.traceHex(ctx, 0, 0, 14, false); ctx.fill();
            ctx.restore();
        }
        ctx.restore();
    }
};

import { Agent } from "../../../game";
import { AnimState, Role } from "../../../../types";
import { HexGeometry } from "../../../graphics/utils/HexGeometry";

/**
 * 叛軍 (Covenant) 渲染器 v21.0 - 狂暴部族版
 * 核心語言：混亂、黑曜石與鮮血、鋸齒幾何
 */
export const CovenantRenderer = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean, isRunning: boolean) {
        const isHit = agent.hitFlashTimer > 0;
        const role = agent.role;

        // 1. 狂暴動力學 (Aggressive Dynamics)
        let bob = 0;
        let lean = 0.25; // 戰鬥前傾姿態

        if (isRunning) {
            const freq = 18; 
            bob = Math.abs(Math.cos(t * freq)) * -10; // 沉重的跳躍跑感
            lean = 0.45;
        } else {
            bob = Math.sin(t * 6) * 2.5; // 高頻脈動呼吸
        }

        ctx.save();
        if (isHit) ctx.translate((Math.random() - 0.5) * 18, 0);

        ctx.translate(0, -35 + bob);
        ctx.rotate(lean);

        // 2. 實體職階建模 (Jagged Modeling)
        this.drawJaggedBody(ctx, role, isHit, t);

        // 3. 殘暴武裝
        this.drawWeapon(ctx, role, t, isRunning);

        ctx.restore();
    },

    drawJaggedBody(ctx: CanvasRenderingContext2D, role: Role, isHit: boolean, t: number) {
        const obsidian = isHit ? '#fff' : '#18181b';
        const blood = isHit ? '#fff' : '#991b1b';
        const fire = '#ea580c';

        ctx.save();

        switch (role) {
            case Role.TANK:
                // 【毀滅大隻佬】：多刺的圓筒重裝
                ctx.fillStyle = obsidian;
                HexGeometry.traceHex(ctx, 0, 15, 30, true); ctx.fill();
                ctx.strokeStyle = blood;
                ctx.lineWidth = 4;
                HexGeometry.traceHex(ctx, 0, 15, 30, true); ctx.stroke();

                // 背部骨刺
                this.drawBoneSpike(ctx, -22, -12, 35, t, -0.6);
                this.drawBoneSpike(ctx, 22, -12, 35, t, 0.6);
                break;

            case Role.WARRIOR:
                // 【掠奪者】：極端非對稱倒三角
                ctx.fillStyle = obsidian;
                ctx.beginPath();
                ctx.moveTo(-32, -22); ctx.lineTo(32, -18); ctx.lineTo(12, 45); ctx.lineTo(-12, 45);
                ctx.closePath(); ctx.fill();

                this.drawBoneSpike(ctx, -35, -25, 28, t * 2, -0.9);
                this.drawBoneSpike(ctx, 35, -25, 28, t * 2, 0.9);
                break;

            case Role.MAGE:
            case Role.SUPPORT:
                // 【邪能引導者】：破碎的懸浮晶體
                ctx.fillStyle = obsidian;
                ctx.save();
                ctx.rotate(t * 0.8);
                HexGeometry.traceRotatedHex(ctx, 0, 0, 26, 0, false); ctx.fill();
                ctx.strokeStyle = fire;
                ctx.lineWidth = 3;
                HexGeometry.traceRotatedHex(ctx, 0, 0, 26, 0.4, false); ctx.stroke();
                ctx.restore();

                // 邪能火球繞行
                ctx.fillStyle = fire;
                ctx.beginPath(); ctx.arc(Math.cos(t*5)*45, Math.sin(t*5)*25 - 25, 8, 0, Math.PI*2); ctx.fill();
                break;

            case Role.RANGER:
                // 【追獵者】：帶刺的長型廓形
                ctx.fillStyle = obsidian;
                ctx.fillRect(-16, -15, 32, 55);
                ctx.fillStyle = blood;
                ctx.fillRect(-16, -15, 32, 12);
                this.drawBoneSpike(ctx, 0, -38, 25, t, 0);
                break;
        }

        // 頭部：獰笑骨面
        ctx.fillStyle = '#fef2f2';
        ctx.beginPath();
        ctx.moveTo(0, -18); ctx.lineTo(14, 0); ctx.lineTo(0, 22); ctx.lineTo(-14, 0);
        ctx.closePath(); ctx.fill();
        ctx.fillStyle = '#f00'; // 兇紅眼窩
        ctx.fillRect(-7, -2, 5, 5); ctx.fillRect(2, -2, 5, 5);

        ctx.restore();
    },

    drawBoneSpike(ctx: CanvasRenderingContext2D, x: number, y: number, h: number, t: number, ang: number) {
        ctx.save();
        ctx.translate(x, y);
        ctx.rotate(ang + Math.sin(t*12)*0.15);
        ctx.fillStyle = '#27272a';
        ctx.beginPath();
        ctx.moveTo(-6, 0); ctx.lineTo(6, 0); ctx.lineTo(0, -h);
        ctx.closePath(); ctx.fill();
        ctx.strokeStyle = '#ef4444';
        ctx.stroke();
        ctx.restore();
    },

    drawWeapon(ctx: CanvasRenderingContext2D, role: Role, t: number, isRunning: boolean) {
        ctx.save();
        ctx.translate(38, 12);
        const swing = Math.cos(t * (isRunning ? 18 : 6)) * 0.45;
        ctx.rotate(swing);

        ctx.fillStyle = '#1c1917';
        ctx.strokeStyle = '#ea580c';
        ctx.lineWidth = 3;

        if (role === Role.WARRIOR || role === Role.TANK) {
            // 雙頭裂骨斧
            ctx.fillRect(-5, -15, 10, 90);
            ctx.fillStyle = '#7f1d1d';
            ctx.beginPath(); // 刃 A
            ctx.moveTo(0, 15); ctx.lineTo(-45, -8); ctx.lineTo(-40, 45); ctx.lineTo(0, 35);
            ctx.closePath(); ctx.fill(); ctx.stroke();
            ctx.beginPath(); // 刃 B
            ctx.moveTo(0, 15); ctx.lineTo(45, -8); ctx.lineTo(40, 45); ctx.lineTo(0, 35);
            ctx.closePath(); ctx.fill(); ctx.stroke();
        } else {
            // 邪能圖騰柱
            ctx.fillRect(-12, -45, 24, 110);
            ctx.fillStyle = '#ef4444';
            ctx.shadowBlur = 20; ctx.shadowColor = '#f00';
            ctx.fillRect(-14, -50, 28, 15);
            ctx.strokeRect(-12, -45, 24, 110);
        }
        ctx.restore();
    }
};

import { ISO_SCALE_Y, BASE_HEIGHT, BLOCK_HEIGHT } from "../../../constants";
import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { SurfacePainter } from "../../graphics/painters/SurfacePainter";
import { HexLayout } from "../../../types";

const WALL_SLOP_EPSILON = 1.0; 

/**
 * 地形渲染器 v21.0 - 低多邊形分面版
 * 解決地形與特效混淆問題，強化實體感
 */
export const TerrainRenderer = {

    drawBlock(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        size: number, height: number, 
        theme: any,
        type: string,
        globalTime: number,
        layout: HexLayout
    ) {
        const visualTopY = -height;
        const vertices = HexGeometry.getVertices(size, true, layout); 

        ctx.save();
        ctx.translate(x, y);

        // --- 1. 牆面渲染 (Faceted Walls) ---
        // 使用高對比顏色強化體積感
        this.drawVerticalWall(ctx, vertices[1], vertices[0], visualTopY, theme.sideDark);
        this.drawVerticalWall(ctx, vertices[2], vertices[1], visualTopY, theme.sideLight);
        if (layout === 'FLAT') {
            this.drawVerticalWall(ctx, vertices[3], vertices[2], visualTopY, theme.sideDark);
        }

        // --- 2. 頂面渲染 (Faceted Top) ---
        ctx.translate(0, visualTopY);

        const topGrad = ctx.createLinearGradient(-size, -size, size, size);
        topGrad.addColorStop(0, theme.rim); 
        topGrad.addColorStop(0.18, theme.top); 
        topGrad.addColorStop(0.85, theme.sideDark); 
        ctx.fillStyle = topGrad;

        HexGeometry.traceHex(ctx, 0, 0, size, true, layout);
        ctx.fill();

        // --- 3. 重點：材質細節 (Material Grit) ---
        // 在頂面繪製一些不透明的小幾何塊，用來建立「粗糙石材/金屬」的質感
        this.drawFacetedGrit(ctx, size, theme.detail, layout, q + r); // 使用穩定種子

        // --- 4. 厚重線框 ---
        ctx.strokeStyle = theme.rim;
        ctx.lineWidth = 1.8;
        ctx.globalAlpha = 1.0; 
        ctx.stroke();

        // 5. 動態場景覆蓋
        this.applyThemeSurfaceDynamics(ctx, size, type, theme, globalTime, layout);

        ctx.restore();
    },

    /**
     * 在方塊頂部繪製分面噪點，強化與特效圈的區別
     */
    drawFacetedGrit(ctx: CanvasRenderingContext2D, size: number, color: string, layout: HexLayout, seed: number) {
        ctx.save();
        ctx.globalAlpha = 0.25;
        ctx.fillStyle = color;

        const count = 4;
        for(let i=0; i<count; i++) {
            const gx = (Math.sin(seed * 1.5 + i) * 0.7) * size;
            const gy = (Math.cos(seed * 0.8 + i) * 0.4) * size * ISO_SCALE_Y;

            // 繪製微型三角形分面
            ctx.beginPath();
            ctx.moveTo(gx, gy);
            ctx.lineTo(gx + 12, gy + 4);
            ctx.lineTo(gx + 6, gy + 10);
            ctx.closePath();
            ctx.fill();
        }
        ctx.restore();
    },

    applyThemeSurfaceDynamics(ctx: CanvasRenderingContext2D, size: number, type: string, theme: any, t: number, layout: HexLayout) {
        ctx.save();
        ctx.globalAlpha = 0.85; 

        if (type === 'FOREST') {
            ctx.strokeStyle = theme.detail;
            ctx.lineWidth = 1;
            const pulse = 0.4 + Math.sin(t * 1.8) * 0.2;
            ctx.globalAlpha = pulse;
            // 低多邊形幾何草紋
            HexGeometry.traceHex(ctx, 0, 0, size * 0.75, true, layout); ctx.stroke();
        } 
        else if (type === 'MAGMA') {
            const offset = (t * 35) % 110;
            ctx.strokeStyle = '#ef4444';
            ctx.lineWidth = 2.5;
            ctx.beginPath();
            ctx.moveTo(-size, -size/2 + offset); ctx.lineTo(size, size/2 - 25 + offset);
            ctx.stroke();
            SurfacePainter.drawLiquid(ctx, 0, 0, '#ef4444', t, 1.3);
        }
        else if (type === 'VOID') {
            ctx.strokeStyle = theme.detail;
            ctx.lineWidth = 1.5;
            const scanY = (t * 55) % (size * 2.8) - size * 1.4;
            ctx.beginPath();
            ctx.moveTo(-size * 0.9, scanY * ISO_SCALE_Y); ctx.lineTo(size * 0.9, scanY * ISO_SCALE_Y);
            ctx.stroke();
        }

        ctx.restore();
    },

    drawVerticalWall(ctx: CanvasRenderingContext2D, vBottom1: {x:number, y:number}, vBottom2: {x:number, y:number}, topY: number, color: string) {
        ctx.fillStyle = color;
        ctx.beginPath();
        ctx.moveTo(vBottom1.x, vBottom1.y);
        ctx.lineTo(vBottom2.x, vBottom2.y);
        ctx.lineTo(vBottom2.x, vBottom2.y + topY);
        ctx.lineTo(vBottom1.x, vBottom1.y + topY);
        ctx.closePath();
        ctx.fill();

        // 牆體間的分隔線
        ctx.strokeStyle = 'rgba(0,0,0,0.35)';
        ctx.lineWidth = 1.2;
        ctx.stroke();
    },

    drawTerrainDetail(
        ctx: CanvasRenderingContext2D, 
        baseX: number, baseY: number, 
        height: number,
        type: string, 
        detailColor: string,
        q: number, r: number
    ) {
        const visualY = baseY - height;
        const seed = Math.abs(Math.sin(q * 12.9 + r * 78.2));
        if (seed > 0.7) { 
             SurfacePainter.drawDetailTexture(ctx, baseX, visualY, type, detailColor, seed);
        }
    }
};

import { useRef, useState, useCallback, useEffect } from 'react';
import { GameEngine, Agent } from '../engine/game';
import { ToolType, Team, Skill, Role, HexLayout } from '../types';
import { SCENE_DB } from '../data/scenes';
import { DesignExporter } from '../engine/systems/DesignExporter';
import { DEFAULT_HEX_LAYOUT } from '../constants';
import { UNIT_DB } from '../data/units';

export const useGameApp = () => {
    const engineRef = useRef(new GameEngine());

    // --- STATE ---
    const [isShowcaseMode, setIsShowcaseMode] = useState(true);
    const [isPlaying, setIsPlaying] = useState(false);
    const [unitCount, setUnitCount] = useState(0); 
    const [tool, setTool] = useState<ToolType>(ToolType.SELECT);
    const [selectedObstacle, setSelectedObstacle] = useState<string>('WALL'); 
    const [selectedAgent, setSelectedAgent] = useState<Agent | null>(null);
    const [hoveredSkill, setHoveredSkill] = useState<Skill | null>(null);
    const [hpInput, setHpInput] = useState(600); 
    const [mapW, setMapW] = useState(12);
    const [mapH, setMapH] = useState(8);
    const [timeScale, setTimeScale] = useState(1.0);
    const [winner, setWinner] = useState<Team | null>(null);
    const [currentSceneId, setCurrentSceneId] = useState('VOID');
    const [spawnMode, setSpawnMode] = useState<'RANDOM' | 'DRAFT'>('RANDOM');
    const [draftRole, setDraftRole] = useState<Role>(Role.WARRIOR);
    const [hexLayout, setHexLayout] = useState<HexLayout>(DEFAULT_HEX_LAYOUT);

    // UI State
    const [showLogs, setShowLogs] = useState(false);
    const [showDB, setShowDB] = useState(false);
    const [showVFXMap, setShowVFXMap] = useState(false); 
    const [transitionPhase, setTransitionPhase] = useState<'IDLE' | 'IN' | 'OUT'>('IDLE');
    const [showFactionWarning, setShowFactionWarning] = useState(false);

    // --- EVENT LISTENER SETUP ---
    useEffect(() => {
        const engine = engineRef.current;
        const handleGameOver = (data: { winner: Team }) => {
            setWinner(data.winner);
            if (engine.isRunning) engine.stop(); 
            setIsPlaying(false);
        };
        engine.bus.on('GAME_OVER', handleGameOver);
        return () => {
            engine.bus.off('GAME_OVER', handleGameOver);
        };
    }, []);

    // Showcase Auto-Loop Logic
    useEffect(() => {
        if (isShowcaseMode && winner !== null) {
            const timer = setTimeout(() => {
                setTransitionPhase('OUT');
                engineRef.current.agents = [];
                engineRef.current.combat.projectiles = [];

                setTimeout(() => {
                    setupShowcaseMap(); 
                    setTransitionPhase('IN'); 
                    setTimeout(() => {
                        setTransitionPhase('IDLE');
                        spawnShowcaseUnits(); 
                    }, 1200); 
                }, 1200); 
            }, 800); 
            return () => clearTimeout(timer);
        }
    }, [winner, isShowcaseMode]);

    // --- LOGIC ---

    const setupShowcaseMap = useCallback(() => {
        const engine = engineRef.current;
        engine.stop();
        setWinner(null);
        setSelectedAgent(null);

        engine.mapConfig.w = Math.floor(11 + Math.random() * 3);
        engine.mapConfig.h = Math.floor(9 + Math.random() * 3);

        const newLayout: HexLayout = Math.random() > 0.5 ? 'FLAT' : 'POINTY';
        engine.mapConfig.layout = newLayout;
        setHexLayout(newLayout);

        engine.randomizeEnvironment(); 
        setCurrentSceneId(engine.currentScene.id);
    }, []);

    /**
     * 重寫生成邏輯：實施「職階編隊制 (Guaranteed Roster)」
     * 確保展示模式中每隊都有坦打遠法補各一名，剩餘名額隨機
     */
    const spawnShowcaseUnits = useCallback(() => {
        const engine = engineRef.current;
        let validHexes = (Array.from(engine.mapKeys) as string[])
            .map(k => {
                const [q, r] = k.split(',').map(Number);
                return {q, r};
            })
            .filter(h => !engine.map.hasObstacle(h.q, h.r));

        // 洗牌可用座標
        for (let i = validHexes.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [validHexes[i], validHexes[j]] = [validHexes[j], validHexes[i]];
        }

        let spawnIndex = 0;
        const REQUIRED_ROLES = [Role.TANK, Role.WARRIOR, Role.RANGER, Role.MAGE, Role.SUPPORT];

        const spawnTeam = (team: Team) => {
            // 1. 保證每個職業至少生成一個 (精英編隊)
            REQUIRED_ROLES.forEach(role => {
                if (spawnIndex < validHexes.length) {
                    const h = validHexes[spawnIndex++];
                    // 根據職業調整血量基準
                    const baseStats = UNIT_DB[role];
                    const hp = baseStats.maxHp + Math.floor(Math.random() * 200);

                    const agent = engine.addAgent(team, h.q, h.r, hp);
                    if (agent) {
                        agent.role = role;
                        agent.maxHp = hp; agent.hp = hp;
                        agent.moveSpeed = baseStats.moveSpeed;
                        agent.movementType = baseStats.movementType;

                        // 重新分配對應職業的技能
                        const validSkills = engine.skillDB.filter(s => s.role === role && (s.team === undefined || s.team === team));
                        const rndS = (ar: Skill[]) => ar.length > 0 ? ar[Math.floor(Math.random() * ar.length)].id : null;
                        agent.skillIds = [
                            rndS(validSkills.filter(s => s.tag === 'ULT')),
                            rndS(validSkills.filter(s => s.tag === 'ACTIVE')),
                            rndS(validSkills.filter(s => s.tag === 'BASIC'))
                        ];

                        agent.saveState();
                        agent.reset(engine.mapConfig);
                    }
                }
            });

            // 2. 額外隨機補充單位 (補充量減少，使精英感更強)
            const EXTRA_COUNT = 1;
            for(let i=0; i<EXTRA_COUNT; i++) {
                if (spawnIndex < validHexes.length) {
                    const h = validHexes[spawnIndex++];
                    engine.addAgent(team, h.q, h.r, 600);
                }
            }
        };

        spawnTeam(Team.BLUE);
        spawnTeam(Team.RED);

        engine.play();
        setIsPlaying(true);
    }, []);

    const startShowcaseMatch = useCallback(() => {
        setupShowcaseMap();
        spawnShowcaseUnits();
    }, [setupShowcaseMap, spawnShowcaseUnits]);

    useEffect(() => {
        startShowcaseMatch();
    }, [startShowcaseMatch]);

    useEffect(() => {
        const interval = setInterval(() => {
            setUnitCount(engineRef.current.agents.length);
        }, 500); 
        return () => clearInterval(interval);
    }, []);

    useEffect(() => {
        engineRef.current.timeScale = timeScale;
    }, [timeScale]);

    const enterManualMode = () => {
        setIsShowcaseMode(false);
        engineRef.current.stop();
        setIsPlaying(false);
        setWinner(null);
        engineRef.current.clear(true); 
        engineRef.current.agents = [];
        setUnitCount(0);
        setMapW(engineRef.current.mapConfig.w);
        setMapH(engineRef.current.mapConfig.h);
        setHexLayout(engineRef.current.mapConfig.layout);
        setCurrentSceneId(engineRef.current.currentScene.id);
    };

    const handleUpdateMapSize = useCallback((w: number, h: number) => {
        setMapW(w);
        setMapH(h);
        engineRef.current.mapConfig.w = w;
        engineRef.current.mapConfig.h = h;
        engineRef.current.clear(false); 
        setSelectedAgent(null);
        setWinner(null);
    }, []);

    const handleUpdateLayout = useCallback((l: HexLayout) => {
        setHexLayout(l);
        engineRef.current.mapConfig.layout = l;
        engineRef.current.clear(true); 
        setSelectedAgent(null);
        setWinner(null);
    }, []);

    const handleSetScene = useCallback((id: string) => {
        const scene = SCENE_DB.find(s => s.id === id);
        if (scene) {
            engineRef.current.currentScene = scene;
            engineRef.current.map.rebuildMap(engineRef.current);
            setCurrentSceneId(id);
        }
    }, []);

    const handleRandomBattlefield = useCallback(() => {
        const engine = engineRef.current;
        engine.stop();
        setWinner(null);
        setSelectedAgent(null);
        engine.clear(false); 

        const newLayout: HexLayout = Math.random() > 0.5 ? 'FLAT' : 'POINTY';
        engine.mapConfig.layout = newLayout;
        setHexLayout(newLayout);

        engine.randomizeEnvironment();
        setMapW(engine.mapConfig.w);
        setMapH(engine.mapConfig.h);
        setCurrentSceneId(engine.currentScene.id);

        spawnShowcaseUnits();
    }, [spawnShowcaseUnits]);

    const handleNextLevel = useCallback(() => {
        handleRandomBattlefield();
        const engine = engineRef.current;
        engine.play();
        setIsPlaying(true);
        setTool(ToolType.SELECT);
    }, [handleRandomBattlefield]);

    const handleReset = useCallback(() => {
        engineRef.current.restart();
        setIsPlaying(false); 
        setWinner(null);
    }, []);

    const togglePlay = useCallback(() => {
        if (winner !== null) return;
        if (isPlaying) {
            engineRef.current.stop();
            setIsPlaying(false);
        } else {
            const hasBlue = engineRef.current.agents.some(a => a.team === Team.BLUE);
            const hasRed = engineRef.current.agents.some(a => a.team === Team.RED);
            if (!hasBlue || !hasRed) {
                setShowFactionWarning(true);
                setTimeout(() => setShowFactionWarning(false), 2500);
                return;
            }
            engineRef.current.play();
            setIsPlaying(true);
            setTool(ToolType.SELECT);
        }
    }, [isPlaying, winner]);

    const handleSelectAgent = (a: Agent | null) => {
        setSelectedAgent(a);
    };

    return {
        engineRef,
        state: {
            isShowcaseMode, isPlaying, unitCount, tool, selectedObstacle,
            selectedAgent, hoveredSkill, hpInput, mapW, mapH, timeScale,
            winner, currentSceneId, spawnMode, draftRole, showLogs, showDB, showVFXMap,
            transitionPhase, showFactionWarning, hexLayout
        },
        setters: {
            setTool, setSelectedObstacle, setHpInput, setTimeScale, 
            setSpawnMode, setDraftRole, setShowLogs, setShowDB, setShowVFXMap,
            setIsShowcaseMode, setSelectedAgent, setHoveredSkill
        },
        actions: {
            enterManualMode,
            handleUpdateMapSize,
            handleUpdateLayout,
            handleSetScene,
            handleRandomBattlefield,
            handleNextLevel,
            handleReset,
            togglePlay,
            onWin: (team: Team) => { engineRef.current.bus.emit('GAME_OVER', {winner: team}) },
            handleSelectAgent,
            startShowcaseMatch,
            downloadSpec: DesignExporter.downloadSpec,
            rematch: () => { 
                setWinner(null); 
                engineRef.current.restart(); 
                engineRef.current.play(); 
                setIsPlaying(true); 
            }
        }
    };
};

import { ISO_SCALE_Y, BASE_HEIGHT, BLOCK_HEIGHT } from "../../../constants";
import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { SurfacePainter } from "../../graphics/painters/SurfacePainter";
import { HexLayout } from "../../../types";

const WALL_SLOP_EPSILON = 1.0; 

/**
 * 地形渲染器 v21.0 - 低多邊形分面版
 * 解決地形與特效混淆問題，強化實體感
 */
export const TerrainRenderer = {

    /**
     * 繪製地形方塊
     * Fix: Added q and r parameters to support stable noise seed for material grit.
     */
    drawBlock(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        size: number, height: number, 
        theme: any,
        type: string,
        globalTime: number,
        layout: HexLayout,
        q: number, r: number
    ) {
        const visualTopY = -height;
        const vertices = HexGeometry.getVertices(size, true, layout); 

        ctx.save();
        ctx.translate(x, y);

        // --- 1. 牆面渲染 (Faceted Walls) ---
        // 使用高對比顏色強化體積感
        this.drawVerticalWall(ctx, vertices[1], vertices[0], visualTopY, theme.sideDark);
        this.drawVerticalWall(ctx, vertices[2], vertices[1], visualTopY, theme.sideLight);
        if (layout === 'FLAT') {
            this.drawVerticalWall(ctx, vertices[3], vertices[2], visualTopY, theme.sideDark);
        }

        // --- 2. 頂面渲染 (Faceted Top) ---
        ctx.translate(0, visualTopY);

        const topGrad = ctx.createLinearGradient(-size, -size, size, size);
        topGrad.addColorStop(0, theme.rim); 
        topGrad.addColorStop(0.18, theme.top); 
        topGrad.addColorStop(0.85, theme.sideDark); 
        ctx.fillStyle = topGrad;

        HexGeometry.traceHex(ctx, 0, 0, size, true, layout);
        ctx.fill();

        // --- 3. 重點：材質細節 (Material Grit) ---
        // 在頂面繪製一些不透明的小幾何塊，用來建立「粗糙石材/金屬」的質感
        this.drawFacetedGrit(ctx, size, theme.detail, layout, q + r); // 使用穩定種子

        // --- 4. 厚重線框 ---
        ctx.strokeStyle = theme.rim;
        ctx.lineWidth = 1.8;
        ctx.globalAlpha = 1.0; 
        ctx.stroke();

        // 5. 動態場景覆蓋
        this.applyThemeSurfaceDynamics(ctx, size, type, theme, globalTime, layout);

        ctx.restore();
    },

    /**
     * 在方塊頂部繪製分面噪點，強化與特效圈的區別
     */
    drawFacetedGrit(ctx: CanvasRenderingContext2D, size: number, color: string, layout: HexLayout, seed: number) {
        ctx.save();
        ctx.globalAlpha = 0.25;
        ctx.fillStyle = color;

        const count = 4;
        for(let i=0; i<count; i++) {
            const gx = (Math.sin(seed * 1.5 + i) * 0.7) * size;
            const gy = (Math.cos(seed * 0.8 + i) * 0.4) * size * ISO_SCALE_Y;

            // 繪製微型三角形分面
            ctx.beginPath();
            ctx.moveTo(gx, gy);
            ctx.lineTo(gx + 12, gy + 4);
            ctx.lineTo(gx + 6, gy + 10);
            ctx.closePath();
            ctx.fill();
        }
        ctx.restore();
    },

    applyThemeSurfaceDynamics(ctx: CanvasRenderingContext2D, size: number, type: string, theme: any, t: number, layout: HexLayout) {
        ctx.save();
        ctx.globalAlpha = 0.85; 

        if (type === 'FOREST') {
            ctx.strokeStyle = theme.detail;
            ctx.lineWidth = 1;
            const pulse = 0.4 + Math.sin(t * 1.8) * 0.2;
            ctx.globalAlpha = pulse;
            // 低多邊形幾何草紋
            HexGeometry.traceHex(ctx, 0, 0, size * 0.75, true, layout); ctx.stroke();
        } 
        else if (type === 'MAGMA') {
            const offset = (t * 35) % 110;
            ctx.strokeStyle = '#ef4444';
            ctx.lineWidth = 2.5;
            ctx.beginPath();
            ctx.moveTo(-size, -size/2 + offset); ctx.lineTo(size, size/2 - 25 + offset);
            ctx.stroke();
            SurfacePainter.drawLiquid(ctx, 0, 0, '#ef4444', t, 1.3);
        }
        else if (type === 'VOID') {
            ctx.strokeStyle = theme.detail;
            ctx.lineWidth = 1.5;
            const scanY = (t * 55) % (size * 2.8) - size * 1.4;
            ctx.beginPath();
            ctx.moveTo(-size * 0.9, scanY * ISO_SCALE_Y); ctx.lineTo(size * 0.9, scanY * ISO_SCALE_Y);
            ctx.stroke();
        }

        ctx.restore();
    },

    drawVerticalWall(ctx: CanvasRenderingContext2D, vBottom1: {x:number, y:number}, vBottom2: {x:number, y:number}, topY: number, color: string) {
        ctx.fillStyle = color;
        ctx.beginPath();
        ctx.moveTo(vBottom1.x, vBottom1.y);
        ctx.lineTo(vBottom2.x, vBottom2.y);
        ctx.lineTo(vBottom2.x, vBottom2.y + topY);
        ctx.lineTo(vBottom1.x, vBottom1.y + topY);
        ctx.closePath();
        ctx.fill();

        // 牆體間的分隔線
        ctx.strokeStyle = 'rgba(0,0,0,0.35)';
        ctx.lineWidth = 1.2;
        ctx.stroke();
    },

    drawTerrainDetail(
        ctx: CanvasRenderingContext2D, 
        baseX: number, baseY: number, 
        height: number,
        type: string, 
        detailColor: string,
        q: number, r: number
    ) {
        const visualY = baseY - height;
        const seed = Math.abs(Math.sin(q * 12.9 + r * 78.2));
        if (seed > 0.7) { 
             SurfacePainter.drawDetailTexture(ctx, baseX, visualY, type, detailColor, seed);
        }
    }
};

import { Agent, GameEngine, VICTORY_PHASE_DURATION } from "../game";
import { Camera, GameRenderer } from "../renderer"; 
import { Hex, Skill } from "../../types";

// Sub-renderers
import { BackgroundRenderer } from "./background";
import { TacticalRenderer } from "./tactical";
import { HUDRenderer } from "./HUDRenderer";
import { PostProcessor } from "./PostProcessor"; 
import { RenderList, RenderOpType } from "./RenderList";
import { ProjectileDrawer } from "./ProjectileDrawer";

// Painters
import { TerrainRenderer } from "./grid/TerrainRenderer";
import { GridOverlays } from "./grid/GridOverlays";
import { ParticleRenderer } from "../systems/vfx/renderers/ParticleRenderer";
import { SpriteManager } from "../sprites";
import { AssetManager } from "../assets";
import { ENV_ANCHOR_X, ENV_ANCHOR_Y } from "../graphics/EnvironmentFactory";

export class RenderPipeline {
    private renderer: GameRenderer;
    private backgroundRenderer: BackgroundRenderer;
    private tacticalRenderer: TacticalRenderer;
    private hudRenderer: HUDRenderer;
    private postProcessor: PostProcessor;
    private renderList: RenderList;

    private transitionT: number = 0;
    private transitionPhase: 'IN' | 'OUT' | 'IDLE' = 'IDLE';

    constructor(renderer: GameRenderer) {
        this.renderer = renderer;
        this.backgroundRenderer = new BackgroundRenderer();
        this.tacticalRenderer = new TacticalRenderer();
        this.hudRenderer = new HUDRenderer();
        this.postProcessor = new PostProcessor();
        this.renderList = new RenderList();
    }

    public setTransition(t: number, phase: 'IN' | 'OUT' | 'IDLE') {
        this.transitionT = t;
        this.transitionPhase = phase;
    }

    public update(dt: number, engine: GameEngine) {
        this.tacticalRenderer.update(dt, engine);
    }

    public draw(
        ctx: CanvasRenderingContext2D, 
        engine: GameEngine, 
        camera: Camera, 
        highlight: Agent | null, 
        fps: number, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null,
        globalTime: number
    ): void {
        const physicalWidth = ctx.canvas.width;
        const physicalHeight = ctx.canvas.height;
        if (physicalWidth === 0 || physicalHeight === 0) return;

        const dpr = window.devicePixelRatio || 1;
        const logicalWidth = physicalWidth / dpr;
        const logicalHeight = physicalHeight / dpr;
        const scene = engine.currentScene;
        const layout = engine.mapConfig.layout;

        ctx.resetTransform();
        ctx.clearRect(0, 0, physicalWidth, physicalHeight);
        ctx.scale(dpr, dpr);
        this.backgroundRenderer.draw(ctx, logicalWidth, logicalHeight, scene, engine.mapConfig, globalTime);

        ctx.save();
        this.renderer.camera.sync(camera); 
        this.renderer.camera.applyTransform(ctx, logicalWidth, logicalHeight);

        this.renderList.reset();
        const terrainHeightFunc = (q: number, r: number) => this.renderer.grid.getTerrainHeight(q, r, engine);

        this.renderer.grid.submitRenderables(
            this.renderList,
            engine, hoveredHex, hoveredSkill, highlight, 
            engine.projectiles,
            this.transitionT, this.transitionPhase,
            globalTime
        );

        this.renderer.vfxRenderer.submitRenderables(
            this.renderList,
            engine,
            this.renderer.vfx,
            terrainHeightFunc,
            engine.mapConfig,
            this.transitionT,
            this.transitionPhase,
            { width: logicalWidth, height: logicalHeight, camera } 
        );

        this.renderer.unit.submitRenderables(
            this.renderList,
            engine.agents, 
            terrainHeightFunc, 
            globalTime, 
            highlight, 
            engine.mapConfig,
            engine.isRunning // 傳遞戰鬥狀態
        );

        this.renderList.sort();

        for (let i = 0; i < this.renderList.count; i++) {
            const op = this.renderList.ops[i];
            const snapX = Math.round(op.tx);
            const snapY = Math.round(op.ty);

            switch (op.type) {
                case RenderOpType.TERRAIN:
                    /**
                     * Fix: Pass missing tq and tr coordinates to TerrainRenderer.drawBlock
                     */
                    TerrainRenderer.drawBlock(ctx, snapX, snapY, op.tsize, op.th, op.ttheme, op.ttype, globalTime, layout, op.tq, op.tr);
                    const visualTopY = snapY - op.th;
                    TerrainRenderer.drawTerrainDetail(ctx, snapX, snapY, op.th, op.ttype, op.tdetail, op.tq, op.tr);
                    GridOverlays.drawOverlays(ctx, snapX, visualTopY, op.tsize, op.oStatus, op.oDanger, op.oLightCol, op.oLightInt, op.oRange, op.oRangeCol, op.oHover, op.oHasUnit, op.tq, op.tr, op.time, op.oHazard, layout);
                    break;
                case RenderOpType.OBSTACLE:
                    const sprite = SpriteManager.getObstacleSprite(op.ttype, layout);
                    ctx.drawImage(sprite, snapX - ENV_ANCHOR_X, snapY - ENV_ANCHOR_Y);
                    break;
                case RenderOpType.UNIT:
                    if (op.agent) this.renderer.unit.drawAssembly(ctx, op.agent, snapX, snapY, op.th, op.time, op.uSelected, op.uSilhouette, op.pIsUlt);
                    break;
                case RenderOpType.DECAL:
                    const dImg = AssetManager.getBlastZone(op.dColor);
                    ctx.save();
                    ctx.translate(snapX, snapY);
                    ctx.scale(op.dScale, op.dScale);
                    ctx.globalAlpha = Math.min(1, op.dLife);
                    ctx.drawImage(dImg, -64, -32, 128, 64);
                    ctx.restore();
                    break;
                case RenderOpType.VFX:
                    if (op.particle) {
                        const p = op.particle;
                        ctx.save();
                        ctx.translate(snapX, snapY);
                        ParticleRenderer.drawSingleParticle(ctx, p, 0, 0, op.vProgress, op.vChaos, layout);
                        ctx.restore();
                    }
                    break;
                case RenderOpType.PROJECTILE:
                    ProjectileDrawer.draw(ctx, op, globalTime);
                    break;
            }
        }

        const occludedAgents = this.renderer.grid.getOccludedAgents(engine);
        if (occludedAgents.length > 0) {
            ctx.save();
            occludedAgents.forEach(agent => {
                this.renderer.unit.drawSilhouette(ctx, agent, terrainHeightFunc, globalTime, engine.mapConfig);
            });
            ctx.restore();
        }

        this.renderer.statusOrchestrator.draw(ctx, engine.agents, globalTime, terrainHeightFunc);
        this.renderer.vfxRenderer.drawTopLayerParticles(ctx, this.renderer.vfx, scene, engine.mapConfig, this.transitionT, this.transitionPhase, layout);
        ctx.restore(); 

        let transitionAberration = 0;
        if (this.transitionPhase !== 'IDLE') transitionAberration = 4 * this.transitionT * (1 - this.transitionT) * 0.5;

        this.postProcessor.apply(ctx, physicalWidth, physicalHeight, this.renderer.camera.getTrauma(), transitionAberration);

        ctx.save(); 
        this.renderer.camera.applyTransform(ctx, logicalWidth, logicalHeight);
        this.tacticalRenderer.drawOverlay(ctx, engine, highlight, this.renderer.grid, globalTime);
        this.hudRenderer.draw(ctx, this.renderer.hud, engine.agents, terrainHeightFunc, engine.mapConfig, highlight, globalTime);
        ctx.restore(); 

        if (engine.directorTargetId) this.tacticalRenderer.drawHUD(ctx, engine, logicalWidth, logicalHeight, camera, globalTime);
        this.tacticalRenderer.drawDebug(ctx, fps);

        let blurAmount = 0;
        if (engine.isFinishing) blurAmount = 1.0 - (engine.victoryTimer / VICTORY_PHASE_DURATION);
        else if (engine.winningTeam !== null) blurAmount = 1.0;

        if (this.transitionPhase === 'OUT') blurAmount = 1.0; 
        else if (this.transitionPhase === 'IN') blurAmount = 1.0 - this.transitionT;

        if (blurAmount > 0) this.postProcessor.applyFinishBlur(ctx, physicalWidth, physicalHeight, Math.max(0, Math.min(1, blurAmount)));
    }
}

import { ISO_SCALE_Y, BASE_HEIGHT, BLOCK_HEIGHT } from "../../../constants";
import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { SurfacePainter } from "../../graphics/painters/SurfacePainter";
import { HexLayout } from "../../../types";

const WALL_SLOP_EPSILON = 1.0; 

/**
 * 地形渲染器 v22.0 - 低多邊形分面版 (健康修正)
 * 修正：補全 q, r 座標引用，確保材質細節在攝像機移動時不會閃爍
 */
export const TerrainRenderer = {

    drawBlock(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        size: number, height: number, 
        theme: any,
        type: string,
        globalTime: number,
        layout: HexLayout,
        q: number, r: number // SSOT: 必須傳入邏輯座標
    ) {
        const visualTopY = -height;
        const vertices = HexGeometry.getVertices(size, true, layout); 

        ctx.save();
        ctx.translate(x, y);

        // --- 1. 牆面 (Faceted Walls) ---
        this.drawVerticalWall(ctx, vertices[1], vertices[0], visualTopY, theme.sideDark);
        this.drawVerticalWall(ctx, vertices[2], vertices[1], visualTopY, theme.sideLight);
        if (layout === 'FLAT') {
            this.drawVerticalWall(ctx, vertices[3], vertices[2], visualTopY, theme.sideDark);
        }

        // --- 2. 頂面 (Faceted Top) ---
        ctx.translate(0, visualTopY);

        const topGrad = ctx.createLinearGradient(-size, -size, size, size);
        topGrad.addColorStop(0, theme.rim); 
        topGrad.addColorStop(0.2, theme.top); 
        topGrad.addColorStop(0.8, theme.sideDark); 
        ctx.fillStyle = topGrad;

        HexGeometry.traceHex(ctx, 0, 0, size, true, layout);
        ctx.fill();

        // --- 3. 材質噪點 (Faceted Grit) ---
        // 使用 q+r 作為穩定種子，防止材質隨機跳動
        this.drawMaterialGrit(ctx, size, theme.detail, layout, q + r);

        // --- 4. 硬派邊線 ---
        ctx.strokeStyle = theme.rim;
        ctx.lineWidth = 1.5;
        ctx.stroke();

        this.applyThemeSurfaceDynamics(ctx, size, type, theme, globalTime, layout);

        ctx.restore();
    },

    drawMaterialGrit(ctx: CanvasRenderingContext2D, size: number, color: string, layout: HexLayout, seed: number) {
        ctx.save();
        ctx.globalAlpha = 0.2;
        ctx.fillStyle = color;

        // 根據座標生成的偽隨機三角形 (低多邊形質感)
        const count = 3;
        for(let i=0; i<count; i++) {
            const gx = (Math.sin(seed * 12.3 + i) * 0.6) * size;
            const gy = (Math.cos(seed * 45.6 + i) * 0.4) * size * ISO_SCALE_Y;
            ctx.beginPath();
            ctx.moveTo(gx, gy);
            ctx.lineTo(gx + 10, gy + 4);
            ctx.lineTo(gx + 5, gy + 12);
            ctx.closePath();
            ctx.fill();
        }
        ctx.restore();
    },

    applyThemeSurfaceDynamics(ctx: CanvasRenderingContext2D, size: number, type: string, theme: any, t: number, layout: HexLayout) {
        ctx.save();
        ctx.globalAlpha = 0.8; 

        if (type === 'FOREST') {
            ctx.strokeStyle = theme.detail;
            ctx.lineWidth = 1;
            const pulse = 0.5 + Math.sin(t * 2) * 0.2;
            ctx.globalAlpha = pulse;
            HexGeometry.traceHex(ctx, 0, 0, size * 0.7, true, layout); ctx.stroke();
        } 
        else if (type === 'MAGMA') {
            const offset = (t * 30) % 100;
            ctx.strokeStyle = '#ef4444';
            ctx.lineWidth = 2;
            ctx.beginPath();
            ctx.moveTo(-size, -size/2 + offset); ctx.lineTo(size, size/2 - 20 + offset);
            ctx.stroke();
            SurfacePainter.drawLiquid(ctx, 0, 0, '#ef4444', t, 1.2);
        }
        else if (type === 'VOID') {
            ctx.strokeStyle = theme.detail;
            ctx.lineWidth = 1.2;
            const scanY = (t * 50) % (size * 2.5) - size * 1.25;
            ctx.beginPath();
            ctx.moveTo(-size * 0.9, scanY * ISO_SCALE_Y); ctx.lineTo(size * 0.9, scanY * ISO_SCALE_Y);
            ctx.stroke();
        }

        ctx.restore();
    },

    drawVerticalWall(ctx: CanvasRenderingContext2D, vBottom1: {x:number, y:number}, vBottom2: {x:number, y:number}, topY: number, color: string) {
        ctx.fillStyle = color;
        ctx.beginPath();
        ctx.moveTo(vBottom1.x, vBottom1.y);
        ctx.lineTo(vBottom2.x, vBottom2.y);
        ctx.lineTo(vBottom2.x, vBottom2.y + topY);
        ctx.lineTo(vBottom1.x, vBottom1.y + topY);
        ctx.closePath();
        ctx.fill();
        ctx.strokeStyle = 'rgba(0,0,0,0.2)';
        ctx.lineWidth = 1;
        ctx.stroke();
    },

    drawTerrainDetail(
        ctx: CanvasRenderingContext2D, 
        baseX: number, baseY: number, 
        height: number,
        type: string, 
        detailColor: string,
        q: number, r: number
    ) {
        const visualY = baseY - height;
        const seed = Math.abs(Math.sin(q * 12.9 + r * 78.2));
        if (seed > 0.6) {
             SurfacePainter.drawDetailTexture(ctx, baseX, visualY, type, detailColor, seed);
        }
    }
};

import { Agent, GameEngine, VICTORY_PHASE_DURATION } from "../game";
