        ctx.resetTransform();
        ctx.clearRect(0, 0, physicalWidth, physicalHeight);
        ctx.scale(dpr, dpr);
        this.backgroundRenderer.draw(ctx, logicalWidth, logicalHeight, scene, engine.mapConfig, globalTime);

        ctx.save();
        this.renderer.camera.sync(camera); 
        this.renderer.camera.applyTransform(ctx, logicalWidth, logicalHeight);

        this.renderList.reset();
        const terrainHeightFunc = (q: number, r: number) => this.renderer.grid.getTerrainHeight(q, r, engine);

        this.renderer.grid.submitRenderables(
            this.renderList,
            engine, hoveredHex, hoveredSkill, highlight, 
            engine.projectiles,
            this.transitionT, this.transitionPhase,
            globalTime
        );

        this.renderer.vfxRenderer.submitRenderables(
            this.renderList,
            engine,
            this.renderer.vfx,
            terrainHeightFunc,
            engine.mapConfig,
            this.transitionT,
            this.transitionPhase,
            { width: logicalWidth, height: logicalHeight, camera } 
        );

        this.renderer.unit.submitRenderables(
            this.renderList,
            engine.agents, 
            terrainHeightFunc, 
            globalTime, 
            highlight, 
            engine.mapConfig,
            engine.isRunning 
        );

        this.renderList.sort();

        for (let i = 0; i < this.renderList.count; i++) {
            const op = this.renderList.ops[i];
            const snapX = Math.round(op.tx);
            const snapY = Math.round(op.ty);

            switch (op.type) {
                case RenderOpType.TERRAIN:
                    // Fix: Pass op.tq and op.tr correctly
                    TerrainRenderer.drawBlock(ctx, snapX, snapY, op.tsize, op.th, op.ttheme, op.ttype, globalTime, layout, op.tq, op.tr);
                    const visualTopY = snapY - op.th;
                    TerrainRenderer.drawTerrainDetail(ctx, snapX, snapY, op.th, op.ttype, op.tdetail, op.tq, op.tr);
                    GridOverlays.drawOverlays(ctx, snapX, visualTopY, op.tsize, op.oStatus, op.oDanger, op.oLightCol, op.oLightInt, op.oRange, op.oRangeCol, op.oHover, op.oHasUnit, op.tq, op.tr, op.time, op.oHazard, layout);
                    break;
                case RenderOpType.OBSTACLE:
                    const sprite = SpriteManager.getObstacleSprite(op.ttype, layout);
                    ctx.drawImage(sprite, snapX - ENV_ANCHOR_X, snapY - ENV_ANCHOR_Y);
                    break;
                case RenderOpType.UNIT:
                    if (op.agent) this.renderer.unit.drawAssembly(ctx, op.agent, snapX, snapY, op.th, op.time, op.uSelected, op.uSilhouette, op.pIsUlt);
                    break;
                case RenderOpType.DECAL:
                    const dImg = AssetManager.getBlastZone(op.dColor);
                    ctx.save();
                    ctx.translate(snapX, snapY);
                    ctx.scale(op.dScale, op.dScale);
                    ctx.globalAlpha = Math.min(1, op.dLife);
                    ctx.drawImage(dImg, -64, -32, 128, 64);
                    ctx.restore();
                    break;
                case RenderOpType.VFX:
                    if (op.particle) {
                        const p = op.particle;
                        ctx.save();
                        ctx.translate(snapX, snapY);
                        ParticleRenderer.drawSingleParticle(ctx, p, 0, 0, op.vProgress, op.vChaos, layout);
                        ctx.restore();
                    }
                    break;
                case RenderOpType.PROJECTILE:
                    ProjectileDrawer.draw(ctx, op, globalTime);
                    break;
            }
        }

        const occludedAgents = this.renderer.grid.getOccludedAgents(engine);
        if (occludedAgents.length > 0) {
            ctx.save();
            occludedAgents.forEach(agent => {
                this.renderer.unit.drawSilhouette(ctx, agent, terrainHeightFunc, globalTime, engine.mapConfig);
            });
            ctx.restore();
        }

        this.renderer.statusOrchestrator.draw(ctx, engine.agents, globalTime, terrainHeightFunc);
        this.renderer.vfxRenderer.drawTopLayerParticles(ctx, this.renderer.vfx, scene, engine.mapConfig, this.transitionT, this.transitionPhase, layout);
        ctx.restore(); 

        let transitionAberration = 0;
        if (this.transitionPhase !== 'IDLE') transitionAberration = 4 * this.transitionT * (1 - this.transitionT) * 0.5;

        this.postProcessor.apply(ctx, physicalWidth, physicalHeight, this.renderer.camera.getTrauma(), transitionAberration);

        ctx.save(); 
        this.renderer.camera.applyTransform(ctx, logicalWidth, logicalHeight);
        this.tacticalRenderer.drawOverlay(ctx, engine, highlight, this.renderer.grid, globalTime);
        this.hudRenderer.draw(ctx, this.renderer.hud, engine.agents, terrainHeightFunc, engine.mapConfig, highlight, globalTime);
        ctx.restore(); 

        if (engine.directorTargetId) this.tacticalRenderer.drawHUD(ctx, engine, logicalWidth, logicalHeight, camera, globalTime);
        this.tacticalRenderer.drawDebug(ctx, fps);

        let blurAmount = 0;
        if (engine.isFinishing) blurAmount = 1.0 - (engine.victoryTimer / VICTORY_PHASE_DURATION);
        else if (engine.winningTeam !== null) blurAmount = 1.0;

        if (this.transitionPhase === 'OUT') blurAmount = 1.0; 
        else if (this.transitionPhase === 'IN') blurAmount = 1.0 - this.transitionT;

        if (blurAmount > 0) this.postProcessor.applyFinishBlur(ctx, physicalWidth, physicalHeight, Math.max(0, Math.min(1, blurAmount)));
    }
}

import { useRef, useState, useCallback, useEffect } from 'react';
import { GameEngine, Agent } from '../engine/game';
import { ToolType, Team, Skill, Role, HexLayout } from '../types';
import { SCENE_DB } from '../data/scenes';
import { DesignExporter } from '../engine/systems/DesignExporter';
import { DEFAULT_HEX_LAYOUT } from '../constants';
import { UNIT_DB } from '../data/units';

export const useGameApp = () => {
    const engineRef = useRef(new GameEngine());

    // --- STATE ---
    const [isShowcaseMode, setIsShowcaseMode] = useState(true);
    const [isPlaying, setIsPlaying] = useState(false);
    const [unitCount, setUnitCount] = useState(0); 
    const [tool, setTool] = useState<ToolType>(ToolType.SELECT);
    const [selectedObstacle, setSelectedObstacle] = useState<string>('WALL'); 
    const [selectedAgent, setSelectedAgent] = useState<Agent | null>(null);
    const [hoveredSkill, setHoveredSkill] = useState<Skill | null>(null);
    const [hpInput, setHpInput] = useState(600); 
    const [mapW, setMapW] = useState(12);
    const [mapH, setMapH] = useState(8);
    const [timeScale, setTimeScale] = useState(1.0);
    const [winner, setWinner] = useState<Team | null>(null);
    const [currentSceneId, setCurrentSceneId] = useState('VOID');
    const [spawnMode, setSpawnMode] = useState<'RANDOM' | 'DRAFT'>('RANDOM');
    const [draftRole, setDraftRole] = useState<Role>(Role.WARRIOR);
    const [hexLayout, setHexLayout] = useState<HexLayout>(DEFAULT_HEX_LAYOUT);

    // UI State
    const [showLogs, setShowLogs] = useState(false);
    const [showDB, setShowDB] = useState(false);
    const [showVFXMap, setShowVFXMap] = useState(false); 
    const [transitionPhase, setTransitionPhase] = useState<'IDLE' | 'IN' | 'OUT'>('IDLE');
    const [showFactionWarning, setShowFactionWarning] = useState(false);

    // --- EVENT LISTENER SETUP ---
    useEffect(() => {
        const engine = engineRef.current;
        const handleGameOver = (data: { winner: Team }) => {
            setWinner(data.winner);
            if (engine.isRunning) engine.stop(); 
            setIsPlaying(false);
        };
        engine.bus.on('GAME_OVER', handleGameOver);
        return () => {
            engine.bus.off('GAME_OVER', handleGameOver);
        };
    }, []);

    // Showcase Auto-Loop Logic
    useEffect(() => {
        if (isShowcaseMode && winner !== null) {
            const timer = setTimeout(() => {
                setTransitionPhase('OUT');
                engineRef.current.agents = [];
                engineRef.current.combat.projectiles = [];

                setTimeout(() => {
                    setupShowcaseMap(); 
                    setTransitionPhase('IN'); 
                    setTimeout(() => {
                        setTransitionPhase('IDLE');
                        spawnShowcaseUnits(); 
                    }, 1200); 
                }, 1200); 
            }, 800); 
            return () => clearTimeout(timer);
        }
    }, [winner, isShowcaseMode]);

    // --- LOGIC ---

    const setupShowcaseMap = useCallback(() => {
        const engine = engineRef.current;
        engine.stop();
        setWinner(null);
        setSelectedAgent(null);

        engine.mapConfig.w = Math.floor(10 + Math.random() * 4);
        engine.mapConfig.h = Math.floor(8 + Math.random() * 4);

        const newLayout: HexLayout = Math.random() > 0.5 ? 'FLAT' : 'POINTY';
        engine.mapConfig.layout = newLayout;
        setHexLayout(newLayout);

        engine.randomizeEnvironment(); 
        setCurrentSceneId(engine.currentScene.id);
    }, []);

    /**
     * 重寫生成邏輯：實施「精英編隊制」
     * 確保每隊五種職階齊全，剩餘名額補強
     */
    const spawnShowcaseUnits = useCallback(() => {
        const engine = engineRef.current;
        let validHexes = (Array.from(engine.mapKeys) as string[])
            .map(k => {
                const [q, r] = k.split(',').map(Number);
                return {q, r};
            })
            .filter(h => !engine.map.hasObstacle(h.q, h.r));

        // 洗牌座標
        for (let i = validHexes.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [validHexes[i], validHexes[j]] = [validHexes[j], validHexes[i]];
        }

        let spawnIndex = 0;
        const ALL_ROLES = [Role.TANK, Role.WARRIOR, Role.RANGER, Role.MAGE, Role.SUPPORT];

        const spawnTeam = (team: Team) => {
            // 1. 強制分配全職階
            ALL_ROLES.forEach(role => {
                if (spawnIndex < validHexes.length) {
                    const h = validHexes[spawnIndex++];
                    const stats = UNIT_DB[role];
                    const hp = stats.maxHp + Math.floor(Math.random() * 200);

                    const agent = engine.addAgent(team, h.q, h.r, hp);
                    if (agent) {
                        agent.role = role;
                        agent.maxHp = hp; agent.hp = hp;
                        agent.moveSpeed = stats.moveSpeed;
                        agent.movementType = stats.movementType;
                        agent.saveState();
                        agent.reset(engine.mapConfig);
                    }
                }
            });

            // 2. 隨機補充 1 名單位
            if (spawnIndex < validHexes.length) {
                engine.addAgent(team, validHexes[spawnIndex++].q, validHexes[spawnIndex++].r, 500);
            }
        };

        spawnTeam(Team.BLUE);
        spawnTeam(Team.RED);

        engine.play();
        setIsPlaying(true);
    }, []);

    const startShowcaseMatch = useCallback(() => {
        setupShowcaseMap();
        spawnShowcaseUnits();
    }, [setupShowcaseMap, spawnShowcaseUnits]);

    useEffect(() => {
        startShowcaseMatch();
    }, [startShowcaseMatch]);

    useEffect(() => {
        const interval = setInterval(() => {
            setUnitCount(engineRef.current.agents.length);
        }, 500); 
        return () => clearInterval(interval);
    }, []);

    useEffect(() => {
        engineRef.current.timeScale = timeScale;
    }, [timeScale]);

    const enterManualMode = () => {
        setIsShowcaseMode(false);
        engineRef.current.stop();
        setIsPlaying(false);
        setWinner(null);
        engineRef.current.clear(true); 
        engineRef.current.agents = [];
        setUnitCount(0);
        setMapW(engineRef.current.mapConfig.w);
        setMapH(engineRef.current.mapConfig.h);
        setHexLayout(engineRef.current.mapConfig.layout);
        setCurrentSceneId(engineRef.current.currentScene.id);
    };

    const handleUpdateMapSize = useCallback((w: number, h: number) => {
        setMapW(w);
        setMapH(h);
        engineRef.current.mapConfig.w = w;
        engineRef.current.mapConfig.h = h;
        engineRef.current.clear(false); 
        setSelectedAgent(null);
        setWinner(null);
    }, []);

    const handleUpdateLayout = useCallback((l: HexLayout) => {
        setHexLayout(l);
        engineRef.current.mapConfig.layout = l;
        engineRef.current.clear(true); 
        setSelectedAgent(null);
        setWinner(null);
    }, []);

    const handleSetScene = useCallback((id: string) => {
        const scene = SCENE_DB.find(s => s.id === id);
        if (scene) {
            engineRef.current.currentScene = scene;
            engineRef.current.map.rebuildMap(engineRef.current);
            setCurrentSceneId(id);
        }
    }, []);

    const handleRandomBattlefield = useCallback(() => {
        const engine = engineRef.current;
        engine.stop();
        setWinner(null);
        setSelectedAgent(null);
        engine.clear(false); 

        const newLayout: HexLayout = Math.random() > 0.5 ? 'FLAT' : 'POINTY';
        engine.mapConfig.layout = newLayout;
        setHexLayout(newLayout);

        engine.randomizeEnvironment();
        setMapW(engine.mapConfig.w);
        setMapH(engine.mapConfig.h);
        setCurrentSceneId(engine.currentScene.id);

        spawnShowcaseUnits();
    }, [spawnShowcaseUnits]);

    const handleNextLevel = useCallback(() => {
        handleRandomBattlefield();
        const engine = engineRef.current;
        engine.play();
        setIsPlaying(true);
        setTool(ToolType.SELECT);
    }, [handleRandomBattlefield]);

    const handleReset = useCallback(() => {
        engineRef.current.restart();
        setIsPlaying(false); 
        setWinner(null);
    }, []);

    const togglePlay = useCallback(() => {
        if (winner !== null) return;
        if (isPlaying) {
            engineRef.current.stop();
            setIsPlaying(false);
        } else {
            const hasBlue = engineRef.current.agents.some(a => a.team === Team.BLUE);
            const hasRed = engineRef.current.agents.some(a => a.team === Team.RED);
            if (!hasBlue || !hasRed) {
                setShowFactionWarning(true);
                setTimeout(() => setShowFactionWarning(false), 2500);
                return;
            }
            engineRef.current.play();
            setIsPlaying(true);
            setTool(ToolType.SELECT);
        }
    }, [isPlaying, winner]);

    const handleSelectAgent = (a: Agent | null) => {
        setSelectedAgent(a);
    };

    return {
        engineRef,
        state: {
            isShowcaseMode, isPlaying, unitCount, tool, selectedObstacle,
            selectedAgent, hoveredSkill, hpInput, mapW, mapH, timeScale,
            winner, currentSceneId, spawnMode, draftRole, showLogs, showDB, showVFXMap,
            transitionPhase, showFactionWarning, hexLayout
        },
        setters: {
            setTool, setSelectedObstacle, setHpInput, setTimeScale, 
            setSpawnMode, setDraftRole, setShowLogs, setShowDB, setShowVFXMap,
            setIsShowcaseMode, setSelectedAgent, setHoveredSkill
        },
        actions: {
            enterManualMode,
            handleUpdateMapSize,
            handleUpdateLayout,
            handleSetScene,
            handleRandomBattlefield,
            handleNextLevel,
            handleReset,
            togglePlay,
            onWin: (team: Team) => { engineRef.current.bus.emit('GAME_OVER', {winner: team}) },
            handleSelectAgent,
            startShowcaseMatch,
            downloadSpec: DesignExporter.downloadSpec,
            rematch: () => { 
                setWinner(null); 
                engineRef.current.restart(); 
                engineRef.current.play(); 
                setIsPlaying(true); 
            }
        }
    };
};

import { ISO_SCALE_Y, BASE_HEIGHT, BLOCK_HEIGHT } from "../../../constants";
import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { SurfacePainter } from "../../graphics/painters/SurfacePainter";
import { HexLayout } from "../../../types";

const WALL_SLOP_EPSILON = 1.0; 

/**
 * 地形渲染器 v23.0 - 低多邊形實體版
 * 解決場景過於扁平問題，強化物理體積與材質細節
 */
export const TerrainRenderer = {

    drawBlock(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        size: number, height: number, 
        theme: any,
        type: string,
        globalTime: number,
        layout: HexLayout,
        q: number, r: number
    ) {
        const visualTopY = -height;
        const vertices = HexGeometry.getVertices(size, true, layout); 

        ctx.save();
        ctx.translate(x, y);

        // --- 1. 物理側牆 (Solid Side Walls) ---
        // 使用硬派的高對比線條強化體積感
        this.drawVerticalWall(ctx, vertices[1], vertices[0], visualTopY, theme.sideDark);
        this.drawVerticalWall(ctx, vertices[2], vertices[1], visualTopY, theme.sideLight);
        if (layout === 'FLAT') {
            this.drawVerticalWall(ctx, vertices[3], vertices[2], visualTopY, theme.sideDark);
        }

        // --- 2. 實體頂面 (Solid Top Face) ---
        ctx.translate(0, visualTopY);

        const topGrad = ctx.createLinearGradient(-size, -size, size, size);
        topGrad.addColorStop(0, theme.rim); 
        topGrad.addColorStop(0.15, theme.top); 
        topGrad.addColorStop(0.85, theme.sideDark); 
        ctx.fillStyle = topGrad;

        HexGeometry.traceHex(ctx, 0, 0, size, true, layout);
        ctx.fill();

        // --- 3. 材質噪點 (Faceted Grit) ---
        // 使用座標穩定的種子，防止移動時材質閃爍
        this.drawMaterialGrit(ctx, size, theme.detail, layout, q + r);

        // --- 4. 硬邊緣勾勒 ---
        ctx.strokeStyle = theme.rim;
        ctx.lineWidth = 1.5;
        ctx.stroke();

        // 應用場景動態
        this.applyThemeSurfaceDynamics(ctx, size, type, theme, globalTime, layout);

        ctx.restore();
    },

    /**
     * 繪製低多邊形風格的材質細節
     */
    drawMaterialGrit(ctx: CanvasRenderingContext2D, size: number, color: string, layout: HexLayout, seed: number) {
        ctx.save();
        ctx.globalAlpha = 0.25;
        ctx.fillStyle = color;

        // 根據邏輯座標生成的穩定幾何塊
        const count = 4;
        for(let i=0; i<count; i++) {
            const gx = (Math.sin(seed * 1.7 + i) * 0.7) * size;
            const gy = (Math.cos(seed * 0.9 + i) * 0.4) * size * ISO_SCALE_Y;

            ctx.beginPath();
            ctx.moveTo(gx, gy);
            ctx.lineTo(gx + 12, gy + 4);
            ctx.lineTo(gx + 6, gy + 10);
            ctx.closePath();
            ctx.fill();
        }
        ctx.restore();
    },

    applyThemeSurfaceDynamics(ctx: CanvasRenderingContext2D, size: number, type: string, theme: any, t: number, layout: HexLayout) {
        ctx.save();
        ctx.globalAlpha = 0.8; 

        if (type === 'FOREST') {
            ctx.strokeStyle = theme.detail;
            ctx.lineWidth = 1;
            const pulse = 0.4 + Math.sin(t * 1.5) * 0.2;
            ctx.globalAlpha = pulse;
            HexGeometry.traceHex(ctx, 0, 0, size * 0.75, true, layout); ctx.stroke();
        } 
        else if (type === 'MAGMA') {
            const offset = (t * 40) % 120;
            ctx.strokeStyle = '#ef4444';
            ctx.lineWidth = 2.5;
            ctx.beginPath();
            ctx.moveTo(-size, -size/2 + offset); ctx.lineTo(size, size/2 - 25 + offset);
            ctx.stroke();
            SurfacePainter.drawLiquid(ctx, 0, 0, '#ef4444', t, 1.4);
        }
        else if (type === 'VOID') {
            ctx.strokeStyle = theme.detail;
            ctx.lineWidth = 1.5;
            const scanY = (t * 60) % (size * 3) - size * 1.5;
            ctx.beginPath();
            ctx.moveTo(-size * 0.9, scanY * ISO_SCALE_Y); ctx.lineTo(size * 0.9, scanY * ISO_SCALE_Y);
            ctx.stroke();
        }

        ctx.restore();
    },

    drawVerticalWall(ctx: CanvasRenderingContext2D, vBottom1: {x:number, y:number}, vBottom2: {x:number, y:number}, topY: number, color: string) {
        ctx.fillStyle = color;
        ctx.beginPath();
        ctx.moveTo(vBottom1.x, vBottom1.y);
        ctx.lineTo(vBottom2.x, vBottom2.y);
        ctx.lineTo(vBottom2.x, vBottom2.y + topY);
        ctx.lineTo(vBottom1.x, vBottom1.y + topY);
        ctx.closePath();
        ctx.fill();

        // 牆面交界硬邊
        ctx.strokeStyle = 'rgba(0,0,0,0.3)';
        ctx.lineWidth = 1.2;
        ctx.stroke();
    },

    drawTerrainDetail(
        ctx: CanvasRenderingContext2D, 
        baseX: number, baseY: number, 
        height: number,
        type: string, 
        detailColor: string,
        q: number, r: number
    ) {
        const visualY = baseY - height;
        const seed = Math.abs(Math.sin(q * 12.9 + r * 78.2));
        if (seed > 0.65) {
             SurfacePainter.drawDetailTexture(ctx, baseX, visualY, type, detailColor, seed);
        }
    }
};

import { Agent } from "../../../game";
import { AnimState, Role } from "../../../../types";
import { HexGeometry } from "../../../graphics/utils/HexGeometry";

/**
 * 帝國 (Imperial) 渲染器 v23.0 - 魔獸經典實體版
 */
export const ImperialRenderer = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean, isRunning: boolean) {
        const isHit = agent.hitFlashTimer > 0;
        const role = agent.role;

        // 1. 英雄式動態骨架 (Heroic Animation)
        let bob = 0;
        let tilt = 0;

        if (isRunning) {
            // 強烈的重力起伏感
            const freq = role === Role.TANK ? 12 : 16;
            const amp = role === Role.TANK ? 8 : 5;
            bob = Math.abs(Math.sin(t * freq)) * -amp;
            tilt = Math.sin(t * freq) * 0.18;
        } else {
            // 待機沉穩呼吸
            bob = Math.sin(t * 2.5) * 2;
        }

        ctx.save();
        if (isHit) ctx.translate((Math.random() - 0.5) * 15, 0);

        // 座標真理定位
        ctx.translate(0, -35 + bob);
        ctx.rotate(tilt);

        // 2. 職階實體建模 (Solid Faceted Shading)
        this.drawSolidBody(ctx, role, isHit, t);

        // 3. 專屬武裝
        this.drawWeapon(ctx, role, t, isRunning);

        ctx.restore();
    },

    drawSolidBody(ctx: CanvasRenderingContext2D, role: Role, isHit: boolean, t: number) {
        const cobalt = isHit ? '#fff' : '#1e40af';
        const silver = isHit ? '#fff' : '#e2e8f0';
        const gold = '#fbbf24';

        ctx.save();

        switch (role) {
            case Role.TANK:
                // 【坦克】：配備重型梯形胸甲
                ctx.fillStyle = cobalt;
                ctx.fillRect(-22, -10, 44, 45); 
                ctx.fillStyle = silver; 
                ctx.fillRect(-18, 0, 36, 15); // 胸甲分面
                ctx.strokeStyle = gold;
                ctx.lineWidth = 3;
                ctx.strokeRect(-22, -10, 44, 45);

                // 巨型肩盾
                this.drawCubeArmor(ctx, -26, -15, 14, gold);
                this.drawCubeArmor(ctx, 26, -15, 14, gold);
                break;

            case Role.WARRIOR:
                // 【戰士】：倒三角英雄身材
                ctx.fillStyle = cobalt;
                ctx.beginPath();
                ctx.moveTo(-28, -20); ctx.lineTo(28, -20); ctx.lineTo(15, 40); ctx.lineTo(-15, 40);
                ctx.closePath(); ctx.fill();
                ctx.strokeStyle = gold;
                ctx.lineWidth = 2.5;
                ctx.stroke();

                this.drawCubeArmor(ctx, -30, -22, 16, silver);
                this.drawCubeArmor(ctx, 30, -22, 16, silver);
                break;

            case Role.MAGE:
            case Role.SUPPORT:
                // 【法系】：懸浮稜鏡法袍 (無腳)
                ctx.fillStyle = cobalt;
                HexGeometry.traceHex(ctx, 0, 15, 25, true); ctx.fill();
                ctx.fillStyle = silver;
                HexGeometry.traceHex(ctx, 0, -5, 20, true); ctx.fill();

                // 奧術幾何環
                ctx.save();
                ctx.rotate(t * 1.2);
                ctx.strokeStyle = gold;
                ctx.setLineDash([8, 4]);
                HexGeometry.traceHex(ctx, 0, 0, 40, false); ctx.stroke();
                ctx.restore();
                break;

            case Role.RANGER:
                // 【遊俠】：纖細流線型，不對稱披風
                ctx.fillStyle = cobalt;
                ctx.fillRect(-16, -12, 32, 50);
                ctx.fillStyle = silver;
                ctx.beginPath();
                ctx.moveTo(-16, -12); ctx.lineTo(16, -12); ctx.lineTo(0, -42); 
                ctx.closePath(); ctx.fill();
                break;
        }

        // 統一英雄桶盔 (桶狀幾何)
        ctx.fillStyle = silver;
        ctx.fillRect(-11, -30, 22, 22);
        ctx.strokeStyle = '#334155';
        ctx.lineWidth = 2;
        ctx.strokeRect(-11, -30, 22, 22);
        // T型護目鏡
        ctx.fillStyle = '#0f172a';
        ctx.fillRect(-9, -20, 18, 4);
        ctx.fillRect(-1, -28, 2, 12);

        ctx.restore();
    },

    drawCubeArmor(ctx: CanvasRenderingContext2D, x: number, y: number, size: number, color: string) {
        ctx.save();
        ctx.translate(x, y);
        ctx.fillStyle = color;
        ctx.fillRect(-size/2, -size/2, size, size);
        ctx.strokeStyle = '#000';
        ctx.lineWidth = 1.5;
        ctx.strokeRect(-size/2, -size/2, size, size);
        ctx.restore();
    },

    drawWeapon(ctx: CanvasRenderingContext2D, role: Role, t: number, isRunning: boolean) {
        ctx.save();
        ctx.translate(36, 5);
        const swing = Math.sin(t * (isRunning ? 15 : 4)) * 0.4;
        ctx.rotate(swing);

        ctx.fillStyle = '#94a3b8';
        ctx.strokeStyle = '#1e40af';
        ctx.lineWidth = 3;

        if (role === Role.TANK) {
            // 巨型物理塔盾
            ctx.fillStyle = '#475569';
            ctx.fillRect(-8, -25, 45, 70);
            ctx.strokeStyle = '#fbbf24';
            ctx.strokeRect(-8, -25, 45, 70);
            ctx.fillStyle = '#3b82f6';
            ctx.fillRect(10, 5, 18, 18);
        } else if (role === Role.WARRIOR) {
            // 寬刃重劍
            ctx.beginPath();
            ctx.moveTo(0, 18); ctx.lineTo(-15, 0); ctx.lineTo(0, -80); ctx.lineTo(15, 0);
            ctx.closePath(); ctx.fill(); ctx.stroke();
            ctx.fillStyle = '#fbbf24';
            ctx.fillRect(-22, -2, 44, 10);
        } else if (role === Role.RANGER) {
            // 重型導軌狙擊槍
            ctx.fillStyle = '#1e293b';
            ctx.fillRect(-25, -6, 60, 12);
            ctx.fillStyle = '#60a5fa';
            ctx.fillRect(30, -8, 14, 14);
        } else {
            // 奧術權杖 (實體)
            ctx.fillRect(-4, -25, 8, 75);
            ctx.fillStyle = '#60a5fa';
            ctx.save();
            ctx.translate(0, -40);
            ctx.rotate(t * 4);
            HexGeometry.traceHex(ctx, 0, 0, 16, false); ctx.fill();
            ctx.restore();
        }
        ctx.restore();
    }
};

import { Agent } from "../../../game";
import { AnimState, Role } from "../../../../types";
import { HexGeometry } from "../../../graphics/utils/HexGeometry";

/**
 * 叛軍 (Covenant) 渲染器 v23.0 - 狂暴部族實體版
 */
export const CovenantRenderer = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean, isRunning: boolean) {
        const isHit = agent.hitFlashTimer > 0;
        const role = agent.role;

        // 1. 侵略性動態 (Aggressive Dynamics)
        let bob = 0;
        let lean = 0.3; // 預設戰鬥前傾

        if (isRunning) {
            const freq = 20; 
            bob = Math.abs(Math.cos(t * freq)) * -12; // 沉重跳躍跑感
            lean = 0.5;
        } else {
            bob = Math.sin(t * 6) * 3; // 高頻心跳感呼吸
        }

        ctx.save();
        if (isHit) ctx.translate((Math.random() - 0.5) * 20, 0);

        ctx.translate(0, -35 + bob);
        ctx.rotate(lean);

        // 2. 職階鋸齒建模 (Jagged Solid Modeling)
        this.drawJaggedBody(ctx, role, isHit, t);

        // 3. 殘暴武裝
        this.drawWeapon(ctx, role, t, isRunning);

        ctx.restore();
    },

    drawJaggedBody(ctx: CanvasRenderingContext2D, role: Role, isHit: boolean, t: number) {
        const obsidian = isHit ? '#fff' : '#18181b';
        const blood = isHit ? '#fff' : '#991b1b';
        const fire = '#ea580c';

        ctx.save();

        switch (role) {
            case Role.TANK:
                // 【毀滅者】：多刺的圓筒重裝
                ctx.fillStyle = obsidian;
                HexGeometry.traceHex(ctx, 0, 15, 32, true); ctx.fill();
                ctx.strokeStyle = blood;
                ctx.lineWidth = 4;
                HexGeometry.traceHex(ctx, 0, 15, 32, true); ctx.stroke();

                this.drawSpike(ctx, -24, -15, 40, t, -0.7);
                this.drawSpike(ctx, 24, -15, 40, t, 0.7);
                break;

            case Role.WARRIOR:
                // 【掠奪者】：極端倒三角非對稱
                ctx.fillStyle = obsidian;
                ctx.beginPath();
                ctx.moveTo(-35, -25); ctx.lineTo(35, -20); ctx.lineTo(15, 45); ctx.lineTo(-15, 45);
                ctx.closePath(); ctx.fill();

                this.drawSpike(ctx, -38, -28, 30, t * 2, -1.0);
                this.drawSpike(ctx, 38, -24, 30, t * 2, 1.0);
                break;

            case Role.MAGE:
            case Role.SUPPORT:
                // 【邪能引導者】：破碎懸浮晶體
                ctx.fillStyle = obsidian;
                ctx.save();
                ctx.rotate(t * 1.5);
                HexGeometry.traceRotatedHex(ctx, 0, 0, 30, 0, false); ctx.fill();
                ctx.strokeStyle = fire;
                ctx.lineWidth = 3;
                HexGeometry.traceRotatedHex(ctx, 0, 0, 30, 0.5, false); ctx.stroke();
                ctx.restore();

                // 圍繞邪能火球
                ctx.fillStyle = fire;
                ctx.beginPath(); ctx.arc(Math.cos(t*6)*50, Math.sin(t*6)*30 - 30, 10, 0, Math.PI*2); ctx.fill();
                break;

            case Role.RANGER:
                // 【追獵者】：帶刺長型廓形
                ctx.fillStyle = obsidian;
                ctx.fillRect(-18, -18, 36, 60);
                ctx.fillStyle = blood;
                ctx.fillRect(-18, -18, 36, 15);
                this.drawSpike(ctx, 0, -45, 30, t, 0);
                break;
        }

        // 頭部：猙獰白骨面具
        ctx.fillStyle = '#fef2f2';
        ctx.beginPath();
        ctx.moveTo(0, -20); ctx.lineTo(16, 0); ctx.lineTo(0, 25); ctx.lineTo(-16, 0);
        ctx.closePath(); ctx.fill();
        ctx.fillStyle = '#f00'; // 兇光眼
        ctx.fillRect(-8, -2, 6, 6); ctx.fillRect(2, -2, 6, 6);

        ctx.restore();
    },

    drawSpike(ctx: CanvasRenderingContext2D, x: number, y: number, h: number, t: number, ang: number) {
        ctx.save();
        ctx.translate(x, y);
        ctx.rotate(ang + Math.sin(t*15)*0.2);
        ctx.fillStyle = '#27272a';
        ctx.beginPath();
        ctx.moveTo(-7, 0); ctx.lineTo(7, 0); ctx.lineTo(0, -h);
        ctx.closePath(); ctx.fill();
        ctx.strokeStyle = '#ef4444';
        ctx.stroke();
        ctx.restore();
    },

    drawWeapon(ctx: CanvasRenderingContext2D, role: Role, t: number, isRunning: boolean) {
        ctx.save();
        ctx.translate(40, 15);
        const swing = Math.cos(t * (isRunning ? 20 : 6)) * 0.5;
        ctx.rotate(swing);

        ctx.fillStyle = '#1c1917';
        ctx.strokeStyle = '#ea580c';
        ctx.lineWidth = 3.5;

        if (role === Role.WARRIOR || role === Role.TANK) {
            // 雙頭裂骨斧
            ctx.fillRect(-6, -15, 12, 100);
            ctx.fillStyle = '#7f1d1d';
            ctx.beginPath(); 
            ctx.moveTo(0, 20); ctx.lineTo(-50, -10); ctx.lineTo(-45, 50); ctx.lineTo(0, 40);
            ctx.closePath(); ctx.fill(); ctx.stroke();
            ctx.beginPath();
            ctx.moveTo(0, 20); ctx.lineTo(50, -10); ctx.lineTo(45, 50); ctx.lineTo(0, 40);
            ctx.closePath(); ctx.fill(); ctx.stroke();
        } else {
            // 邪能圖騰柱
            ctx.fillRect(-15, -50, 30, 120);
            ctx.fillStyle = '#ef4444';
            ctx.shadowBlur = 25; ctx.shadowColor = '#f00';
            ctx.fillRect(-18, -55, 36, 18);
            ctx.strokeRect(-15, -50, 30, 120);
        }
        ctx.restore();
    }
};

import { Agent, GameEngine, VICTORY_PHASE_DURATION } from "../game";
import { Camera, GameRenderer } from "../renderer"; 
import { Hex, Skill } from "../../types";

// Sub-renderers
import { BackgroundRenderer } from "./background";
import { TacticalRenderer } from "./tactical";
import { HUDRenderer } from "./HUDRenderer";
import { PostProcessor } from "./PostProcessor"; 
import { RenderList, RenderOpType } from "./RenderList";
import { ProjectileDrawer } from "./ProjectileDrawer";

// Painters
import { TerrainRenderer } from "./grid/TerrainRenderer";
import { GridOverlays } from "./grid/GridOverlays";
import { ParticleRenderer } from "../systems/vfx/renderers/ParticleRenderer";
import { SpriteManager } from "../sprites";
import { AssetManager } from "../assets";
import { ENV_ANCHOR_X, ENV_ANCHOR_Y } from "../graphics/EnvironmentFactory";

export class RenderPipeline {
    private renderer: GameRenderer;
    private backgroundRenderer: BackgroundRenderer;
    private tacticalRenderer: TacticalRenderer;
    private hudRenderer: HUDRenderer;
    private postProcessor: PostProcessor;
    private renderList: RenderList;

    private transitionT: number = 0;
    private transitionPhase: 'IN' | 'OUT' | 'IDLE' = 'IDLE';

    constructor(renderer: GameRenderer) {
        this.renderer = renderer;
        this.backgroundRenderer = new BackgroundRenderer();
        this.tacticalRenderer = new TacticalRenderer();
        this.hudRenderer = new HUDRenderer();
        this.postProcessor = new PostProcessor();
        this.renderList = new RenderList();
    }

    public setTransition(t: number, phase: 'IN' | 'OUT' | 'IDLE') {
        this.transitionT = t;
        this.transitionPhase = phase;
    }

    public update(dt: number, engine: GameEngine) {
        this.tacticalRenderer.update(dt, engine);
    }

    public draw(
        ctx: CanvasRenderingContext2D, 
        engine: GameEngine, 
        camera: Camera, 
        highlight: Agent | null, 
        fps: number, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null,
        globalTime: number
    ): void {
        const physicalWidth = ctx.canvas.width;
        const physicalHeight = ctx.canvas.height;
        if (physicalWidth === 0 || physicalHeight === 0) return;

        const dpr = window.devicePixelRatio || 1;
        const logicalWidth = physicalWidth / dpr;
        const logicalHeight = physicalHeight / dpr;
        const scene = engine.currentScene;
        const layout = engine.mapConfig.layout;

        ctx.resetTransform();
        ctx.clearRect(0, 0, physicalWidth, physicalHeight);
        ctx.scale(dpr, dpr);
        this.backgroundRenderer.draw(ctx, logicalWidth, logicalHeight, scene, engine.mapConfig, globalTime);

        ctx.save();
        this.renderer.camera.sync(camera); 
        this.renderer.camera.applyTransform(ctx, logicalWidth, logicalHeight);

        this.renderList.reset();
        const terrainHeightFunc = (q: number, r: number) => this.renderer.grid.getTerrainHeight(q, r, engine);

        this.renderer.grid.submitRenderables(
            this.renderList,
            engine, hoveredHex, hoveredSkill, highlight, 
            engine.projectiles,
            this.transitionT, this.transitionPhase,
            globalTime
        );

        this.renderer.vfxRenderer.submitRenderables(
            this.renderList,
            engine,
            this.renderer.vfx,
            terrainHeightFunc,
            engine.mapConfig,
            this.transitionT,
            this.transitionPhase,
            { width: logicalWidth, height: logicalHeight, camera } 
        );

        this.renderer.unit.submitRenderables(
            this.renderList,
            engine.agents, 
            terrainHeightFunc, 
            globalTime, 
            highlight, 
            engine.mapConfig,
            engine.isRunning 
        );

        this.renderList.sort();

        for (let i = 0; i < this.renderList.count; i++) {
            const op = this.renderList.ops[i];
            const snapX = Math.round(op.tx);
            const snapY = Math.round(op.ty);

            switch (op.type) {
                case RenderOpType.TERRAIN:
                    // SSOT: Pass op.tq and op.tr to the terrain drawer for stable seeding
                    TerrainRenderer.drawBlock(ctx, snapX, snapY, op.tsize, op.th, op.ttheme, op.ttype, globalTime, layout, op.tq, op.tr);
                    const visualTopY = snapY - op.th;
                    TerrainRenderer.drawTerrainDetail(ctx, snapX, snapY, op.th, op.ttype, op.tdetail, op.tq, op.tr);
                    GridOverlays.drawOverlays(ctx, snapX, visualTopY, op.tsize, op.oStatus, op.oDanger, op.oLightCol, op.oLightInt, op.oRange, op.oRangeCol, op.oHover, op.oHasUnit, op.tq, op.tr, op.time, op.oHazard, layout);
                    break;
                case RenderOpType.OBSTACLE:
                    const sprite = SpriteManager.getObstacleSprite(op.ttype, layout);
                    ctx.drawImage(sprite, snapX - ENV_ANCHOR_X, snapY - ENV_ANCHOR_Y);
                    break;
                case RenderOpType.UNIT:
                    if (op.agent) this.renderer.unit.drawAssembly(ctx, op.agent, snapX, snapY, op.th, op.time, op.uSelected, op.uSilhouette, op.pIsUlt);
                    break;
                case RenderOpType.DECAL:
                    const dImg = AssetManager.getBlastZone(op.dColor);
                    ctx.save();
                    ctx.translate(snapX, snapY);
                    ctx.scale(op.dScale, op.dScale);
                    ctx.globalAlpha = Math.min(1, op.dLife);
                    ctx.drawImage(dImg, -64, -32, 128, 64);
                    ctx.restore();
                    break;
                case RenderOpType.VFX:
                    if (op.particle) {
                        const p = op.particle;
                        ctx.save();
                        ctx.translate(snapX, snapY);
                        ParticleRenderer.drawSingleParticle(ctx, p, 0, 0, op.vProgress, op.vChaos, layout);
                        ctx.restore();
                    }
                    break;
                case RenderOpType.PROJECTILE:
                    ProjectileDrawer.draw(ctx, op, globalTime);
                    break;
            }
        }

        const occludedAgents = this.renderer.grid.getOccludedAgents(engine);
        if (occludedAgents.length > 0) {
            ctx.save();
            occludedAgents.forEach(agent => {
                this.renderer.unit.drawSilhouette(ctx, agent, terrainHeightFunc, globalTime, engine.mapConfig);
            });
            ctx.restore();
        }

        this.renderer.statusOrchestrator.draw(ctx, engine.agents, globalTime, terrainHeightFunc);
        this.renderer.vfxRenderer.drawTopLayerParticles(ctx, this.renderer.vfx, scene, engine.mapConfig, this.transitionT, this.transitionPhase, layout);
        ctx.restore(); 

        let transitionAberration = 0;
        if (this.transitionPhase !== 'IDLE') transitionAberration = 4 * this.transitionT * (1 - this.transitionT) * 0.5;

        this.postProcessor.apply(ctx, physicalWidth, physicalHeight, this.renderer.camera.getTrauma(), transitionAberration);

        ctx.save(); 
        this.renderer.camera.applyTransform(ctx, logicalWidth, logicalHeight);
        this.tacticalRenderer.drawOverlay(ctx, engine, highlight, this.renderer.grid, globalTime);
        this.hudRenderer.draw(ctx, this.renderer.hud, engine.agents, terrainHeightFunc, engine.mapConfig, highlight, globalTime);
        ctx.restore(); 

        if (engine.directorTargetId) this.tacticalRenderer.drawHUD(ctx, engine, logicalWidth, logicalHeight, camera, globalTime);
        this.tacticalRenderer.drawDebug(ctx, fps);

        let blurAmount = 0;
        if (engine.isFinishing) blurAmount = 1.0 - (engine.victoryTimer / VICTORY_PHASE_DURATION);
        else if (engine.winningTeam !== null) blurAmount = 1.0;

        if (this.transitionPhase === 'OUT') blurAmount = 1.0; 
        else if (this.transitionPhase === 'IN') blurAmount = 1.0 - this.transitionT;

        if (blurAmount > 0) this.postProcessor.applyFinishBlur(ctx, physicalWidth, physicalHeight, Math.max(0, Math.min(1, blurAmount)));
    }
}

import { useRef, useState, useCallback, useEffect } from 'react';
import { GameEngine, Agent } from '../engine/game';
import { ToolType, Team, Skill, Role, HexLayout } from '../types';
import { SCENE_DB } from '../data/scenes';
import { DesignExporter } from '../engine/systems/DesignExporter';
import { DEFAULT_HEX_LAYOUT } from '../constants';
import { UNIT_DB } from '../data/units';

export const useGameApp = () => {
    const engineRef = useRef(new GameEngine());

    // --- STATE ---
    const [isShowcaseMode, setIsShowcaseMode] = useState(true);
    const [isPlaying, setIsPlaying] = useState(false);
    const [unitCount, setUnitCount] = useState(0); 
    const [tool, setTool] = useState<ToolType>(ToolType.SELECT);
    const [selectedObstacle, setSelectedObstacle] = useState<string>('WALL'); 
    const [selectedAgent, setSelectedAgent] = useState<Agent | null>(null);
    const [hoveredSkill, setHoveredSkill] = useState<Skill | null>(null);
    const [hpInput, setHpInput] = useState(600); 
    const [mapW, setMapW] = useState(12);
    const [mapH, setMapH] = useState(8);
    const [timeScale, setTimeScale] = useState(1.0);
    const [winner, setWinner] = useState<Team | null>(null);
    const [currentSceneId, setCurrentSceneId] = useState('VOID');
    const [spawnMode, setSpawnMode] = useState<'RANDOM' | 'DRAFT'>('RANDOM');
    const [draftRole, setDraftRole] = useState<Role>(Role.WARRIOR);
    const [hexLayout, setHexLayout] = useState<HexLayout>(DEFAULT_HEX_LAYOUT);

    // UI State
    const [showLogs, setShowLogs] = useState(false);
    const [showDB, setShowDB] = useState(false);
    const [showVFXMap, setShowVFXMap] = useState(false); 
    const [transitionPhase, setTransitionPhase] = useState<'IDLE' | 'IN' | 'OUT'>('IDLE');
    const [showFactionWarning, setShowFactionWarning] = useState(false);

    // --- EVENT LISTENER SETUP ---
    useEffect(() => {
        const engine = engineRef.current;
        const handleGameOver = (data: { winner: Team }) => {
            setWinner(data.winner);
            if (engine.isRunning) engine.stop(); 
            setIsPlaying(false);
        };
        engine.bus.on('GAME_OVER', handleGameOver);
        return () => {
            engine.bus.off('GAME_OVER', handleGameOver);
        };
    }, []);

    // Showcase Auto-Loop Logic
    useEffect(() => {
        if (isShowcaseMode && winner !== null) {
            const timer = setTimeout(() => {
                setTransitionPhase('OUT');
                engineRef.current.agents = [];
                engineRef.current.combat.projectiles = [];

                setTimeout(() => {
                    setupShowcaseMap(); 
                    setTransitionPhase('IN'); 
                    setTimeout(() => {
                        setTransitionPhase('IDLE');
                        spawnShowcaseUnits(); 
                    }, 1200); 
                }, 1200); 
            }, 800); 
            return () => clearTimeout(timer);
        }
    }, [winner, isShowcaseMode]);

    // --- LOGIC ---

    const setupShowcaseMap = useCallback(() => {
        const engine = engineRef.current;
        engine.stop();
        setWinner(null);
        setSelectedAgent(null);

        engine.mapConfig.w = Math.floor(10 + Math.random() * 4);
        engine.mapConfig.h = Math.floor(8 + Math.random() * 4);

        const newLayout: HexLayout = Math.random() > 0.5 ? 'FLAT' : 'POINTY';
        engine.mapConfig.layout = newLayout;
        setHexLayout(newLayout);

        engine.randomizeEnvironment(); 
        setCurrentSceneId(engine.currentScene.id);
    }, []);

    /**
     * 重寫生成邏輯：實施「精英編隊制 (Guaranteed Roster)」
     * 確保每隊五種職階齊全，剩餘名額隨機補充
     */
    const spawnShowcaseUnits = useCallback(() => {
        const engine = engineRef.current;
        let validHexes = (Array.from(engine.mapKeys) as string[])
            .map(k => {
                const [q, r] = k.split(',').map(Number);
                return {q, r};
            })
            .filter(h => !engine.map.hasObstacle(h.q, h.r));

        // 洗牌座標
        for (let i = validHexes.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [validHexes[i], validHexes[j]] = [validHexes[j], validHexes[i]];
        }

        let spawnIndex = 0;
        const ALL_ROLES = [Role.TANK, Role.WARRIOR, Role.RANGER, Role.MAGE, Role.SUPPORT];

        const spawnTeam = (team: Team) => {
            // 1. 強制分配五大職階
            ALL_ROLES.forEach(role => {
                if (spawnIndex < validHexes.length) {
                    const h = validHexes[spawnIndex++];
                    const stats = UNIT_DB[role];
                    const hp = stats.maxHp + Math.floor(Math.random() * 200);

                    const agent = engine.addAgent(team, h.q, h.r, hp);
                    if (agent) {
                        agent.role = role;
                        agent.maxHp = hp; agent.hp = hp;
                        agent.moveSpeed = stats.moveSpeed;
                        agent.movementType = stats.movementType;
                        agent.saveState();
                        agent.reset(engine.mapConfig);
                    }
                }
            });

            // 2. 隨機補充 1 名單位，確保總體量感
            if (spawnIndex < validHexes.length) {
                engine.addAgent(team, validHexes[spawnIndex++].q, validHexes[spawnIndex++].r, 500);
            }
        };

        spawnTeam(Team.BLUE);
        spawnTeam(Team.RED);

        engine.play();
        setIsPlaying(true);
    }, []);

    const startShowcaseMatch = useCallback(() => {
        setupShowcaseMap();
        spawnShowcaseUnits();
    }, [setupShowcaseMap, spawnShowcaseUnits]);

    useEffect(() => {
        startShowcaseMatch();
    }, [startShowcaseMatch]);

    useEffect(() => {
        const interval = setInterval(() => {
            setUnitCount(engineRef.current.agents.length);
        }, 500); 
        return () => clearInterval(interval);
    }, []);

    useEffect(() => {
        engineRef.current.timeScale = timeScale;
    }, [timeScale]);

    const enterManualMode = () => {
        setIsShowcaseMode(false);
        engineRef.current.stop();
        setIsPlaying(false);
        setWinner(null);
        engineRef.current.clear(true); 
        engineRef.current.agents = [];
        setUnitCount(0);
        setMapW(engineRef.current.mapConfig.w);
        setMapH(engineRef.current.mapConfig.h);
        setHexLayout(engineRef.current.mapConfig.layout);
        setCurrentSceneId(engineRef.current.currentScene.id);
    };

    const handleUpdateMapSize = useCallback((w: number, h: number) => {
        setMapW(w);
        setMapH(h);
        engineRef.current.mapConfig.w = w;
        engineRef.current.mapConfig.h = h;
        engineRef.current.clear(false); 
        setSelectedAgent(null);
        setWinner(null);
    }, []);

    const handleUpdateLayout = useCallback((l: HexLayout) => {
        setHexLayout(l);
        engineRef.current.mapConfig.layout = l;
        engineRef.current.clear(true); 
        setSelectedAgent(null);
        setWinner(null);
    }, []);

    const handleSetScene = useCallback((id: string) => {
        const scene = SCENE_DB.find(s => s.id === id);
        if (scene) {
            engineRef.current.currentScene = scene;
            engineRef.current.map.rebuildMap(engineRef.current);
            setCurrentSceneId(id);
        }
    }, []);

    const handleRandomBattlefield = useCallback(() => {
        const engine = engineRef.current;
        engine.stop();
        setWinner(null);
        setSelectedAgent(null);
        engine.clear(false); 

        const newLayout: HexLayout = Math.random() > 0.5 ? 'FLAT' : 'POINTY';
        engine.mapConfig.layout = newLayout;
        setHexLayout(newLayout);

        engine.randomizeEnvironment();
        setMapW(engine.mapConfig.w);
        setMapH(engine.mapConfig.h);
        setCurrentSceneId(engine.currentScene.id);

        spawnShowcaseUnits();
    }, [spawnShowcaseUnits]);

    const handleNextLevel = useCallback(() => {
        handleRandomBattlefield();
        const engine = engineRef.current;
        engine.play();
        setIsPlaying(true);
        setTool(ToolType.SELECT);
    }, [handleRandomBattlefield]);

    const handleReset = useCallback(() => {
        engineRef.current.restart();
        setIsPlaying(false); 
        setWinner(null);
    }, []);

    const togglePlay = useCallback(() => {
        if (winner !== null) return;
        if (isPlaying) {
            engineRef.current.stop();
            setIsPlaying(false);
        } else {
            const hasBlue = engineRef.current.agents.some(a => a.team === Team.BLUE);
            const hasRed = engineRef.current.agents.some(a => a.team === Team.RED);
            if (!hasBlue || !hasRed) {
                setShowFactionWarning(true);
                setTimeout(() => setShowFactionWarning(false), 2500);
                return;
            }
            engineRef.current.play();
            setIsPlaying(true);
            setTool(ToolType.SELECT);
        }
    }, [isPlaying, winner]);

    const handleSelectAgent = (a: Agent | null) => {
        setSelectedAgent(a);
    };

    return {
        engineRef,
        state: {
            isShowcaseMode, isPlaying, unitCount, tool, selectedObstacle,
            selectedAgent, hoveredSkill, hpInput, mapW, mapH, timeScale,
            winner, currentSceneId, spawnMode, draftRole, showLogs, showDB, showVFXMap,
            transitionPhase, showFactionWarning, hexLayout
        },
        setters: {
            setTool, setSelectedObstacle, setHpInput, setTimeScale, 
            setSpawnMode, setDraftRole, setShowLogs, setShowDB, setShowVFXMap,
            setIsShowcaseMode, setSelectedAgent, setHoveredSkill
        },
        actions: {
            enterManualMode,
            handleUpdateMapSize,
            handleUpdateLayout,
            handleSetScene,
            handleRandomBattlefield,
            handleNextLevel,
            handleReset,
            togglePlay,
            onWin: (team: Team) => { engineRef.current.bus.emit('GAME_OVER', {winner: team}) },
            handleSelectAgent,
            startShowcaseMatch,
            downloadSpec: DesignExporter.downloadSpec,
            rematch: () => { 
                setWinner(null); 
                engineRef.current.restart(); 
                engineRef.current.play(); 
                setIsPlaying(true); 
            }
        }
    };
};

export interface Camera {
    x: number;
    y: number;
    zoom: number;
}

/**
 * 攝像機系統 v24.0 - 動量物理版
 * 優化：加入平滑滑行 (Kinetic Panning)
 */
export class CameraSystem {
    public x: number = 0;
    public y: number = 0;
    public zoom: number = 1.0;

    private targetX: number = 0;
    private targetY: number = 0;
    private targetZoom: number = 1.0;

    // 動量物理參數
    private vx: number = 0;
    private vy: number = 0;
    private readonly MOMENTUM_FRICTION = 0.88; // 滑行阻力
    private readonly PAN_DAMPING = 15.0;       // 跟隨靈敏度
    private readonly ZOOM_DAMPING = 12.0;

    private trauma: number = 0;
    private readonly DECAY_RATE = 8.0;

    constructor() {}

    public snapTo(x: number, y: number, zoom: number) {
        this.x = this.targetX = x;
        this.y = this.targetY = y;
        this.zoom = this.targetZoom = zoom;
        this.vx = this.vy = 0;
    }

    public reset() { 
        this.trauma = 0; 
        this.vx = this.vy = 0;
    }

    public sync(camera: Camera) {
        // 更新目標位置
        this.targetX = camera.x;
        this.targetY = camera.y;
        this.targetZoom = camera.zoom;
    }

    /**
     * 應用即時位移 (由 Input 調用)
     */
    public applyPanOffset(dx: number, dy: number) {
        const factor = 1.0 / this.zoom;
        this.targetX -= dx * factor;
        this.targetY -= dy * factor;

        // 累積動量
        this.vx = -dx * factor;
        this.vy = -dy * factor;
    }

    public addTrauma(amount: number) {
        this.trauma = Math.min(1.0, this.trauma + amount);
    }

    public getTrauma(): number { return this.trauma; }

    public update(dt: number) {
        if (this.trauma > 0) {
            this.trauma = Math.max(0, this.trauma - dt * this.DECAY_RATE);
        }

        // 1. 處理滑動動量 (當沒有 active input 時)
        if (Math.abs(this.vx) > 0.1 || Math.abs(this.vy) > 0.1) {
            this.targetX += this.vx * dt * 20;
            this.targetY += this.vy * dt * 20;
            this.vx *= this.MOMENTUM_FRICTION;
            this.vy *= this.MOMENTUM_FRICTION;
        }

        // 2. 平滑追蹤目標 (Damping)
        const panT = 1 - Math.exp(-this.PAN_DAMPING * dt);
        const zoomT = 1 - Math.exp(-this.ZOOM_DAMPING * dt);

        this.x += (this.targetX - this.x) * panT;
        this.y += (this.targetY - this.y) * panT;
        this.zoom += (this.targetZoom - this.zoom) * zoomT;
    }

    public applyTransform(ctx: CanvasRenderingContext2D, width: number, height: number) {
        const cx = width / 2;
        const cy = height / 2;

        // 抖動偏移 (純邏輯層)
        let shakeX = 0, shakeY = 0;
        if (this.trauma > 0) {
            const p = this.trauma * this.trauma;
            shakeX = (Math.random() - 0.5) * 40 * p;
            shakeY = (Math.random() - 0.5) * 40 * p;
        }

        const targetTx = cx - (this.x + shakeX) * this.zoom;
        const targetTy = cy - (this.y + shakeY) * this.zoom;

        ctx.translate(Math.round(targetTx), Math.round(targetTy));
        ctx.scale(this.zoom, this.zoom);
    }
}

import { useEffect, useRef, MutableRefObject } from 'react';

interface CameraControlProps {
    canvasRef: MutableRefObject<HTMLCanvasElement | null>;
    cameraRef: MutableRefObject<{ x: number; y: number; zoom: number }>;
    onPan: (dx: number, dy: number) => void;
    onZoom: (delta: number) => void;
    engine: any; // 需要傳入 engine 以獲取物理系統
}

export const useCameraControl = ({ canvasRef, cameraRef, onPan, onZoom, engine }: CameraControlProps) => {
    const isPanning = useRef(false);
    const lastPointerPos = useRef<{x: number, y: number} | null>(null);
    const lastPinchDist = useRef<number>(0);

    useEffect(() => {
        const cvs = canvasRef.current;
        if (!cvs) return;

        const handleStart = (x: number, y: number, isRightClick: boolean) => {
            if (isRightClick) {
                isPanning.current = true;
                lastPointerPos.current = { x, y };
                cvs.style.cursor = 'move';
            }
        };

        const handleMove = (x: number, y: number) => {
            if (isPanning.current && lastPointerPos.current) {
                const dx = x - lastPointerPos.current.x;
                const dy = y - lastPointerPos.current.y;

                // 改為調用 System 層級的動量平移
                if (engine.renderer?.camera) {
                    engine.renderer.camera.applyPanOffset(dx, dy);
                    // 同步給組件層級的 Ref 以維持 UI 狀態
                    cameraRef.current.x = engine.renderer.camera.x;
                    cameraRef.current.y = engine.renderer.camera.y;
                }

                lastPointerPos.current = { x, y };
            }
        };

        const handleEnd = () => {
            if (isPanning.current) {
                isPanning.current = false;
                lastPointerPos.current = null;
                cvs.style.cursor = 'default';
            }
        };

        const onMouseDown = (e: MouseEvent) => {
            if (e.button === 2) { 
                e.preventDefault();
                handleStart(e.clientX, e.clientY, true);
            }
        };

        const onMouseMove = (e: MouseEvent) => {
            if (isPanning.current) handleMove(e.clientX, e.clientY);
        };

        const onMouseUp = () => handleEnd();
        const onWheel = (e: WheelEvent) => {
            e.preventDefault();
            const delta = e.deltaY > 0 ? -0.15 : 0.15;
            onZoom(delta);
        };

        const onTouchStart = (e: TouchEvent) => {
            if (e.touches.length === 2) {
                e.preventDefault();
                const t1 = e.touches[0];
                const t2 = e.touches[1];
                lastPinchDist.current = Math.hypot(t1.clientX - t2.clientX, t1.clientY - t2.clientY);
            }
        };

        const onTouchMove = (e: TouchEvent) => {
            if (e.touches.length === 2) {
                e.preventDefault();
                const t1 = e.touches[0];
                const t2 = e.touches[1];
                const dist = Math.hypot(t1.clientX - t2.clientX, t1.clientY - t2.clientY);
                if (lastPinchDist.current > 0) {
                    const delta = (dist - lastPinchDist.current) * 0.008;
                    onZoom(delta);
                }
                lastPinchDist.current = dist;
            }
        };

        cvs.addEventListener('mousedown', onMouseDown);
        window.addEventListener('mousemove', onMouseMove);
        window.addEventListener('mouseup', onMouseUp);
        cvs.addEventListener('wheel', onWheel, { passive: false });
        cvs.addEventListener('touchstart', onTouchStart, { passive: false });
        cvs.addEventListener('touchmove', onTouchMove, { passive: false });

        return () => {
            cvs.removeEventListener('mousedown', onMouseDown);
            window.removeEventListener('mousemove', onMouseMove);
            window.removeEventListener('mouseup', onMouseUp);
            cvs.removeEventListener('wheel', onWheel);
            cvs.removeEventListener('touchstart', onTouchStart);
            cvs.removeEventListener('touchmove', onTouchMove);
        };
    }, [canvasRef, engine]);
};

import { Particle } from "../../state";
import { VFXFactory } from "../../../../graphics/VFXFactory";

/**
 * 告示板粒子繪製器 v24.0 - 視覺降噪版
 */
export const BillboardPainter = {
    draw(ctx: CanvasRenderingContext2D, p: Particle, drawX: number, drawY: number, progress: number) {
        let img = p.image || p.texture;

        if (!img && p.type !== 'SPRITE' && p.type !== 'GENERIC_DEBUG') {
            p.image = VFXFactory.getTexture(p.type as any, p.color);
            img = p.image;
        }

        let scale = 1.0;
        let alpha = 1.0; 
        const type = p.type;

        // --- 特效清爽化修正 (Visual Balancing) ---
        if (type === 'SMOKE' || type === 'SMOKE_PUFF' || type === 'ATMOSPHERE') {
            // 縮放曲線優化：減緩末期膨脹
            const blastEase = 1 - Math.pow(1 - progress, 5);
            scale = 0.8 + blastEase * 0.5; // 從 0.6 降至 0.5

            // 淡出速度提升 (Fade speed increase)
            // 原本在 0.8 開始淡出，現在 0.7 就開始漸隱
            if (progress < 0.7) {
                alpha = 0.85; // 基礎透明度降低 10% (原 0.95)
            } else {
                // 更加陡峭的淡出曲線
                alpha = (1.0 - progress) * 3.33; // 1/0.3 = 3.33
            }
        } 
        else if (type === 'SPARK' || type === 'GLOW') {
            scale = 1.0 - (progress * 0.6); 
            alpha = Math.min(0.9, (1.0 - progress) * 3.0); 
        } 
        else if (['RUBBLE', 'ROCK', 'DEBRIS', 'SHARD', 'SPRITE'].includes(type)) {
            scale = 1.0;
            alpha = progress > 0.9 ? (1.0 - progress) * 10 : 1.0;
        } 
        else {
            scale = 1.0 - (progress * progress);
            alpha = 1.0 - progress;
        }

        if (alpha <= 0.01) return;

        ctx.save();
        ctx.translate(drawX, drawY);
        if (p.rotation) ctx.rotate(p.rotation);

        if (p.blendMode) {
            ctx.globalCompositeOperation = p.blendMode;
        } else {
            const isEnergy = (type === 'SPARK' || type === 'GLOW' || type === 'ATMOSPHERE');
            ctx.globalCompositeOperation = isEnergy ? 'screen' : 'source-over';
        }

        ctx.globalAlpha = alpha;
        const drawSize = p.size * scale;

        // 影子微調：隨透明度同步消失
        if (['RUBBLE', 'DEBRIS', 'ROCK', 'SHARD', 'SPRITE'].includes(type)) {
            ctx.save();
            ctx.globalCompositeOperation = 'multiply';
            ctx.globalAlpha = 0.4 * alpha;
            ctx.fillStyle = 'rgba(0,0,0,1)';
            ctx.beginPath(); ctx.arc(2, 4, drawSize * 0.8, 0, Math.PI*2); ctx.fill();
            ctx.restore();
        }

        if (img) {
            ctx.drawImage(img, -drawSize, -drawSize, drawSize * 2, drawSize * 2);
        } else {
            ctx.fillStyle = p.color;
            ctx.beginPath(); ctx.arc(0, 0, drawSize, 0, Math.PI*2); ctx.fill();
        }
        ctx.restore();
    }
};

import React, { useRef, useEffect, useCallback } from 'react';
import { Agent, GameEngine } from '../engine/game';
import { GameRenderer } from '../engine/renderer';
import { SpriteManager } from '../engine/sprites';
import { Team, ToolType, Skill, Role } from '../types';

// Hooks
import { useGameLoop } from '../hooks/useGameLoop';
import { useGameCamera } from '../hooks/useGameCamera';
import { useGameInput } from '../hooks/useGameInput';
import { useCameraControl } from '../hooks/useCameraControl';
import { Icons } from './ui/icons';

interface GameCanvasProps {
    engine: GameEngine;
    tool: ToolType;
    selectedObstacle: string; 
    hpInput: number;
    selectedAgent: Agent | null; 
    hoveredSkill: Skill | null;
    isShowcaseMode: boolean; 
    spawnMode: 'RANDOM' | 'DRAFT';
    draftRole: Role; 
    onSelect: (a: Agent | null) => void;
    winner: Team | null;
    rematch: () => void;
    nextLevel: () => void;
    transitionPhase: 'IDLE' | 'IN' | 'OUT';
    onOpenLogs: () => void;
}

const GameCanvas: React.FC<GameCanvasProps> = (props) => {
    const { 
        engine, tool, selectedObstacle, hpInput, selectedAgent, hoveredSkill, 
        isShowcaseMode, spawnMode, draftRole, onSelect, winner, rematch, nextLevel, transitionPhase, onOpenLogs 
    } = props;

    const canvasRef = useRef<HTMLCanvasElement>(null);
    const wrapperRef = useRef<HTMLDivElement>(null);

    // Animation State ref
    const transitionProgress = useRef(0);
    const lastPhase = useRef(transitionPhase);

    // Lifecycle: Instantiate Renderer ONCE
    const rendererRef = useRef<GameRenderer | null>(null);
    if (rendererRef.current === null) {
        rendererRef.current = new GameRenderer();
        engine.renderer = rendererRef.current;
    }

    // 1. Camera System
    const { camera, centerCamera, pan, zoom } = useGameCamera(engine);

    // 2. Camera Controls (Enhanced with engine for momentum)
    useCameraControl({
        canvasRef, 
        cameraRef: camera,
        onPan: pan,
        onZoom: zoom,
        engine // 傳入 engine 以啟用 Kinetic Panning
    });

    // 3. Input System (Game Logic Only)
    const { pressedAgent, draggedObstacle, hoveredHexRef } = useGameInput({
        canvasRef, engine, rendererRef: rendererRef as React.MutableRefObject<GameRenderer>, cameraRef: camera,
        tool, selectedObstacle, hpInput, spawnMode, draftRole, winner,
        onSelect,
        onPan: (dx, dy) => {
            // Mobile 1-finger pan also uses momentum system
            if(engine.renderer?.camera) engine.renderer.camera.applyPanOffset(dx, dy);
        }
    });

    // Reset progress when phase changes
    useEffect(() => {
        if (transitionPhase !== lastPhase.current) {
            transitionProgress.current = 0;
            lastPhase.current = transitionPhase;
        }
    }, [transitionPhase]);

    // 4. Render Handler
    const handleDraw = useCallback((ctx: CanvasRenderingContext2D, fps: number) => {
        if (!rendererRef.current) return;

        if (transitionPhase !== 'IDLE') {
            const dt = 1 / 60; 
            transitionProgress.current = Math.min(1.0, transitionProgress.current + dt * 0.8);
        } else {
            transitionProgress.current = 0;
        }

        rendererRef.current.setTransition(transitionProgress.current, transitionPhase); 
        const highlight = pressedAgent || selectedAgent || null;
        const currentHoverHex = hoveredHexRef.current;

        rendererRef.current.draw(
            ctx, 
            engine, 
            camera.current, 
            highlight, 
            fps, 
            currentHoverHex, 
            hoveredSkill
        );

        // Draw Ghost Obstacle
        if (draggedObstacle && canvasRef.current) {
            const { type, px, py } = draggedObstacle;
            const { x, y, zoom: camZoom } = camera.current;
            const dpr = window.devicePixelRatio || 1;

            ctx.save();
            ctx.scale(dpr, dpr);

            const logicalW = canvasRef.current.width / dpr;
            const logicalH = canvasRef.current.height / dpr;

            ctx.translate(logicalW / 2, logicalH / 2);
            ctx.scale(camZoom, camZoom);
            ctx.translate(-x, -y); 

            const sprite = SpriteManager.getObstacleSprite(type, engine.mapConfig.layout);
            const liftOffset = 40; 

            ctx.shadowColor = 'rgba(0,0,0,0.5)';
            ctx.shadowBlur = 30;
            ctx.shadowOffsetY = 30;
            ctx.globalAlpha = 0.9;

            ctx.drawImage(sprite, px - 32, py - 80 - liftOffset);
            ctx.restore();
        }
    }, [engine, transitionPhase, pressedAgent, selectedAgent, hoveredHexRef, hoveredSkill, draggedObstacle, camera]);

    const handleResize = useCallback((w: number, h: number) => {
        if (w > 0 && h > 0) {
            centerCamera(w, h);
        }
    }, [centerCamera]);

    // 5. Game Loop Hook
    const { fpsRef } = useGameLoop(
        engine, 
        canvasRef, 
        wrapperRef, 
        rendererRef, 
        handleDraw, 
        handleResize
    );

    // Initial Camera Center
    useEffect(() => {
        if (wrapperRef.current) {
            const t = setTimeout(() => {
                if (wrapperRef.current) {
                    centerCamera(wrapperRef.current.clientWidth, wrapperRef.current.clientHeight);
                }
            }, 100);
            return () => clearTimeout(t);
        }
    }, [engine.mapConfig.w, engine.mapConfig.h, isShowcaseMode, transitionPhase, centerCamera]);

    return (
        <div ref={wrapperRef} className="w-full h-full overflow-hidden relative bg-slate-950">
            <canvas 
                ref={canvasRef} 
                className="block w-full h-full"
                style={{ 
                    backgroundColor: engine.currentScene.background,
                    touchAction: 'none' 
                }} 
                onContextMenu={(e) => e.preventDefault()}
            />

            {winner !== null && !isShowcaseMode && (
                <div className="absolute inset-0 flex items-center justify-center bg-black/60 backdrop-blur-sm z-50 pointer-events-auto">
                    <div className="text-center p-10 liquid-glass rounded-3xl animate-bounce-in max-w-lg w-full border border-white/10 shadow-[0_0_50px_rgba(0,0,0,0.8)]">
                        <div className="mb-6">
                            <span className="text-xs font-mono font-bold tracking-[0.5em] text-slate-400 uppercase block mb-2">Simulation Complete</span>
                            <h2 className={`text-5xl md:text-6xl font-black tracking-tighter ${winner === Team.BLUE ? 'text-blue-400 drop-shadow-[0_0_30px_rgba(59,130,246,0.6)]' : 'text-red-500 drop-shadow-[0_0_30px_rgba(239,68,68,0.6)]'}`}>
                                {winner === Team.BLUE ? 'IMPERIAL' : 'COVENANT'}
                            </h2>
                            <h2 className="text-4xl md:text-5xl font-black text-white tracking-widest mt-1 opacity-90">
                                VICTORY
                            </h2>
                        </div>
                        <div className="h-px w-24 mx-auto bg-white/20 rounded-full mb-8"></div>
                        <div className="flex flex-col gap-3">
                            <button 
                                onClick={nextLevel} 
                                className="liquid-btn-primary px-8 py-4 rounded-xl text-lg font-bold shadow-lg w-full flex items-center justify-center gap-3 group"
                            >
                                <Icons.Dice className="w-5 h-5 group-hover:scale-110 transition-transform" />
                                <span>前進下一關 (Next Level)</span>
                            </button>
                            <button 
                                onClick={onOpenLogs} 
                                className="liquid-btn px-8 py-3 rounded-xl text-sm font-bold bg-slate-800/50 hover:bg-slate-700/50 border-white/10 text-cyan-400 shadow-md w-full flex items-center justify-center gap-2 group"
                            >
                                <Icons.Log className="w-4 h-4 opacity-80 group-hover:scale-110 transition-transform" />
                                <span>戰鬥記錄 (Battle Logs)</span>
                            </button>
                            <button 
                                onClick={rematch} 
                                className="liquid-btn px-8 py-3 rounded-xl text-sm font-bold bg-white/5 hover:bg-white/10 border-white/10 text-slate-300 shadow-lg w-full flex items-center justify-center gap-2 group"
                            >
                                <Icons.Restart className="w-4 h-4 opacity-70 group-hover:opacity-100 group-hover:-rotate-90 transition-all" />
                                <span>再戰一局 (Rematch)</span>
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default GameCanvas;

import { useRef, useEffect, MutableRefObject } from 'react';
import { GameEngine, Agent } from '../engine/game';
import { ToolType, Hex, Team, Role, Skill } from '../types';
import { HexUtils } from '../engine/utils';
import { GameRenderer } from '../engine/renderer';

interface GameInputProps {
    canvasRef: MutableRefObject<HTMLCanvasElement | null>;
    engine: GameEngine;
    rendererRef: MutableRefObject<GameRenderer>;
    cameraRef: MutableRefObject<{ x: number; y: number; zoom: number }>;

    // Tool State
    tool: ToolType;
    selectedObstacle: string;
    hpInput: number;
    spawnMode: 'RANDOM' | 'DRAFT';
    draftRole: Role;
    winner: Team | null;

    // Callbacks
    onSelect: (a: Agent | null) => void;
    onPan: (dx: number, dy: number) => void;
}

type InteractionMode = 'IDLE' | 'DOWN' | 'DRAG_UNIT' | 'DRAG_OBS' | 'PAINT' | 'PAN';

export const useGameInput = (props: GameInputProps) => {
    const { 
        canvasRef, engine, rendererRef, cameraRef, 
        tool, selectedObstacle, hpInput, spawnMode, draftRole, winner,
        onSelect, onPan
    } = props;

    // --- State Refs ---
    const interactionMode = useRef<InteractionMode>('IDLE');
    const pressStartPos = useRef<{x: number, y: number} | null>(null);
    const lastPanPos = useRef<{x: number, y: number} | null>(null);
    const inputSourceRef = useRef<'MOUSE' | 'TOUCH'>('MOUSE'); 
    const lastPaintHex = useRef<string>("");

    // Action Context Refs
    const pressedAgentRef = useRef<Agent | null>(null);
    const draggedObstacleRef = useRef<{ type: string; originQ: number; originR: number; px: number; py: number; } | null>(null);
    const hoveredHexRef = useRef<Hex | null>(null);

    const configRef = useRef({ tool, selectedObstacle, hpInput, spawnMode, draftRole, winner });
    useEffect(() => { configRef.current = { tool, selectedObstacle, hpInput, spawnMode, draftRole, winner }; }, [tool, selectedObstacle, hpInput, spawnMode, draftRole, winner]);

    const getHexFromCoords = (sx: number, sy: number) => {
        const rect = canvasRef.current!.getBoundingClientRect();
        return rendererRef.current.getHexAtScreenPoint(sx, sy, rect.width, rect.height, cameraRef.current, engine);
    };

    const getWorldPos = (sx: number, sy: number) => {
        const rect = canvasRef.current!.getBoundingClientRect();
        const cx = rect.width / 2;
        const cy = rect.height / 2;
        const { x: camX, y: camY, zoom } = cameraRef.current;

        const wx = (sx - cx) / zoom + camX;
        const hex = getHexFromCoords(sx, sy);
        let h = 0;
        if (hex) h = rendererRef.current.getTerrainHeight(hex.q, hex.r, engine);

        const visualWy = (sy - cy) / zoom + camY;
        return { x: wx, y: visualWy + h };
    };

    const getHitAgent = (sx: number, sy: number) => {
        const rect = canvasRef.current!.getBoundingClientRect();
        const cx = rect.width / 2;
        const cy = rect.height / 2;
        const { x: camX, y: camY, zoom } = cameraRef.current;

        const wx = (sx - cx) / zoom + camX;
        const wy = (sy - cy) / zoom + camY;

        const candidates = engine.agents.map(a => {
            if (a.hp <= 0 && a.fullyDead) return null;
            const h = rendererRef.current.getTerrainHeight(a.q, a.r, engine);
            const visualY = a.py - h - 40; 
            return { agent: a, visualY, dist: Math.abs(wy - visualY) + Math.abs(wx - a.px) };
        }).filter(Boolean) as { agent: Agent, visualY: number }[];

        candidates.sort((a, b) => b.visualY - a.visualY);

        for (const item of candidates) {
            const dx = Math.abs(wx - item.agent.px);
            const dy = wy - item.visualY; 
            if (dx < 35 && dy > -35 && dy < 40) return item.agent;
        }
        return null;
    };

    const executePaintAction = (h: Hex) => {
        const { tool, winner, selectedObstacle, spawnMode, draftRole, hpInput } = configRef.current;
        if (engine.isRunning || winner !== null) return;

        const k = HexUtils.key(h);
        if (lastPaintHex.current === k) return; 
        lastPaintHex.current = k;

        if (tool === ToolType.DELETE) {
            engine.removeObstacle(h.q, h.r);
            engine.removeAgent(h.q, h.r);
            return;
        }

        const existingAgent = engine.getAgentAt(h.q, h.r);
        if (tool === ToolType.OBSTACLE) {
            if (existingAgent) engine.removeAgent(h.q, h.r);
            engine.setObstacle(h.q, h.r, selectedObstacle);
            return;
        }

        if (!existingAgent && !engine.hasObstacle(h.q, h.r)) {
            let agent: Agent | null = null;
            if (tool === ToolType.ADD_BLUE) agent = engine.addAgent(Team.BLUE, h.q, h.r, hpInput);
            else if (tool === ToolType.ADD_RED) agent = engine.addAgent(Team.RED, h.q, h.r, hpInput);

            if (agent && spawnMode === 'DRAFT') {
                agent.role = draftRole;
                const validSkills = engine.skillDB.filter(s => s.role === agent!.role && (s.team === undefined || s.team === agent!.team));
                const rnd = (ar: Skill[]) => ar.length > 0 ? ar[Math.floor(Math.random() * ar.length)].id : null;
                agent.skillIds = [
                    rnd(validSkills.filter(s => s.tag === 'ULT')),
                    rnd(validSkills.filter(s => s.tag === 'ACTIVE')),
                    rnd(validSkills.filter(s => s.tag === 'BASIC'))
                ];
                agent.saveState();
                agent.reset(engine.mapConfig);
            }
        }
    };

    const handleInputStart = (sx: number, sy: number) => {
        pressStartPos.current = { x: sx, y: sy };
        lastPaintHex.current = "";

        const hitAgent = getHitAgent(sx, sy);
        if (hitAgent) {
            pressedAgentRef.current = hitAgent;
            interactionMode.current = 'DOWN';
            return;
        }

        const { tool, winner } = configRef.current;
        const isEditing = !engine.isRunning && winner === null;
        const h = getHexFromCoords(sx, sy);
        const hasHex = h && engine.isValid(h.q, h.r);

        if (isEditing && hasHex) {
            if (tool === ToolType.SELECT && engine.hasObstacle(h!.q, h!.r)) {
                const obsType = engine.map.obstacles.get(HexUtils.key(h!));
                if (obsType) {
                    draggedObstacleRef.current = { type: obsType, originQ: h!.q, originR: h!.r, px: 0, py: 0 };
                    interactionMode.current = 'DOWN';
                    return;
                }
            }
            if (tool !== ToolType.SELECT) {
                executePaintAction(h!);
                interactionMode.current = 'PAINT';
                return;
            }
        }

        interactionMode.current = 'DOWN';
    };

    const handleInputMove = (sx: number, sy: number) => {
        const cvs = canvasRef.current;
        const h = getHexFromCoords(sx, sy);
        hoveredHexRef.current = (h && engine.isValid(h.q, h.r)) ? h : null;

        if (cvs) {
            const { tool, winner } = configRef.current;
            const isEditing = !engine.isRunning && winner === null;
            const hitAgent = getHitAgent(sx, sy);

            if (interactionMode.current === 'DRAG_UNIT' || interactionMode.current === 'DRAG_OBS') cvs.style.cursor = 'grabbing';
            else if (isEditing && tool !== ToolType.SELECT) cvs.style.cursor = 'crosshair';
            else if (hitAgent) cvs.style.cursor = 'pointer';
            else if (interactionMode.current === 'PAN') cvs.style.cursor = 'move';
            else cvs.style.cursor = 'default';
        }

        if (interactionMode.current === 'IDLE') return;

        if (interactionMode.current === 'PAINT') {
            if (h && engine.isValid(h.q, h.r)) executePaintAction(h);
            return;
        }
        if (interactionMode.current === 'PAN') {
            if (lastPanPos.current) {
                const dx = sx - lastPanPos.current.x;
                const dy = sy - lastPanPos.current.y;
                onPan(dx, dy);
            }
            lastPanPos.current = { x: sx, y: sy };
            return;
        }
        if (interactionMode.current === 'DRAG_UNIT' && pressedAgentRef.current) {
            const wPos = getWorldPos(sx, sy);
            pressedAgentRef.current.px = wPos.x;
            pressedAgentRef.current.py = wPos.y;
            return;
        }
        if (interactionMode.current === 'DRAG_OBS' && draggedObstacleRef.current) {
            const wPos = getWorldPos(sx, sy);
            draggedObstacleRef.current.px = wPos.x;
            draggedObstacleRef.current.py = wPos.y;
            return;
        }

        if (interactionMode.current === 'DOWN' && pressStartPos.current) {
            const dist = Math.hypot(sx - pressStartPos.current.x, sy - pressStartPos.current.y);
            if (dist > 8) {
                const { tool, winner } = configRef.current;
                const isEditing = !engine.isRunning && winner === null;

                if (isEditing && pressedAgentRef.current && tool === ToolType.SELECT) {
                    interactionMode.current = 'DRAG_UNIT';
                    pressedAgentRef.current.physics.z = 20; 
                    onSelect(pressedAgentRef.current);
                } else if (isEditing && draggedObstacleRef.current && tool === ToolType.SELECT) {
                    interactionMode.current = 'DRAG_OBS';
                    const { originQ, originR } = draggedObstacleRef.current;
                    engine.removeObstacle(originQ, originR); 
                    const wPos = getWorldPos(sx, sy);
                    draggedObstacleRef.current.px = wPos.x;
                    draggedObstacleRef.current.py = wPos.y;
                } else {
                    // Unified PAN Protocol: Left-Click on empty ground now triggers panning on PC
                    interactionMode.current = 'PAN';
                    lastPanPos.current = { x: sx, y: sy };
                }
            }
        }
    };

    const handleInputEnd = (sx: number, sy: number) => {
        const { tool, winner } = configRef.current;
        const isEditing = !engine.isRunning && winner === null;
        const h = getHexFromCoords(sx, sy);

        if (interactionMode.current === 'DOWN') {
            if (pressedAgentRef.current) {
                if (isEditing && tool === ToolType.DELETE) {
                    engine.removeAgent(pressedAgentRef.current.q, pressedAgentRef.current.r);
                    onSelect(null);
                } else {
                    onSelect(pressedAgentRef.current);
                }
            } else if (isEditing && h && engine.hasObstacle(h.q, h.r) && tool === ToolType.DELETE) {
                engine.removeObstacle(h.q, h.r);
            } else if (!pressedAgentRef.current) {
                onSelect(null);
            }
        }

        if (interactionMode.current === 'DRAG_UNIT' && pressedAgentRef.current) {
            const agent = pressedAgentRef.current;
            agent.physics.z = 0;
            const valid = h && engine.isValid(h.q, h.r) && !engine.isBlocked(h.q, h.r, agent.id, agent.movementType);

            if (valid && h) {
                engine.updateAgentPosition(agent, h.q, h.r);
                const p = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                agent.px = p.x; agent.py = p.y;
            } else {
                const p = HexUtils.toPx(agent.q, agent.r, engine.mapConfig);
                agent.px = p.x; agent.py = p.y;
            }
            onSelect(agent);
        }

        if (interactionMode.current === 'DRAG_OBS' && draggedObstacleRef.current) {
            const { type, originQ, originR } = draggedObstacleRef.current;
            const valid = h && engine.isValid(h.q, h.r) && !engine.getAgentAt(h.q, h.r) && !engine.hasObstacle(h.q, h.r);
            if (valid && h) engine.setObstacle(h.q, h.r, type);
            else engine.setObstacle(originQ, originR, type);
        }

        interactionMode.current = 'IDLE';
        pressedAgentRef.current = null;
        draggedObstacleRef.current = null;
        pressStartPos.current = null;
        lastPanPos.current = null;
    };

    useEffect(() => {
        const cvs = canvasRef.current;
        if (!cvs) return;

        const onMouseDown = (e: MouseEvent) => {
            if (e.button !== 0) return;
            inputSourceRef.current = 'MOUSE';
            const rect = cvs.getBoundingClientRect();
            handleInputStart(e.clientX - rect.left, e.clientY - rect.top);
        };
        const onMouseMove = (e: MouseEvent) => {
            const rect = cvs.getBoundingClientRect();
            handleInputMove(e.clientX - rect.left, e.clientY - rect.top);
        };
        const onMouseUp = (e: MouseEvent) => {
            const rect = cvs.getBoundingClientRect();
            handleInputEnd(e.clientX - rect.left, e.clientY - rect.top);
        };
        const onCtx = (e: MouseEvent) => e.preventDefault();

        const getTouchPos = (t: Touch) => {
            const rect = cvs.getBoundingClientRect();
            return { x: t.clientX - rect.left, y: t.clientY - rect.top };
        };
        const onTouchStart = (e: TouchEvent) => {
            if (e.touches.length === 1) {
                inputSourceRef.current = 'TOUCH';
                const { x, y } = getTouchPos(e.touches[0]);
                handleInputStart(x, y);
            }
        };
        const onTouchMove = (e: TouchEvent) => {
            if (e.touches.length === 1) {
                const { x, y } = getTouchPos(e.touches[0]);
                handleInputMove(x, y);
            }
        };
        const onTouchEnd = (e: TouchEvent) => {
            if (e.changedTouches.length > 0 && e.touches.length === 0) {
                const { x, y } = getTouchPos(e.changedTouches[0]);
                handleInputEnd(x, y);
            }
        };

        cvs.addEventListener('mousedown', onMouseDown);
        window.addEventListener('mousemove', onMouseMove);
        window.addEventListener('mouseup', onMouseUp);
        cvs.addEventListener('contextmenu', onCtx);
        cvs.addEventListener('touchstart', onTouchStart, { passive: false });
        cvs.addEventListener('touchmove', onTouchMove, { passive: false });
        cvs.addEventListener('touchend', onTouchEnd, { passive: false });

        return () => {
            cvs.removeEventListener('mousedown', onMouseDown);
            window.removeEventListener('mousemove', onMouseMove);
            window.removeEventListener('mouseup', onMouseUp);
            cvs.removeEventListener('contextmenu', onCtx);
            cvs.removeEventListener('touchstart', onTouchStart);
            cvs.removeEventListener('touchmove', onTouchMove);
            cvs.removeEventListener('touchend', onTouchEnd);
        };
    }, []);

    return {
        pressedAgent: pressedAgentRef.current,
        draggedObstacle: draggedObstacleRef.current,
        hoveredHexRef: hoveredHexRef
    };
};

import { Particle } from "../../state";
import { VFXFactory } from "../../../../graphics/VFXFactory";

/**
 * 告示板粒子繪製器 v24.1 - 視覺清爽化版
 */
export const BillboardPainter = {
    draw(ctx: CanvasRenderingContext2D, p: Particle, drawX: number, drawY: number, progress: number) {
        let img = p.image || p.texture;

        if (!img && p.type !== 'SPRITE' && p.type !== 'GENERIC_DEBUG') {
            p.image = VFXFactory.getTexture(p.type as any, p.color);
            img = p.image;
        }

        let scale = 1.0;
        let alpha = 1.0; 
        const type = p.type;

        // --- 特效清爽化修正 (Visual Balancing v24.1) ---
        if (type === 'SMOKE' || type === 'SMOKE_PUFF' || type === 'ATMOSPHERE') {
            const blastEase = 1 - Math.pow(1 - progress, 5);
            scale = 0.8 + blastEase * 0.5; 

            // 基礎透明度降低至 0.75 (符合減少 10% 要求)
            // 淡出啟動點提前至 0.65 (加速 10%)
            if (progress < 0.65) {
                alpha = 0.75; 
            } else {
                // 陡峭淡出曲線：(1.0 - 0.65) = 0.35, 1/0.35 ≈ 2.85
                alpha = (1.0 - progress) * 2.85; 
            }
        } 
        else if (type === 'SPARK' || type === 'GLOW') {
            scale = 1.0 - (progress * 0.6); 
            alpha = Math.min(0.9, (1.0 - progress) * 3.0); 
        } 
        else if (['RUBBLE', 'ROCK', 'DEBRIS', 'SHARD', 'SPRITE'].includes(type)) {
            scale = 1.0;
            alpha = progress > 0.9 ? (1.0 - progress) * 10 : 1.0;
        } 
        else {
            scale = 1.0 - (progress * progress);
            alpha = 1.0 - progress;
        }

        if (alpha <= 0.01) return;

        ctx.save();
        ctx.translate(drawX, drawY);
        if (p.rotation) ctx.rotate(p.rotation);

        if (p.blendMode) {
            ctx.globalCompositeOperation = p.blendMode;
        } else {
            const isEnergy = (type === 'SPARK' || type === 'GLOW' || type === 'ATMOSPHERE');
            ctx.globalCompositeOperation = isEnergy ? 'screen' : 'source-over';
        }

        ctx.globalAlpha = alpha;
        const drawSize = p.size * scale;

        if (['RUBBLE', 'DEBRIS', 'ROCK', 'SHARD', 'SPRITE'].includes(type)) {
            ctx.save();
            ctx.globalCompositeOperation = 'multiply';
            ctx.globalAlpha = 0.4 * alpha;
            ctx.fillStyle = 'rgba(0,0,0,1)';
            ctx.beginPath(); ctx.arc(2, 4, drawSize * 0.8, 0, Math.PI*2); ctx.fill();
            ctx.restore();
        }

        if (img) {
            ctx.drawImage(img, -drawSize, -drawSize, drawSize * 2, drawSize * 2);
        } else {
            ctx.fillStyle = p.color;
            ctx.beginPath(); ctx.arc(0, 0, drawSize, 0, Math.PI*2); ctx.fill();
        }
        ctx.restore();
    }
};

import { useEffect, useRef, MutableRefObject } from 'react';

interface CameraControlProps {
    canvasRef: MutableRefObject<HTMLCanvasElement | null>;
    cameraRef: MutableRefObject<{ x: number; y: number; zoom: number }>;
    onPan: (dx: number, dy: number) => void;
    onZoom: (delta: number) => void;
    engine: any;
}

/**
 * 攝像機交互控制器 v25.0
 * 僅保留縮放功能，平移邏輯已整合至 useGameInput 以解決 PC 上的左鍵拖曳衝突
 */
export const useCameraControl = ({ canvasRef, cameraRef, onPan, onZoom, engine }: CameraControlProps) => {
    const lastPinchDist = useRef<number>(0);

    useEffect(() => {
        const cvs = canvasRef.current;
        if (!cvs) return;

        const onWheel = (e: WheelEvent) => {
            e.preventDefault();
            // 縮放不受平移衝突影響
            const delta = e.deltaY > 0 ? -0.15 : 0.15;
            onZoom(delta);
        };

        const onTouchStart = (e: TouchEvent) => {
            if (e.touches.length === 2) {
                e.preventDefault();
                const t1 = e.touches[0];
                const t2 = e.touches[1];
                lastPinchDist.current = Math.hypot(t1.clientX - t2.clientX, t1.clientY - t2.clientY);
            }
        };

        const onTouchMove = (e: TouchEvent) => {
            if (e.touches.length === 2) {
                e.preventDefault();
                const t1 = e.touches[0];
                const t2 = e.touches[1];
                const dist = Math.hypot(t1.clientX - t2.clientX, t1.clientY - t2.clientY);
                if (lastPinchDist.current > 0) {
                    const delta = (dist - lastPinchDist.current) * 0.008;
                    onZoom(delta);
                }
                lastPinchDist.current = dist;
            }
        };

        cvs.addEventListener('wheel', onWheel, { passive: false });
        cvs.addEventListener('touchstart', onTouchStart, { passive: false });
        cvs.addEventListener('touchmove', onTouchMove, { passive: false });

        return () => {
            cvs.removeEventListener('wheel', onWheel);
            cvs.removeEventListener('touchstart', onTouchStart);
            cvs.removeEventListener('touchmove', onTouchMove);
        };
    }, [canvasRef, onZoom]);
};

import { useRef, useEffect, MutableRefObject } from 'react';
import { GameEngine, Agent } from '../engine/game';
import { ToolType, Hex, Team, Role, Skill } from '../types';
import { HexUtils } from '../engine/utils';
import { GameRenderer } from '../engine/renderer';

interface GameInputProps {
    canvasRef: MutableRefObject<HTMLCanvasElement | null>;
    engine: GameEngine;
    rendererRef: MutableRefObject<GameRenderer>;
    cameraRef: MutableRefObject<{ x: number; y: number; zoom: number }>;

    tool: ToolType;
    selectedObstacle: string;
    hpInput: number;
    spawnMode: 'RANDOM' | 'DRAFT';
    draftRole: Role;
    winner: Team | null;

    onSelect: (a: Agent | null) => void;
    onPan: (dx: number, dy: number) => void;
}

type InteractionMode = 'IDLE' | 'DOWN' | 'DRAG_UNIT' | 'DRAG_OBS' | 'PAINT' | 'PAN';

export const useGameInput = (props: GameInputProps) => {
    const { 
        canvasRef, engine, rendererRef, cameraRef, 
        tool, selectedObstacle, hpInput, spawnMode, draftRole, winner,
        onSelect, onPan
    } = props;

    const interactionMode = useRef<InteractionMode>('IDLE');
    const pressStartPos = useRef<{x: number, y: number} | null>(null);
    const lastPanPos = useRef<{x: number, y: number} | null>(null);
    const lastPaintHex = useRef<string>("");
    const pressedAgentRef = useRef<Agent | null>(null);
    const draggedObstacleRef = useRef<any>(null);
    const hoveredHexRef = useRef<Hex | null>(null);

    const configRef = useRef({ tool, selectedObstacle, hpInput, spawnMode, draftRole, winner });
    useEffect(() => { configRef.current = { tool, selectedObstacle, hpInput, spawnMode, draftRole, winner }; }, [tool, selectedObstacle, hpInput, spawnMode, draftRole, winner]);

    const getHexFromCoords = (sx: number, sy: number) => {
        if (!canvasRef.current || !rendererRef.current) return null;
        const rect = canvasRef.current.getBoundingClientRect();
        return rendererRef.current.getHexAtScreenPoint(sx, sy, rect.width, rect.height, cameraRef.current, engine);
    };

    const getWorldPos = (sx: number, sy: number) => {
        const rect = canvasRef.current!.getBoundingClientRect();
        const cx = rect.width / 2;
        const cy = rect.height / 2;
        const { x: camX, y: camY, zoom } = cameraRef.current;
        const wx = (sx - cx) / zoom + camX;
        const hex = getHexFromCoords(sx, sy);
        let h = 0;
        if (hex) h = rendererRef.current.getTerrainHeight(hex.q, hex.r, engine);
        const visualWy = (sy - cy) / zoom + camY;
        return { x: wx, y: visualWy + h };
    };

    const getHitAgent = (sx: number, sy: number) => {
        if (!canvasRef.current) return null;
        const rect = canvasRef.current.getBoundingClientRect();
        const cx = rect.width / 2;
        const cy = rect.height / 2;
        const { x: camX, y: camY, zoom } = cameraRef.current;
        const wx = (sx - cx) / zoom + camX;
        const wy = (sy - cy) / zoom + camY;

        const candidates = engine.agents.map(a => {
            if (a.hp <= 0 && a.fullyDead) return null;
            const h = rendererRef.current.getTerrainHeight(a.q, a.r, engine);
            const visualY = a.py - h - 40; 
            return { agent: a, visualY };
        }).filter(Boolean) as { agent: Agent, visualY: number }[];

        candidates.sort((a, b) => b.visualY - a.visualY);
        for (const item of candidates) {
            const dx = Math.abs(wx - item.agent.px);
            const dy = wy - item.visualY; 
            if (dx < 35 && dy > -35 && dy < 40) return item.agent;
        }
        return null;
    };

    const handleInputStart = (sx: number, sy: number) => {
        pressStartPos.current = { x: sx, y: sy };
        lastPaintHex.current = "";

        const hitAgent = getHitAgent(sx, sy);
        if (hitAgent) {
            pressedAgentRef.current = hitAgent;
            interactionMode.current = 'DOWN';
            return;
        }

        const { tool, winner } = configRef.current;
        const isEditing = !engine.isRunning && winner === null;
        const h = getHexFromCoords(sx, sy);

        if (isEditing && h && engine.isValid(h.q, h.r)) {
            if (tool === ToolType.SELECT && engine.hasObstacle(h!.q, h!.r)) {
                const obsType = engine.map.obstacles.get(HexUtils.key(h!));
                if (obsType) {
                    draggedObstacleRef.current = { type: obsType, originQ: h!.q, originR: h!.r, px: 0, py: 0 };
                    interactionMode.current = 'DOWN';
                    return;
                }
            }
            if (tool !== ToolType.SELECT) {
                interactionMode.current = 'PAINT';
                // Paint initial hex
                const hex = getHexFromCoords(sx, sy);
                if (hex) executePaintAction(hex);
                return;
            }
        }

        interactionMode.current = 'DOWN';
    };

    const executePaintAction = (h: Hex) => {
        const { tool, winner, selectedObstacle, spawnMode, draftRole, hpInput } = configRef.current;
        if (engine.isRunning || winner !== null) return;
        const k = HexUtils.key(h);
        if (lastPaintHex.current === k) return; 
        lastPaintHex.current = k;

        if (tool === ToolType.DELETE) {
            engine.removeObstacle(h.q, h.r);
            engine.removeAgent(h.q, h.r);
        } else if (tool === ToolType.OBSTACLE) {
            engine.removeAgent(h.q, h.r);
            engine.setObstacle(h.q, h.r, selectedObstacle);
        } else {
            const existing = engine.getAgentAt(h.q, h.r);
            if (!existing && !engine.hasObstacle(h.q, h.r)) {
                let agent: Agent | null = null;
                if (tool === ToolType.ADD_BLUE) agent = engine.addAgent(Team.BLUE, h.q, h.r, hpInput);
                else if (tool === ToolType.ADD_RED) agent = engine.addAgent(Team.RED, h.q, h.r, hpInput);
                if (agent && spawnMode === 'DRAFT') {
                    agent.role = draftRole;
                    agent.saveState();
                    agent.reset(engine.mapConfig);
                }
            }
        }
    };

    const handleInputMove = (sx: number, sy: number) => {
        const cvs = canvasRef.current;
        if (!cvs) return;
        const h = getHexFromCoords(sx, sy);
        hoveredHexRef.current = (h && engine.isValid(h.q, h.r)) ? h : null;

        if (interactionMode.current === 'PAINT' && h && engine.isValid(h.q, h.r)) {
            executePaintAction(h);
            return;
        }

        if (interactionMode.current === 'PAN') {
            if (lastPanPos.current) {
                const dx = sx - lastPanPos.current.x;
                const dy = sy - lastPanPos.current.y;
                // 直接使用物理系統的偏移，解決「強制拉回」
                if (engine.renderer?.camera) {
                    engine.renderer.camera.applyPanOffset(dx, dy);
                    cameraRef.current.x = engine.renderer.camera.x;
                    cameraRef.current.y = engine.renderer.camera.y;
                }
            }
            lastPanPos.current = { x: sx, y: sy };
            return;
        }

        if (interactionMode.current === 'DRAG_UNIT' && pressedAgentRef.current) {
            const wPos = getWorldPos(sx, sy);
            pressedAgentRef.current.px = wPos.x;
            pressedAgentRef.current.py = wPos.y;
            return;
        }

        if (interactionMode.current === 'DRAG_OBS' && draggedObstacleRef.current) {
            const wPos = getWorldPos(sx, sy);
            draggedObstacleRef.current.px = wPos.x;
            draggedObstacleRef.current.py = wPos.y;
            return;
        }

        if (interactionMode.current === 'DOWN' && pressStartPos.current) {
            const dist = Math.hypot(sx - pressStartPos.current.x, sy - pressStartPos.current.y);
            if (dist > 5) {
                const { tool, winner } = configRef.current;
                const isEditing = !engine.isRunning && winner === null;
                if (isEditing && pressedAgentRef.current && tool === ToolType.SELECT) {
                    interactionMode.current = 'DRAG_UNIT';
                    pressedAgentRef.current.physics.z = 20; 
                    onSelect(pressedAgentRef.current);
                } else if (isEditing && draggedObstacleRef.current && tool === ToolType.SELECT) {
                    interactionMode.current = 'DRAG_OBS';
                    engine.removeObstacle(draggedObstacleRef.current.originQ, draggedObstacleRef.current.originR); 
                } else {
                    interactionMode.current = 'PAN';
                    lastPanPos.current = { x: sx, y: sy };
                    cvs.style.cursor = 'move';
                }
            }
        }
    };

    const handleInputEnd = (sx: number, sy: number) => {
        const { tool, winner } = configRef.current;
        const isEditing = !engine.isRunning && winner === null;
        const h = getHexFromCoords(sx, sy);

        if (interactionMode.current === 'DOWN') {
            if (pressedAgentRef.current) {
                if (isEditing && tool === ToolType.DELETE) engine.removeAgent(pressedAgentRef.current.q, pressedAgentRef.current.r);
                onSelect(pressedAgentRef.current);
            } else if (!pressedAgentRef.current) {
                onSelect(null);
            }
        }

        if (interactionMode.current === 'DRAG_UNIT' && pressedAgentRef.current) {
            const agent = pressedAgentRef.current;
            agent.physics.z = 0;
            const valid = h && engine.isValid(h.q, h.r) && !engine.isBlocked(h.q, h.r, agent.id, agent.movementType);
            if (valid && h) {
                engine.updateAgentPosition(agent, h.q, h.r);
                const p = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                agent.px = p.x; agent.py = p.y;
            } else {
                const p = HexUtils.toPx(agent.q, agent.r, engine.mapConfig);
                agent.px = p.x; agent.py = p.y;
            }
            onSelect(agent);
        }

        if (interactionMode.current === 'DRAG_OBS' && draggedObstacleRef.current) {
            const { type, originQ, originR } = draggedObstacleRef.current;
            const valid = h && engine.isValid(h.q, h.r) && !engine.getAgentAt(h.q, h.r) && !engine.hasObstacle(h.q, h.r);
            if (valid && h) engine.setObstacle(h.q, h.r, type);
            else engine.setObstacle(originQ, originR, type);
        }

        interactionMode.current = 'IDLE';
        pressedAgentRef.current = null;
        draggedObstacleRef.current = null;
        pressStartPos.current = null;
        lastPanPos.current = null;
        if (canvasRef.current) canvasRef.current.style.cursor = 'default';
    };

    useEffect(() => {
        const cvs = canvasRef.current;
        if (!cvs) return;

        const onMouseDown = (e: MouseEvent) => {
            if (e.button !== 0) return; // 只處理左鍵
            const rect = cvs.getBoundingClientRect();
            handleInputStart(e.clientX - rect.left, e.clientY - rect.top);
        };
        const onMouseMove = (e: MouseEvent) => {
            const rect = cvs.getBoundingClientRect();
            handleInputMove(e.clientX - rect.left, e.clientY - rect.top);
        };
        const onMouseUp = (e: MouseEvent) => {
            const rect = cvs.getBoundingClientRect();
            handleInputEnd(e.clientX - rect.left, e.clientY - rect.top);
        };

        cvs.addEventListener('mousedown', onMouseDown);
        window.addEventListener('mousemove', onMouseMove);
        window.addEventListener('mouseup', onMouseUp);

        return () => {
            cvs.removeEventListener('mousedown', onMouseDown);
            window.removeEventListener('mousemove', onMouseMove);
            window.removeEventListener('mouseup', onMouseUp);
        };
    }, []);

    return {
        pressedAgent: pressedAgentRef.current,
        draggedObstacle: draggedObstacleRef.current,
        hoveredHexRef
    };
};

