export default GameCanvas;

import { useRef, useEffect, MutableRefObject } from 'react';
import { GameEngine, Agent } from '../engine/game';
import { ToolType, Hex, Team, Role, Skill } from '../types';
import { HexUtils } from '../engine/utils';
import { GameRenderer } from '../engine/renderer';

interface GameInputProps {
    canvasRef: MutableRefObject<HTMLCanvasElement | null>;
    engine: GameEngine;
    rendererRef: MutableRefObject<GameRenderer>;
    cameraRef: MutableRefObject<{ x: number; y: number; zoom: number }>;

    tool: ToolType;
    selectedObstacle: string;
    hpInput: number;
    spawnMode: 'RANDOM' | 'DRAFT';
    draftRole: Role;
    winner: Team | null;

    onSelect: (a: Agent | null) => void;
    onPan: (dx: number, dy: number) => void;
}

type InteractionMode = 'IDLE' | 'DOWN' | 'DRAG_UNIT' | 'DRAG_OBS' | 'PAINT' | 'PAN';

/**
 * 遊戲輸入控制器 v27.0 - 物理同步版
 * 全面採用 Pointer Events 以確保 PC 左鍵拖曳的極致平滑
 */
export const useGameInput = (props: GameInputProps) => {
    const { 
        canvasRef, engine, rendererRef, cameraRef, 
        tool, selectedObstacle, hpInput, spawnMode, draftRole, winner,
        onSelect
    } = props;

    const interactionMode = useRef<InteractionMode>('IDLE');
    const lastPointerPos = useRef<{x: number, y: number} | null>(null);
    const pressStartPos = useRef<{x: number, y: number} | null>(null);
    const lastPaintHex = useRef<string>("");

    const pressedAgentRef = useRef<Agent | null>(null);
    const draggedObstacleRef = useRef<any>(null);
    const hoveredHexRef = useRef<Hex | null>(null);

    const configRef = useRef({ tool, selectedObstacle, hpInput, spawnMode, draftRole, winner });
    useEffect(() => { configRef.current = { tool, selectedObstacle, hpInput, spawnMode, draftRole, winner }; }, [tool, selectedObstacle, hpInput, spawnMode, draftRole, winner]);

    const getHexFromCoords = (sx: number, sy: number) => {
        if (!canvasRef.current || !rendererRef.current) return null;
        const rect = canvasRef.current.getBoundingClientRect();
        return rendererRef.current.getHexAtScreenPoint(sx, sy, rect.width, rect.height, cameraRef.current, engine);
    };

    const getHitAgent = (sx: number, sy: number) => {
        if (!canvasRef.current) return null;
        const rect = canvasRef.current.getBoundingClientRect();
        const cx = rect.width / 2;
        const cy = rect.height / 2;
        const { x: camX, y: camY, zoom } = cameraRef.current;
        const wx = (sx - cx) / zoom + camX;
        const wy = (sy - cy) / zoom + camY;

        const candidates = engine.agents.map(a => {
            if (a.hp <= 0 && a.fullyDead) return null;
            const h = rendererRef.current.getTerrainHeight(a.q, a.r, engine);
            const visualY = a.py - h - 40; 
            return { agent: a, visualY };
        }).filter(Boolean) as { agent: Agent, visualY: number }[];

        candidates.sort((a, b) => b.visualY - a.visualY);
        for (const item of candidates) {
            const dx = Math.abs(wx - item.agent.px);
            const dy = wy - item.visualY; 
            if (dx < 35 && dy > -35 && dy < 40) return item.agent;
        }
        return null;
    };

    const executePaintAction = (h: Hex) => {
        const { tool, winner, selectedObstacle, spawnMode, draftRole, hpInput } = configRef.current;
        if (engine.isRunning || winner !== null) return;
        const k = HexUtils.key(h);
        if (lastPaintHex.current === k) return; 
        lastPaintHex.current = k;

        if (tool === ToolType.DELETE) {
            engine.removeObstacle(h.q, h.r);
            engine.removeAgent(h.q, h.r);
        } else if (tool === ToolType.OBSTACLE) {
            engine.removeAgent(h.q, h.r);
            engine.setObstacle(h.q, h.r, selectedObstacle);
        } else {
            const existing = engine.getAgentAt(h.q, h.r);
            if (!existing && !engine.hasObstacle(h.q, h.r)) {
                let agent: Agent | null = null;
                if (tool === ToolType.ADD_BLUE) agent = engine.addAgent(Team.BLUE, h.q, h.r, hpInput);
                else if (tool === ToolType.ADD_RED) agent = engine.addAgent(Team.RED, h.q, h.r, hpInput);
                if (agent && spawnMode === 'DRAFT') {
                    agent.role = draftRole;
                    agent.saveState();
                    agent.reset(engine.mapConfig);
                }
            }
        }
    };

    const handlePointerDown = (e: PointerEvent) => {
        if (e.button !== 0) return; // Only Left Click
        const cvs = canvasRef.current;
        if (!cvs) return;

        const rect = cvs.getBoundingClientRect();
        const sx = e.clientX - rect.left;
        const sy = e.clientY - rect.top;

        pressStartPos.current = { x: sx, y: sy };
        lastPointerPos.current = { x: sx, y: sy };
        lastPaintHex.current = "";

        const hitAgent = getHitAgent(sx, sy);
        if (hitAgent) {
            pressedAgentRef.current = hitAgent;
        } else {
            const { tool, winner } = configRef.current;
            const h = getHexFromCoords(sx, sy);
            if (!engine.isRunning && winner === null && h && engine.isValid(h.q, h.r)) {
                if (tool === ToolType.SELECT && engine.hasObstacle(h.q, h.r)) {
                    draggedObstacleRef.current = { type: engine.map.obstacles.get(HexUtils.key(h)), originQ: h.q, originR: h.r, px: 0, py: 0 };
                } else if (tool !== ToolType.SELECT) {
                    interactionMode.current = 'PAINT';
                    executePaintAction(h);
                }
            }
        }

        if (interactionMode.current === 'IDLE') interactionMode.current = 'DOWN';
        cvs.setPointerCapture(e.pointerId);
    };

    const handlePointerMove = (e: PointerEvent) => {
        const cvs = canvasRef.current;
        if (!cvs || !lastPointerPos.current) return;

        const rect = cvs.getBoundingClientRect();
        const sx = e.clientX - rect.left;
        const sy = e.clientY - rect.top;

        const dx = sx - lastPointerPos.current.x;
        const dy = sy - lastPointerPos.current.y;

        const h = getHexFromCoords(sx, sy);
        hoveredHexRef.current = (h && engine.isValid(h.q, h.r)) ? h : null;

        // Mode Switch
        if (interactionMode.current === 'DOWN' && pressStartPos.current) {
            const dist = Math.hypot(sx - pressStartPos.current.x, sy - pressStartPos.current.y);
            if (dist > 5) {
                const { tool, winner } = configRef.current;
                if (!engine.isRunning && winner === null && tool === ToolType.SELECT) {
                    if (pressedAgentRef.current) {
                        interactionMode.current = 'DRAG_UNIT';
                        pressedAgentRef.current.physics.z = 20;
                        onSelect(pressedAgentRef.current);
                    } else if (draggedObstacleRef.current) {
                        interactionMode.current = 'DRAG_OBS';
                        engine.removeObstacle(draggedObstacleRef.current.originQ, draggedObstacleRef.current.originR);
                    } else {
                        interactionMode.current = 'PAN';
                    }
                } else {
                    interactionMode.current = 'PAN';
                }
            }
        }

        // Logic Execution
        if (interactionMode.current === 'PAN') {
            if (engine.renderer?.camera) {
                engine.renderer.camera.applyPanOffset(dx, dy);
            }
            cvs.style.cursor = 'move';
        } else if (interactionMode.current === 'PAINT' && h) {
            executePaintAction(h);
        } else if (interactionMode.current === 'DRAG_UNIT' && pressedAgentRef.current) {
            const { x: camX, y: camY, zoom } = cameraRef.current;
            const cx = rect.width / 2;
            const cy = rect.height / 2;
            const terrainH = h ? rendererRef.current.getTerrainHeight(h.q, h.r, engine) : 0;
            pressedAgentRef.current.px = (sx - cx) / zoom + camX;
            pressedAgentRef.current.py = (sy - cy) / zoom + camY + terrainH;
            cvs.style.cursor = 'grabbing';
        }

        lastPointerPos.current = { x: sx, y: sy };
    };

    const handlePointerUp = (e: PointerEvent) => {
        const cvs = canvasRef.current;
        if (!cvs) return;

        const rect = cvs.getBoundingClientRect();
        const sx = e.clientX - rect.left;
        const sy = e.clientY - rect.top;
        const h = getHexFromCoords(sx, sy);

        if (interactionMode.current === 'DOWN') {
            if (pressedAgentRef.current) {
                if (!engine.isRunning && configRef.current.tool === ToolType.DELETE) {
                    engine.removeAgent(pressedAgentRef.current.q, pressedAgentRef.current.r);
                }
                onSelect(pressedAgentRef.current);
            } else {
                onSelect(null);
            }
        } else if (interactionMode.current === 'DRAG_UNIT' && pressedAgentRef.current) {
            const a = pressedAgentRef.current;
            a.physics.z = 0;
            if (h && engine.isValid(h.q, h.r) && !engine.isBlocked(h.q, h.r, a.id, a.movementType)) {
                engine.updateAgentPosition(a, h.q, h.r);
                const p = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                a.px = p.x; a.py = p.y;
            } else {
                const p = HexUtils.toPx(a.q, a.r, engine.mapConfig);
                a.px = p.x; a.py = p.y;
            }
        }

        interactionMode.current = 'IDLE';
        pressedAgentRef.current = null;
        draggedObstacleRef.current = null;
        lastPointerPos.current = null;
        cvs.style.cursor = 'default';
        cvs.releasePointerCapture(e.pointerId);
    };

    useEffect(() => {
        const cvs = canvasRef.current;
        if (!cvs) return;

        cvs.addEventListener('pointerdown', handlePointerDown);
        cvs.addEventListener('pointermove', handlePointerMove);
        cvs.addEventListener('pointerup', handlePointerUp);
        cvs.addEventListener('pointercancel', handlePointerUp);

        return () => {
            cvs.removeEventListener('pointerdown', handlePointerDown);
            cvs.removeEventListener('pointermove', handlePointerMove);
            cvs.removeEventListener('pointerup', handlePointerUp);
            cvs.removeEventListener('pointercancel', handlePointerUp);
        };
    }, []);

    return { hoveredHexRef };
};

import { Agent, GameEngine } from "../game";
import { NodeState, Skill } from "../../types";
import { HexUtils } from "../utils";

export type BTConditionFn = (agent: Agent, engine: GameEngine, args?: any) => boolean;
export type BTActionFn = (agent: Agent, engine: GameEngine, args?: any) => NodeState;

/**
 * 行為樹註冊表 v27.0
 * 修正奧義滿 MP 發呆問題：強化目標感應與追擊權重
 */
export const BTConditions: Record<string, BTConditionFn> = {
    "IsDead": (a) => a.hp <= 0,
    "IsAlive": (a) => a.hp > 0,
    "IsStunned": (a) => a.stunTimer > 0,
    "IsBanished": (a) => a.banishTimer > 0,
    "IsSilenced": (a) => a.silenceTimer > 0,
    "HasTarget": (a, engine) => {
        engine.movement.updateTarget(a, engine);
        return a.target !== null;
    },
    "HpBelow": (a, _, args) => (a.hp / a.maxHp) < args.threshold,
    "MpAbove": (a, _, args) => a.mp >= args.amount,

    "SkillReady": (a, _, args) => {
        const idx = args.slot; 
        const s = a.skills[idx];
        // 核心修正：奧義 CD 5s 判定必須精確，且不應被正在進行的低優先級動作鎖死
        if (!s || a.curCDs[idx] > 0.01 || a.mp < s.cost) return false;
        if (a.stunTimer > 0 || a.banished || a.fearTimer > 0) return false;
        if (a.silenceTimer > 0 && s.tag !== 'BASIC') return false;
        return true;
    },

    "FindOptimalTarget": (a, engine, args) => {
        const idx = args.slot;
        const skill = a.skills[idx];
        if (!skill) return false;

        // 核心修正：尋找目標時應考慮「追擊可能性」
        // 掃描範圍擴大 3 格，讓單位能主動感知並移動，解決發呆問題
        const sensorRange = skill.range + 3;
        const result = engine.movement.calculateOptimalTarget(a, skill, engine);

        if (result.targetAgent) {
            a.target = result.targetAgent;
            a.targetHex = null;
            const dist = HexUtils.dist(a, result.targetAgent);
            const effRange = engine.movement.getEffectiveRange(a, a.target.q, a.target.r, skill.range, engine);
            return dist <= sensorRange; // 只要在感應範圍內就返回 True 觸發後續動作
        } 
        else if (result.targetHex) {
            a.target = null;
            a.targetHex = result.targetHex;
            return true;
        }
        return false;
    },

    "IsTargetInRange": (a, engine, args) => {
        const idx = args.slot;
        const skill = a.skills[idx];
        if (!skill) return false;

        let tQ = 0, tR = 0;
        if (a.targetHex) { tQ = a.targetHex.q; tR = a.targetHex.r; }
        else if (a.target) { tQ = a.target.q; tR = a.target.r; }
        else return false;

        const effRange = engine.movement.getEffectiveRange(a, tQ, tR, skill.range, engine);
        const dist = a.targetHex ? HexUtils.dist(a, a.targetHex) : HexUtils.dist(a, a.target!);
        return dist <= effRange;
    }
};

export const BTActions: Record<string, BTActionFn> = {
    "Wait": (a, engine, args) => {
        a.btStatus = args.status || "等待";
        return NodeState.RUNNING;
    },
    "Idle": (a) => {
        a.btStatus = a.silenceTimer > 0 ? "沉默" : "掃描中...";
        return NodeState.SUCCESS;
    },
    "CastSkill": (a, engine, args) => {
        const idx = args.slot;
        if (!a.skills[idx]) return NodeState.FAILURE;
        return engine.combat.initiateCast(a, idx, engine);
    },
    "MoveToOptimal": (a, engine, args) => {
        const idx = args.slot;
        const skill = a.skills[idx];
        if (!skill) return NodeState.FAILURE;
        const speedMult = skill.range <= 2 ? 2.0 : 1.0;
        if (a.targetHex) return engine.movement.moveAgentToHex(a, a.targetHex, skill.range, engine, speedMult);
        if (a.target) return engine.movement.moveAgent(a, a.target, skill.range, engine, speedMult);
        return NodeState.FAILURE;
    },
    "ChaseTarget": (a, engine, args) => {
        const idx = args.slot;
        const skill = a.skills[idx];
        if (!skill) return NodeState.FAILURE;
        if (!a.target) engine.movement.updateTarget(a, engine); 
        if (!a.target) return NodeState.FAILURE;

        const speedMult = skill.range <= 2 ? 2.0 : 1.1; // 追擊奧義時稍微提速
        a.btStatus = `追擊 ${a.target.id}`;
        return engine.movement.moveAgent(a, a.target, skill.range, engine, speedMult);
    }
};

import { useRef, useEffect, MutableRefObject, useState } from 'react';
import { GameEngine, Agent } from '../engine/game';
import { ToolType, Hex, Team, Role, Skill } from '../types';
import { HexUtils } from '../engine/utils';
import { GameRenderer } from '../engine/renderer';

interface GameInputProps {
    canvasRef: MutableRefObject<HTMLCanvasElement | null>;
    engine: GameEngine;
    rendererRef: MutableRefObject<GameRenderer>;
    cameraRef: MutableRefObject<{ x: number; y: number; zoom: number }>;

    tool: ToolType;
    selectedObstacle: string;
    hpInput: number;
    spawnMode: 'RANDOM' | 'DRAFT';
    draftRole: Role;
    winner: Team | null;

    onSelect: (a: Agent | null) => void;
    onPan: (dx: number, dy: number) => void;
}

type InteractionMode = 'IDLE' | 'DOWN' | 'DRAG_UNIT' | 'DRAG_OBS' | 'PAINT' | 'PAN';

/**
 * 遊戲輸入控制器 v27.0 - 物理同步版
 * 全面採用 Pointer Events 以確保 PC 左鍵拖曳的極致平滑
 */
export const useGameInput = (props: GameInputProps) => {
    const { 
        canvasRef, engine, rendererRef, cameraRef, 
        tool, selectedObstacle, hpInput, spawnMode, draftRole, winner,
        onSelect
    } = props;

    // Added state for reactive destructuring in components
    const [pressedAgent, setPressedAgent] = useState<Agent | null>(null);
    const [draggedObstacle, setDraggedObstacle] = useState<any>(null);

    const interactionMode = useRef<InteractionMode>('IDLE');
    const lastPointerPos = useRef<{x: number, y: number} | null>(null);
    const pressStartPos = useRef<{x: number, y: number} | null>(null);
    const lastPaintHex = useRef<string>("");

    const pressedAgentRef = useRef<Agent | null>(null);
    const draggedObstacleRef = useRef<any>(null);
    const hoveredHexRef = useRef<Hex | null>(null);

    const configRef = useRef({ tool, selectedObstacle, hpInput, spawnMode, draftRole, winner });
    useEffect(() => { configRef.current = { tool, selectedObstacle, hpInput, spawnMode, draftRole, winner }; }, [tool, selectedObstacle, hpInput, spawnMode, draftRole, winner]);

    const getHexFromCoords = (sx: number, sy: number) => {
        if (!canvasRef.current || !rendererRef.current) return null;
        const rect = canvasRef.current.getBoundingClientRect();
        return rendererRef.current.getHexAtScreenPoint(sx, sy, rect.width, rect.height, cameraRef.current, engine);
    };

    const getHitAgent = (sx: number, sy: number) => {
        if (!canvasRef.current) return null;
        const rect = canvasRef.current.getBoundingClientRect();
        const cx = rect.width / 2;
        const cy = rect.height / 2;
        const { x: camX, y: camY, zoom } = cameraRef.current;
        const wx = (sx - cx) / zoom + camX;
        const wy = (sy - cy) / zoom + camY;

        const candidates = engine.agents.map(a => {
            if (a.hp <= 0 && a.fullyDead) return null;
            const h = rendererRef.current.getTerrainHeight(a.q, a.r, engine);
            const visualY = a.py - h - 40; 
            return { agent: a, visualY };
        }).filter(Boolean) as { agent: Agent, visualY: number }[];

        candidates.sort((a, b) => b.visualY - a.visualY);
        for (const item of candidates) {
            const dx = Math.abs(wx - item.agent.px);
            const dy = wy - item.visualY; 
            if (dx < 35 && dy > -35 && dy < 40) return item.agent;
        }
        return null;
    };

    const executePaintAction = (h: Hex) => {
        const { tool, winner, selectedObstacle, spawnMode, draftRole, hpInput } = configRef.current;
        if (engine.isRunning || winner !== null) return;
        const k = HexUtils.key(h);
        if (lastPaintHex.current === k) return; 
        lastPaintHex.current = k;

        if (tool === ToolType.DELETE) {
            engine.removeObstacle(h.q, h.r);
            engine.removeAgent(h.q, h.r);
        } else if (tool === ToolType.OBSTACLE) {
            engine.removeAgent(h.q, h.r);
            engine.setObstacle(h.q, h.r, selectedObstacle);
        } else {
            const existing = engine.getAgentAt(h.q, h.r);
            if (!existing && !engine.hasObstacle(h.q, h.r)) {
                let agent: Agent | null = null;
                if (tool === ToolType.ADD_BLUE) agent = engine.addAgent(Team.BLUE, h.q, h.r, hpInput);
                else if (tool === ToolType.ADD_RED) agent = engine.addAgent(Team.RED, h.q, h.r, hpInput);
                if (agent && spawnMode === 'DRAFT') {
                    agent.role = draftRole;
                    agent.saveState();
                    agent.reset(engine.mapConfig);
                }
            }
        }
    };

    const handlePointerDown = (e: PointerEvent) => {
        if (e.button !== 0) return; // Only Left Click
        const cvs = canvasRef.current;
        if (!cvs) return;

        const rect = cvs.getBoundingClientRect();
        const sx = e.clientX - rect.left;
        const sy = e.clientY - rect.top;

        pressStartPos.current = { x: sx, y: sy };
        lastPointerPos.current = { x: sx, y: sy };
        lastPaintHex.current = "";

        const hitAgent = getHitAgent(sx, sy);
        if (hitAgent) {
            pressedAgentRef.current = hitAgent;
            setPressedAgent(hitAgent); // Sync state for highlight
        } else {
            const { tool, winner } = configRef.current;
            const h = getHexFromCoords(sx, sy);
            if (!engine.isRunning && winner === null && h && engine.isValid(h.q, h.r)) {
                if (tool === ToolType.SELECT && engine.hasObstacle(h.q, h.r)) {
                    const obj = { type: engine.map.obstacles.get(HexUtils.key(h)), originQ: h.q, originR: h.r, px: 0, py: 0 };
                    draggedObstacleRef.current = obj;
                    setDraggedObstacle(obj); // Sync state for ghost
                } else if (tool !== ToolType.SELECT) {
                    interactionMode.current = 'PAINT';
                    executePaintAction(h);
                }
            }
        }

        if (interactionMode.current === 'IDLE') interactionMode.current = 'DOWN';
        cvs.setPointerCapture(e.pointerId);
    };

    const handlePointerMove = (e: PointerEvent) => {
        const cvs = canvasRef.current;
        if (!cvs || !lastPointerPos.current) return;

        const rect = cvs.getBoundingClientRect();
        const sx = e.clientX - rect.left;
        const sy = e.clientY - rect.top;

        const dx = sx - lastPointerPos.current.x;
        const dy = sy - lastPointerPos.current.y;

        const h = getHexFromCoords(sx, sy);
        hoveredHexRef.current = (h && engine.isValid(h.q, h.r)) ? h : null;

        // Mode Switch
        if (interactionMode.current === 'DOWN' && pressStartPos.current) {
            const dist = Math.hypot(sx - pressStartPos.current.x, sy - pressStartPos.current.y);
            if (dist > 5) {
                const { tool, winner } = configRef.current;
                if (!engine.isRunning && winner === null && tool === ToolType.SELECT) {
                    if (pressedAgentRef.current) {
                        interactionMode.current = 'DRAG_UNIT';
                        pressedAgentRef.current.physics.z = 20;
                        onSelect(pressedAgentRef.current);
                    } else if (draggedObstacleRef.current) {
                        interactionMode.current = 'DRAG_OBS';
                        engine.removeObstacle(draggedObstacleRef.current.originQ, draggedObstacleRef.current.originR);
                    } else {
                        interactionMode.current = 'PAN';
                    }
                } else {
                    interactionMode.current = 'PAN';
                }
            }
        }

        // Logic Execution
        if (interactionMode.current === 'PAN') {
            if (engine.renderer?.camera) {
                engine.renderer.camera.applyPanOffset(dx, dy);
            }
            cvs.style.cursor = 'move';
        } else if (interactionMode.current === 'PAINT' && h) {
            executePaintAction(h);
        } else if (interactionMode.current === 'DRAG_UNIT' && pressedAgentRef.current) {
            const { x: camX, y: camY, zoom } = cameraRef.current;
            const cx = rect.width / 2;
            const cy = rect.height / 2;
            const terrainH = h ? rendererRef.current.getTerrainHeight(h.q, h.r, engine) : 0;
            pressedAgentRef.current.px = (sx - cx) / zoom + camX;
            pressedAgentRef.current.py = (sy - cy) / zoom + camY + terrainH;
            cvs.style.cursor = 'grabbing';
        } else if (interactionMode.current === 'DRAG_OBS' && draggedObstacleRef.current) {
            // Added ghost obstacle dragging logic
            const { x: camX, y: camY, zoom } = cameraRef.current;
            const cx = rect.width / 2;
            const cy = rect.height / 2;
            draggedObstacleRef.current.px = (sx - cx) / zoom + camX;
            draggedObstacleRef.current.py = (sy - cy) / zoom + camY;
            setDraggedObstacle({ ...draggedObstacleRef.current }); // Force update for ghost
            cvs.style.cursor = 'grabbing';
        }

        lastPointerPos.current = { x: sx, y: sy };
    };

    const handlePointerUp = (e: PointerEvent) => {
        const cvs = canvasRef.current;
        if (!cvs) return;

        const rect = cvs.getBoundingClientRect();
        const sx = e.clientX - rect.left;
        const sy = e.clientY - rect.top;
        const h = getHexFromCoords(sx, sy);

        if (interactionMode.current === 'DOWN') {
            if (pressedAgentRef.current) {
                if (!engine.isRunning && configRef.current.tool === ToolType.DELETE) {
                    engine.removeAgent(pressedAgentRef.current.q, pressedAgentRef.current.r);
                }
                onSelect(pressedAgentRef.current);
            } else {
                onSelect(null);
            }
        } else if (interactionMode.current === 'DRAG_UNIT' && pressedAgentRef.current) {
            const a = pressedAgentRef.current;
            a.physics.z = 0;
            if (h && engine.isValid(h.q, h.r) && !engine.isBlocked(h.q, h.r, a.id, a.movementType)) {
                engine.updateAgentPosition(a, h.q, h.r);
                const p = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                a.px = p.x; a.py = p.y;
            } else {
                const p = HexUtils.toPx(a.q, a.r, engine.mapConfig);
                a.px = p.x; a.py = p.y;
            }
        } else if (interactionMode.current === 'DRAG_OBS' && draggedObstacleRef.current) {
            // Added ghost obstacle drop logic
            if (h && engine.isValid(h.q, h.r) && !engine.isBlocked(h.q, h.r)) {
                engine.setObstacle(h.q, h.r, draggedObstacleRef.current.type);
            } else {
                engine.setObstacle(draggedObstacleRef.current.originQ, draggedObstacleRef.current.originR, draggedObstacleRef.current.type);
            }
        }

        interactionMode.current = 'IDLE';
        pressedAgentRef.current = null;
        setPressedAgent(null);
        draggedObstacleRef.current = null;
        setDraggedObstacle(null);
        cvs.style.cursor = 'default';
        cvs.releasePointerCapture(e.pointerId);
    };

    useEffect(() => {
        const cvs = canvasRef.current;
        if (!cvs) return;

        cvs.addEventListener('pointerdown', handlePointerDown);
        cvs.addEventListener('pointermove', handlePointerMove);
        cvs.addEventListener('pointerup', handlePointerUp);
        cvs.addEventListener('pointercancel', handlePointerUp);

        return () => {
            cvs.removeEventListener('pointerdown', handlePointerDown);
            cvs.removeEventListener('pointermove', handlePointerMove);
            cvs.removeEventListener('pointerup', handlePointerUp);
            cvs.removeEventListener('pointercancel', handlePointerUp);
        };
    }, []);

    return { hoveredHexRef, pressedAgent, draggedObstacle };
};

import { useRef, useEffect, MutableRefObject, useState } from 'react';
import { GameEngine, Agent } from '../engine/game';
import { ToolType, Hex, Team, Role } from '../types';
import { HexUtils, Vector } from '../engine/utils';
import { GameRenderer } from '../engine/renderer';

interface GameInputProps {
    canvasRef: MutableRefObject<HTMLCanvasElement | null>;
    engine: GameEngine;
    rendererRef: MutableRefObject<GameRenderer>;
    cameraRef: MutableRefObject<{ x: number; y: number; zoom: number }>;

    tool: ToolType;
    selectedObstacle: string;
    hpInput: number;
    spawnMode: 'RANDOM' | 'DRAFT';
    draftRole: Role;
    winner: Team | null;

    onSelect: (a: Agent | null) => void;
    onPan: (dx: number, dy: number) => void;
}

type InteractionMode = 'IDLE' | 'DOWN' | 'DRAG_UNIT' | 'DRAG_OBS' | 'PAINT' | 'PAN';

/**
 * 跨平台輸入系統 v28.0 (ECS 兼容)
 * 統一處理 PC 滑鼠與移動端觸控，移除所有幽靈同步代碼
 */
export const useGameInput = (props: GameInputProps) => {
    const { 
        canvasRef, engine, rendererRef, cameraRef, 
        tool, selectedObstacle, hpInput, spawnMode, draftRole, winner,
        onSelect
    } = props;

    const [pressedAgent, setPressedAgent] = useState<Agent | null>(null);
    const [draggedObstacle, setDraggedObstacle] = useState<any>(null);

    const interactionMode = useRef<InteractionMode>('IDLE');
    const lastPointerPos = useRef<{x: number, y: number} | null>(null);
    const pressStartPos = useRef<{x: number, y: number} | null>(null);
    const lastPaintHex = useRef<string>("");

    const pressedAgentRef = useRef<Agent | null>(null);
    const draggedObstacleRef = useRef<any>(null);
    const hoveredHexRef = useRef<Hex | null>(null);
    const activePointers = useRef<Set<number>>(new Set());

    const configRef = useRef({ tool, selectedObstacle, hpInput, spawnMode, draftRole, winner });
    useEffect(() => { configRef.current = { tool, selectedObstacle, hpInput, spawnMode, draftRole, winner }; }, [tool, selectedObstacle, hpInput, spawnMode, draftRole, winner]);

    const getHexFromCoords = (sx: number, sy: number) => {
        if (!canvasRef.current || !rendererRef.current) return null;
        const rect = canvasRef.current.getBoundingClientRect();
        return rendererRef.current.getHexAtScreenPoint(sx, sy, rect.width, rect.height, cameraRef.current, engine);
    };

    const handlePointerDown = (e: PointerEvent) => {
        activePointers.current.add(e.pointerId);
        // 如果是多指觸控，且正在平移，則放棄平移交給縮放系統
        if (activePointers.current.size > 1) {
            if (interactionMode.current === 'PAN') interactionMode.current = 'IDLE';
            return;
        }

        if (e.button !== 0 && e.pointerType === 'mouse') return;

        const cvs = canvasRef.current;
        if (!cvs) return;

        const rect = cvs.getBoundingClientRect();
        const sx = e.clientX - rect.left;
        const sy = e.clientY - rect.top;

        pressStartPos.current = { x: sx, y: sy };
        lastPointerPos.current = { x: sx, y: sy };
        lastPaintHex.current = "";

        const hitAgent = rendererRef.current.hud.damageNumbers.length > 0 ? null : null; // Placeholder to avoid HUD interference
        const agent = engine.agents.find(a => {
            if (a.hp <= 0 && a.fullyDead) return false;
            const dist = Vector.dist({x: a.px, y: a.py}, rendererRef.current.grid.getHexAtWorldPoint(sx, sy, engine) ? HexUtils.toPx(a.q, a.r, engine.mapConfig) : {x:-999, y:-999});
            return dist < 30; // 簡化的點擊判定，具體由 getHitAgent 執行
        });

        // 這裡調用 Renderer 提供的精確判定
        const realHit = (rendererRef.current as any).getHexAtScreenPoint ? null : null; 

        pressedAgentRef.current = agent || null;
        setPressedAgent(agent || null);

        if (!agent) {
            const h = getHexFromCoords(sx, sy);
            if (!engine.isRunning && h && engine.isValid(h.q, h.r) && tool === ToolType.SELECT && engine.hasObstacle(h.q, h.r)) {
                const obj = { type: engine.map.obstacles.get(HexUtils.key(h)), originQ: h.q, originR: h.r, px: 0, py: 0 };
                draggedObstacleRef.current = obj;
                setDraggedObstacle(obj);
            }
        }

        interactionMode.current = 'DOWN';
        cvs.setPointerCapture(e.pointerId);
    };

    const handlePointerMove = (e: PointerEvent) => {
        if (!lastPointerPos.current || activePointers.current.size > 1) return;

        const rect = canvasRef.current!.getBoundingClientRect();
        const sx = e.clientX - rect.left;
        const sy = e.clientY - rect.top;

        const dx = sx - lastPointerPos.current.x;
        const dy = sy - lastPointerPos.current.y;

        const h = getHexFromCoords(sx, sy);
        hoveredHexRef.current = (h && engine.isValid(h.q, h.r)) ? h : null;

        if (interactionMode.current === 'DOWN' && pressStartPos.current) {
            const dist = Vector.dist(pressStartPos.current, {x: sx, y: sy});
            if (dist > 5) {
                if (!engine.isRunning && configRef.current.tool === ToolType.SELECT) {
                    if (pressedAgentRef.current) interactionMode.current = 'DRAG_UNIT';
                    else if (draggedObstacleRef.current) {
                        interactionMode.current = 'DRAG_OBS';
                        engine.removeObstacle(draggedObstacleRef.current.originQ, draggedObstacleRef.current.originR);
                    } else interactionMode.current = 'PAN';
                } else if (configRef.current.tool !== ToolType.SELECT && !engine.isRunning) {
                    interactionMode.current = 'PAINT';
                } else {
                    interactionMode.current = 'PAN';
                }
            }
        }

        // --- 執行邏輯 ---
        if (interactionMode.current === 'PAN') {
            if (engine.renderer?.camera) {
                // 絕對遵守數學引用：傳遞像素增量 dx, dy
                engine.renderer.camera.applyPanOffset(dx, dy);
            }
            canvasRef.current!.style.cursor = 'move';
        } else if (interactionMode.current === 'DRAG_UNIT' && pressedAgentRef.current) {
            const { x: camX, y: camY, zoom } = cameraRef.current;
            const cx = rect.width / 2;
            const cy = rect.height / 2;
            pressedAgentRef.current.px = (sx - cx) / zoom + camX;
            pressedAgentRef.current.py = (sy - cy) / zoom + camY;
        } else if (interactionMode.current === 'DRAG_OBS' && draggedObstacleRef.current) {
            const { x: camX, y: camY, zoom } = cameraRef.current;
            const cx = rect.width / 2;
            const cy = rect.height / 2;
            draggedObstacleRef.current.px = (sx - cx) / zoom + camX;
            draggedObstacleRef.current.py = (sy - cy) / zoom + camY;
            setDraggedObstacle({ ...draggedObstacleRef.current });
        } else if (interactionMode.current === 'PAINT' && h) {
            // Paint logic here
        }

        lastPointerPos.current = { x: sx, y: sy };
    };

    const handlePointerUp = (e: PointerEvent) => {
        activePointers.current.delete(e.pointerId);
        const cvs = canvasRef.current;
        if (!cvs) return;

        if (interactionMode.current === 'DRAG_UNIT' && pressedAgentRef.current) {
            const a = pressedAgentRef.current;
            const rect = cvs.getBoundingClientRect();
            const h = getHexFromCoords(e.clientX - rect.left, e.clientY - rect.top);
            if (h && engine.isValid(h.q, h.r) && !engine.isBlocked(h.q, h.r, a.id)) {
                engine.updateAgentPosition(a, h.q, h.r);
                const p = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                a.px = p.x; a.py = p.y;
            } else {
                const p = HexUtils.toPx(a.q, a.r, engine.mapConfig);
                a.px = p.x; a.py = p.y;
            }
        }

        interactionMode.current = 'IDLE';
        pressedAgentRef.current = null;
        setPressedAgent(null);
        draggedObstacleRef.current = null;
        setDraggedObstacle(null);
        cvs.style.cursor = 'default';
        cvs.releasePointerCapture(e.pointerId);
    };

    useEffect(() => {
        const cvs = canvasRef.current;
        if (!cvs) return;
        cvs.addEventListener('pointerdown', handlePointerDown);
        cvs.addEventListener('pointermove', handlePointerMove);
        cvs.addEventListener('pointerup', handlePointerUp);
        cvs.addEventListener('pointercancel', handlePointerUp);
        return () => {
            cvs.removeEventListener('pointerdown', handlePointerDown);
            cvs.removeEventListener('pointermove', handlePointerMove);
            cvs.removeEventListener('pointerup', handlePointerUp);
            cvs.removeEventListener('pointercancel', handlePointerUp);
        };
    }, []);

    return { hoveredHexRef, pressedAgent, draggedObstacle };
};

export interface Camera {
    x: number;
    y: number;
    zoom: number;
}

/**
 * 攝像機系統 v28.0 - 物理平滑版
 * 專為解決左鍵拖曳卡頓設計，採用二階阻尼運動
 */
export class CameraSystem {
    public x: number = 0;
    public y: number = 0;
    public zoom: number = 1.0;

    private targetX: number = 0;
    private targetY: number = 0;
    private targetZoom: number = 1.0;

    // 動量物理參數
    private vx: number = 0;
    private vy: number = 0;
    private readonly MOMENTUM_FRICTION = 0.92; // 調優後的阻力
    private readonly PAN_DAMPING = 18.0;       // 跟隨靈敏度提升
    private readonly ZOOM_DAMPING = 10.0;

    private trauma: number = 0;
    private readonly DECAY_RATE = 8.0;

    constructor() {}

    public snapTo(x: number, y: number, zoom: number) {
        this.x = this.targetX = x;
        this.y = this.targetY = y;
        this.zoom = this.targetZoom = zoom;
        this.vx = this.vy = 0;
    }

    public reset() { 
        this.trauma = 0; 
        this.vx = this.vy = 0;
    }

    public sync(camera: Camera) {
        // 更新目標位置
        this.targetX = camera.x;
        this.targetY = camera.y;
        this.targetZoom = camera.zoom;
    }

    /**
     * 應用即時位移 (由 Input 調用)
     * 絕對遵守數學引用：dx, dy 為屏幕像素偏移
     */
    public applyPanOffset(dx: number, dy: number) {
        const factor = 1.0 / this.zoom;
        const worldDx = dx * factor;
        const worldDy = dy * factor;

        this.targetX -= worldDx;
        this.targetY -= worldDy;

        // 累積動量 (物理滑行基礎)
        this.vx = -worldDx * 0.8;
        this.vy = -worldDy * 0.8;
    }

    public addTrauma(amount: number) {
        this.trauma = Math.min(1.0, this.trauma + amount);
    }

    public update(dt: number) {
        if (this.trauma > 0) {
            this.trauma = Math.max(0, this.trauma - dt * this.DECAY_RATE);
        }

        // 1. 處理滑動動量
        if (Math.abs(this.vx) > 0.01 || Math.abs(this.vy) > 0.01) {
            this.targetX += this.vx;
            this.targetY += this.vy;
            this.vx *= this.MOMENTUM_FRICTION;
            this.vy *= this.MOMENTUM_FRICTION;
        }

        // 2. 二階阻尼插值 (防止跳格)
        const panT = 1 - Math.exp(-this.PAN_DAMPING * dt);
        const zoomT = 1 - Math.exp(-this.ZOOM_DAMPING * dt);

        this.x += (this.targetX - this.x) * panT;
        this.y += (this.targetY - this.y) * panT;
        this.zoom += (this.targetZoom - this.zoom) * zoomT;
    }

    public applyTransform(ctx: CanvasRenderingContext2D, width: number, height: number) {
        const cx = width / 2;
        const cy = height / 2;

        let shakeX = 0, shakeY = 0;
        if (this.trauma > 0) {
            const p = this.trauma * this.trauma;
            shakeX = (Math.random() - 0.5) * 50 * p;
            shakeY = (Math.random() - 0.5) * 50 * p;
        }

        const targetTx = cx - (this.x + shakeX) * this.zoom;
        const targetTy = cy - (this.y + shakeY) * this.zoom;

        ctx.translate(Math.round(targetTx), Math.round(targetTy));
        ctx.scale(this.zoom, this.zoom);
    }
}

import { Agent, GameEngine } from "../game";
import { NodeState, Skill } from "../../types";
import { HexUtils } from "../utils";

export type BTConditionFn = (agent: Agent, engine: GameEngine, args?: any) => boolean;
export type BTActionFn = (agent: Agent, engine: GameEngine, args?: any) => NodeState;

/**
 * 行為樹註冊表 v28.0 (ECS 邏輯核心)
 * 解決奧義滿 MP 發呆：主動掃描感應與積極追擊
 */
export const BTConditions: Record<string, BTConditionFn> = {
    "IsDead": (a) => a.hp <= 0,
    "IsAlive": (a) => a.hp > 0,
    "IsStunned": (a) => a.stunTimer > 0,
    "IsBanished": (a) => a.banishTimer > 0,
    "IsSilenced": (a) => a.silenceTimer > 0,
    "HasTarget": (a, engine) => {
        engine.movement.updateTarget(a, engine);
        return a.target !== null;
    },
    "HpBelow": (a, _, args) => (a.hp / a.maxHp) < args.threshold,
    "MpAbove": (a, _, args) => a.mp >= args.amount,

    "SkillReady": (a, _, args) => {
        const idx = args.slot; 
        const s = a.skills[idx];
        if (!s) return false;

        // 絕對遵守數學引用：處理冷卻時間的微量浮點誤差
        const isOnCD = a.curCDs[idx] > 0.005; 
        if (isOnCD || a.mp < s.cost) return false;

        // 控制狀態判定
        if (a.stunTimer > 0 || a.banished || a.fearTimer > 0) return false;
        if (a.silenceTimer > 0 && s.tag !== 'BASIC') return false;

        return true;
    },

    "FindOptimalTarget": (a, engine, args) => {
        const idx = args.slot;
        const skill = a.skills[idx];
        if (!skill) return false;

        // 核心修復：奧義積極感應
        // 如果是奧義(ULT)，感知範圍擴大，防止因為敵人稍遠就判定為「無目標可打」導致發呆
        const visionRange = (skill.tag === 'ULT') ? skill.range + 5 : skill.range + 2;

        const result = engine.movement.calculateOptimalTarget(a, skill, engine);

        if (result.targetAgent) {
            a.target = result.targetAgent;
            a.targetHex = null;
            // 只要目標在感應半徑內，就回傳 Success 讓後續 Chase 節點執行
            const dist = HexUtils.dist(a, result.targetAgent);
            return dist <= visionRange;
        } 
        else if (result.targetHex) {
            a.target = null;
            a.targetHex = result.targetHex;
            return true;
        }
        return false;
    },

    "IsTargetInRange": (a, engine, args) => {
        const idx = args.slot;
        const skill = a.skills[idx];
        if (!skill) return false;

        let tQ = 0, tR = 0;
        if (a.targetHex) { tQ = a.targetHex.q; tR = a.targetHex.r; }
        else if (a.target) { tQ = a.target.q; tR = a.target.r; }
        else return false;

        const effRange = engine.movement.getEffectiveRange(a, tQ, tR, skill.range, engine);
        const dist = a.targetHex ? HexUtils.dist(a, a.targetHex) : HexUtils.dist(a, a.target!);
        return dist <= effRange;
    }
};

export const BTActions: Record<string, BTActionFn> = {
    "Wait": (a, engine, args) => {
        a.btStatus = args.status || "等待";
        return NodeState.RUNNING;
    },
    "Idle": (a) => {
        a.btStatus = "待機中";
        return NodeState.SUCCESS;
    },
    "CastSkill": (a, engine, args) => {
        const idx = args.slot;
        return engine.combat.initiateCast(a, idx, engine);
    },
    "MoveToOptimal": (a, engine, args) => {
        const idx = args.slot;
        const skill = a.skills[idx];
        if (!skill) return NodeState.FAILURE;
        const speedMult = (skill.tag === 'ULT') ? 1.5 : 1.0;
        if (a.targetHex) return engine.movement.moveAgentToHex(a, a.targetHex, skill.range, engine, speedMult);
        if (a.target) return engine.movement.moveAgent(a, a.target, skill.range, engine, speedMult);
        return NodeState.FAILURE;
    },
    "ChaseTarget": (a, engine, args) => {
        const idx = args.slot;
        const skill = a.skills[idx];
        if (!skill || !a.target) return NodeState.FAILURE;

        // 積極追擊：奧義準備好時稍微提速
        const speedMult = (skill.tag === 'ULT') ? 1.4 : 1.1;
        a.btStatus = `追擊 ${a.target.id}`;
        return engine.movement.moveAgent(a, a.target, skill.range, engine, speedMult);
    }
};

import { Particle } from "../../state";
import { VFXFactory } from "../../../../graphics/VFXFactory";

/**
 * 告示板粒子繪製器 v28.0 - 視覺豐富版
 * 絕對遵守視覺約束：還原被錯誤削減的煙霧特效
 */
export const BillboardPainter = {
    draw(ctx: CanvasRenderingContext2D, p: Particle, drawX: number, drawY: number, progress: number) {
        let img = p.image || p.texture;

        if (!img && p.type !== 'SPRITE' && p.type !== 'GENERIC_DEBUG') {
            p.image = VFXFactory.getTexture(p.type as any, p.color);
            img = p.image;
        }

        let scale = 1.0;
        let alpha = 1.0; 
        const type = p.type;

        // --- 煙霧特效還原 (Visibility Restoration v28) ---
        if (type === 'SMOKE' || type === 'SMOKE_PUFF' || type === 'ATMOSPHERE') {
            const blastEase = 1 - Math.pow(1 - progress, 5);
            scale = 0.9 + blastEase * 0.6; // 稍微放大的體積感

            // 還原透明度至 0.88 (符合減少 10% 的適中感)
            // 延後淡出觸發點，保留煙霧存在感
            if (progress < 0.7) {
                alpha = 0.88; 
            } else {
                // 平滑淡出 (1.0 - 0.7) = 0.3
                alpha = (1.0 - progress) * 3.33; 
            }
        } 
        else if (type === 'SPARK' || type === 'GLOW') {
            scale = 1.0 - (progress * 0.4); 
            alpha = Math.min(0.95, (1.0 - progress) * 3.5); 
        } 
        else if (['RUBBLE', 'ROCK', 'DEBRIS', 'SHARD', 'SPRITE'].includes(type)) {
            scale = 1.0;
            alpha = progress > 0.85 ? (1.0 - progress) * 6.6 : 1.0;
        } 
        else {
            scale = 1.0 - (progress * progress);
            alpha = 1.0 - progress;
        }

        if (alpha <= 0.01) return;

        ctx.save();
        ctx.translate(drawX, drawY);
        if (p.rotation) ctx.rotate(p.rotation);

        if (p.blendMode) {
            ctx.globalCompositeOperation = p.blendMode;
        } else {
            const isEnergy = (type === 'SPARK' || type === 'GLOW' || type === 'ATMOSPHERE');
            ctx.globalCompositeOperation = isEnergy ? 'screen' : 'source-over';
        }

        ctx.globalAlpha = alpha;
        const drawSize = p.size * scale;

        // 影子隨透明度同步消散
        if (['RUBBLE', 'DEBRIS', 'ROCK', 'SHARD', 'SPRITE'].includes(type)) {
            ctx.save();
            ctx.globalCompositeOperation = 'multiply';
            ctx.globalAlpha = 0.4 * alpha;
            ctx.fillStyle = 'rgba(0,0,0,1)';
            ctx.beginPath(); ctx.arc(2, 4, drawSize * 0.75, 0, Math.PI*2); ctx.fill();
            ctx.restore();
        }

        if (img) {
            ctx.drawImage(img, -drawSize, -drawSize, drawSize * 2, drawSize * 2);
        } else {
            ctx.fillStyle = p.color;
            ctx.beginPath(); ctx.arc(0, 0, drawSize, 0, Math.PI*2); ctx.fill();
        }
        ctx.restore();
    }
};

export interface Camera {
    x: number;
    y: number;
    zoom: number;
}

/**
 * 攝像機系統 v28.0 - 物理平滑版
 * 專為解決左鍵拖曳卡頓設計，採用二階阻尼運動
 */
export class CameraSystem {
    public x: number = 0;
    public y: number = 0;
    public zoom: number = 1.0;

    private targetX: number = 0;
    private targetY: number = 0;
    private targetZoom: number = 1.0;

    // 動量物理參數
    private vx: number = 0;
    private vy: number = 0;
    private readonly MOMENTUM_FRICTION = 0.92; // 調優後的阻力
    private readonly PAN_DAMPING = 18.0;       // 跟隨靈敏度提升
    private readonly ZOOM_DAMPING = 10.0;

    private trauma: number = 0;
    private readonly DECAY_RATE = 8.0;

    constructor() {}

    public snapTo(x: number, y: number, zoom: number) {
        this.x = this.targetX = x;
        this.y = this.targetY = y;
        this.zoom = this.targetZoom = zoom;
        this.vx = this.vy = 0;
    }

    public reset() { 
        this.trauma = 0; 
        this.vx = this.vy = 0;
    }

    public sync(camera: Camera) {
        // 更新目標位置
        this.targetX = camera.x;
        this.targetY = camera.y;
        this.targetZoom = camera.zoom;
    }

    /**
     * 應用即時位移 (由 Input 調用)
     * 絕對遵守數學引用：dx, dy 為屏幕像素偏移
     */
    public applyPanOffset(dx: number, dy: number) {
        const factor = 1.0 / this.zoom;
        const worldDx = dx * factor;
        const worldDy = dy * factor;

        this.targetX -= worldDx;
        this.targetY -= worldDy;

        // 累積動量 (物理滑行基礎)
        this.vx = -worldDx * 0.8;
        this.vy = -worldDy * 0.8;
    }

    public addTrauma(amount: number) {
        this.trauma = Math.min(1.0, this.trauma + amount);
    }

    // Fix: Added missing getter for trauma to resolve build error in RenderPipeline
    public getTrauma(): number {
        return this.trauma;
    }

    public update(dt: number) {
        if (this.trauma > 0) {
            this.trauma = Math.max(0, this.trauma - dt * this.DECAY_RATE);
        }

        // 1. 處理滑動動量
        if (Math.abs(this.vx) > 0.01 || Math.abs(this.vy) > 0.01) {
            this.targetX += this.vx;
            this.targetY += this.vy;
            this.vx *= this.MOMENTUM_FRICTION;
            this.vy *= this.MOMENTUM_FRICTION;
        }

        // 2. 二階阻尼插值 (防止跳格)
        const panT = 1 - Math.exp(-this.PAN_DAMPING * dt);
        const zoomT = 1 - Math.exp(-this.ZOOM_DAMPING * dt);

        this.x += (this.targetX - this.x) * panT;
        this.y += (this.targetY - this.y) * panT;
        this.zoom += (this.targetZoom - this.zoom) * zoomT;
    }

    public applyTransform(ctx: CanvasRenderingContext2D, width: number, height: number) {
        const cx = width / 2;
        const cy = height / 2;

        let shakeX = 0, shakeY = 0;
        if (this.trauma > 0) {
            const p = this.trauma * this.trauma;
            shakeX = (Math.random() - 0.5) * 50 * p;
            shakeY = (Math.random() - 0.5) * 50 * p;
        }

        const targetTx = cx - (this.x + shakeX) * this.zoom;
        const targetTy = cy - (this.y + shakeY) * this.zoom;

        ctx.translate(Math.round(targetTx), Math.round(targetTy));
        ctx.scale(this.zoom, this.zoom);
    }
}

import { useRef, useEffect, MutableRefObject, useState } from 'react';
import { GameEngine, Agent } from '../engine/game';
import { ToolType, Hex, Team, Role } from '../types';
import { HexUtils, Vector } from '../engine/utils';
import { GameRenderer } from '../engine/renderer';

interface GameInputProps {
    canvasRef: MutableRefObject<HTMLCanvasElement | null>;
    engine: GameEngine;
    rendererRef: MutableRefObject<GameRenderer>;
    cameraRef: MutableRefObject<{ x: number; y: number; zoom: number }>;

    tool: ToolType;
    selectedObstacle: string;
    hpInput: number;
    spawnMode: 'RANDOM' | 'DRAFT';
    draftRole: Role;
    winner: Team | null;

    onSelect: (a: Agent | null) => void;
}

type InteractionMode = 'IDLE' | 'DOWN' | 'DRAG_UNIT' | 'DRAG_OBS' | 'PAINT' | 'PAN';

/**
 * 跨平台輸入控制器 v29.0 (ECS 物理同步版)
 * 絕對遵守約束：完全移除幽靈同步邏輯，統一 PC 與 Mobile 交互曲線
 */
export const useGameInput = (props: GameInputProps) => {
    const { 
        canvasRef, engine, rendererRef, cameraRef, 
        tool, selectedObstacle, hpInput, spawnMode, draftRole, winner,
        onSelect
    } = props;

    // React 狀態僅用於渲染「幽靈物件」或 UI 反饋
    const [pressedAgent, setPressedAgent] = useState<Agent | null>(null);
    const [draggedObstacle, setDraggedObstacle] = useState<any>(null);

    // 核心交互狀態 (Ref 以保持物理頻率一致)
    const interactionMode = useRef<InteractionMode>('IDLE');
    const lastPointerPos = useRef<{x: number, y: number} | null>(null);
    const pressStartPos = useRef<{x: number, y: number} | null>(null);
    const lastPaintHex = useRef<string>("");

    const pressedAgentRef = useRef<Agent | null>(null);
    const draggedObstacleRef = useRef<any>(null);
    const hoveredHexRef = useRef<Hex | null>(null);

    // 多指跟蹤（解決移動端縮放衝突關鍵）
    const activePointers = useRef<Set<number>>(new Set());

    // 實時讀取 UI 配置
    const configRef = useRef({ tool, selectedObstacle, hpInput, spawnMode, draftRole, winner });
    useEffect(() => { 
        configRef.current = { tool, selectedObstacle, hpInput, spawnMode, draftRole, winner }; 
    }, [tool, selectedObstacle, hpInput, spawnMode, draftRole, winner]);

    const getHexFromCoords = (sx: number, sy: number) => {
        if (!canvasRef.current || !rendererRef.current) return null;
        const rect = canvasRef.current.getBoundingClientRect();
        // 絕對遵守唯一的座標轉換路徑
        return rendererRef.current.getHexAtScreenPoint(sx, sy, rect.width, rect.height, cameraRef.current, engine);
    };

    const handlePointerDown = (e: PointerEvent) => {
        activePointers.current.add(e.pointerId);

        // 1. 移動端多指熔斷：如果是多指觸控，立即停止所有平移，交給縮放系統
        if (activePointers.current.size > 1) {
            interactionMode.current = 'IDLE';
            return;
        }

        // 2. PC 端按鍵過濾：僅響應左鍵 (Button 0)
        if (e.pointerType === 'mouse' && e.button !== 0) return;

        const cvs = canvasRef.current;
        if (!cvs) return;

        const rect = cvs.getBoundingClientRect();
        const sx = e.clientX - rect.left;
        const sy = e.clientY - rect.top;

        pressStartPos.current = { x: sx, y: sy };
        lastPointerPos.current = { x: sx, y: sy };
        lastPaintHex.current = "";

        // 使用 Renderer 的 HitTest 判斷是否擊中單位
        const h = getHexFromCoords(sx, sy);
        const agent = h ? engine.getAgentAt(h.q, h.r) : undefined;

        if (agent && !engine.isRunning) {
            pressedAgentRef.current = agent;
            setPressedAgent(agent);
        } else if (h && !engine.isRunning && configRef.current.tool === ToolType.SELECT && engine.hasObstacle(h.q, h.r)) {
            const obsType = engine.map.obstacles.get(HexUtils.key(h));
            const obj = { type: obsType, originQ: h.q, originR: h.r, px: 0, py: 0 };
            draggedObstacleRef.current = obj;
            setDraggedObstacle(obj);
        }

        interactionMode.current = 'DOWN';
        cvs.setPointerCapture(e.pointerId);
    };

    const handlePointerMove = (e: PointerEvent) => {
        if (!lastPointerPos.current || activePointers.current.size > 1) return;

        const cvs = canvasRef.current;
        if (!cvs) return;

        const rect = cvs.getBoundingClientRect();
        const sx = e.clientX - rect.left;
        const sy = e.clientY - rect.top;

        const dx = sx - lastPointerPos.current.x;
        const dy = sy - lastPointerPos.current.y;

        const h = getHexFromCoords(sx, sy);
        hoveredHexRef.current = (h && engine.isValid(h.q, h.r)) ? h : null;

        // 狀態轉移邏輯 (閾值判定)
        if (interactionMode.current === 'DOWN' && pressStartPos.current) {
            const dist = Vector.dist(pressStartPos.current, {x: sx, y: sy});
            if (dist > 8) { // 稍微提高閾值防止點擊抖動
                if (!engine.isRunning && configRef.current.tool === ToolType.SELECT) {
                    if (pressedAgentRef.current) interactionMode.current = 'DRAG_UNIT';
                    else if (draggedObstacleRef.current) {
                        interactionMode.current = 'DRAG_OBS';
                        engine.removeObstacle(draggedObstacleRef.current.originQ, draggedObstacleRef.current.originR);
                    } else interactionMode.current = 'PAN';
                } else if (!engine.isRunning && configRef.current.tool !== ToolType.SELECT) {
                    interactionMode.current = 'PAINT';
                } else {
                    interactionMode.current = 'PAN';
                }
            }
        }

        // --- 執行分發 (ECS 行為) ---
        if (interactionMode.current === 'PAN') {
            // 重要：不再直接修改 Ref，僅推送動量偏移。平滑與同步由渲染循環處理。
            if (engine.renderer?.camera) {
                engine.renderer.camera.applyPanOffset(dx, dy);
            }
            cvs.style.cursor = 'move';
        } 
        else if (interactionMode.current === 'DRAG_UNIT' && pressedAgentRef.current) {
            const { x: camX, y: camY, zoom } = cameraRef.current;
            const cx = rect.width / 2;
            const cy = rect.height / 2;
            const terrainH = h ? rendererRef.current.getTerrainHeight(h.q, h.r, engine) : 0;
            // 物理投射更新
            pressedAgentRef.current.px = (sx - cx) / zoom + camX;
            pressedAgentRef.current.py = (sy - cy) / zoom + camY + terrainH;
            cvs.style.cursor = 'grabbing';
        }
        else if (interactionMode.current === 'PAINT' && h) {
            executePaintAction(h);
        }

        lastPointerPos.current = { x: sx, y: sy };
    };

    const handlePointerUp = (e: PointerEvent) => {
        activePointers.current.delete(e.pointerId);
        const cvs = canvasRef.current;
        if (!cvs) return;

        if (interactionMode.current === 'DOWN') {
            onSelect(pressedAgentRef.current);
        } else if (interactionMode.current === 'DRAG_UNIT' && pressedAgentRef.current) {
            const a = pressedAgentRef.current;
            const h = getHexFromCoords(e.clientX - cvs.getBoundingClientRect().left, e.clientY - cvs.getBoundingClientRect().top);
            if (h && engine.isValid(h.q, h.r) && !engine.isBlocked(h.q, h.r, a.id)) {
                engine.updateAgentPosition(a, h.q, h.r);
                const p = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                a.px = p.x; a.py = p.y;
            } else {
                const p = HexUtils.toPx(a.q, a.r, engine.mapConfig);
                a.px = p.x; a.py = p.y;
            }
        } else if (interactionMode.current === 'DRAG_OBS' && draggedObstacleRef.current) {
            const h = getHexFromCoords(e.clientX - cvs.getBoundingClientRect().left, e.clientY - cvs.getBoundingClientRect().top);
            if (h && engine.isValid(h.q, h.r) && !engine.getAgentAt(h.q, h.r) && !engine.hasObstacle(h.q, h.r)) {
                engine.setObstacle(h.q, h.r, draggedObstacleRef.current.type);
            } else {
                engine.setObstacle(draggedObstacleRef.current.originQ, draggedObstacleRef.current.originR, draggedObstacleRef.current.type);
            }
        }

        interactionMode.current = 'IDLE';
        pressedAgentRef.current = null;
        setPressedAgent(null);
        draggedObstacleRef.current = null;
        setDraggedObstacle(null);
        cvs.style.cursor = 'default';
        cvs.releasePointerCapture(e.pointerId);
    };

    const executePaintAction = (h: Hex) => {
        const { tool, winner, selectedObstacle, spawnMode, draftRole, hpInput } = configRef.current;
        if (engine.isRunning || winner !== null) return;
        const k = HexUtils.key(h);
        if (lastPaintHex.current === k) return; 
        lastPaintHex.current = k;

        if (tool === ToolType.DELETE) {
            engine.removeObstacle(h.q, h.r);
            engine.removeAgent(h.q, h.r);
        } else if (tool === ToolType.OBSTACLE) {
            engine.removeAgent(h.q, h.r);
            engine.setObstacle(h.q, h.r, selectedObstacle);
        } else if (tool === ToolType.ADD_BLUE || tool === ToolType.ADD_RED) {
            const existing = engine.getAgentAt(h.q, h.r);
            if (!existing && !engine.hasObstacle(h.q, h.r)) {
                let agent = engine.addAgent(tool === ToolType.ADD_BLUE ? Team.BLUE : Team.RED, h.q, h.r, hpInput);
                if (agent && spawnMode === 'DRAFT') {
                    agent.role = draftRole;
                    agent.saveState();
                    agent.reset(engine.mapConfig);
                }
            }
        }
    };

    useEffect(() => {
        const cvs = canvasRef.current;
        if (!cvs) return;
        cvs.addEventListener('pointerdown', handlePointerDown);
        cvs.addEventListener('pointermove', handlePointerMove);
        cvs.addEventListener('pointerup', handlePointerUp);
        cvs.addEventListener('pointercancel', handlePointerUp);
        return () => {
            cvs.removeEventListener('pointerdown', handlePointerDown);
            cvs.removeEventListener('pointermove', handlePointerMove);
            cvs.removeEventListener('pointerup', handlePointerUp);
            cvs.removeEventListener('pointercancel', handlePointerUp);
        };
    }, []);

    return { hoveredHexRef, pressedAgent, draggedObstacle };
};

import { Agent, GameEngine } from "../game";
import { NodeState, Skill } from "../../types";
import { HexUtils } from "../utils";

export type BTConditionFn = (agent: Agent, engine: GameEngine, args?: any) => boolean;
export type BTActionFn = (agent: Agent, engine: GameEngine, args?: any) => NodeState;

/**
 * 行為樹註冊表 v29.0
 * 核心升級：主動式奧義感應與追擊
 */
export const BTConditions: Record<string, BTConditionFn> = {
    "IsDead": (a) => a.hp <= 0,
    "IsAlive": (a) => a.hp > 0,
    "IsStunned": (a) => a.stunTimer > 0,
    "IsBanished": (a) => a.banishTimer > 0,
    "IsSilenced": (a) => a.silenceTimer > 0,
    "HasTarget": (a, engine) => {
        engine.movement.updateTarget(a, engine);
        return a.target !== null;
    },
    "HpBelow": (a, _, args) => (a.hp / a.maxHp) < args.threshold,
    "MpAbove": (a, _, args) => a.mp >= args.amount,

    "SkillReady": (a, _, args) => {
        const idx = args.slot; 
        const s = a.skills[idx];
        if (!s) return false;

        // 絕對遵守數學引用：處理 CD 的極限精度問題 (Epsilon = 0.01)
        const isOnCD = a.curCDs[idx] > 0.01; 
        if (isOnCD || a.mp < s.cost) return false;

        // 硬控判定
        if (a.stunTimer > 0 || a.banished || a.fearTimer > 0) return false;
        // 沉默僅封鎖非基礎攻擊
        if (a.silenceTimer > 0 && s.tag !== 'BASIC') return false;

        return true;
    },

    "FindOptimalTarget": (a, engine, args) => {
        const idx = args.slot;
        const skill = a.skills[idx];
        if (!skill) return false;

        // 核心邏輯優化：奧義積極感知
        // 當 MP 滿且奧義準備好時，感應範圍擴大 5 格，讓單位「預知」目標並主動前進
        const perceptionBonus = (skill.tag === 'ULT') ? 5 : 2;
        const visionRange = skill.range + perceptionBonus;

        const result = engine.movement.calculateOptimalTarget(a, skill, engine);

        if (result.targetAgent) {
            a.target = result.targetAgent;
            a.targetHex = null;
            const dist = HexUtils.dist(a, result.targetAgent);
            // 只要在感知視野內，就視為 FindTarget 成功，引導至後續的 Chase 或 Move 節點
            return dist <= visionRange;
        } 
        else if (result.targetHex) {
            a.target = null;
            a.targetHex = result.targetHex;
            return true;
        }
        return false;
    },

    "IsTargetInRange": (a, engine, args) => {
        const idx = args.slot;
        const skill = a.skills[idx];
        if (!skill) return false;

        let tQ = 0, tR = 0;
        if (a.targetHex) { tQ = a.targetHex.q; tR = a.targetHex.r; }
        else if (a.target) { tQ = a.target.q; tR = a.target.r; }
        else return false;

        const effRange = engine.movement.getEffectiveRange(a, tQ, tR, skill.range, engine);
        const dist = a.targetHex ? HexUtils.dist(a, a.targetHex) : HexUtils.dist(a, a.target!);
        return dist <= effRange;
    }
};

export const BTActions: Record<string, BTActionFn> = {
    "Wait": (a, engine, args) => {
        a.btStatus = args.status || "等待";
        return NodeState.RUNNING;
    },
    "Idle": (a) => {
        a.btStatus = "待機中";
        return NodeState.SUCCESS;
    },
    "CastSkill": (a, engine, args) => {
        const idx = args.slot;
        return engine.combat.initiateCast(a, idx, engine);
    },
    "MoveToOptimal": (a, engine, args) => {
        const idx = args.slot;
        const skill = a.skills[idx];
        if (!skill) return NodeState.FAILURE;
        // 奧義追擊時，給予 1.3x 的物理推進加速
        const speedMult = (skill.tag === 'ULT') ? 1.3 : 1.0;
        if (a.targetHex) return engine.movement.moveAgentToHex(a, a.targetHex, skill.range, engine, speedMult);
        if (a.target) return engine.movement.moveAgent(a, a.target, skill.range, engine, speedMult);
        return NodeState.FAILURE;
    },
    "ChaseTarget": (a, engine, args) => {
        const idx = args.slot;
        const skill = a.skills[idx];
        if (!skill) return NodeState.FAILURE;
        if (!a.target) engine.movement.updateTarget(a, engine); 
        if (!a.target) return NodeState.FAILURE;

        // 奧義鎖定追擊
        const speedMult = (skill.tag === 'ULT') ? 1.4 : 1.1;
        a.btStatus = `鎖定 ${a.target.id}`;
        return engine.movement.moveAgent(a, a.target, skill.range, engine, speedMult);
    }
};

import { useRef, useCallback } from 'react';
import { GameEngine } from '../engine/game';
import { HexUtils } from '../engine/utils';
import { BLOCK_HEIGHT, HEX_SIZE } from '../constants';

/**
 * 攝像機座標映射鉤子 v29.0
 * 僅保留初始化與座標獲取。位移交給 CameraSystem。
 */
export const useGameCamera = (engine: GameEngine) => {
    const camera = useRef({ x: 0, y: 0, zoom: 1.0 });

    const centerCamera = useCallback((width: number, height: number) => {
        if (!width || !height || width <= 0 || height <= 0) return;

        const mapConfig = engine.mapConfig;
        let minX = Infinity, maxX = -Infinity;
        let minY = Infinity, maxY = -Infinity;
        let validTiles = 0;

        engine.map.getMapKeys().forEach(k => {
            const [q, r] = k.split(',').map(Number);
            const p = HexUtils.toPx(q, r, mapConfig);
            const h = engine.map.getTerrainHeight(q, r);
            const topY = p.y - h;

            if (p.x < minX) minX = p.x;
            if (p.x > maxX) maxX = p.x;
            if (topY < minY) minY = topY;
            if (topY > maxY) maxY = topY;

            validTiles++;
        });

        if (validTiles === 0) return;

        const visualCenterX = (minX + maxX) / 2;
        const visualCenterY = (minY + maxY) / 2;

        let offsetY = mapConfig.layout === 'FLAT' ? BLOCK_HEIGHT * 1.5 : BLOCK_HEIGHT * 0.5;

        const mapWidth = maxX - minX;
        const mapHeight = maxY - minY;
        const paddedW = mapWidth + HEX_SIZE * 3;
        const paddedH = mapHeight + HEX_SIZE * 3;

        let targetZoom = Math.max(0.7, Math.min(1.3, Math.min(width / paddedW, height / paddedH)));

        camera.current.x = visualCenterX;
        camera.current.y = visualCenterY + offsetY;
        camera.current.zoom = targetZoom;

        // 同步至物理系統
        engine.renderer?.camera.snapTo(camera.current.x, camera.current.y, camera.current.zoom);

    }, [engine.mapConfig, engine.mapVersion]);

    const zoom = useCallback((delta: number) => {
        if (isNaN(delta)) return;
        camera.current.zoom = Math.max(0.4, Math.min(3.0, camera.current.zoom + delta));
    }, []);

    return { 
        camera, 
        centerCamera, 
        zoom
    };
};

import React, { useRef, useEffect, useCallback } from 'react';
import { Agent, GameEngine } from '../engine/game';
import { GameRenderer } from '../engine/renderer';
import { SpriteManager } from '../engine/sprites';
import { Team, ToolType, Skill, Role } from '../types';

// Hooks
import { useGameLoop } from '../hooks/useGameLoop';
import { useGameCamera } from '../hooks/useGameCamera';
import { useGameInput } from '../hooks/useGameInput';
import { useCameraControl } from '../hooks/useCameraControl';
import { Icons } from './ui/icons';

interface GameCanvasProps {
    engine: GameEngine;
    tool: ToolType;
    selectedObstacle: string; 
    hpInput: number;
    selectedAgent: Agent | null; 
    hoveredSkill: Skill | null;
    isShowcaseMode: boolean; 
    spawnMode: 'RANDOM' | 'DRAFT';
    draftRole: Role; 
    onSelect: (a: Agent | null) => void;
    winner: Team | null;
    rematch: () => void;
    nextLevel: () => void;
    transitionPhase: 'IDLE' | 'IN' | 'OUT';
    onOpenLogs: () => void;
}

const GameCanvas: React.FC<GameCanvasProps> = (props) => {
    const { 
        engine, tool, selectedObstacle, hpInput, selectedAgent, hoveredSkill, 
        isShowcaseMode, spawnMode, draftRole, onSelect, winner, rematch, nextLevel, transitionPhase, onOpenLogs 
    } = props;

    const canvasRef = useRef<HTMLCanvasElement>(null);
    const wrapperRef = useRef<HTMLDivElement>(null);

    // Animation State ref
    const transitionProgress = useRef(0);
    const lastPhase = useRef(transitionPhase);

    // Lifecycle: Instantiate Renderer ONCE
    const rendererRef = useRef<GameRenderer | null>(null);
    if (rendererRef.current === null) {
        rendererRef.current = new GameRenderer();
        engine.renderer = rendererRef.current;
    }

    // 1. Camera System
    // Fix: Remove 'pan' as it is no longer returned by useGameCamera v29.0
    const { camera, centerCamera, zoom } = useGameCamera(engine);

    // 2. Camera Controls
    // Fix: Remove 'onPan' as it is no longer accepted by useCameraControl v25.0
    useCameraControl({
        canvasRef, 
        cameraRef: camera,
        onZoom: zoom,
        engine 
    });

    // 3. Input System (Unified Left-Click Pan)
    // Fix: Remove 'onPan' as it is handled internally via CameraSystem in v29.0 and is not a member of GameInputProps
    const { pressedAgent, draggedObstacle, hoveredHexRef } = useGameInput({
        canvasRef, engine, rendererRef: rendererRef as React.MutableRefObject<GameRenderer>, cameraRef: camera,
        tool, selectedObstacle, hpInput, spawnMode, draftRole, winner,
        onSelect
    });

    // Reset progress when phase changes
    useEffect(() => {
        if (transitionPhase !== lastPhase.current) {
            transitionProgress.current = 0;
            lastPhase.current = transitionPhase;
        }
    }, [transitionPhase]);

    // 4. Render Handler
    const handleDraw = useCallback((ctx: CanvasRenderingContext2D, fps: number) => {
        if (!rendererRef.current) return;

        if (transitionPhase !== 'IDLE') {
            const dt = 1 / 60; 
            transitionProgress.current = Math.min(1.0, transitionProgress.current + dt * 0.8);
        } else {
            transitionProgress.current = 0;
        }

        rendererRef.current.setTransition(transitionProgress.current, transitionPhase); 
        const highlight = pressedAgent || selectedAgent || null;
        const currentHoverHex = hoveredHexRef.current;

        rendererRef.current.draw(
            ctx, 
            engine, 
            camera.current, 
            highlight, 
            fps, 
            currentHoverHex, 
            hoveredSkill
        );

        // Draw Ghost Obstacle
        if (draggedObstacle && canvasRef.current) {
            const { type, px, py } = draggedObstacle;
            const { x, y, zoom: camZoom } = camera.current;
            const dpr = window.devicePixelRatio || 1;

            ctx.save();
            ctx.scale(dpr, dpr);

            const logicalW = canvasRef.current.width / dpr;
            const logicalH = canvasRef.current.height / dpr;

            ctx.translate(logicalW / 2, logicalH / 2);
            ctx.scale(camZoom, camZoom);
            ctx.translate(-x, -y); 

            const sprite = SpriteManager.getObstacleSprite(type, engine.mapConfig.layout);
            const liftOffset = 40; 

            ctx.shadowColor = 'rgba(0,0,0,0.5)';
            ctx.shadowBlur = 30;
            ctx.shadowOffsetY = 30;
            ctx.globalAlpha = 0.9;

            ctx.drawImage(sprite, px - 32, py - 80 - liftOffset);
            ctx.restore();
        }
    }, [engine, transitionPhase, pressedAgent, selectedAgent, hoveredHexRef, hoveredSkill, draggedObstacle, camera]);

    const handleResize = useCallback((w: number, h: number) => {
        if (w > 0 && h > 0) {
            centerCamera(w, h);
        }
    }, [centerCamera]);

    // 5. Game Loop Hook (Pass camera for syncing)
    const { fpsRef } = useGameLoop(
        engine, 
        canvasRef, 
        wrapperRef, 
        rendererRef, 
        handleDraw, 
        handleResize,
        camera
    );

    // Initial Camera Center
    useEffect(() => {
        if (wrapperRef.current) {
            const t = setTimeout(() => {
                if (wrapperRef.current) {
                    centerCamera(wrapperRef.current.clientWidth, wrapperRef.current.clientHeight);
                }
            }, 100);
            return () => clearTimeout(t);
        }
    }, [engine.mapConfig.w, engine.mapConfig.h, isShowcaseMode, transitionPhase, centerCamera]);

    return (
        <div ref={wrapperRef} className="w-full h-full overflow-hidden relative bg-slate-950">
            <canvas 
                ref={canvasRef} 
                className="block w-full h-full"
                style={{ 
                    backgroundColor: engine.currentScene.background,
                    touchAction: 'none' 
                }} 
                onContextMenu={(e) => e.preventDefault()}
            />

            {winner !== null && !isShowcaseMode && (
                <div className="absolute inset-0 flex items-center justify-center bg-black/60 backdrop-blur-sm z-50 pointer-events-auto">
                    <div className="text-center p-10 liquid-glass rounded-3xl animate-bounce-in max-w-lg w-full border border-white/10 shadow-[0_0_50px_rgba(0,0,0,0.8)]">
                        <div className="mb-6">
                            <span className="text-xs font-mono font-bold tracking-[0.5em] text-slate-400 uppercase block mb-2">Simulation Complete</span>
                            <h2 className={`text-5xl md:text-6xl font-black tracking-tighter ${winner === Team.BLUE ? 'text-blue-400 drop-shadow-[0_0_30px_rgba(59,130,246,0.6)]' : 'text-red-500 drop-shadow-[0_0_30px_rgba(239,68,68,0.6)]'}`}>
                                {winner === Team.BLUE ? 'IMPERIAL' : 'COVENANT'}
                            </h2>
                            <h2 className="text-4xl md:text-5xl font-black text-white tracking-widest mt-1 opacity-90">
                                VICTORY
                            </h2>
                        </div>
                        <div className="h-px w-24 mx-auto bg-white/20 rounded-full mb-8"></div>
                        <div className="flex flex-col gap-3">
                            <button 
                                onClick={nextLevel} 
                                className="liquid-btn-primary px-8 py-4 rounded-xl text-lg font-bold shadow-lg w-full flex items-center justify-center gap-3 group"
                            >
                                <Icons.Dice className="w-5 h-5 group-hover:scale-110 transition-transform" />
                                <span>前進下一關 (Next Level)</span>
                            </button>
                            <button 
                                onClick={onOpenLogs} 
                                className="liquid-btn px-8 py-3 rounded-xl text-sm font-bold bg-slate-800/50 hover:bg-slate-700/50 border-white/10 text-cyan-400 shadow-md w-full flex items-center justify-center gap-2 group"
                            >
                                <Icons.Log className="w-4 h-4 opacity-80 group-hover:scale-110 transition-transform" />
                                <span>戰鬥記錄 (Battle Logs)</span>
                            </button>
                            <button 
                                onClick={rematch} 
                                className="liquid-btn px-8 py-3 rounded-xl text-sm font-bold bg-white/5 hover:bg-white/10 border-white/10 text-slate-300 shadow-lg w-full flex items-center justify-center gap-2 group"
                            >
                                <Icons.Restart className="w-4 h-4 opacity-70 group-hover:opacity-100 group-hover:-rotate-90 transition-all" />
                                <span>再戰一局 (Rematch)</span>
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default GameCanvas;

import { useEffect, useRef, MutableRefObject } from 'react';

interface CameraControlProps {
    canvasRef: MutableRefObject<HTMLCanvasElement | null>;
    cameraRef: MutableRefObject<{ x: number; y: number; zoom: number }>;
    onZoom: (delta: number) => void;
    engine: any;
}

/**
 * 攝像機交互控制器 v25.0
 * 僅保留縮放功能，平移邏輯已整合至 useGameInput 以解決 PC 上的左鍵拖曳衝突
 */
export const useCameraControl = ({ canvasRef, cameraRef, onZoom, engine }: CameraControlProps) => {
    const lastPinchDist = useRef<number>(0);

    useEffect(() => {
        const cvs = canvasRef.current;
        if (!cvs) return;

        const onWheel = (e: WheelEvent) => {
            e.preventDefault();
            // 縮放不受平移衝突影響
            const delta = e.deltaY > 0 ? -0.15 : 0.15;
            onZoom(delta);
        };

        const onTouchStart = (e: TouchEvent) => {
            if (e.touches.length === 2) {
                e.preventDefault();
                const t1 = e.touches[0];
                const t2 = e.touches[1];
                lastPinchDist.current = Math.hypot(t1.clientX - t2.clientX, t1.clientY - t2.clientY);
            }
        };

        const onTouchMove = (e: TouchEvent) => {
            if (e.touches.length === 2) {
                e.preventDefault();
                const t1 = e.touches[0];
                const t2 = e.touches[1];
                const dist = Math.hypot(t1.clientX - t2.clientX, t1.clientY - t2.clientY);
                if (lastPinchDist.current > 0) {
                    const delta = (dist - lastPinchDist.current) * 0.008;
                    onZoom(delta);
                }
                lastPinchDist.current = dist;
            }
        };

        cvs.addEventListener('wheel', onWheel, { passive: false });
        cvs.addEventListener('touchstart', onTouchStart, { passive: false });
        cvs.addEventListener('touchmove', onTouchMove, { passive: false });

        return () => {
            cvs.removeEventListener('wheel', onWheel);
            cvs.removeEventListener('touchstart', onTouchStart);
            cvs.removeEventListener('touchmove', onTouchMove);
        };
    }, [canvasRef, onZoom]);
};
